      pick: (xs) => xs[Math.floor(f() * xs.length) % xs.length],
      chance: (p) => f() < p,
      _get: () => [a, b, c, d],
      _set: (st) => { a = st[0]; b = st[1]; c = st[2]; d = st[3]; },
