  // base's own hue — lighten toward its glow, darken toward its own
  // deepened self — never toward the gray that made every coat and
  // ground read as one dusty mid-value smear
  const tintT = (c, t) => mix(c, mix(glow(c, 0.9), [255, 250, 240], 0.30), t);
  const shadeT = (c, t) =>
    mix(c, mix(c.map(v => Math.round(v * 0.42)), [26, 22, 18], 0.22), t);
