        WSKY = '#4a9ad8', WCYAN = '#3ec6d8', WORANGE = '#d97b2a';

  // ------------------------------------------------------------ geometry
  function smoothArr(vals, passes, closed) {
    const n = vals.length;
    for (let p = 0; p < passes; p++) {
      const v = vals.slice();
      for (let i = 0; i < n; i++) {
        if (!closed && (i === 0 || i === n - 1)) continue;
        vals[i] = (v[(i - 1 + n) % n] + v[i] + v[(i + 1) % n]) / 3;
      }
    }
    return vals;
  }

  function resample(pts, closed, step) {
    const P = closed ? pts.concat([pts[0]]) : pts;
    const out = [[P[0][0], P[0][1]]];
    let carry = 0;
    for (let i = 0; i < P.length - 1; i++) {
      const x1 = P[i][0], y1 = P[i][1], x2 = P[i + 1][0], y2 = P[i + 1][1];
      const d = Math.hypot(x2 - x1, y2 - y1);
      if (d < 1e-6) continue;
      let t = (step - carry) / d;
      while (t <= 1) {
        out.push([x1 + (x2 - x1) * t, y1 + (y2 - y1) * t]);
        t += step / d;
      }
      carry = (carry + d) % step;
    }
    if (closed) out.pop();
    else out.push([P[P.length - 1][0], P[P.length - 1][1]]);
    return out;
  }

  function smoothPts(pts, closed, passes) {
    const xs = smoothArr(pts.map(p => p[0]), passes, closed);
    const ys = smoothArr(pts.map(p => p[1]), passes, closed);
    return xs.map((x, i) => [x, ys[i]]);
  }

  function poly(ctx, pts, close) {
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    if (close) ctx.closePath();
  }

  function fillPts(...args) {
    if (RMH.depth || !RMH.fillPts) return fillPts_ORIG(...args);
    RMH.depth++;
    try { return RMH.fillPts(fillPts_ORIG, ...args); } finally { RMH.depth--; }
  }
  function fillPts_ORIG(ctx, pts, color) {
    ctx.fillStyle = css(color);
    ctx.beginPath();
    poly(ctx, pts, true);
    ctx.fill();
  }

  // organic closed blob
  function blob(rng, cx, cy, rx, ry, n, mag, tilt) {
    n = n || 24; mag = mag === undefined ? 0.07 : mag; tilt = tilt || 0;
    const noise = smoothArr(Array.from({ length: n }, () => rng.f() * 2 - 1), 2, true);
    const pts = [];
    for (let i = 0; i < n; i++) {
      const a = tilt + i / n * Math.PI * 2;
      const r = 1 + noise[i] * mag;
      pts.push([cx + Math.cos(a) * rx * r, cy + Math.sin(a) * ry * r]);
    }
    return pts;
  }

  // ------------------------------------------------- weighted ribbon line
  // The signature line: a filled variable-width ribbon. Thick-thin with a
  // slow hand-wobble; ends taper on open strokes.
  function ribbon(...args) {
    if (RMH.depth || !RMH.ribbon) return ribbon_ORIG(...args);
    RMH.depth++;
    try { return RMH.ribbon(ribbon_ORIG, ...args); } finally { RMH.depth--; }
  }
  function ribbon_ORIG(ctx, rng, pts, color, w, opt, emit) {
    opt = opt || {};
    const closed = !!opt.closed;
    // adaptive resample: the step shrinks with the mark, so a SHORT stroke
    // still carries enough spine points for the pressure and load engine —
    // the old fixed step dropped every small mark back to a flat ribbon
    let plen = 0;
    for (let i = 0; i < pts.length - 1; i++)
      plen += Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
    const step = closed ? (opt.step || 11)
      : Math.max(3.5, Math.min(opt.step || 11, plen / 10));
    let P = resample(pts, closed, step);
    if (P.length < 3) return;
    const jit = opt.jit === undefined ? 2.0 : opt.jit;
    if (jit > 0) {
      P = P.map(p => [p[0] + (rng.f() * 2 - 1) * jit,
                      p[1] + (rng.f() * 2 - 1) * jit]);
      P = smoothPts(P, closed, 1);
    }
    const n = P.length;
    const nz = smoothArr(Array.from({ length: n }, () => rng.f() * 2 - 1), 3, closed);
    const wob = opt.wob === undefined ? 0.38 : opt.wob;
    const taperP = opt.taper === undefined ? 0.45 : opt.taper;
    // grav: directional weight. The stroke carries ink on its underside
    // (jaw, shadowed flanks) and starves at the top of the form.
    const grav = opt.grav || 0;
    let gcx = 0, gcy = 0;
    if (grav > 0) {
      for (let i = 0; i < n; i++) { gcx += P[i][0]; gcy += P[i][1]; }
      gcx /= n; gcy /= n;
    }
    // pressure: every open mark long enough to be a PULL (not a feature
    // dab) owns a start weight and an end weight — it lands loaded and
    // near its full width, thins as the arm drags, and either lifts to a
    // dry tip or stops blunt where the brush stopped. Short feature marks
    // (eye pulls, nose dabs) stay symmetric and crisp.
    const isPull = !closed && opt.press !== 0 && plen > w * 2.2;
    let wS = 1, wE = 1, pPow = 1, rampT = 0, chat = 0;
    if (isPull) {
      wS = rng.r(1.0, 1.36);
      wE = rng.r(0.24, 0.72);
      pPow = rng.r(0.8, 1.5);
      rampT = rng.r(0.03, 0.10);          // the landing stamp expands fast
      chat = opt.chat === undefined ? 0.09 : opt.chat;   // bristle chatter
    }
    const L = [], Rt = [], WI = [];
    for (let i = 0; i < n; i++) {
      const ip = closed ? (i - 1 + n) % n : Math.max(0, i - 1);
      const iq = closed ? (i + 1) % n : Math.min(n - 1, i + 1);
      const dx = P[iq][0] - P[ip][0], dy = P[iq][1] - P[ip][1];
      const d = Math.hypot(dx, dy) || 1;
      let taper = 1;
      if (!closed && opt.end) {
        // one-sided dry-brush: loaded at the start, starving to nothing
        const t = i / (n - 1);
        taper = t < 0.10 ? 0.72 + 2.8 * t
              : Math.pow(Math.max(0.03, (1 - t) / 0.90), opt.end);
      } else if (!closed && taperP > 0) {
        const t = i / (n - 1);
        taper = Math.pow(Math.sin(Math.PI * Math.min(0.98, Math.max(0.02, t))), taperP);
      }
      if (grav > 0) {
        const ox = P[i][0] - gcx, oy = P[i][1] - gcy;
        const ol = Math.hypot(ox, oy) || 1;
        // light falls from the upper left: the contour starves to almost
        // nothing where it faces the light and carries its ink down the
        // shadow side and under the jaw
        const dt = (ox * -0.55 + oy * -0.835) / ol;   // 1 = facing light
        const sh = (1 - dt) / 2;                      // 0 lit .. 1 shadow
        taper *= 1 - grav + grav * (0.10 + 1.85 * Math.pow(sh, 1.8));
      }
      if (isPull) {
        const t = i / (n - 1);
        let press = wS + (wE - wS) * Math.pow(t, pPow);
        if (t < rampT) press *= 0.55 + 0.45 * t / rampT;
        // unsmoothed per-point chatter: the edge is the sum of bristle
        // ends, never a clean geometric boundary
        taper *= press * (1 + (rng.f() * 2 - 1) * chat);
      }
      const wi = Math.max(opt.min === undefined ? 0.35 : opt.min,
                          w * (1 + nz[i] * wob) * taper) / 2;
      L.push([P[i][0] - dy / d * wi, P[i][1] + dx / d * wi]);
      Rt.push([P[i][0] + dy / d * wi, P[i][1] - dx / d * wi]);
      WI.push(wi * 2);
    }
    if (emit) emit(P, WI, closed);
    // --- pigment load: the mark lands wet and near-opaque, runs out of
    // paint along its own path, and its tail breaks into separate bristle
    // threads. opt.load in (0,1] is how much of the brush's charge is
    // spent by the end of the pull; 0/undefined keeps the flat mark
    // (closed contours, tiny feature dabs).
    const load = (!closed && opt.load && n >= 6) ? opt.load : 0;
    if (!load) {
      ctx.fillStyle = css(color);
      ctx.beginPath();
      if (closed) {
        poly(ctx, L, true);
        poly(ctx, Rt.slice().reverse(), true);
        ctx.fill('evenodd');
      } else {
        poly(ctx, L.concat(Rt.slice().reverse()), true);
        ctx.fill();
      }
      return;
    }
    const gA = ctx.globalAlpha;
    // a sub-band of the stroke between resample indices, width remapped by
    // f(t): the same bristle bundle drawn at a different charge
    const band = (i0, i1, f, col) => {
      const A = [], B = [];
      for (let i = i0; i <= i1; i++) {
        const k = f ? f((i - i0) / Math.max(1, i1 - i0)) : 1;
        A.push([P[i][0] + (L[i][0] - P[i][0]) * k,
                P[i][1] + (L[i][1] - P[i][1]) * k]);
        B.push([P[i][0] + (Rt[i][0] - P[i][0]) * k,
                P[i][1] + (Rt[i][1] - P[i][1]) * k]);
      }
      ctx.fillStyle = css(col || color);
      ctx.beginPath();
      poly(ctx, A.concat(B.reverse()), true);
      ctx.fill();
    };
    // an offset polyline riding inside the bundle at u of the halfwidth
    const rail = (i0, i1, u) => {
      const tp = [];
      for (let i = i0; i <= i1; i++)
        tp.push([P[i][0] + (L[i][0] - P[i][0]) * u,
                 P[i][1] + (L[i][1] - P[i][1]) * u]);
      return tp;
    };
    // 1. the spent body: full length of the pull minus the very tail,
    //    already thinned to what charge is left when the brush gets there
    const iS = Math.min(n - 2, Math.max(4, Math.floor(n * rng.r(0.66, 0.86))));
    ctx.globalAlpha = gA * (1 - load * 0.45);
    band(0, iS, t => t > 0.72 ? 1 - (t - 0.72) / 0.28 * 0.42 : 1);
    // 2. the wet head laid over it: DENSER, slightly darker pigment where
    //    the brush landed, tapering away as the charge runs down — the
    //    color drifts a hair, paint mixing as it drags
    ctx.globalAlpha = gA * load * rng.r(0.50, 0.74);
    band(0, Math.max(3, Math.floor(iS * rng.r(0.42, 0.68))),
         t => t > 0.55 ? Math.max(0.06, 1 - (t - 0.55) / 0.45) : 1,
         drift(rng, sink(color, rng.r(0.02, 0.08)), 0.04));
    if (rng.chance(0.6)) {
      ctx.globalAlpha = gA * load * rng.r(0.28, 0.44);
      band(0, Math.max(2, Math.floor(iS * rng.r(0.24, 0.42))),
           t => t > 0.5 ? Math.max(0.06, 1 - (t - 0.5) / 0.5) : 1);
    }
    // 2b. sometimes the landing itself pools: a blunt stamp of settled
    //     pigment right where the brush first pressed
    if (w >= 6 && rng.chance(0.25)) {
      ctx.globalAlpha = gA * rng.r(0.18, 0.34);
      band(0, Math.max(2, Math.floor(n * rng.r(0.06, 0.14))),
           t => 1.04 - t * 0.2, sink(color, rng.r(0.08, 0.16)));
    }
    // 3. the tail: the bundle separates into two or three bristle threads,
    //    each dying at its own moment — dry breakup EMERGES from bristles
    //    dropping out, never from a uniform fade
    const nTh = rng.chance(0.55) ? 3 : 2;
    for (let j = 0; j < nTh; j++) {
      const u = (j / (nTh - 1) * 2 - 1) * rng.r(0.30, 0.78);
      const i0 = Math.max(0, Math.floor(iS * rng.r(0.80, 0.97)));
      const i1 = Math.min(n - 1,
        i0 + 2 + Math.floor((n - 1 - i0) * rng.r(0.45, 1.0)));
      if (i1 - i0 < 2) continue;
      ctx.globalAlpha = gA * (1 - load * rng.r(0.30, 0.55));
      ribbon(ctx, rng, rail(i0, i1, u), color,
             Math.max(1.1, w * rng.r(0.10, 0.22)),
             { taper: 0, end: rng.r(0.7, 1.4), min: 0.3, wob: 0.4,
               jit: 0.5, step: opt.step || 11 });
    }
    // 4. bristle streaks INSIDE the body: lifted and sunk hairlines where
    //    individual bristles carried more or less pigment — a wide mark
    //    carries several, so zooming into any pass finds its bristles
    if (w >= 6) {
      const kS = Math.max(1, Math.min(4, Math.round(w / 8)))
                 + (rng.chance(0.5) ? 1 : 0);
      for (let j = 0; j < kS; j++) {
        const i0 = Math.floor(n * rng.r(0.04, 0.22));
        const i1 = Math.min(iS, i0 + 3 + Math.floor(n * rng.r(0.30, 0.68)));
        if (i1 - i0 < 3) continue;
        ctx.globalAlpha = gA * rng.r(0.28, 0.52);
        ribbon(ctx, rng, rail(i0, i1, rng.r(-0.68, 0.68)),
               rng.chance(0.5) ? lift(color, rng.r(0.07, 0.16))
                               : sink(color, rng.r(0.06, 0.15)),
               Math.max(1, w * rng.r(0.08, 0.16)),
               { taper: 0.4, wob: 0.4, jit: 0.5, step: opt.step || 11 });
      }
    }
    // 5. sometimes a darker pooled rim along one edge near the landing,
    //    where the wet pigment settled
    if (w >= 8 && rng.chance(0.22)) {
      const i1 = Math.max(3, Math.floor(n * rng.r(0.30, 0.5)));
      ctx.globalAlpha = gA * rng.r(0.24, 0.40);
      ribbon(ctx, rng, rail(0, i1, (rng.chance(0.5) ? 1 : -1) * rng.r(0.58, 0.8)),
             sink(color, rng.r(0.10, 0.18)),
             Math.max(1, w * rng.r(0.13, 0.22)),
             { taper: 0.5, end: 1.0, min: 0.3, wob: 0.5, jit: 0.5,
               step: opt.step || 11 });
    }
    ctx.globalAlpha = gA;
  }

  // a contour that breaks and restarts: runs of ink separated by silence
  function brokenRibbon(ctx, rng, pts, color, w, opt) {
    const P = resample(pts, false, 9);
    const n = P.length;
    let i = 0;
    while (i < n - 3) {
      const run = Math.max(5, Math.floor(n * rng.r(0.10, 0.30)));
      const seg = P.slice(i, Math.min(n, i + run));
      if (seg.length > 2)
        ribbon(ctx, rng, seg, color, w,
               Object.assign({ taper: 0.7 }, opt, { closed: false }));
      i += run + Math.max(3, Math.floor(n * rng.r(0.04, 0.11)));
    }
  }

  // ------------------------------------------------- the physical dry brush
  // A stroke is an OBJECT, not an alpha rectangle along a path: a bundle of
  // bristles stamped down the spine, each bristle owning its lane, its own
  // pigment charge, its own drain rate and its own thickness. As the pull
  // travels, charge drains; a bristle whose charge falls under the ambient
  // tooth of the canvas stops depositing — first for a stamp or two, then
  // for good. The mark therefore decays from a solid wet band into separate
  // streaks into speckle into nothing, and whatever is underneath READS
  // THROUGH the gaps, because where a bristle skipped there simply is no
  // paint. Nothing here fades: every deposit is a small opaque touch.
  //   opt.fade  how much of the charge is spent by the end (default 1)
  //   opt.a     deposit alpha ceiling (default 0.9)
  //   opt.press width profile flattener: 0 = even, 1 = strong lift at end
  //   opt.grain 0..1 canvas tooth — higher = earlier, rougher breakup
  function dryStroke(...args) {
    if (RMH.depth || !RMH.dryStroke) return dryStroke_ORIG(...args);
    RMH.depth++;
    try { return RMH.dryStroke(dryStroke_ORIG, ...args); } finally { RMH.depth--; }
  }
  function dryStroke_ORIG(ctx, rng, pts, color, w, opt) {
    opt = opt || {};
    let plen = 0;
    for (let i = 0; i < pts.length - 1; i++)
      plen += Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
    const P = resample(pts, false, opt.step ||
                       Math.max(2.6, Math.min(4.5, plen / 90)));
    const n = P.length;
    if (n < 4) return;
    const nB = Math.max(5, Math.min(16, Math.round(w / 2.4)));
    const grain = opt.grain === undefined ? 0.5 : opt.grain;
    const fade = opt.fade === undefined ? 1 : opt.fade;
    const press = opt.press === undefined ? 0.55 : opt.press;
    const aTop = opt.a === undefined ? 0.9 : opt.a;
    const B = [];
    for (let j = 0; j < nB; j++)
      B.push({
        u: (((j + 0.5) / nB) * 2 - 1) * rng.r(0.84, 1.0) + rng.r(-0.06, 0.06),
        ch: rng.r(0.8, 1.35),           // pigment loaded on this bristle
        dr: rng.r(0.75, 1.5),           // how fast it drains
        wj: rng.r(0.55, 1.25),          // bristle thickness
        hu: rng.r(-0.03, 0.03),         // lane drift along the pull
      });
    // THE HAND PRESSES AND LIFTS along the pull (jonpick9): a slow
    // per-stroke pressure envelope breathes through width and deposit
    // together, so no two inches of the mark carry the same weight —
    // the difference between a drawn stroke and a stamped dash-train
    const pAmp = opt.pAmp === undefined ? 0.30 : opt.pAmp;
    const pEnv = smoothArr(
      Array.from({ length: 7 }, () => rng.f() * 2 - 1), 2, false);
    const gA = ctx.globalAlpha;
    const colA = css(color);
    const colB = css(sink(color, 0.07));   // pigment settles a shade darker
    for (let i = 0; i < n; i++) {
      const t = i / (n - 1);
      const ip = Math.max(0, i - 1), iq = Math.min(n - 1, i + 1);
      let nx = -(P[iq][1] - P[ip][1]), ny = P[iq][0] - P[ip][0];
      const nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;
      // the arm lifts as it drags: the bundle narrows toward the tail —
      // and the pressure envelope breathes on top of that lift
      const pv = pEnv[Math.min(6, Math.floor(t * 6.999))];
      const prs = 1 + pAmp * pv;
      const lift_ = (1 - press * Math.pow(t, 1.6) * 0.6) * prs;
      for (let j = 0; j < nB; j++) {
        const b = B[j];
        // charge drains along the pull, wobbling as the bristle re-wets
        // from its neighbors; the tooth of the canvas eats the weak —
        // a pressing hand feeds charge back into the paper
        const c = b.ch - b.dr * t * fade * 1.15 + (rng.f() - 0.5) * 0.34 +
                  pAmp * pv * 0.4;
        if (c < rng.f() * (0.42 + grain * 0.5)) continue;   // dropout
        const u = (b.u + b.hu * t * 6) * lift_;
        const rr = Math.max(0.7, (w / nB) * b.wj *
                            (0.62 + Math.min(1, c) * 0.55) * prs);
        ctx.globalAlpha = gA * aTop * Math.min(1, 0.42 + c * 0.75);
        ctx.fillStyle = c > 1.0 ? colB : colA;
        ctx.beginPath();
        ctx.ellipse(P[i][0] + nx * u * (w / 2), P[i][1] + ny * u * (w / 2),
                    rr * 1.25, rr * 0.9,
                    Math.atan2(P[iq][1] - P[ip][1], P[iq][0] - P[ip][0]),
                    0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.globalAlpha = gA;
  }

  // ================================================== THE AEROSOL (r130)
  // Nava's signature mark, and until this round the collection had none
  // of it. A spray mark is ATOMIZED, not stroked: a dense soft core that
  // falls off into a haze of separated droplets, with a hard edge
  // nowhere. Built as a real droplet scatter — every droplet is its own
  // deterministic deposit off the seed's rng — never as a blurred brush.
  //   spray(ctx, rng, x, y, r, color, dens, opt)
  //     r      nominal radius of the cloud (model units)
  //     dens   ~0.4 whisper .. 2.2 loaded can
  //     opt.a       alpha ceiling (default 0.75)
  //     opt.spread  sigma as a share of r (default 0.40; bigger = hazier)
  //     opt.elx/ely ellipse squash of the whole cloud
  //     opt.settle  chance of a darker settled droplet (default 0.12)
  function spray(ctx, rng, x, y, r, color, dens, opt) {
    opt = opt || {};
    const PX = 1000 / Math.max(1, ctx.canvas.width);
    const a0 = opt.a === undefined ? 0.75 : opt.a;
    const elx = opt.elx || 1, ely = opt.ely || 1;
    const sg = (opt.spread === undefined ? 0.40 : opt.spread) * r;
    const gA = ctx.globalAlpha;
    // droplet count is resolution-independent so the mark reads the
    // same on the 400px sheet and the 760px detail crop; only the
    // droplet size floor knows about pixels
    const N = Math.max(6, Math.round((dens || 1) * r * r / 16));
    // three alpha tiers, batched into three fills: the core builds its
    // density out of many soft overlaps, the fringe stays crisp lonely
    // dots — which is exactly how a can lays paint down
    const colA = css(color), colB = css(sink(color, 0.10));
    const tiers = [
      { a: a0 * 0.34, main: true, pts: [] },   // core mist
      { a: a0 * 0.62, main: true, pts: [] },   // body droplets
      { a: a0 * 0.88, main: true, pts: [] },   // fringe dots
      { a: a0 * 0.55, main: false, pts: [] },  // settled darker droplets
    ];
    for (let i = 0; i < N; i++) {
      // Rayleigh scatter: the 2-D gaussian a nozzle actually throws
      const u = Math.sqrt(-2 * Math.log(1 - rng.f() * 0.99930));
      if (u > 3.1) continue;
      const d = u * sg;
      const a = rng.f() * 6.28318530718;
      const px = x + Math.cos(a) * d * elx, py = y + Math.sin(a) * d * ely;
      // droplets shrink and separate as the cloud thins outward
      const rr = Math.max(PX * 0.62,
        r * 0.052 * (1.45 - Math.min(1.1, u * 0.40)) * rng.r(0.50, 1.60));
      const dark = rng.f() < (opt.settle === undefined ? 0.12 : opt.settle);
      const ti = dark ? 3 : u < 0.8 ? (rng.f() < 0.6 ? 0 : 1)
               : u < 1.6 ? 1 : 2;
      tiers[ti].pts.push([px, py, rr]);
    }
    tiers.forEach(tr => {
      if (!tr.pts.length) return;
      ctx.globalAlpha = gA * tr.a;
      ctx.fillStyle = tr.main ? colA : colB;
      ctx.beginPath();
      tr.pts.forEach(p => {
        ctx.moveTo(p[0] + p[2], p[1]);
        ctx.arc(p[0], p[1], p[2], 0, 6.28318530718);
      });
      ctx.fill();
    });
    ctx.globalAlpha = gA;
  }

  // a drip: spray laid too wet lets go and runs. A thin wandering track
  // falling straight down, thinning, ending in one heavier bead.
  function sprayDrip(ctx, rng, x, y, color, len, w0) {
    const PX = 1000 / Math.max(1, ctx.canvas.width);
    const gA = ctx.globalAlpha;
    const L = len || rng.r(50, 170);
    const w = Math.max(PX * 0.8, w0 || rng.r(3.2, 6.5));
    const n = Math.max(5, Math.round(L / 7));
    let px = x;
    ctx.fillStyle = css(color);
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      px += rng.r(-1.4, 1.4);
      const rr = Math.max(PX * 0.6, w * (1 - t * 0.62) * rng.r(0.7, 1.1) * 0.5);
      ctx.globalAlpha = gA * rng.r(0.5, 0.85);
      ctx.beginPath();
      ctx.arc(px, y + L * t, rr, 0, 6.28318530718);
      ctx.fill();
    }
    ctx.globalAlpha = gA * rng.r(0.7, 0.95);
    ctx.beginPath();
    ctx.arc(px + rng.r(-1, 1), y + L + rng.r(0, 4),
            Math.max(PX * 0.8, w * rng.r(0.55, 0.8)), 0, 6.28318530718);
    ctx.fill();
    ctx.globalAlpha = gA;
  }

  // a sprayed LINE: the can travels. A fat soft-cored band with droplet
  // fringe, pressure breathing along the pass, and — laid too wet — it
  // drips. This is the mark thrown across a whole finished painting in
  // nava06, the halo of nava04, the black bars of nava11.
  //   opt.dens    density multiplier (default 1)
  //   opt.drip    drips per 1000 units of travel (default 0 = dry)
  //   opt.spread  passed through to spray (default 0.38)
  function sprayStroke(ctx, rng, pts, w, color, opt) {
    opt = opt || {};
    const P = resample(pts, false, Math.max(6, w * 0.52));
    if (P.length < 2) return;
    const pEnv = smoothArr(
      Array.from({ length: 6 }, () => rng.f() * 2 - 1), 2, false);
    const dripP = (opt.drip || 0) * Math.max(6, w * 0.52) / 1000;
    for (let i = 0; i < P.length; i++) {
      const t = i / (P.length - 1);
      const pv = 1 + 0.34 * pEnv[Math.min(5, Math.floor(t * 5.999))];
      spray(ctx, rng, P[i][0], P[i][1], w * 0.62 * pv, color,
            (opt.dens || 1) * 0.9 * pv,
            { a: opt.a === undefined ? 0.7 : opt.a,
              spread: opt.spread === undefined ? 0.38 : opt.spread,
              settle: 0.08 });
      if (dripP && rng.f() < dripP)
        sprayDrip(ctx, rng, P[i][0] + rng.r(-w * 0.2, w * 0.2), P[i][1],
                  color, rng.r(40, 150), Math.max(2.8, w * 0.10));
    }
  }

  // ================================================ THE OIL STICK (r130)
  // Nava's other hand: a raw fast contour left uncorrected. Doubled
  // lines, overshoot past the corner, a waxy drag that skips on the
  // tooth, and nobody ever comes back to fix it. The confident closed
  // silhouette keeps the skull and the eyes; THIS mark owns the
  // secondary drawing — horizons, grass, scribbles, witnesses, stars.
  //   opt.dbl     chance of a second uncorrected pass (default 0.55)
  //   opt.over    overshoot length past each end, model units (default 26)
  //   opt.tooth   0..1 skip amount (default 0.35)
  //   opt.a       alpha ceiling (default 0.9)
  //   opt.wob     hand wobble in units (default w*0.5)
  function oilStick(...args) {
    if (RMH.depth || !RMH.oilStick) return oilStick_ORIG(...args);
    RMH.depth++;
    try { return RMH.oilStick(oilStick_ORIG, ...args); } finally { RMH.depth--; }
  }
  function oilStick_ORIG(ctx, rng, pts, color, w, opt) {
    opt = opt || {};
    const PX = 1000 / Math.max(1, ctx.canvas.width);
    const gA = ctx.globalAlpha;
    const a0 = opt.a === undefined ? 0.9 : opt.a;
    const tooth = opt.tooth === undefined ? 0.35 : opt.tooth;
    const passes = 1 + (rng.f() < (opt.dbl === undefined ? 0.55 : opt.dbl)
                        ? 1 : 0);
    const colA = css(color), colB = css(sink(color, 0.08));
    for (let ps = 0; ps < passes; ps++) {
      // the second pass is the SAME gesture done again, off-register:
      // shifted, slightly re-scaled, never erased
      const ox = ps ? rng.r(-w * 1.1, w * 1.1) : 0;
      const oy = ps ? rng.r(-w * 1.1, w * 1.1) : 0;
      let P = pts.map(p => [p[0] + ox, p[1] + oy]);
      // overshoot: the hand does not stop at the corner
      const ovA = (opt.over === undefined ? 26 : opt.over) * rng.r(0.4, 1.3);
      const ovB = (opt.over === undefined ? 26 : opt.over) * rng.r(0.4, 1.3);
      const ext = (a, b, L) => {
        const dx = b[0] - a[0], dy = b[1] - a[1];
        const dl = Math.hypot(dx, dy) || 1;
        return [b[0] + dx / dl * L, b[1] + dy / dl * L];
      };
      if (P.length >= 2) {
        P = [ext(P[1], P[0], ovA)].concat(P, [ext(P[P.length - 2],
                                                  P[P.length - 1], ovB)]);
      }
      const dotR = Math.max(PX * 0.6, w * 0.13);
      const step = Math.max(PX * 0.8, dotR * 0.9);
      const Q = resample(P, false, step);
      const wob = opt.wob === undefined ? w * 0.5 : opt.wob;
      const wEnv = smoothArr(
        Array.from({ length: 7 }, () => rng.f() * 2 - 1), 1, false);
      // the walk keeps its pace per unit of travel, not per stamp
      const keep = Math.pow(0.82, step / Math.max(2.6, w * 0.42));
      const kick = 0.42 * Math.sqrt(1 - keep * keep) / Math.sqrt(1 - 0.82 * 0.82);
      let wx = 0, wy = 0;
      const nQ = Q.length;
      for (let i = 0; i < nQ; i++) {
        const t = i / Math.max(1, nQ - 1);
        wx = wx * keep + rng.r(-wob, wob) * kick;
        wy = wy * keep + rng.r(-wob, wob) * kick;
        const ip = Math.max(0, i - 1), iq = Math.min(nQ - 1, i + 1);
        const dx = Q[iq][0] - Q[ip][0], dy = Q[iq][1] - Q[ip][1];
        const dl = Math.hypot(dx, dy) || 1;
        const nx = -dy / dl, ny = dx / dl, ang = Math.atan2(dy, dx);
        // waxy skip: where the tooth dips the stick presses lighter for a
        // stretch and the line thins and frays; it does not break into beads
        const dip = rng.f() < tooth * 0.12 ? rng.r(0.25, 0.6) : 1;
        const pv = (1 + 0.42 * wEnv[Math.min(6, Math.floor(t * 6.999))]) * dip;
        const hw = Math.max(PX * 0.5, w * 0.5 * pv);
        const K = Math.max(2, Math.min(7, Math.round(hw / dotR * 1.3)));
        const cx = Q[i][0] + wx, cy = Q[i][1] + wy;
        for (let k = 0; k < K; k++) {
          const u = (rng.f() * 2 - 1) * 1.05;
          const cover = (1 - 0.55 * Math.pow(Math.abs(u), 2.0)) * (0.7 + 0.3 * dip);
          if (rng.f() > cover) continue;
          const rr = dotR * rng.r(0.8, 1.3);
          ctx.globalAlpha = gA * a0 * (0.78 + 0.22 * cover) * (ps ? 0.72 : 1);
          ctx.fillStyle = rng.f() < 0.22 ? colB : colA;
          ctx.beginPath();
          ctx.ellipse(cx + nx * u * hw, cy + ny * u * hw, rr * 1.6, rr * 0.8,
                      ang, 0, 6.28318530718);
          ctx.fill();
        }
      }
    }
    ctx.globalAlpha = gA;
  }

  // a scribble that ignores its own boundary (nava02's bird head): a
  // fast zigzag walk across a region, one gesture, never cleaned up
  function oilScribble(ctx, rng, cx, cy, rx, ry, color, w, opt) {
    opt = opt || {};
    const n = opt.n || Math.max(4, Math.round(rng.r(5, 9)));
    const pts = [];
    let px = cx + rng.r(-rx, rx) * 0.8, py = cy - ry * rng.r(0.6, 1.0);
    pts.push([px, py]);
    for (let i = 0; i < n; i++) {
      // each swing overshoots the region a little: the scribble does
      // not respect the shape it is filling
      px = cx + (i % 2 ? -1 : 1) * rx * rng.r(0.7, 1.25);
      py += (ry * 2 / n) * rng.r(0.55, 1.35);
      pts.push([px + rng.r(-rx * 0.15, rx * 0.15), py]);
    }
    oilStick(ctx, rng, pts, color, w,
             { dbl: 0.25, over: rx * 0.3, tooth: opt.tooth === undefined
                 ? 0.3 : opt.tooth, a: opt.a, wob: w * 0.8 });
  }

  // a hand star (nava03's silver stars): three or four short crossing
  // strokes through one center, arm lengths disagreeing
  function starMark(ctx, rng, x, y, r, color, a0) {
    const gA = ctx.globalAlpha;
    const arms = 3 + (rng.f() < 0.5 ? 1 : 0);
    const a1 = rng.r(0, 3.14);
    for (let i = 0; i < arms; i++) {
      const a = a1 + i * 3.14159 / arms + rng.r(-0.2, 0.2);
      const l1 = r * rng.r(0.6, 1.2), l2 = r * rng.r(0.6, 1.2);
      ctx.globalAlpha = gA * (a0 || rng.r(0.6, 0.95));
      ribbon(ctx, rng,
             [[x - Math.cos(a) * l1, y - Math.sin(a) * l1],
              [x + Math.cos(a) * l2, y + Math.sin(a) * l2]],
             color, Math.max(2.6, r * rng.r(0.16, 0.26)),
             { taper: 0.5, wob: 0.3, jit: 0.8, step: 5 });
    }
    ctx.globalAlpha = gA;
  }

  // the tiny stick-figure witness (nava03): a child's drawing of a
  // person standing at the beast's foot, which is what makes the beast
  // enormous. Oil stick, one gesture per limb, sometimes holding a stick.
  function stickWitness(ctx, rng, x, y, h, color) {
    const hr = h * 0.16;
    const so = { dbl: 0.2, over: h * 0.06, tooth: 0.22, wob: 1.6 };
    const w = Math.max(3.2, h * 0.045);
    // head: an open wobbling ring
    const ring = [];
    for (let k = 0; k <= 9; k++) {
      const a = -0.4 + k / 9 * 5.9;
      ring.push([x + Math.cos(a) * hr * rng.r(0.9, 1.1),
                 y - h + hr + Math.sin(a) * hr * rng.r(0.9, 1.1)]);
    }
    oilStick(ctx, rng, ring, color, w, so);
    const neckY = y - h + hr * 2.1;
    const hipY = y - h * 0.32;
    oilStick(ctx, rng, [[x, neckY], [x + rng.r(-2, 2), hipY]], color, w, so);
    // arms: one gesture, maybe raised, maybe holding a stick out
    const armY = neckY + h * 0.10;
    const aSd = rng.chance(0.5) ? 1 : -1;
    oilStick(ctx, rng,
             [[x - aSd * h * 0.20, armY + h * rng.r(0.02, 0.16)],
              [x, armY],
              [x + aSd * h * 0.22, armY + h * rng.r(-0.14, 0.10)]],
             color, w, so);
    if (rng.chance(0.5))
      oilStick(ctx, rng,
               [[x + aSd * h * 0.20, armY + h * rng.r(-0.12, 0.06)],
                [x + aSd * h * rng.r(0.26, 0.36), armY - h * rng.r(0.16, 0.30)]],
               color, w * 0.8, so);
    // legs
    oilStick(ctx, rng, [[x, hipY],
                        [x - h * rng.r(0.08, 0.16), y + rng.r(-2, 3)]],
             color, w, so);
    oilStick(ctx, rng, [[x, hipY],
                        [x + h * rng.r(0.08, 0.16), y + rng.r(-2, 3)]],
             color, w, so);
  }

  // Nava margin creature: a few aerosol strokes, unshaded, ten seconds
  // on a wall. Dragons, rabbits, snakes, sharks, birds, skulls.
  // TWOMBLY'S KNOT (2026-09-02). A loop of cursive scribble in pencil grey
  // or oil stick, then the palm drags it (the canvas copied onto itself a
  // few pixels along at low alpha), then a fresh loop over the smudge: three
  // or four generations so the knot reads as time, not as a doodle.
  function scribbleKnot(ctx, rng, cx, cy, r, color, gens) {
    for (let g = 0; g < gens; g++) {
      const loops = 2 + Math.floor(rng.f() * 3);
      const n = loops * 16;
      const pts = [];
      const ph = rng.r(0, 6.28), ex = rng.r(1.1, 1.6), ey = rng.r(0.45, 0.75);
      for (let i = 0; i <= n; i++) {
        const t = i / n * Math.PI * 2 * loops;
        const rr = r * (0.55 + 0.45 * Math.sin(t * 0.37 + ph + g));
        pts.push([cx + Math.cos(t) * rr * ex + (i / n - 0.5) * r * rng.r(0.2, 0.6) + rng.r(-r * 0.05, r * 0.05),
                  cy + Math.sin(t) * rr * ey + (i / n - 0.5) * r * 0.35 + rng.r(-r * 0.04, r * 0.04)]);
      }
      ctx.globalAlpha = 0.58 + g * 0.14;
      oilStick(ctx, rng, pts, color, Math.max(3.5, r * 0.055 * (1 + g * 0.35)),
               { dbl: 0.15, over: 6, tooth: 0.55, wob: 2.5 });
      ctx.globalAlpha = 1;
      if (g < gens - 1) palmSmudge(ctx, rng, cx - r * 1.7, cy - r * 0.9, r * 3.4, r * 1.8,
                                   rng.r(-1, 1) * r * 0.12, rng.r(0.02, 0.08) * r);
    }
  }

  // the heel of the hand across wet stick: the region copied onto itself
  function palmSmudge(ctx, rng, x, y, w, h, ox, oy) {
    let m = null;
    try { m = ctx.getTransform ? ctx.getTransform() : null; } catch (e) { m = null; }
    if (!m) return;
    const X = m.a * x + m.c * y + m.e, Y = m.b * x + m.d * y + m.f;
    const W = Math.abs(m.a) * w, H = Math.abs(m.d) * h;
    const cw = ctx.canvas.width, ch = ctx.canvas.height;
    const sx = Math.max(0, Math.floor(X)), sy = Math.max(0, Math.floor(Y));
    const sw = Math.min(cw - sx, Math.ceil(W)), sh = Math.min(ch - sy, Math.ceil(H));
    if (sw < 4 || sh < 4) return;
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    for (let k = 1; k <= 3; k++) {
      ctx.globalAlpha = 0.22 - k * 0.05;
      ctx.drawImage(ctx.canvas, sx, sy, sw, sh,
                    sx + m.a * ox * k / 3, sy + m.d * oy * k / 3, sw, sh);
    }
    ctx.restore();
  }

  function sprayCreature(ctx, rng, kind, x, y, s, color) {
    const ink = mix(hx('#14100c'), color, 0.08);
    const so = { dbl: 0.45, over: s * 0.16, tooth: 0.32, wob: Math.max(2.4, s * 0.045) };
    const fat = Math.max(10, s * 0.30);
    const bone = Math.max(5.5, s * 0.085);
    if (kind === 'dragon') {
      const body = [];
      for (let i = 0; i <= 8; i++) {
        const t = i / 8;
        body.push([x + (t - 0.15) * s * 1.7 + Math.sin(t * 5.5) * s * 0.16,
                   y + Math.sin(t * 3.1) * s * 0.42]);
      }
      sprayStroke(ctx, rng, body, fat, color,
                  { dens: 0.95, a: 0.82, spread: 0.38, drip: 0.5 });
      oilStick(ctx, rng, body, ink, bone, so);
      oilStick(ctx, rng, [[x + s * 0.02, y - s * 0.18],
                          [x - s * 0.18, y - s * 0.62]], ink, bone, so);
      oilStick(ctx, rng, [[x + s * 0.06, y - s * 0.16],
                          [x + s * 0.22, y - s * 0.58]], ink, bone * 0.9, so);
      spray(ctx, rng, x + s * 0.08, y - s * 0.10, s * 0.09, hx('#e02424'), 1.15,
            { a: 0.82, spread: 0.32 });
      // a little fire off the snout
      sprayStroke(ctx, rng,
                  [[x + s * 0.22, y],
                   [x + s * 0.55, y - s * rng.r(0.05, 0.25)],
                   [x + s * 0.82, y + s * rng.r(-0.18, 0.10)]],
                  fat * 0.55, mix(hx('#f06a20'), color, 0.15),
                  { dens: 0.8, a: 0.7, spread: 0.46, drip: 0.2 });
    } else if (kind === 'rabbit') {
      spray(ctx, rng, x, y, s * 0.42, color, 1.05,
            { a: 0.70, spread: 0.40, elx: 1.1, ely: 0.9 });
      sprayStroke(ctx, rng,
                  [[x - s * 0.12, y - s * 0.18], [x - s * 0.22, y - s * 0.92]],
                  fat * 0.55, color, { dens: 0.85, a: 0.80, spread: 0.36 });
      sprayStroke(ctx, rng,
                  [[x + s * 0.10, y - s * 0.16], [x + s * 0.20, y - s * 0.82]],
                  fat * 0.48, color, { dens: 0.85, a: 0.78, spread: 0.36 });
      oilStick(ctx, rng, [[x - s * 0.12, y - s * 0.10],
                          [x - s * 0.22, y - s * 0.92]], ink, bone, so);
      oilStick(ctx, rng, [[x + s * 0.10, y - s * 0.10],
                          [x + s * 0.20, y - s * 0.82]], ink, bone * 0.9, so);
      oilStick(ctx, rng, [[x - s * 0.08, y + s * 0.05],
                          [x + s * 0.10, y + s * 0.02]], ink, bone * 0.7, so);
    } else if (kind === 'snake') {
      const body = [];
      for (let i = 0; i <= 11; i++) {
        const t = i / 11;
        body.push([x + t * s * 1.85, y + Math.sin(t * 7.2) * s * 0.38]);
      }
      sprayStroke(ctx, rng, body, fat * 0.72, color,
                  { dens: 0.90, a: 0.82, spread: 0.38, drip: 0.35 });
      oilStick(ctx, rng, body, ink, bone, so);
      spray(ctx, rng, body[0][0], body[0][1], s * 0.10, hx('#e02424'), 1.1,
            { a: 0.8, spread: 0.3 });
    } else if (kind === 'shark') {
      const nose = [x + s * 0.85, y];
      const top = [x - s * 0.15, y - s * 0.55];
      const bot = [x - s * 0.10, y + s * 0.48];
      sprayStroke(ctx, rng, [bot, nose, top], fat * 1.05, color,
                  { dens: 0.95, a: 0.82, spread: 0.38 });
      oilStick(ctx, rng, [bot, nose, top, bot], ink, bone, so);
      spray(ctx, rng, x + s * 0.15, y - s * 0.08, s * 0.48, color, 0.9,
            { a: 0.55, spread: 0.42, elx: 1.3, ely: 0.75 });
      const nT = 4 + Math.floor(rng.f() * 3);
      for (let i = 0; i < nT; i++) {
        const tx = x - s * 0.02 + i * s * 0.14;
        oilStick(ctx, rng, [[tx, y + s * 0.06], [tx + s * 0.04, y + s * 0.28]],
                 ink, s * 0.045, so);
      }
    } else if (kind === 'bird') {
      spray(ctx, rng, x, y, s * 0.28, color, 1.0, { a: 0.72, spread: 0.38 });
      sprayStroke(ctx, rng,
                  [[x - s * 0.55, y + s * 0.08], [x, y - s * 0.05],
                   [x + s * 0.60, y + s * 0.12]],
                  fat * 0.7, color, { dens: 0.7, a: 0.68, spread: 0.42 });
      oilStick(ctx, rng, [[x + s * 0.12, y], [x + s * 0.42, y + s * 0.08]],
               mix(hx('#e04030'), color, 0.2), s * 0.05, so);
    } else {
      // skull: nava07's white bone in the corner
      spray(ctx, rng, x, y, s * 0.42, color, 1.05,
            { a: 0.72, spread: 0.36, elx: 0.9, ely: 1.05 });
      spray(ctx, rng, x - s * 0.14, y - s * 0.04, s * 0.11, ink, 1.2,
            { a: 0.85, spread: 0.28 });
      spray(ctx, rng, x + s * 0.14, y - s * 0.04, s * 0.11, ink, 1.2,
            { a: 0.85, spread: 0.28 });
      oilStick(ctx, rng, [[x - s * 0.18, y + s * 0.16],
                          [x + s * 0.18, y + s * 0.18]], ink, s * 0.045, so);
    }
  }

  function dot(ctx, x, y, r, color) {
    ctx.fillStyle = css(color);
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  // ------------------------------------------------------------- pigment
  // per-stroke color drift: each brushload comes off the palette slightly
  // warmer or cooler, lighter or darker, than the last — never the same mix
  function drift(rng, c, amt) {
    const warm = [232, 158, 92], cool = [64, 96, 148];
    let o = mix(c, rng.chance(0.5) ? warm : cool, rng.r(0.02, amt));
    o = rng.chance(0.5) ? lift(o, rng.r(0, amt * 1.1)) : sink(o, rng.r(0, amt * 1.1));
    return o;
  }

  // a brushstroke along an arbitrary curved path, same pigment charge
  function strokePath(ctx, rng, path, w, color, alpha) {
    ctx.globalAlpha = alpha;
    ribbon(ctx, rng, path, color, w,
           { taper: rng.r(0.3, 0.8), wob: 0.5, jit: 2.2, step: 14,
             load: rng.r(0.55, 0.85) });
    ctx.globalAlpha = 1;
  }

  function scalePoly(pts, cx, cy, fn) {
    return pts.map((p, i) => {
      const k = fn(i, Math.atan2(p[1] - cy, p[0] - cx));
      return [cx + (p[0] - cx) * k, cy + (p[1] - cy) * k];
    });
  }

  const LX = -0.55, LY = -0.835;      // light falls from the upper left

  // the stroke's path knows what form it is describing
  function flowPath(rng, opt, px, py, L) {
    if (opt.flow === 'dome') {
      // a long pull arcing with the skull dome / shoulder mass; each
      // stroke's own pivot wanders so the pulls never nest into rings
      const cj = opt.cJit || 0;
      const c = [opt.center[0] + rng.r(-1, 1) * cj,
                 opt.center[1] + rng.r(-1, 1) * cj];
      const ox = px - c[0], oy = py - c[1];
      const r = Math.hypot(ox, oy) || 1;
      // arc length stays close to L: longer arcs curl into rings
      const da = Math.min(0.55, L / (1.7 * r));
      const path = [];
      for (let k = 0; k <= 5; k++) {
        const th = -da + 2 * da * k / 5;
        const ct = Math.cos(th), st = Math.sin(th);
        path.push([c[0] + ox * ct - oy * st, c[1] + ox * st + oy * ct]);
      }
      return path;
    }
    if (opt.flow === 'wrap') {
      // passes that WRAP the form the way nara1's skull is built: the
      // stroke runs along the local tangent around a (jittered) center and
      // bows gently AWAY from it — a flattened arc that suggests the dome
      // without ever nesting into rings
      const cj = opt.cJit || 0;
      const c = [opt.center[0] + rng.r(-1, 1) * cj,
                 opt.center[1] + rng.r(-1, 1) * cj];
      const ox = px - c[0], oy = py - c[1];
      const r = Math.hypot(ox, oy) || 1;
      const a2 = Math.atan2(oy, ox) + Math.PI / 2 +
                 rng.r(-1, 1) * (opt.aJit === undefined ? 0.16 : opt.aJit);
      const tx = Math.cos(a2), ty = Math.sin(a2);
      const bow = Math.min(L * 0.45, (L * L) / (2 * r)) * rng.r(0.45, 0.95);
      return [[px - tx * L, py - ty * L],
              [px + ox / r * bow, py + oy / r * bow],
              [px + tx * L, py + ty * L]];
    }
    if (opt.flow === 'splay') {
      // passes that SPLAY outward from a root — fur falling away down the
      // muzzle, whiskers of paint leaving the nose bridge
      const c = opt.center;
      const a2 = Math.atan2(py - c[1], px - c[0]) +
                 rng.r(-1, 1) * (opt.aJit === undefined ? 0.24 : opt.aJit);
      const ca = Math.cos(a2), sa = Math.sin(a2);
      const bow = rng.r(-0.14, 0.14) * L;
      return [[px - ca * L * 0.6, py - sa * L * 0.6],
              [px - sa * bow, py + ca * bow],
              [px + ca * L * 1.4, py + sa * L * 1.4]];
    }
    if (opt.flow === 'drape') {
      // cloth falling off a crown: near-vertical but flaring outward and
      // bowing as it drops — never a straight streak
      const lean = (px - opt.cx) * (opt.spread || 0.35);
      return [[px - lean * 0.30, py - L * 0.55],
              [px + rng.r(-8, 8), py],
              [px + lean * 0.55, py + L * 0.55]];
    }
    // free scumble with a gentle bow — near-PARALLEL to the shape's base
    // angle, so a filled form reads as combed passes, not crossed flags
    const a = opt.baseA +
              rng.r(-1, 1) * (opt.aJit === undefined ? 0.32 : opt.aJit);
    const bow = rng.r(-0.2, 0.2) * L;
    return [[px - Math.cos(a) * L, py - Math.sin(a) * L],
            [px - Math.sin(a) * bow, py + Math.cos(a) * bow],
            [px + Math.cos(a) * L, py + Math.sin(a) * L]];
  }

  // CRAYON PRESSURE (feel2): directional skinny ellipses whose skips
  // leave the underpaint. Cheap, countable, not a smear.
  function crayonHatch(...args) {
    if (RMH.depth || !RMH.crayonHatch) return crayonHatch_ORIG(...args);
    RMH.depth++;
    try { return RMH.crayonHatch(crayonHatch_ORIG, ...args); } finally { RMH.depth--; }
  }
  function crayonHatch_ORIG(ctx, rng, pts, base, opt) {
    opt = opt || {};
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
    }
    const w = x1 - x0, h = y1 - y0;
    const dim = Math.sqrt(Math.max(40, w * h));
    const ang = opt.ang === undefined ? rng.r(-0.5, 0.5) : opt.ang;
    ctx.save();
    ctx.beginPath(); poly(ctx, pts, true); ctx.clip();
    const n = opt.n || Math.max(8, Math.min(42, Math.round(w * h / 6200)));
    for (let i = 0; i < n; i++) {
      const px = x0 + w * rng.r(0.03, 0.97);
      const py = y0 + h * rng.r(0.03, 0.97);
      const L = dim * rng.r(0.09, 0.26);
      const ww = Math.max(2.8, dim * rng.r(0.016, 0.042));
      const tone = i % 3 === 0 ? base
        : (i % 2 ? tintT(base, rng.r(0.14, 0.30))
                 : shadeT(base, rng.r(0.12, lum(base) > 170 ? 0.32 : 0.22)));
      ctx.globalAlpha = rng.r(0.58, 0.94) * (opt.aMul || 1);
      ctx.fillStyle = css(drift(rng, tone, 0.05));
      ctx.beginPath();
      ctx.ellipse(px, py, L, ww * 0.52, ang + rng.r(-0.14, 0.14), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // ONE ENGINE: every mark is a bristle bundle that lands wet and runs dry.
  function drawStroke(ctx, rng, path, brush) {
    dryStroke(ctx, rng, path, brush.color, brush.w, brush);
  }

  // WOODBLOCK FILL (jonpick9): opaque patches two-to-three values apart,
  // then crayon hatch, then a few dry bristle drags. Never a translucent
  // soup that averages to one smear.
  function paintShape(...args) {
    if (RMH.depth || !RMH.paintShape) return paintShape_ORIG(...args);
    RMH.depth++;
    try { return RMH.paintShape(paintShape_ORIG, ...args); } finally { RMH.depth--; }
  }
  function paintShape_ORIG(ctx, rng, pts, base, opt) {
    opt = opt || {};
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9, cx = 0, cy = 0;
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
      cx += p[0]; cy += p[1];
    }
    cx /= pts.length; cy /= pts.length;
    const w = x1 - x0, h = y1 - y0;
    const dim = Math.sqrt(Math.max(40, w * h));
    const oNz = smoothArr(Array.from({ length: pts.length }, () => rng.f()), 2, true);
    const outer = scalePoly(pts, cx, cy, i => 1 + oNz[i] * 0.015);
    ctx.save();
    ctx.beginPath(); poly(ctx, outer, true); ctx.clip();
    ctx.globalAlpha = opt.under === undefined ? 1 : opt.under;
    ctx.fillStyle = css(opt.underC || base);
    ctx.beginPath(); poly(ctx, pts, true); ctx.fill();
    ctx.globalAlpha = 1;
    const dr = opt.drift === undefined ? 0.14 : opt.drift;
    const hasHue = hueOf(base)[1] > 0.10;
    const nP = Math.max(5, Math.min(20,
      opt.n ? Math.round(opt.n * 0.85) : Math.round(w * h / 11000)));
    const ang0 = opt.ang !== undefined ? opt.ang
               : (opt.baseA !== undefined ? opt.baseA : rng.r(-0.4, 0.4));
    const rad0 = Math.max(1, Math.hypot(w, h) / 2);
    for (let i = 0; i < nP; i++) {
      const pw = dim * rng.r(0.18, 0.42) * (opt.szMul || 1);
      const ph = pw * rng.r(0.55, 1.15);
      const px = x0 + w * rng.r(0.08, 0.92);
      const py = y0 + h * rng.r(0.08, 0.92);
      // the patch answers the light: on the lit upper-left of the form
      // the registers TINT, on the shadow side they SHADE — one
      // directional division per form, never an even dusting
      const shF = (1 - ((px - cx) * LX + (py - cy) * LY) / rad0) / 2;
      const toShade = rng.chance(shF > 0.52 ? 0.78 : 0.22);
      let tone;
      if (hasHue && rng.chance(0.45)) {
        tone = hueShiftC(base, rng.r(8, 22) * (rng.chance(0.5) ? 1 : -1));
        tone = toShade ? shadeT(tone, rng.r(0.08, 0.16))
                       : tintT(tone, rng.r(0.08, 0.18));
      } else {
        tone = toShade ? shadeT(base, rng.r(0.08, lum(base) > 170 ? 0.16 : 0.18))
                       : tintT(base, rng.r(0.10, 0.22));
      }
      ctx.globalAlpha = rng.r(0.62, 0.92);
      fillPts(ctx, blob(rng, px, py, pw, ph, 12, 0.18, ang0 + rng.r(-0.3, 0.3)),
              drift(rng, tone, dr * 0.5));
    }
    ctx.globalAlpha = 1;
    crayonHatch(ctx, rng, pts, base,
                { ang: ang0, n: Math.max(8, Math.min(36, Math.round(w * h / 7000))),
                  aMul: 0.85 });
    // a few dry bristle drags so zoom finds streaks, not just patches
    const nD = 2 + (rng.chance(0.55) ? 1 : 0) + (dim > 180 ? 1 : 0);
    for (let i = 0; i < nD; i++) {
      const px = x0 + w * rng.r(0.12, 0.88);
      const py = y0 + h * rng.r(0.12, 0.88);
      const L = dim * rng.r(0.28, 0.55);
      const a = ang0 + rng.r(-0.18, 0.18);
      const tone = rng.chance(0.5) ? tintT(base, rng.r(0.16, 0.30))
                                   : shadeT(base, rng.r(0.10, 0.22));
      ctx.globalAlpha = rng.r(0.48, 0.78);
      drawStroke(ctx, rng,
                 [[px - Math.cos(a) * L, py - Math.sin(a) * L],
                  [px, py],
                  [px + Math.cos(a) * L, py + Math.sin(a) * L]],
                 { color: drift(rng, tone, 0.04),
                   w: Math.max(7, dim * rng.r(0.04, 0.08)),
                   fade: rng.r(0.85, 1.35), grain: rng.r(0.4, 0.7),
                   press: rng.r(0.4, 0.8) });
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  // the contour as paint leaves it: no drawn line, but the pigment gathers
  // into a dark smudge along the shadow side and under the chin, while the
  // lit side is held by nothing but the value change against the wash
  function shadowEdge(ctx, rng, pts, ink, w, opt) {
    opt = opt || {};
    const P = resample(pts, true, 13);
    const n = P.length;
    let cx = 0, cy = 0;
    for (let i = 0; i < n; i++) { cx += P[i][0]; cy += P[i][1]; }
    cx /= n; cy /= n;
    const sh = P.map(p => {
      const ox = p[0] - cx, oy = p[1] - cy;
      const ol = Math.hypot(ox, oy) || 1;
      return (1 - (ox * LX + oy * LY) / ol) / 2;
    });
    const th = opt.th === undefined ? 0.60 : opt.th;
    let i = 0;
    while (i < n) {
      if (sh[i] > th + rng.r(-0.06, 0.06)) {
        let j = i;
        while (j - i < n * 0.5 && sh[j % n] > th - 0.08) j++;
        const seg = [];
        for (let k = i; k < j; k++) seg.push(P[k % n]);
        if (seg.length > 3 && rng.chance(opt.p === undefined ? 0.85 : opt.p)) {
          const s0 = Math.floor(seg.length * rng.r(0, 0.25));
          const s1 = seg.length - Math.floor(seg.length * rng.r(0, 0.25));
          if (s1 - s0 > 3) {
            const shm = sh[Math.floor((i + j) / 2) % n];
            ctx.globalAlpha = (0.30 + 0.50 * shm) * (opt.aMul || 1);
            ribbon(ctx, rng, seg.slice(s0, s1), ink, w * (0.55 + shm * 0.8),
                   { taper: 0.75, wob: 0.55, jit: 2.6,
                     load: rng.chance(0.5) ? rng.r(0.2, 0.42) : 0 });
            ctx.globalAlpha = 1;
          }
        }
        i = j + Math.max(2, Math.floor(n * rng.r(0.03, 0.10)));
      } else i++;
    }
  }

  // short broken chops riding the silhouette where it turns away from the
  // light: the brush hitting the edge of the form at the jaw and the ear
  function edgeChops(ctx, rng, pts, base, k) {
    const P = resample(pts, true, 24);
    const n = P.length;
    let cx = 0, cy = 0;
    for (let i = 0; i < n; i++) { cx += P[i][0]; cy += P[i][1]; }
    cx /= n; cy /= n;
    for (let i = 0; i < k; i++) {
      const j = Math.floor(rng.f() * n) % n;
      const p = P[j], q = P[(j + 1) % n];
      const ox = p[0] - cx, oy = p[1] - cy;
      const ol = Math.hypot(ox, oy) || 1;
      if ((1 - (ox * LX + oy * LY) / ol) / 2 < 0.42) continue;   // lit: skip
      let tx = q[0] - p[0], ty = q[1] - p[1];
      const tl = Math.hypot(tx, ty) || 1; tx /= tl; ty /= tl;
      const L = rng.r(9, 22);
      const off = rng.r(-6, 6);
      ctx.globalAlpha = rng.r(0.25, 0.55);
      ribbon(ctx, rng,
             [[p[0] - tx * L - ty * off, p[1] - ty * L + tx * off],
              [p[0] + tx * L - ty * off, p[1] + ty * L + tx * off]],
             drift(rng, sink(base, rng.r(0.05, 0.22)), 0.08),
             rng.r(6, 14), { taper: 0.7, jit: 2 });
      ctx.globalAlpha = 1;
    }
  }

  // dry-brush edge chatter: a few short LOADED flecks of the coat itself
  // riding the contour's tangent — opaque paint catching just past the
  // edge, the way a loaded brush overshoots, never a translucent flag
  function fray(ctx, rng, pts, base, k) {
    const P = resample(pts, true, 30);
    const n = P.length;
    for (let i = 0; i < (k || 4); i++) {
      const j = Math.floor(rng.f() * n) % n;
      const p = P[j], q = P[(j + 1) % n];
      let tx = q[0] - p[0], ty = q[1] - p[1];
      const tl = Math.hypot(tx, ty) || 1; tx /= tl; ty /= tl;
      const l = rng.r(7, 18);
      const off = rng.r(-4, 4);
      ctx.globalAlpha = rng.r(0.6, 0.88);
      ribbon(ctx, rng,
             [[p[0] - tx * l - ty * off, p[1] - ty * l + tx * off],
              [p[0] + tx * l - ty * off, p[1] + ty * l + tx * off]],
             drift(rng, base, 0.07), rng.r(6, 13), { taper: 0.75, jit: 1.6 });
      ctx.globalAlpha = 1;
    }
  }

  // ------------------------------------------------------- the fur pass
  // dozens of SHORT NARROW strokes following the form — arcs around a dome
  // center or pulls along one angle — two or three values off the base,
  // each with a dry lifted tip, some splitting into two or three bristle
  // streaks. This is the close-range weather of a coat: form, not noise.
  function furPass(...args) {
    if (RMH.depth || !RMH.furPass) return furPass_ORIG(...args);
    RMH.depth++;
    try { return RMH.furPass(furPass_ORIG, ...args); } finally { RMH.depth--; }
  }
  function furPass_ORIG(ctx, rng, pts, base, opt) {
    opt = opt || {};
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (const p of pts) {
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
    }
    const w = x1 - x0, h = y1 - y0;
    ctx.save();
    ctx.beginPath(); poly(ctx, pts, true); ctx.clip();
    // the mark scales to the FORM it describes: a small shape gets fewer,
    // relatively larger flecks, a big one longer pulls — never one absolute
    // streak size stamped across every subject
    const dim = Math.sqrt(w * h);
    const n = opt.n || Math.max(10, Math.min(52, Math.round(w * h / 10000)));
    const wid = opt.w || Math.max(5, Math.min(18, dim * 0.045));
    const fcx = (x0 + x1) / 2, fcy = (y0 + y1) / 2;
    const frad = Math.max(1, Math.hypot(w, h) / 2);
    for (let i = 0; i < n; i++) {
      const px = x0 + w * rng.r(0.04, 0.96);
      const py = y0 + h * rng.r(0.04, 0.96);
      // THE FUR GATHERS ON THE SHADOW SIDE (the verdict's exact ask):
      // where the form faces the light the coat stays a clean settled
      // pass — most strokes that land there are skipped, and the few
      // that stay only TINT — while the turned-away side carries the
      // weather. The smudge is reserved for the shadow now.
      const shF = (1 - ((px - fcx) * LX + (py - fcy) * LY) / frad) / 2;
      if (shF < 0.46 && rng.chance(0.60)) continue;
      const L = (opt.len || dim * 0.17) * rng.r(0.45, 1.75);
      let path;
      if (opt.center) {
        path = flowPath(rng, { flow: 'dome', center: opt.center,
                               cJit: opt.cJit || w * 0.10 }, px, py, L);
      } else {
        const a = (opt.ang === undefined ? rng.r(0, Math.PI) : opt.ang) +
                  rng.r(-0.22, 0.22);
        const bow = rng.r(-0.16, 0.16) * L;
        path = [[px - Math.cos(a) * L, py - Math.sin(a) * L],
                [px - Math.sin(a) * bow, py + Math.cos(a) * bow],
                [px + Math.cos(a) * L, py + Math.sin(a) * L]];
      }
      // alternate a lifted and a sunk register so the pass reads as fur
      // catching light, never one smeared value — and the steps are REAL
      // (two or three values off the coat), because a whisper of a step
      // averages back into the one-smear surface the verdict named
      const tone = rng.chance(shF < 0.50 ? 0.85 : 0.35)
        ? tintT(base, rng.r(0.12, 0.26))
        : shadeT(base, rng.r(0.10, 0.24));
      const col = drift(rng, tone, 0.05);
      const ww = wid * rng.r(0.6, 1.25);
      // THE MARK IS OPAQUE AND COUNTABLE: it lands with a visible stamp
      // (the press), runs committed, and its tail breaks dry — a stroke
      // the eye can follow at 760px, never a translucent averaging pass
      ctx.globalAlpha = rng.r(opt.a0 === undefined ? 0.50 : opt.a0,
                              opt.a1 === undefined ? 0.82 : opt.a1);
      if (rng.chance(0.26)) {
        // a share of the passes go through the physical dry brush whole:
        // bristle lanes, dropout, speckled ends
        dryStroke(ctx, rng, path, col, ww * rng.r(1.0, 1.3),
                  { fade: rng.r(0.7, 1.1), grain: rng.r(0.28, 0.46),
                    press: rng.r(0.35, 0.6) });
      } else {
        // the stamped landing: a blunt press where the brush first touched
        ctx.fillStyle = css(col);
        ctx.beginPath();
        ctx.ellipse(path[0][0], path[0][1], ww * rng.r(0.52, 0.72),
                    ww * rng.r(0.40, 0.55),
                    Math.atan2(path[1][1] - path[0][1],
                               path[1][0] - path[0][0]),
                    0, Math.PI * 2);
        ctx.fill();
        ribbon(ctx, rng, path, col, ww,
               { end: rng.r(0.8, 1.5), min: 0.3, wob: 0.5, jit: 1.1, step: 8,
                 load: rng.r(0.45, 0.75) });
      }
      if (rng.chance(0.14)) {
        // the brush splits: a thinner streak rides beside the stroke where
        // bristles separated
        const q = path[path.length - 1], p0 = path[0];
        let nx2 = -(q[1] - p0[1]), ny2 = q[0] - p0[0];
        const nl = Math.hypot(nx2, ny2) || 1;
        nx2 = nx2 / nl * ww * rng.r(0.8, 1.4);
        ny2 = ny2 / nl * ww * rng.r(0.8, 1.4);
        ctx.globalAlpha *= 0.7;
        ribbon(ctx, rng, path.map(p => [p[0] + nx2, p[1] + ny2]), col,
               ww * rng.r(0.32, 0.5),
               { end: rng.r(1.0, 1.8), min: 0.3, wob: 0.5, jit: 1.0, step: 8 });
      }
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  }

  // ------------------------------------------------------ the dry weather
  // After the opaque body settles: three to five STIFF drags of a
  // neighboring value pulled across the form with the physical dry brush,
  // each landing loaded and running to zero in speckled gaps, the settled
  // coat reading through the breakup — nara's white dog is one opaque
  // body plus a handful of drags, never a mosaic of soft slabs. The clip
  // is a hair expanded so a drag's last specks can land just past the
  // silhouette, the way a real overshooting brush does.
  function dryPass(...args) {
    if (RMH.depth || !RMH.dryPass) return dryPass_ORIG(...args);
    RMH.depth++;
    try { return RMH.dryPass(dryPass_ORIG, ...args); } finally { RMH.depth--; }
  }
  function dryPass_ORIG(ctx, rng, pts, base, opt) {
    opt = opt || {};
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9, cx = 0, cy = 0;
    for (const p of pts) {
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
      cx += p[0]; cy += p[1];
    }
    cx /= pts.length; cy /= pts.length;
    const w = x1 - x0, h = y1 - y0;
    const dim = Math.sqrt(w * h);
    ctx.save();
    ctx.beginPath();
    poly(ctx, scalePoly(pts, cx, cy, () => 1.028), true);
    ctx.clip();
    const k = opt.n || 3 + (rng.chance(0.55) ? 1 : 0) + (rng.chance(0.25) ? 1 : 0);
    const baseA = opt.ang === undefined ? rng.r(-0.35, 0.35) : opt.ang;
    const pale = lum(base) > 196, dark = lum(base) < 84;
    for (let i = 0; i < k; i++) {
      const a = baseA + rng.r(-0.16, 0.16);
      const L = Math.max(w, h) * rng.r(0.42, 0.80);
      // lifted drags ride the upper (lit) half, sunk ones the lower
      const liftMe = dark ? !rng.chance(0.2) : pale ? rng.chance(0.3) : i % 2 === 0;
      const px = x0 + w * rng.r(0.16, 0.84);
      const py = y0 + h * (liftMe ? rng.r(0.08, 0.52) : rng.r(0.42, 0.92));
      const bow = rng.r(-0.14, 0.10) * L;
      const tone = liftMe ? tintT(base, rng.r(0.15, 0.30))
                          : shadeT(base, rng.r(0.10, 0.22));
      ctx.globalAlpha = rng.r(0.55, 0.85) * (opt.aMul || 1);
      dryStroke(ctx, rng,
                [[px - Math.cos(a) * L, py - Math.sin(a) * L],
                 [px - Math.sin(a) * bow, py + Math.cos(a) * bow],
                 [px + Math.cos(a) * L, py + Math.sin(a) * L]],
                drift(rng, tone, 0.04),
                opt.w || Math.max(9, Math.min(26, dim * rng.r(0.05, 0.075))),
                { fade: rng.r(0.9, 1.4), grain: rng.r(0.45, 0.7),
                  press: rng.r(0.4, 0.8) });
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  // ---------------------------------------------- the coat's own weather
  // THE DOG IS PAINTED WITH THE GROUND'S BRUSH: the same chopped-slab
  // language the grounds speak — a committed landing pull, dry siblings,
  // a pooled rim — laid INSIDE the coat silhouette in tones two or three
  // values off the coat (hue-neighbors when the coat carries chroma),
  // then a light dry pass dragged along the silhouette's lit edge,
  // breaking into speckle there, so the fill and the contour end in the
  // same hand instead of a flat wash meeting a drawn line
  function coatWeather(...args) {
    if (RMH.depth || !RMH.coatWeather) return coatWeather_ORIG(...args);
    RMH.depth++;
    try { return RMH.coatWeather(coatWeather_ORIG, ...args); } finally { RMH.depth--; }
  }
  function coatWeather_ORIG(ctx, rng, pts, base, opt) {
    opt = opt || {};
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9, cx = 0, cy = 0;
    for (const p of pts) {
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
      cx += p[0]; cy += p[1];
    }
    cx /= pts.length; cy /= pts.length;
    const w = x1 - x0, h = y1 - y0;
    const dim = Math.sqrt(w * h);
    const baseA = opt.ang === undefined ? rng.r(-0.3, 0.3) : opt.ang;
    ctx.save();
    ctx.beginPath();
    poly(ctx, scalePoly(pts, cx, cy, () => 1.015), true);
    ctx.clip();
    // 2-4 chopped slabs: adjacent hues when the coat has chroma to lean
    // on, pure value registers when it is near-neutral (hue-shifting a
    // near-grey lands arbitrary green — the milk-coat dirt trap)
    const hasHue = hueOf(base)[1] > 0.11;
    const nS = opt.nSlab === undefined
      ? 2 + (rng.chance(0.6) ? 1 : 0) + (rng.chance(0.3) ? 1 : 0)
      : opt.nSlab;
    for (let i = 0; i < nS; i++) {
      let tone;
      if (hasHue && rng.chance(0.55)) {
        tone = hueShiftC(base, rng.r(8, 20) * (rng.chance(0.5) ? 1 : -1));
        if (Math.abs(lum(tone) - lum(base)) > 24) tone = mix(tone, base, 0.5);
        tone = rng.chance(0.5) ? lift(tone, rng.r(0.05, 0.13))
                               : sink(tone, rng.r(0.04, 0.11));
      } else {
        tone = rng.chance(0.5) ? lift(base, rng.r(0.10, 0.20))
                               : sink(base, rng.r(0.08, 0.18));
      }
      const sx = x0 + w * rng.r(0.14, 0.86);
      const sy = y0 + h * (opt.low ? rng.r(0.30, 0.88) : rng.r(0.12, 0.88));
      scrubPatch(ctx, rng, sx, sy, dim * rng.r(0.22, 0.38),
                 dim * rng.r(0.14, 0.24), baseA + rng.r(-0.35, 0.35), tone,
                 rng.r(0.28, 0.44) * (opt.aMul || 1), rng.chance(0.62));
    }
    ctx.restore();
    if (opt.edge === false) return;
    // the dry light pass riding the lit edge: it starts a breath inside
    // the silhouette, runs along the contour's tangent, and its charge
    // breaks into speckle — the expanded clip lets the last flecks land
    // just past the edge the way an overshooting dry brush does
    const P = resample(pts, true, 26);
    const n = P.length;
    ctx.save();
    ctx.beginPath();
    poly(ctx, scalePoly(pts, cx, cy, () => 1.035), true);
    ctx.clip();
    const kE = 2 + (rng.chance(0.6) ? 1 : 0);
    let laid = 0, tries = 0;
    while (laid < kE && tries < 14) {
      tries++;
      const j = Math.floor(rng.f() * n) % n;
      const p = P[j], q = P[(j + 2) % n];
      const ox = p[0] - cx, oy = p[1] - cy;
      const ol = Math.hypot(ox, oy) || 1;
      if ((1 - (ox * LX + oy * LY) / ol) / 2 > 0.60) continue;   // lit only
      let tx = q[0] - p[0], ty = q[1] - p[1];
      const tl = Math.hypot(tx, ty) || 1; tx /= tl; ty /= tl;
      const inr = dim * rng.r(0.035, 0.08);
      const L2 = dim * rng.r(0.20, 0.40);
      ctx.globalAlpha = rng.r(0.50, 0.80) * (opt.aMul || 1);
      dryStroke(ctx, rng,
                [[p[0] - tx * L2 - ox / ol * inr, p[1] - ty * L2 - oy / ol * inr],
                 [p[0] - ox / ol * inr * 0.55, p[1] - oy / ol * inr * 0.55],
                 [p[0] + tx * L2 - ox / ol * inr, p[1] + ty * L2 - oy / ol * inr]],
                drift(rng, lift(base, rng.r(0.16, 0.28)), 0.04),
                Math.max(8, dim * rng.r(0.035, 0.055)),
                { fade: rng.r(0.8, 1.2), grain: rng.r(0.35, 0.55),
                  press: rng.r(0.4, 0.7) });
      laid++;
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  // ------------------------------------------------------- the ink engine
  // ONE rebuilt brush renders every drawn mark. The caller owns the
  // DRAWING — a spine and a width at every point (the pressure); this
  // renders the MATERIAL: a bristle bundle whose edges are the sum of
  // bristle ends, a wet second touch where the brush pressed hardest,
  // lifted hairline rails inside the band (the close-range proof of
  // bristles), and a pooled rim where the wet pigment settled along one
  // edge. Nothing here is a uniform alpha rectangle.
  function inkDraw(...args) {
    if (RMH.depth || !RMH.inkDraw) return inkDraw_ORIG(...args);
    RMH.depth++;
    try { return RMH.inkDraw(inkDraw_ORIG, ...args); } finally { RMH.depth--; }
  }
  function inkDraw_ORIG(ctx, rng, spine, W, ink, opt) {
    opt = opt || {};
    const n = spine.length;
    if (n < 3) return;
    const gA = ctx.globalAlpha;
    const aM = opt.aMul === undefined ? 1 : opt.aMul;
    let wMax = 0, iMax = 0;
    for (let i = 0; i < n; i++) if (W[i] > wMax) { wMax = W[i]; iMax = i; }
    const NX = [], NY = [], Lp = [], Rp = [];
    // the roughness of the edge BREATHES along the mark: a slow envelope
    // decides where the line runs calm (wet, smooth-edged) and where it
    // furs out dry — the constant tuft-frequency serration was a crutch
    // the verdict named. opt.chat scales the whole envelope per call, so
    // a feature line can run nearly clean while a jaw stretch furs.
    const chAmp = opt.chat === undefined ? 0.20 : opt.chat;
    const env = smoothArr(smoothArr(
      Array.from({ length: n }, () => rng.f()), 3, false), 2, false);
    for (let i = 0; i < n; i++) {
      const ip = Math.max(0, i - 1), iq = Math.min(n - 1, i + 1);
      const dx = spine[iq][0] - spine[ip][0], dy = spine[iq][1] - spine[ip][1];
      const d = Math.hypot(dx, dy) || 1;
      NX.push(-dy / d); NY.push(dx / d);
      // per-point bristle chatter — PER SIDE, so the two edges of the
      // mark disagree the way bristle ends do; never a geometric band
      const wb = Math.max(0.5, W[i]) / 2;
      const ca = chAmp * (0.25 + 1.5 * env[i] * env[i]);
      const chL = 1 + (rng.f() * 2 - 1) * ca;
      const chR = 1 + (rng.f() * 2 - 1) * ca;
      Lp.push([spine[i][0] + NX[i] * wb * chL, spine[i][1] + NY[i] * wb * chL]);
      Rp.push([spine[i][0] - NX[i] * wb * chR, spine[i][1] - NY[i] * wb * chR]);
    }
    // 1. the core: near-opaque, pigment drifting a hair as it drags
    ctx.globalAlpha = Math.min(1, 0.96 * aM * gA);
    ctx.fillStyle = css(drift(rng, ink, 0.03));
    ctx.beginPath();
    poly(ctx, Lp.concat(Rp.slice().reverse()), true);
    ctx.fill();
    // 2. the wet second touch: where the brush pressed hardest a shorter
    // sunk pass rides inside the band — the mark reads twice-loaded
    if (wMax > 4 && n > 6) {
      const h0 = Math.max(0, iMax - Math.floor(n * rng.r(0.16, 0.30)));
      const h1 = Math.min(n - 1, iMax + Math.floor(n * rng.r(0.16, 0.30)));
      if (h1 - h0 > 2) {
        const A2 = [], B2 = [];
        for (let i = h0; i <= h1; i++) {
          const k = 0.62 * Math.sin(Math.PI * (i - h0) / (h1 - h0));
          const wi = W[i] * k / 2;
          A2.push([spine[i][0] + NX[i] * wi, spine[i][1] + NY[i] * wi]);
          B2.push([spine[i][0] - NX[i] * wi, spine[i][1] - NY[i] * wi]);
        }
        ctx.globalAlpha = Math.min(1, rng.r(0.30, 0.5) * aM * gA);
        ctx.fillStyle = css(sink(ink, rng.r(0.05, 0.12)));
        ctx.beginPath();
        poly(ctx, A2.concat(B2.reverse()), true);
        ctx.fill();
      }
    }
    // 3. bristle rails: one to three lifted hairlines INSIDE the band
    // where individual bristles starved — zooming into any heavy stretch
    // of line finds its bristles
    if (wMax > 6) {
      const kR = 1 + (rng.chance(0.6) ? 1 : 0) + (wMax > 12 ? 1 : 0);
      for (let j = 0; j < kR; j++) {
        const u = rng.r(-0.62, 0.62);
        const r0 = Math.floor(n * rng.r(0.05, 0.4));
        const r1 = Math.min(n - 1, r0 + Math.floor(n * rng.r(0.25, 0.55)));
        if (r1 - r0 < 3) continue;
        const rail = [];
        for (let i = r0; i <= r1; i++)
          rail.push([spine[i][0] + NX[i] * W[i] * u / 2,
                     spine[i][1] + NY[i] * W[i] * u / 2]);
        ctx.globalAlpha = rng.r(0.28, 0.44) * aM * gA;
        ribbon(ctx, rng, rail, lift(ink, rng.r(0.16, 0.30)),
               Math.max(0.9, wMax * rng.r(0.06, 0.12)),
               { taper: 0.5, wob: 0.5, jit: 0.5, step: 9,
                 end: rng.r(0.8, 1.3), min: 0.3 });
      }
    }
    // 4. sometimes the wet pigment settles along one edge near the
    // heaviest press: a darker pooled rim
    if (wMax > 8 && rng.chance(0.4)) {
      const sgn = rng.chance(0.5) ? 1 : -1;
      const r0 = Math.max(0, iMax - Math.floor(n * 0.2));
      const r1 = Math.min(n - 1, iMax + Math.floor(n * 0.2));
      if (r1 - r0 > 2) {
        const rim = [];
        for (let i = r0; i <= r1; i++)
          rim.push([spine[i][0] + NX[i] * W[i] * 0.42 * sgn,
                    spine[i][1] + NY[i] * W[i] * 0.42 * sgn]);
        ctx.globalAlpha = rng.r(0.25, 0.4) * aM * gA;
        ribbon(ctx, rng, rim, sink(ink, rng.r(0.10, 0.18)),
               Math.max(1, wMax * rng.r(0.10, 0.16)),
               { taper: 0.6, wob: 0.5, jit: 0.6, step: 9, end: 1.0, min: 0.3 });
      }
    }
    ctx.globalAlpha = gA;
  }

  // ------------------------------------------------------------ the line
  // the contour comes back: thick, confident, near-black, laid as runs of
  // the same weighted ribbon as everything else. Pressure varies with the
  // light (heavy under the jaw and the shadow cheek, lighter on the lit
  // crown), corners happen where two runs MEET — small overshoots, tiny
  // gaps where the brush lifted — and fast curves go dry.
  //
  // the line along an OPEN path — the interior drawing tool: ear
  // folds, the jaw under the muzzle, the head-into-shoulders seam, the
  // near foreleg, prop edges. ONE continuous mark with its own pressure
  // design: loaded at one end or through the middle, lifting to a
  // hairline at the other, running dry past the lift.
  function inkPath(ctx, rng, pts, ink, w, opt) {
    opt = opt || {};
    const P0 = resample(pts, false, 10);
    const n = P0.length;
    if (n < 4) return;
    const P = P0.map(p => [p[0] + rng.r(-1.2, 1.2), p[1] + rng.r(-1.2, 1.2)]);
    const mode = opt.press || rng.pick(['start', 'start', 'mid', 'end']);
    const nz = smoothArr(Array.from({ length: n }, () => rng.f() * 2 - 1),
                         2, false);
    const W = [];
    for (let i = 0; i < n; i++) {
      const t = i / (n - 1);
      const pr = mode === 'start' ? 1 - 0.74 * Math.pow(t, 1.15)
               : mode === 'end'   ? 0.26 + 0.74 * Math.pow(t, 1.15)
               : 0.34 + 0.66 * Math.sin(Math.PI *
                                        Math.min(0.98, Math.max(0.02, t)));
      W.push(Math.max(w * 0.15, w * pr * (1 + nz[i] * 0.24)));
    }
    inkDraw(ctx, rng, P, W, ink,
            { aMul: opt.aMul === undefined ? 0.95 : opt.aMul,
              chat: opt.chat === undefined ? 0.12 : opt.chat });
    // the lifted end runs dry: a stamp-train tail carries a few specks on
    if (rng.chance(0.55)) {
      const tail = mode === 'start' ? [P[n - 1], P[n - 2]] : [P[0], P[1]];
      const dl = Math.hypot(tail[0][0] - tail[1][0],
                            tail[0][1] - tail[1][1]) || 1;
      const tx = (tail[0][0] - tail[1][0]) / dl,
            ty = (tail[0][1] - tail[1][1]) / dl;
      const ov = rng.r(8, 22);
      ctx.globalAlpha = rng.r(0.4, 0.65) *
                        (opt.aMul === undefined ? 1 : opt.aMul);
      dryStroke(ctx, rng,
                [[tail[0][0], tail[0][1]],
                 [tail[0][0] + tx * ov, tail[0][1] + ty * ov]],
                ink, Math.max(2, w * 0.3),
                { fade: rng.r(1.0, 1.5), grain: 0.7, press: 0.6 });
      ctx.globalAlpha = 1;
    }
  }

  // the drawn ring: jonpick1's eye — the same fat brush that closes the
  // jaw circles the eye, pressing hard over the top and outer turn,
  // thinning to a light touch below, lifting for a breath at one point
  // so the ring stays a drawn thing and never a die-cut annulus
  function inkRing(ctx, rng, cx, cy, rx, ry, w, ink, opt) {
    opt = opt || {};
    const a0 = rng.r(0, Math.PI * 2);
    const gap = rng.chance(0.85) ? rng.r(0.16, 0.55) : 0;
    // the ellipse LEANS off its axes — no ring sits compass-straight
    const lean = rng.r(-0.22, 0.22);
    const lc = Math.cos(lean), ls = Math.sin(lean);
    const n = 30;
    const P = [], W = [];
    // heaviest around the top of the ring (the brow side), lightest at
    // the lower-inner turn — the lid presses, the cheek releases
    const hv = opt.heavyAt === undefined ? -Math.PI / 2 : opt.heavyAt;
    // the hand's wobble is SLOW: the ring bows in and out a few times
    // over its whole run. Per-point jitter smooths back into a compass —
    // this low-frequency radius drift is what reads as drawn.
    const wobA = rng.r(0.045, 0.09);
    const rz = smoothArr(Array.from({ length: n + 1 },
                                    () => rng.f() * 2 - 1), 3, false);
    const nz = smoothArr(Array.from({ length: n + 1 },
                                    () => rng.f() * 2 - 1), 2, false);
    const at = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const a = a0 + gap / 2 + t * (Math.PI * 2 - gap);
      at.push(a);
      const rad = 1 + rz[i] * wobA;
      const px0 = Math.cos(a) * rx * rad, py0 = Math.sin(a) * ry * rad;
      P.push([cx + px0 * lc - py0 * ls, cy + px0 * ls + py0 * lc]);
      let dd = Math.abs(a - hv) % (Math.PI * 2);
      dd = Math.min(dd, Math.PI * 2 - dd);
      // a true swell-and-release: the press runs a full 3x over the turn
      const press = 0.40 + 0.86 * Math.exp(-(dd * dd) / 1.3);
      let ramp = 1;
      if (i === 0) ramp = 0.55; else if (i === 1) ramp = 0.8;
      if (t > 0.88) ramp *= Math.max(0.35, 1 - (t - 0.88) * 4.5);
      W.push(Math.max(w * 0.26, w * press * (1 + nz[i] * 0.34) * ramp));
    }
    // the corner overshoot: the brush runs past where the ring lifts off
    if (gap && rng.chance(0.7)) {
      const m = P.length - 1;
      const dxo = P[m][0] - P[m - 1][0], dyo = P[m][1] - P[m - 1][1];
      const dl = Math.max(1, Math.hypot(dxo, dyo));
      const ov = rng.r(6, Math.max(8, rx * 0.34));
      P.push([P[m][0] + dxo / dl * ov * 0.6, P[m][1] + dyo / dl * ov * 0.6]);
      P.push([P[m][0] + dxo / dl * ov, P[m][1] + dyo / dl * ov]);
      W.push(w * 0.34, w * 0.18);
    }
    inkDraw(ctx, rng, P, W, ink,
            { aMul: opt.aMul === undefined ? 0.93 : opt.aMul,
              chat: opt.chat === undefined ? 0.10 : opt.chat });
    // the re-touch: a second short pass where the hand pressed the ring
    // again — slightly off-register, jonpick1's re-worked corner
    if (rng.chance(0.55)) {
      const span = rng.r(0.6, 1.3);
      const b0 = hv + rng.r(-0.7, 0.2);
      const off = rng.r(-0.06, 0.015);
      const P2 = [], W2 = [];
      for (let i = 0; i <= 7; i++) {
        const a = b0 + span * i / 7;
        const rad = 1 + off + rz[Math.min(n, i * 4)] * wobA * 0.7;
        const px0 = Math.cos(a) * rx * rad, py0 = Math.sin(a) * ry * rad;
        P2.push([cx + px0 * lc - py0 * ls, cy + px0 * ls + py0 * lc]);
        const tt = i / 7;
        W2.push(w * (0.5 + 0.6 * Math.sin(Math.PI * Math.pow(tt, 0.8))));
      }
      inkDraw(ctx, rng, P2, W2, ink,
              { aMul: (opt.aMul === undefined ? 0.93 : opt.aMul) * 0.72,
                chat: opt.chat === undefined ? 0.10 : opt.chat });
    }
  }

  // -------------------------------------------------- the one journey
  // ROUND 90: the contour stops being per-form. The dog's TRUE outer
  // silhouette — skull, ears, shoulders, chest, standing body, legs — is
  // computed as the union of every painted mass (a coarse deterministic
  // raster + marching squares), and ONE brushed journey of ink closes it:
  // pressure from the HAND (anchor swells at the chin, the ear roots, the
  // shoulder joins; slow breathing everywhere else), never from the light;
  // a still-visible hairline over the crown; overshoots where the path
  // turns a corner; nothing where the figure leaves the frame.
  function pointInPoly(x, y, P) {
    let inside = false;
    for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
      const yi = P[i][1], yj = P[j][1];
      if ((yi > y) !== (yj > y) &&
          x < (P[j][0] - P[i][0]) * (y - yi) / (yj - yi) + P[i][0])
        inside = !inside;
    }
    return inside;
  }

  // union of polygons -> the single largest closed boundary loop.
  // clip = [x0, y0, x1, y1]: the visible frame (figure coords) plus a
  // margin; masses running past it are cut and the cut edge is later
  // marked as never-drawn (the brush does not paint the frame's border).
  function unionTrace(polys, step, clip) {
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    polys.forEach(P => P.forEach(p => {
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
    }));
    x0 = Math.max(x0 - step * 3, clip[0]);
    y0 = Math.max(y0 - step * 3, clip[1]);
    x1 = Math.min(x1 + step * 3, clip[2]);
    y1 = Math.min(y1 + step * 3, clip[3]);
    if (x1 - x0 < step * 4 || y1 - y0 < step * 4) return null;
    const nx = Math.ceil((x1 - x0) / step) + 2;
    const ny = Math.ceil((y1 - y0) / step) + 2;
    const ins = new Uint8Array(nx * ny);
    for (let j = 1; j < ny - 1; j++) {
      const py = y0 + j * step;
      for (let i = 1; i < nx - 1; i++) {
        const px = x0 + i * step;
        for (let k = 0; k < polys.length; k++) {
          if (pointInPoly(px, py, polys[k])) { ins[j * nx + i] = 1; break; }
        }
      }
    }
    // marching squares over cells; each boundary cell yields segments
    // between edge midpoints, chained into loops
    const segs = new Map();          // point key -> [neighbor pts]
    const key = p => (Math.round(p[0] * 2) + ',' + Math.round(p[1] * 2));
    const link = (p, q) => {
      const kp = key(p), kq = key(q);
      let ap = segs.get(kp); if (!ap) { ap = { p: p, n: [] }; segs.set(kp, ap); }
      let aq = segs.get(kq); if (!aq) { aq = { p: q, n: [] }; segs.set(kq, aq); }
      ap.n.push(kq); aq.n.push(kp);
    };
    for (let j = 0; j < ny - 1; j++) {
      for (let i = 0; i < nx - 1; i++) {
        const a = ins[j * nx + i], b = ins[j * nx + i + 1];
        const c = ins[(j + 1) * nx + i + 1], d = ins[(j + 1) * nx + i];
        const code = a * 8 + b * 4 + c * 2 + d * 1;
        if (code === 0 || code === 15) continue;
        const gx = x0 + i * step, gy = y0 + j * step;
        const T = [gx + step / 2, gy], R2 = [gx + step, gy + step / 2];
        const B = [gx + step / 2, gy + step], L2 = [gx, gy + step / 2];
        switch (code) {
          case 1: link(L2, B); break;
          case 2: link(B, R2); break;
          case 3: link(L2, R2); break;
          case 4: link(T, R2); break;
          case 5: link(T, L2); link(B, R2); break;
          case 6: link(T, B); break;
          case 7: link(T, L2); break;
          case 8: link(T, L2); break;
          case 9: link(T, B); break;
          case 10: link(T, R2); link(L2, B); break;
          case 11: link(T, R2); break;
          case 12: link(L2, R2); break;
          case 13: link(B, R2); break;
          case 14: link(L2, B); break;
        }
      }
    }
    // walk loops; keep the longest
    const used = new Set();
    let best = null;
    for (const [k0, node0] of segs) {
      if (used.has(k0)) continue;
      const loop = [];
      let prevK = null, curK = k0;
      let guard = segs.size * 2 + 8;
      while (guard-- > 0) {
        const node = segs.get(curK);
        if (!node) break;
        loop.push(node.p);
        used.add(curK);
        let nextK = null;
        for (let t = 0; t < node.n.length; t++) {
          if (node.n[t] !== prevK && !used.has(node.n[t])) { nextK = node.n[t]; break; }
        }
        if (nextK === null) {
          // closing back to the start ends the loop
          if (node.n.indexOf(k0) >= 0 && loop.length > 3) nextK = k0;
          if (nextK === k0 || nextK === null) break;
        }
        if (nextK === k0) break;
        prevK = curK; curK = nextK;
      }
      if (loop.length > 12 && (!best || loop.length > best.length)) best = loop;
    }
    if (!best || best.length < 16) return null;
    return smoothPts(resample(best, true, 9), true, 2);
  }

  // ONE brushed journey around a closed silhouette. Width comes from the
  // hand: a slow breathing pressure plus anchor swells where two forms
  // meet; the light contributes only a whisper of width and the dryness
  // of the mark. The line thins over the lit crown but NEVER dies; it
  // stops only where the figure leaves the picture.
  function inkJourney(ctx, rng, pts, opt) {
    opt = opt || {};
    const P = resample(pts, true, 9);
    const n = P.length;
    if (n < 10) return;
    const w = opt.w || 14;
    const wMax = opt.wMax || w * 3.8;
    const clip = opt.clip;
    const inset = (opt.step || 6) * 1.8;
    const skip = P.map(p => clip
      ? (p[0] < clip[0] + inset || p[0] > clip[2] - inset ||
         p[1] < clip[1] + inset || p[1] > clip[3] - inset)
      : false);
    let cx = 0, cy = 0;
    for (let i = 0; i < n; i++) { cx += P[i][0]; cy += P[i][1]; }
    cx /= n; cy /= n;
    let sh = P.map(p => {
      const ox = p[0] - cx, oy = p[1] - cy;
      const ol = Math.hypot(ox, oy) || 1;
      return (1 - (ox * LX + oy * LY) / ol) / 2;
    });
    sh = smoothArr(sh, 3, true);
    // the hand's breathing is a long swell-and-release, not a flutter:
    // very low-frequency noise so a single pull visibly presses and lifts
    const nz = smoothArr(smoothArr(
      Array.from({ length: n }, () => rng.f() * 2 - 1), 5, true), 4, true);
    const wob = smoothArr(Array.from({ length: n }, () => rng.f() * 2 - 1), 2, true);
    const anc = opt.anchors || [];
    const WA = [];
    for (let i = 0; i < n; i++) {
      let m = 1;
      for (let s = 0; s < anc.length; s++) {
        const a = anc[s];
        const dx = P[i][0] - a[0], dy = P[i][1] - a[1];
        m += (a[2] - 1) * Math.exp(-(dx * dx + dy * dy) / (2 * a[3] * a[3]));
      }
      // the hand: a real swell-and-release. Width must swing 3-4x along
      // a single run or it reads as a constant hairline at thumbnail.
      let wi = w * m * (1 + nz[i] * 0.38) * (0.58 + 0.62 * sh[i]);
      WA.push(Math.min(wMax, Math.max(w * 0.36, wi)));
    }
    // corners: local maxima of curvature — where the path truly turns,
    // the brush lifts and comes back (overshoot, tiny gap, re-touch)
    const turn = [];
    for (let i = 0; i < n; i++) {
      const a1 = P[(i - 3 + n) % n], a2 = P[(i + 3) % n];
      const t1 = Math.atan2(P[i][1] - a1[1], P[i][0] - a1[0]);
      const t2 = Math.atan2(a2[1] - P[i][1], a2[0] - P[i][0]);
      let dd = t2 - t1;
      while (dd > Math.PI) dd -= 2 * Math.PI;
      while (dd < -Math.PI) dd += 2 * Math.PI;
      turn.push(Math.abs(dd));
    }
    const cuts = [];
    for (let i = 0; i < n; i++) {
      if (turn[i] < 0.30) continue;
      const pr3 = turn[(i - 3 + n) % n], nx3 = turn[(i + 3) % n];
      if (turn[i] >= pr3 && turn[i] >= nx3) {
        if (cuts.length === 0 ||
            (i - cuts[cuts.length - 1] >= 7 && (n - i + cuts[0]) >= 7))
          cuts.push(i);
      }
    }
    // collect drawable arcs (split on skip stretches)
    const arcs = [];
    let s0 = 0;
    while (s0 < n && !skip[s0]) s0++;
    if (s0 === n) {
      // fully inside the frame: one closed journey, opened at a corner
      const st = cuts.length ? cuts[0] : 0;
      arcs.push([st, st + n]);
    } else {
      let k = s0, steps = 0;
      while (steps < n) {
        while (steps < n && skip[k % n]) { k++; steps++; }
        if (steps >= n) break;
        const r0 = k;
        while (steps < n && !skip[k % n]) { k++; steps++; }
        if (k - r0 >= 5) arcs.push([r0, k]);
      }
    }
    const wan = opt.wander === undefined ? 2.4 : opt.wander;
    const aM = opt.aMul === undefined ? 0.95 : opt.aMul;
    // radial bias: negative rides the line INSIDE the form — a dark line
    // on a pale form against a near-black ground must land on the form
    // or it vanishes into the night
    const bias = opt.bias || 0;
    arcs.forEach(([r0, r1]) => {
      // cut the arc into passes at the corners inside it, plus a breath
      // cut on any very long run
      const pass = [];
      let a0 = r0;
      for (let k = r0 + 6; k < r1 - 6; k++) {
        const gi = k % n;
        // corners cut the line; long runs breathe; and on LIT stretches
        // the brush truly lifts — the line breaks and skips before the
        // hand comes back down (the jonpick1 crown, the fast dry curve)
        const isCut = cuts.indexOf(gi) >= 0 ||
                      (!opt.calm && k - a0 > 48 && rng.chance(0.10)) ||
                      (!opt.calm && k - a0 > 18 && sh[gi] < 0.42 && rng.chance(0.18));
        if (isCut && k - a0 >= 6) {
          pass.push([a0, k]);
          // a lift leaves a REAL gap of bare ground — two or three
          // overlapping segments per shape, never one closed hoop
          a0 = opt.calm ? k - 3
            : (sh[gi] < 0.44 && rng.chance(0.78))
            ? k + 5 + Math.floor(rng.f() * 8)
            : k - (rng.chance(0.45) ? 3 : -2);
        }
      }
      if (r1 - a0 >= 5) pass.push([a0, r1]);
      pass.forEach(([b0, b1], pi) => {
        const m = (b0 + b1) >> 1;
        const shm = sh[((m % n) + n) % n];
        const spine = [], W = [];
        const len = b1 - b0;
        for (let k = b0; k <= b1; k++) {
          const gi = ((k % n) + n) % n;
          const p = P[gi];
          const ox = p[0] - cx, oy = p[1] - cy;
          const ol = Math.hypot(ox, oy) || 1;
          const wo = wob[gi] * wan + bias;
          spine.push([p[0] + ox / ol * wo + rng.r(-1.1, 1.1),
                      p[1] + oy / ol * wo + rng.r(-1.1, 1.1)]);
          const t = (k - b0) / len;
          // PRESS, DRAG, LIFT: each segment swells ~2.5x at the belly
          const belly = 0.48 + 0.52 * Math.sin(Math.PI * Math.min(0.98, Math.max(0.02, t)));
          let ramp = belly;
          if (k - b0 === 0) ramp *= 0.70;
          else if (k - b0 === 1) ramp *= 0.86;
          if (t > 0.82) ramp *= Math.max(0.30, 1 - (t - 0.82) * 4.0);
          W.push(Math.max(w * 0.32, WA[gi] * ramp));
        }
        // overshoot: the spine itself runs a few px past the corner
        if (!opt.calm && spine.length > 3 && rng.chance(0.7)) {
          const e = spine[spine.length - 1], e2 = spine[spine.length - 2];
          const dl = Math.hypot(e[0] - e2[0], e[1] - e2[1]) || 1;
          const tx = (e[0] - e2[0]) / dl, ty = (e[1] - e2[1]) / dl;
          const ov = rng.r(6, 15);
          spine.push([e[0] + tx * ov * 0.6, e[1] + ty * ov * 0.6]);
          spine.push([e[0] + tx * ov, e[1] + ty * ov]);
          const wl = W[W.length - 1];
          W.push(wl * 0.55); W.push(Math.max(1.4, wl * 0.26));
        }
        inkDraw(ctx, rng, spine, W, opt.ink,
                { aMul: aM * (0.93 + 0.07 * shm), chat: opt.chat });
        // lit stretches go dry: a stamp-train tail off the lifted end
        if (!opt.calm && rng.chance(shm < 0.42 ? 0.7 : 0.4)) {
          const e = spine[spine.length - 1], e2 = spine[spine.length - 3] ||
                    spine[spine.length - 2];
          const dl = Math.hypot(e[0] - e2[0], e[1] - e2[1]) || 1;
          const tx = (e[0] - e2[0]) / dl, ty = (e[1] - e2[1]) / dl;
          const ov = rng.r(9, 24);
          ctx.globalAlpha = Math.min(1, rng.r(0.5, 0.8) * aM);
          dryStroke(ctx, rng,
                    [[e[0], e[1]], [e[0] + tx * ov, e[1] + ty * ov]],
                    opt.ink, Math.max(2.2, W[W.length - 1] * 0.9),
                    { fade: rng.r(1.0, 1.5), grain: 0.65, press: 0.7 });
          ctx.globalAlpha = 1;
        }
      });
    });
  }

  // ======================================================================
  // ROUND 123 BET — THE SUPPORT ENGINE. THE GROUND IS A SURFACE.
  // jonpick11's panel is not striped. It is a wall of paint laid down and
  // then WORN, and what the eye reads in it is granular abrasion at three
  // scales at once: broad continents where the rag took the top coat off
  // entirely, a medium blotch under that, and a fine bitten tooth, with
  // the value drifting so no two corners agree and the bare board coming
  // back at the hardest-used points. Ribbons cannot make that surface.
  // Every ground this collection has ever shipped was long horizontal
  // pulls, which is exactly the "one horizontal scoured sweep" the
  // verdict named running through all three languages at once.
  // So the support is COMPUTED now: a stack of geological coats over a
  // bare board, and one scalar WEAR field per panel deciding at every
  // point how many coats survived there. The three languages become
  // three parameter sets of one engine — heavy wear and five coats for
  // the scoured wash, near-total wear and two for the crayon board,
  // almost no wear and banded coats for flat daylight — which is what
  // finally makes them three different SURFACES instead of three stripe
  // densities. Brushwork still goes on top of it; it is a support, not
  // a picture.
  // ======================================================================

  // a seeded value lattice, smooth-sampled. gx and gy are independent, so
  // a field can be stretched: gx=2,gy=22 gives features that run the
  // width of the canvas — the rag's long sweeps living inside the same
  // field as the granular bite.
  function lat(rng, gx, gy) {
    const w = gx + 1, a = new Float32Array(w * (gy + 1));
    for (let i = 0; i < a.length; i++) a[i] = rng.f();
    return { a, gx, gy, w };
  }
  function latAt(L, u, v) {
    let x = u * L.gx, y = v * L.gy;
    if (!(x > 0)) x = 0; else if (x > L.gx) x = L.gx;
    if (!(y > 0)) y = 0; else if (y > L.gy) y = L.gy;
    let x0 = x | 0; if (x0 >= L.gx) x0 = L.gx - 1;
    let y0 = y | 0; if (y0 >= L.gy) y0 = L.gy - 1;
    let fx = x - x0, fy = y - y0;
    fx = fx * fx * (3 - 2 * fx); fy = fy * fy * (3 - 2 * fy);
    const i0 = y0 * L.w + x0, i1 = i0 + L.w, A = L.a;
    const p0 = A[i0] + (A[i0 + 1] - A[i0]) * fx;
    const p1 = A[i1] + (A[i1 + 1] - A[i1]) * fx;
    return p0 + (p1 - p0) * fy;
  }
  function fbm(rng, gx, gy, oct, gain) {
    const ls = []; let amp = 1, tot = 0, k = 1;
    for (let o = 0; o < oct; o++) {
      ls.push([lat(rng, Math.max(1, Math.round(gx * k)),
                        Math.max(1, Math.round(gy * k))), amp]);
      tot += amp; amp *= gain; k *= 2.17;
    }
    return { ls, inv: 1 / tot };
  }
  function fbmAt(F, u, v) {
    let s = 0;
    for (let i = 0; i < F.ls.length; i++) s += latAt(F.ls[i][0], u, v) * F.ls[i][1];
    return s * F.inv;
  }
  // the pixel-scale tooth of the board — the grain the rag bit into
  function hsh(x, y, s) {
    let h = (Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ s) | 0;
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    return ((h ^ (h >>> 16)) >>> 0) * 2.3283064365386963e-10;
  }

  // coats are given BOTTOM FIRST: {c, thr, hard, jit, dr, y0, y1, wob}.
  // thr is the wear at which that coat finally gives way, hard is how
  // abruptly its edge breaks (low = soft continents, high = granular
  // speckle), jit decorrelates one coat's boundary from the next so the
  // strata are not nested contours, dr is how far the coat's own value
  // drifts across the panel, y0/y1 confine it to a band with a
  // hand-wobbled edge.
  function paintSupport(ctx, rng, board, coats, opt) {
    const cv = ctx.canvas, W = cv.width, H = cv.height, o = opt || {};
    const QW = Math.max(6, Math.ceil(W / 2)), QH = Math.max(6, Math.ceil(H / 2));
    const Fc = fbm(rng, 3, 2, 3, 0.56);                       // continents
    const Fb = fbm(rng, 9, 7, 3, 0.50);                       // blotch
    const Fs = fbm(rng, 2, 20, 2, 0.48);                      // rag sweeps
    // the bite: what the rag's own weave left. Clumped, and dragged a
    // little wider than it is tall, so the fine scale still carries the
    // direction of the hand instead of reading as sprayed dust.
    const gxa = Math.max(7, QW >> 3);
    const Fg = fbm(rng, gxa, Math.max(7, Math.round(gxa * 1.4)), 3, 0.5);
    const Fj = fbm(rng, 5, 4, 3, 0.52);                       // stratum jitter
    const Fd = fbm(rng, 3, 3, 2, 0.5);                        // value drift
    const Fv = fbm(rng, 1, Math.max(10, QH >> 3), 2, 0.5);    // long grain
    const cw = o.contW == null ? 0.40 : o.contW,
          bw = o.blotW == null ? 0.26 : o.blotW,
          sw = o.sweepW == null ? 0.16 : o.sweepW,
          gw = o.biteW == null ? 0.18 : o.biteW;
    const tw = 1 / (cw + bw + sw + gw);
    const wb = new Float32Array(QW * QH), jb = new Float32Array(QW * QH),
          db = new Float32Array(QW * QH), gb = new Float32Array(QW * QH);
    const lx = (o.litX == null ? 300 : o.litX) / 1000,
          ly = (o.litY == null ? 200 : o.litY) / 1000;
    let mn = 2, mx = -1;
    for (let j = 0; j < QH; j++) {
      const v = j / (QH - 1);
      for (let i = 0; i < QW; i++) {
        const u = i / (QW - 1), k = j * QW + i;
        const q = (fbmAt(Fc, u, v) * cw + fbmAt(Fb, u, v) * bw +
                   fbmAt(Fs, u, v) * sw + fbmAt(Fg, u, v) * gw) * tw;
        wb[k] = q; if (q < mn) mn = q; if (q > mx) mx = q;
        jb[k] = fbmAt(Fj, u, v) - 0.5;
        const dl = 1 - Math.min(1, Math.sqrt((u - lx) * (u - lx) +
                                             (v - ly) * (v - ly)) * 0.95);
        db[k] = Math.max(0, Math.min(1,
                 fbmAt(Fd, u, v) * 0.56 + dl * 0.62 - 0.09));
        gb[k] = fbmAt(Fv, u, v) - 0.5;
      }
    }
    const nsc = 1 / Math.max(1e-4, mx - mn),
          amp = o.wearAmp == null ? 1 : o.wearAmp;
    for (let i = 0; i < wb.length; i++)
      wb[i] = 0.5 + ((wb[i] - mn) * nsc - 0.5) * amp;
    // the panel: jonpick11 is a triptych and its seams are part of the
    // surface — each panel was handled its own amount
    const nPan = o.panels || 1, cuts = [];
    if (nPan > 1) {
      const st = [];
      for (let p = 0; p < nPan; p++) st.push([rng.r(-0.10, 0.10), rng.r(-0.13, 0.13)]);
      for (let p = 1; p < nPan; p++) cuts.push(rng.r(0.24, 0.76));
      cuts.sort((a, b) => a - b);
      for (let j = 0; j < QH; j++) for (let i = 0; i < QW; i++) {
        const u = i / (QW - 1); let p = 0;
        while (p < cuts.length && u > cuts[p]) p++;
        const k = j * QW + i;
        wb[k] += st[p][0];
        db[k] = Math.max(0, Math.min(1, db[k] + st[p][1]));
      }
    }
    // one 33-step value ramp per coat: the whole panel drifts together
    // because it is one light falling on it, so every stratum that
    // surfaces surfaces at the right key for where it surfaced
    const NL = 33, nC = coats.length, LUT = [], BT = [], BB = [];
    const THR = new Float32Array(nC), HRD = new Float32Array(nC),
          JAM = new Float32Array(nC), DIX = new Int32Array(nC),
          DIY = new Int32Array(nC);
    for (let k = 0; k < nC; k++) {
      const cc = coats[k], arr = new Uint8Array(NL * 3);
      const dr = cc.dr == null ? 0.30 : cc.dr;
      for (let i = 0; i < NL; i++) {
        const t = (i / (NL - 1) - 0.5) * 2;
        const c = t > 0 ? glow(cc.c, t * dr) : sink(cc.c, -t * dr * 0.95);
        arr[i * 3] = c[0]; arr[i * 3 + 1] = c[1]; arr[i * 3 + 2] = c[2];
      }
      LUT.push(arr);
      THR[k] = cc.thr; HRD[k] = cc.hard;
      JAM[k] = cc.jit == null ? 0.12 : cc.jit;
      DIX[k] = Math.round(rng.r(-0.34, 0.34) * QW);
      DIY[k] = Math.round(rng.r(-0.34, 0.34) * QH);
      if (cc.y0 != null) {
        const bt = new Float32Array(W), bb2 = new Float32Array(W);
        const w1 = lat(rng, 7, 1), w2 = lat(rng, 15, 1),
              aw = cc.wob == null ? 8 : cc.wob;
        for (let x = 0; x < W; x++) {
          const u = x / (W - 1);
          bt[x] = (cc.y0 + (latAt(w1, u, 0.5) - 0.5) * aw * 2 +
                          (latAt(w2, u, 0.5) - 0.5) * aw) / 1000 * H;
          bb2[x] = (cc.y1 + (latAt(w2, u, 0.5) - 0.5) * aw * 2 +
                           (latAt(w1, u, 0.5) - 0.5) * aw) / 1000 * H;
        }
        BT.push(bt); BB.push(bb2);
      } else { BT.push(null); BB.push(null); }
    }
    const bLUT = new Uint8Array(NL * 3);
    for (let i = 0; i < NL; i++) {
      const t = (i / (NL - 1) - 0.5) * 2;
      const c = t > 0 ? lift(board, t * 0.20) : sink(board, -t * 0.24);
      bLUT[i * 3] = c[0]; bLUT[i * 3 + 1] = c[1]; bLUT[i * 3 + 2] = c[2];
    }
    const img = ctx.createImageData(W, H), P = img.data;
    const tA = o.tooth == null ? 0.11 : o.tooth,
          tB = o.tooth2 == null ? 0.07 : o.tooth2,
          gV = o.grainV == null ? 0.05 : o.grainV,
          pl = o.pool == null ? 0.11 : o.pool,
          fbA = o.fiber == null ? 24 : o.fiber;
    const S1 = (rng.f() * 4294967296) >>> 0, S2 = (rng.f() * 4294967296) >>> 0,
          S3 = (rng.f() * 4294967296) >>> 0;
    let pi = 0;
    for (let y = 0; y < H; y++) {
      const qy = y * 0.5, j0 = qy | 0, fyy = qy - j0,
            j1 = j0 + 1 < QH ? j0 + 1 : QH - 1;
      const rA = j0 * QW, rB = j1 * QW;
      for (let x = 0; x < W; x++, pi += 4) {
        const qx = x * 0.5, i0 = qx | 0, fxx = qx - i0,
              i1 = i0 + 1 < QW ? i0 + 1 : QW - 1;
        const wA = wb[rA + i0] + (wb[rA + i1] - wb[rA + i0]) * fxx;
        const wB = wb[rB + i0] + (wb[rB + i1] - wb[rB + i0]) * fxx;
        let w = wA + (wB - wA) * fyy;
        w += (hsh(x, y, S1) - 0.5) * tA + (hsh(x >> 1, y >> 1, S2) - 0.5) * tB;
        const dA = db[rA + i0] + (db[rA + i1] - db[rA + i0]) * fxx;
        const dB = db[rB + i0] + (db[rB + i1] - db[rB + i0]) * fxx;
        let li = ((dA + (dB - dA) * fyy) * (NL - 1)) | 0;
        if (li < 0) li = 0; else if (li > NL - 1) li = NL - 1;
        li *= 3;
        // the bare board, with its own fiber running the long way
        const fib = (hsh(x >> 2, y, S3) - 0.5) * fbA;
        let r = bLUT[li] + fib, g = bLUT[li + 1] + fib * 0.9,
            b = bLUT[li + 2] + fib * 0.72;
        for (let k = 0; k < nC; k++) {
          let jx = i0 + DIX[k]; if (jx < 0) jx += QW; else if (jx >= QW) jx -= QW;
          let jy = j0 + DIY[k]; if (jy < 0) jy += QH; else if (jy >= QH) jy -= QH;
          let a = (THR[k] + JAM[k] * jb[jy * QW + jx] - w) * HRD[k];
          if (a <= 0.004) continue;
          if (a > 1) a = 1;
          const bt = BT[k];
          if (bt) {
            const t0 = bt[x], t1 = BB[k][x];
            if (y < t0 - 1.6 || y > t1 + 1.6) continue;
            if (y < t0 + 1.6) a *= Math.max(0, (y - t0 + 1.6) * 0.3125);
            if (y > t1 - 1.6) a *= Math.max(0, (t1 + 1.6 - y) * 0.3125);
            if (a <= 0.004) continue;
          }
          const L2 = LUT[k];
          r += (L2[li] - r) * a; g += (L2[li + 1] - g) * a;
          b += (L2[li + 2] - b) * a;
          // pigment settles at the torn edge of every stratum
          if (a < 0.88) {
            const p2 = 1 - Math.abs(a - 0.44) * 2.3;
            if (p2 > 0) { const q2 = 1 - pl * p2; r *= q2; g *= q2; b *= q2; }
          }
        }
        const gA = gb[rA + i0] + (gb[rA + i1] - gb[rA + i0]) * fxx;
        const gB = gb[rB + i0] + (gb[rB + i1] - gb[rB + i0]) * fxx;
        const gm = 1 + (gA + (gB - gA) * fyy) * gV * 2;
        r *= gm; g *= gm; b *= gm;
        P[pi] = r < 0 ? 0 : r > 255 ? 255 : r;
        P[pi + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
        P[pi + 2] = b < 0 ? 0 : b > 255 ? 255 : b;
        P[pi + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    return cuts;
  }

  // ---------------------------------------------------------------- ground
  // The ground is a painting before the dog arrives. Three voices, chosen
  // by seed:
  //   'mosaic'  — feel6: big soft rectangles of adjacent hue laid side by
  //               side, never blended to mud — slabs, a raft of mids, and
  //               small punctuation notes in a farther hue
  //   'wash'    — nara2: cloudy tonal masses the size of the dog's head,
  //               lighter where the brush ran dry near the light, pigment
  //               pooling along the borders
  //   'horizon' — two bands, a floor and a sky, meeting in a dry scrubbed
  //               seam where the pigment pools dark (brush2's stage)
  // Every mark is a broad scrub that runs DRY at its end (never a fade),
  // and a darker rim pools where one pass settles against the next.

  // one loaded patch: parallel pulls sharing a direction, each running out
  // of paint at its own moment; optionally a pooled darker rim along one
  // long edge where the pass meets its neighbor
  function scrubPatch(ctx, rng, cx, cy, L, W, ang, col, a, pool) {
    const ca = Math.cos(ang), sa = Math.sin(ang);
    const sw = Math.min(96, Math.max(26, W / rng.r(2.0, 3.2)));
    const k = Math.max(2, Math.round(W / (sw * 0.72)));
    for (let i = 0; i < k; i++) {
      const off = (i + 0.5) / k * W - W / 2 + rng.r(-0.2, 0.2) * sw;
      const px = cx - sa * off, py = cy + ca * off;
      // the landing pull runs LONG — a block you can count, not a dash
      const l2 = L * (i === 0 ? rng.r(0.52, 0.70) : rng.r(0.38, 0.55));
      const bow = rng.r(-0.09, 0.09) * L;
      const sgn = rng.chance(0.5) ? 1 : -1;   // the dry tail alternates ends
      // pressure variance INSIDE one patch: the FIRST pull is the landing —
      // committed, near-opaque, loaded, a mark you can count from across
      // the room — and the passes after it graze drier and weaker. A patch
      // whose every pull sits at half strength averages into mottle.
      const lead = i === 0;
      ctx.globalAlpha = lead ? Math.min(1, Math.max(a * 1.45, 0.55) * rng.r(0.9, 1.1))
                             : Math.min(1, a * rng.r(0.58, 1.05));
      ribbon(ctx, rng,
             [[px - ca * l2 * sgn, py - sa * l2 * sgn],
              [px - sa * bow, py + ca * bow],
              [px + ca * l2 * sgn, py + sa * l2 * sgn]],
             drift(rng, col, 0.05), sw,
             lead ? { taper: 0.12, min: 0.4, wob: 0.4, jit: 2, step: 15,
                      load: rng.r(0.62, 0.9) }
                  : { end: rng.r(0.5, 1.3), min: 0.4, wob: 0.5, jit: 2.5,
                      step: 16, load: rng.r(0.35, 0.65) });
    }
    if (pool) {
      // pigment settles where two passes meet: a darker rim hugs one edge
      const side = rng.chance(0.72) ? 1 : -1;      // mostly the under edge
      const off = W / 2 * rng.r(0.78, 1.02) * side;
      const px = cx - sa * off, py = cy + ca * off;
      const l2 = L * rng.r(0.32, 0.5);
      ctx.globalAlpha = rng.r(0.20, 0.38);
      ribbon(ctx, rng,
             [[px - ca * l2, py - sa * l2],
              [px + rng.r(-9, 9), py + rng.r(-7, 7)],
              [px + ca * l2, py + sa * l2]],
             drift(rng, sink(col, rng.r(0.10, 0.20)), 0.05),
             sw * rng.r(0.30, 0.5),
             { end: rng.r(0.7, 1.4), min: 0.4, wob: 0.6, jit: 2.5, step: 15 });
    }
    ctx.globalAlpha = 1;
  }

  // ======================================================================
  // THE GROUND: THREE LANGUAGES, AND A PIECE SPEAKS ONE
  // ROUND 122. The verdict: "one mark-making voice runs unbroken through
  // 46 wardrobe panels, 16 fresh seeds and 20 one-of-ones, so the sheet
  // reads as wallpaper." The six old 'modes' all finished through one
  // shared suite of scrubs, veils, clean-light passages and foreign
  // patches, which is why they averaged to one hatch. That suite is
  // DEAD. Three procedures now exist, they share nothing but the board,
  // and a piece commits to exactly one:
  //   SCOURED  (jonpick11) — four full-panel opaque layers, then broad
  //            dry rag sweeps the width of the canvas that wear the top
  //            coat back to the ones beneath it. Continents, not speckle.
  //   CRAYON   (jonpick12) — a near-bare warm paperboard with the sky
  //            DRAWN on it in 300-450 countable waxy strokes laid side by
  //            side, never blended, skipping across the tooth.
  //   DAYLIGHT (jonpick7)  — two or three broad evenly keyed flat fields
  //            and ONE big graphic cloud or hill carried by a soft broken
  //            dark contour. All the drama in the shape.
  //   AURORA               — the immortal's alone: impossible light, four
  //            ribboned hues crossing one panel. The only piece on the
  //            sheet allowed to break the one-chord rule.
  // ======================================================================
  // ================ THE THREE GROUND LANGUAGES (+ the aurora)
  // A piece speaks exactly one of these. Each takes `g`, the panel
  // context paintGround builds (the board already laid, the chord, the
  // figure keep-out, the lit corner) and paints the whole room.
  // Registered in GROUND_LANGS; scoured is the fallback.

  // ======= CRAYON WEATHER (jonpick12) =======
  // A pale scrubbed support close to bare with the sky DRAWN onto it:
  // long waxy pulls skipping across the tooth, countable one by one.
  function groundCrayon(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig, LG = g.LG;
    const GO = g.GO, board = g.board, deep = g.deep, satUpG = g.satUpG;
    const litX = g.litX, litY = g.litY;
  // ======= CRAYON WEATHER (jonpick12) — round 126 rebuild =======
  // THE BET OF THE ROUND, and the round's whole mandate. Every
  // previous pass at this language SPRAYED: short tapered dashes
  // scattered at a density, which is why the verdicts kept calling
  // it confetti, debris, grass. Open the reference again and the
  // sky is not dashes at all. It is a few dozen LONG CONTINUOUS
  // PULLS of wax. Each one travels most of the panel in a slow
  // wave; they lie side by side in parallel families, teal under
  // and coral over; and every one of them BEADS — the wax lands
  // where the tooth of the board stands up and misses where it
  // dips, so the gaps BELONG TO THE LINE and the eye can follow a
  // single stroke from one edge of the picture to the other.
  // So the primitive changes. waxLine() walks a path and deposits
  // against a shared board-tooth field; pressure breathes along the
  // pull; the colour drifts as the stick picks up what is under it.
  // Countable marks, and the whites are the board, never paint.
  const TAU = Math.PI * 2;
  // model units per device pixel: a wax line has to survive the
  // 400px sheet as well as the 760px detail crop, so the stick
  // never gets thinner than a pixel and a bit
  const PXu = 1000 / Math.max(1, ctx.canvas.width);

  // ---- THE BOARD IS NEARLY BARE, AND IT IS LIGHT ----------------
  // jonpick12 is a warm paperboard scrubbed almost to white. The
  // wax must always be the darkest thing in the panel, so this
  // language keeps its support in the top of the value range and
  // carries the piece's temperature in the STICKS, which is what
  // makes crayon the lightest and most childlike of the three and
  // why every fate may speak it.
  const milk = deep ? mix(hx('#f0ebde'), glow(paper, 0.72), 0.14)
                    : mix(hx('#f3efe4'), paper, 0.10);
  const sup = rng.f();
  // three registers: the reference's bone board; a board carrying a
  // real breath of the piece's own temperature; and a genuinely
  // COLOURED support — the crayon language kept coming back cream
  // sixteen panels in a row, which is its own kind of wallpaper.
  const tinted = sup < 0.72, strong = sup < 0.40;
  let tintB = tinted
    ? mix(board, LG(glow(deep ? glow(paper, 0.70) : paper,
                         strong ? rng.r(0.10, 0.30) : rng.r(0.34, 0.58))),
          strong ? rng.r(0.62, 0.86) : rng.r(0.34, 0.60))
    : mix(board, hx('#f2eee2'), rng.r(0.40, 0.66));
  let milkC = strong ? mix(tintB, hx('#f2ece0'), rng.r(0.16, 0.34))
            : tinted ? mix(milk, hx('#f7f4ea'), rng.r(0.10, 0.34))
                     : mix(milk, hx('#fbf9f2'), rng.r(0.34, 0.62));
  // ...and every one of them stays out of the mud: even the coloured
  // board sits above the wax so the drawing reads.
  const loFloor = strong ? 138 : tinted ? 176 : 196;
  for (let i = 0; i < 8 && lum(tintB) < loFloor; i++) tintB = glow(tintB, 0.16);
  for (let i = 0; i < 8 && lum(milkC) < loFloor + 12; i++) milkC = glow(milkC, 0.16);
  for (let i = 0; i < 6 && lum(tintB) > 236; i++) tintB = sink(tintB, 0.08);
  paintSupport(ctx, rng, board, [
    { c: tintB,
      thr: rng.r(0.62, 0.90), hard: rng.r(1.8, 3.6),
      jit: rng.r(0.14, 0.28), dr: rng.r(0.16, 0.34) },
    { c: milkC, thr: rng.r(0.34, 0.66),
      hard: rng.r(1.6, 3.2),
      jit: rng.r(0.16, 0.32), dr: rng.r(0.16, 0.36) },
  ], { wearAmp: rng.r(0.95, 1.20), contW: rng.r(0.46, 0.58),
       blotW: rng.r(0.16, 0.26), sweepW: rng.r(0.10, 0.20),
       biteW: rng.r(0.10, 0.18), tooth: rng.r(0.07, 0.13),
       tooth2: rng.r(0.04, 0.09), grainV: rng.r(0.03, 0.06),
       pool: rng.r(0.02, 0.06), fiber: rng.r(24, 42), litX, litY });
  ctx.globalAlpha = 1;
  const boardL = (lum(tintB) + lum(milkC)) * 0.5;

  // ---- THE CRAYON BOX -------------------------------------------
  // Three sticks and a pencil. One carries the piece's own hue, one
  // crosses the temperature the way the orange crosses the blue in
  // the reference, one stays a pale note, and the pencil is a
  // near-neutral graphite that gives the panel its bottom value.
  const cb = deep ? glow(paper, rng.r(0.22, 0.40)) : paper;
  // every stick is driven until it stands a REAL value step off the
  // board — a pale mark on cream is not restraint, it is an empty
  // panel, and that is the failure this language keeps finding
  const key = (c, want, sat) => {
    let k = c;
    for (let i = 0; i < 12 && boardL - lum(k) < want; i++) k = sink(k, 0.13);
    for (let i = 0; i < 6 && boardL - lum(k) > want + 74; i++) k = glow(k, 0.12);
    // sinking toward warm black grays the stick out; a crayon is
    // pigment in wax and keeps its chroma all the way down
    return sat === 0 ? k : satUpG(k, sat == null ? 0.55 : sat);
  };
  const c1 = key(LG(satUpG(hueShiftC(cb, rng.r(-16, 16)), 0.70)),
                 rng.r(62, 92));
  const c2 = key(LG(satUpG(hueShiftC(cb,
                 (rng.chance(0.5) ? 1 : -1) * rng.r(38, 74)), 0.78)),
                 rng.r(56, 86));
  const c3 = key(LG(satUpG(hueShiftC(cb,
                 (rng.chance(0.5) ? 1 : -1) * rng.r(76, 132)), 0.62)),
                 rng.r(40, 64));
  // the pencil: the gray-brown hooks and the smudged band that hold
  // jonpick12 together underneath all that colour
  const cP = key(mix(hx(rng.pick(['#6a6258', '#5e5a52', '#70645a',
                                  '#5a5f63'])), cb, rng.r(0.06, 0.22)),
                 rng.r(92, 126), 0);
  const sticks = [c1, c1, c1, c2, c2, c3];

  // ---- THE TOOTH OF THE BOARD -----------------------------------
  // ONE field, shared by every line in the panel, so lines crossing
  // the same bald patch fade together the way real wax does. This
  // is what makes a family of pulls read as one surface instead of
  // as independent strokes.
  const Ft = fbm(rng, 40, 30, 3, 0.55);
  const tSalt = (rng.f() * 60000) | 0;

  // ---- WHERE THE WEATHER GATHERS --------------------------------
  // A low-frequency field with real zeros in it. A pull crossing a
  // dead region simply stops depositing and picks up again on the
  // far side — the gap is part of the stroke, not a missing stroke.
  const Fw = fbm(rng, 3, 3, 2, 0.55);
  let wMax = 0, wmU = 0.5, wmV = 0.35;
  for (let j = 0; j <= 12; j++)
    for (let i = 0; i <= 12; i++) {
      const q = fbmAt(Fw, i / 12, j / 12);
      if (q > wMax) { wMax = q; wmU = i / 12; wmV = j / 12; }
    }
  const wCut = wMax * rng.r(0.28, 0.50);
  const wGain = 1 / Math.max(0.08, wMax - wCut);
  // ...and the weather sits in a BAND of sky, the way it does in the
  // reference, instead of dusting the panel corner to corner. The
  // band is anchored on the field's own richest passage, so a panel
  // can never come out with its whole weather off the canvas.
  const wy = Math.max(-40, Math.min(880,
               wmV * 1280 - 140 + rng.r(-130, 130)));
  const wr = rng.r(360, 860);
  const wxC = wmU * 1280 - 140;
  const densAt = (x, y) => {
    const u = Math.max(0, Math.min(1, (x + 140) / 1280));
    const v = Math.max(0, Math.min(1, (y + 140) / 1280));
    const f = Math.max(0, fbmAt(Fw, u, v) - wCut) * wGain;
    const dv = (y - wy) / wr;
    // never zero: the pull keeps travelling through the bare
    // continents and only thins there, which is what makes the gap
    // belong to the stroke instead of being a missing stroke
    // the contrast between weather and bare board is the whole
    // picture: inside a gathering the wax lays down nearly solid,
    // outside it the same pull survives as a few beads or nothing
    return 0.16 + 1.34 * Math.min(1.05, f) * (0.26 + 0.74 * Math.exp(-dv * dv));
  };

  // ---- ONE CRAYON LINE ------------------------------------------
  let waxLaid = 0;               // how much wax actually reached the board
  const waxLine = (pts, col, o) => {
    o = o || {};
    const w0 = Math.max(o.w == null ? 5 : o.w, PXu * 1.25);
    const base = o.press == null ? 0.86 : o.press;
    const salt = (rng.f() * 60000) | 0;
    const f1 = rng.r(0.8, 2.6), p1 = rng.r(0, TAU);
    const f2 = rng.r(3.5, 9.0), p2 = rng.r(0, TAU);
    const f3 = rng.r(11, 26), p3 = rng.r(0, TAU);
    const cum = [0];
    let total = 0;
    for (let i = 1; i < pts.length; i++) {
      total += Math.hypot(pts[i][0] - pts[i - 1][0],
                          pts[i][1] - pts[i - 1][1]);
      cum.push(total);
    }
    if (total < 6) return;
    const n = Math.min(3400,
              Math.max(6, Math.ceil(total / (w0 * (o.step || 0.40)))));
    // the wax picks up what is under it: the pull is laid in four
    // stretches, each a hair off the last in hue and value
    const nSeg = 4, NB = 4;
    const cols = [];
    for (let k = 0; k < nSeg; k++)
      cols.push(css(drift(rng, k % 2 ? sink(col, 0.07) : lift(col, 0.03),
                          0.055)));
    const coreC = css(sink(drift(rng, col, 0.04), 0.20));
    const bins = new Array(nSeg * NB);
    const core = [];
    let j = 1, laid = 0;
    for (let i = 0; i < n; i++) {
      const t = i / (n - 1), s = t * total;
      while (j < cum.length - 1 && cum[j] < s) j++;
      const s0 = cum[j - 1], s1 = cum[j];
      const f = s1 > s0 ? (s - s0) / (s1 - s0) : 0;
      const x = pts[j - 1][0] + (pts[j][0] - pts[j - 1][0]) * f;
      const y = pts[j - 1][1] + (pts[j][1] - pts[j - 1][1]) * f;
      if (x < -70 || x > 1070 || y < -70 || y > 1070) continue;
      const ang = Math.atan2(pts[j][1] - pts[j - 1][1],
                             pts[j][0] - pts[j - 1][0]);
      // PRESS, DRAG, LIFT — and a slow breath under it, so a pull
      // runs solid for a stretch and ghosts out for the next
      let p = base *
        (0.58 + 0.42 * Math.sin(t * f1 * TAU + p1)) *
        (0.74 + 0.26 * Math.sin(t * f2 * TAU + p2)) *
        (0.86 + 0.14 * Math.sin(t * f3 * TAU + p3));
      p *= Math.min(1, 0.10 + t / 0.045) * Math.min(1, 0.06 + (1 - t) / 0.07);
      const dn = o.dens ? o.dens(x, y) : 1;
      if (p * dn <= 0.06) continue;
      // the tooth: a medium grain that runs in short beads, a fine
      // grain that eats the bead's edges, and the board's own field
      // the medium grain carries the RUN — the wax holds for three or
      // four beads and then loses the board for two — while the fine
      // grain only eats the edges of what it laid
      const tk = 0.22 * fbmAt(Ft, (x + 140) / 1280, (y + 140) / 1280) +
                 0.50 * hsh(x * 0.13, y * 0.13, salt) +
                 0.18 * hsh(x * 0.80, y * 0.80, salt ^ 0x5bf03b) +
                 0.12 * hsh(x * 0.13 + 7, y * 0.13 - 3, tSalt) - 0.06;
      // where the weather gathers the wax lays down solid; where the
      // board is bald the same pull survives as a chain of beads
      const cov = p * dn * 1.78 - 0.15;
      if (tk > cov) continue;
      laid++;
      const pr2 = Math.max(0.20, Math.min(1.25, p * (0.42 + 0.66 * dn)));
      // a wax bead is a small ROUND deposit, a hair drawn out along
      // the pull — not a shard. Shards were the splinter look.
      // a wax bead never falls below a device pixel: at sheet
      // resolution a sub-pixel deposit antialiases away to nothing,
      // which is why the crayon panels kept reading empty small and
      // crisp large
      const rx = Math.max(PXu * 0.62,
        w0 * (0.34 + 0.26 * pr2) * (0.86 + hsh(i, salt, 11) * 0.30));
      const ry = Math.max(PXu * 0.52, rx * (0.66 + hsh(i, salt, 29) * 0.32));
      const bIdx = Math.min(NB - 1, (pr2 * NB) | 0);
      const sIdx = Math.min(nSeg - 1, (t * nSeg) | 0);
      const kIdx = sIdx * NB + bIdx;
      let arr = bins[kIdx]; if (!arr) arr = bins[kIdx] = [];
      const jx = (hsh(i, salt, 3) - 0.5) * w0 * 0.5;
      const jy = (hsh(i, salt, 5) - 0.5) * w0 * 0.5;
      arr.push(x + jx, y + jy, rx, ry, ang);
      // WAXY BUILDUP where the hand leaned on it
      if (pr2 > 0.96 && hsh(i, salt, 13) < 0.30)
        core.push(x + jx * 0.4, y + jy * 0.4, rx * 0.55, ry * 0.62, ang);
      // ...and the skitter: the stick jumps the tooth sideways and
      // leaves a little tick off the line. jonpick12's orange is
      // full of them.
      if (hsh(i, salt, 17) < (o.skit == null ? 0.11 : o.skit)) {
        const sgn = hsh(i, salt, 19) < 0.5 ? -1 : 1;
        const off = w0 * (0.55 + hsh(i, salt, 23) * 0.85) * sgn;
        arr.push(x - Math.sin(ang) * off, y + Math.cos(ang) * off,
                 rx * 0.62, ry * 0.78, ang + sgn * 0.9);
      }
    }
    waxLaid += laid;
    if (!laid) return;
    const aBase = o.alpha == null ? 0.94 : o.alpha;
    for (let sI = 0; sI < nSeg; sI++)
      for (let b = 0; b < NB; b++) {
        const arr = bins[sI * NB + b];
        if (!arr || !arr.length) continue;
        ctx.globalAlpha = Math.min(1, aBase * (0.62 + 0.38 * (b + 0.6) / NB));
        ctx.fillStyle = cols[sI];
        ctx.beginPath();
        for (let q = 0; q < arr.length; q += 5) {
          // every bead is its own subpath: without the moveTo the
          // canvas joins one deposit to the next and the panel fills
          // with connecting shards
          ctx.moveTo(arr[q] + arr[q + 2] * Math.cos(arr[q + 4]),
                     arr[q + 1] + arr[q + 2] * Math.sin(arr[q + 4]));
          ctx.ellipse(arr[q], arr[q + 1], arr[q + 2], arr[q + 3],
                      arr[q + 4], 0, TAU);
        }
        ctx.fill();
      }
    if (core.length) {
      ctx.globalAlpha = Math.min(1, aBase * 0.72);
      ctx.fillStyle = coreC;
      ctx.beginPath();
      for (let q = 0; q < core.length; q += 5) {
        ctx.moveTo(core[q] + core[q + 2] * Math.cos(core[q + 4]),
                   core[q + 1] + core[q + 2] * Math.sin(core[q + 4]));
        ctx.ellipse(core[q], core[q + 1], core[q + 2], core[q + 3],
                    core[q + 4], 0, TAU);
      }
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  };

  // ---- THE SKY, DRAWN -------------------------------------------
  // Families of parallel pulls. Inside a family every line shares
  // the same slow wave, so the band wanders as one weather; between
  // families the angles and the sticks disagree and cross.
  const wsc = rng.r(0.78, 1.42);
  const nBand = 4 + Math.floor(rng.f() * 4);
  for (let b = 0; b < nBand; b++) {
    const stick = sticks[(b + (rng.f() * 6 | 0)) % sticks.length];
    const useP = rng.chance(0.16);
    const col = useP ? cP : stick;
    const ang = rng.chance(0.78) ? rng.r(-0.15, 0.15)
              : rng.r(0.26, 0.80) * (rng.chance(0.5) ? 1 : -1);
    const dx = Math.cos(ang), dy = Math.sin(ang);
    const nxv = -dy, nyv = dx;
    const len = rng.r(700, 1520);
    // THE WEATHER IS A SKY, NOT A WALLPAPER. Most families gather in
    // the panel's own weather band and the rest of the board is left
    // frankly bare — one or two outliers wander off on their own so
    // the placement never reads as a stripe.
    const ox = (b < 3 || rng.chance(0.60))
      ? wxC - len * rng.r(0.35, 0.72) + rng.r(-90, 90)
      : rng.r(-280, 220);
    const oy = (b < 3 || rng.chance(0.72))
      ? wy + rng.r(-0.55, 0.55) * wr * 0.7
      : rng.r(-110, 1080);
    const spac = rng.r(10, 27) * wsc;
    const nL = 5 + Math.floor(rng.f() * (useP ? 4 : 17));
    const A1 = rng.r(8, 40), W1 = rng.r(420, 1200), P1 = rng.r(0, TAU);
    const A2 = rng.r(2.5, 9.5), W2 = rng.r(150, 380), P2 = rng.r(0, TAU);
    const wS = rng.r(3.0, 5.8) * wsc * (useP ? 0.74 : 1);
    const bPress = rng.r(0.94, 1.26);
    for (let k = 0; k < nL; k++) {
      const off = (k - (nL - 1) / 2) * spac + rng.r(-5.5, 5.5);
      const ph = rng.r(-1.1, 1.1);
      // the family shares one weather but no two pulls are nested
      // copies: each line's own swing runs a quarter wider or
      // narrower than its neighbour's, so lines drift together,
      // cross, and part again the way a hand does
      const kA = rng.r(0.72, 1.34), kW = rng.r(0.86, 1.18);
      const s0 = rng.r(-0.14, 0.10) * len, s1 = len * rng.r(0.70, 1.08);
      const nP = 34;
      const pl = [];
      for (let q = 0; q <= nP; q++) {
        const s = s0 + (s1 - s0) * (q / nP);
        const wob = A1 * kA * Math.sin(s / (W1 * kW) * TAU + P1 + ph * 0.45) +
                    A2 * Math.sin(s / W2 * TAU + P2 + ph);
        pl.push([ox + dx * s + nxv * (off + wob),
                 oy + dy * s + nyv * (off + wob)]);
      }
      waxLine(pl, drift(rng, col, 0.05),
              { w: wS * rng.r(0.82, 1.22),
                press: bPress * rng.r(0.80, 1.14),
                dens: densAt, alpha: useP ? rng.r(0.72, 0.90)
                                          : rng.r(0.86, 1.0),
                skit: rng.r(0.04, 0.15) });
    }
  }

  // ...and no panel ships empty. If the field's zeros swallowed the
  // weather, a short committed family goes down on the richest
  // passage at full pressure — the reference always has SOMETHING
  // drawn on it.
  if (waxLaid < 2600) {
    const need = 2 + Math.floor(rng.f() * 2);
    for (let b = 0; b < need; b++) {
      const ang = rng.r(-0.13, 0.13);
      const dx = Math.cos(ang), dy = Math.sin(ang);
      const nxv = -dy, nyv = dx;
      const len = rng.r(680, 1300);
      const ox = wxC - len * rng.r(0.40, 0.66);
      const oy = wy + rng.r(-0.34, 0.34) * wr * 0.6;
      const spac = rng.r(13, 30) * wsc;
      const nL = 5 + Math.floor(rng.f() * 8);
      const A1 = rng.r(10, 40), W1 = rng.r(430, 1100), P1 = rng.r(0, TAU);
      const col = b % 2 ? c2 : c1;
      for (let k = 0; k < nL; k++) {
        const off = (k - (nL - 1) / 2) * spac + rng.r(-4, 4);
        const ph = rng.r(-0.8, 0.8);
        const pl = [];
        for (let q = 0; q <= 34; q++) {
          const sS = len * (q / 34);
          const wob = A1 * Math.sin(sS / W1 * TAU + P1 + ph * 0.4);
          pl.push([ox + dx * sS + nxv * (off + wob),
                   oy + dy * sS + nyv * (off + wob)]);
        }
        waxLine(pl, drift(rng, col, 0.05),
                { w: rng.r(3.0, 5.6) * wsc, press: rng.r(0.94, 1.20),
                  dens: (x, y) => 0.62 + 0.5 * densAt(x, y),
                  alpha: rng.r(0.88, 1.0), skit: rng.r(0.05, 0.16) });
      }
    }
  }

  // ---- THE SCRIBBLE ---------------------------------------------
  // The child's shading run: one stick going back and forth without
  // leaving the paper, the hooks at the turns pressed harder than
  // the straights. One or two per panel, never more.
  const nScrib = rng.chance(0.66) ? 1 + Math.floor(rng.f() * 2) : 0;
  for (let i = 0; i < nScrib; i++) {
    const ang = rng.r(-0.30, 0.30) + (rng.chance(0.22) ? 1.4 : 0);
    const dx = Math.cos(ang), dy = Math.sin(ang);
    const nxv = -dy, nyv = dx;
    const ox = rng.r(-120, 780), oy = rng.r(-40, 900);
    const amp = rng.r(26, 92), wl = rng.r(52, 150);
    const len = rng.r(280, 820);
    const nP = Math.round(len / 5);
    const pl = [];
    for (let q = 0; q <= nP; q++) {
      const s = len * q / nP;
      const per = amp * Math.sin(s / wl * TAU) +
                  rng.r(-1.6, 1.6);
      pl.push([ox + dx * s + nxv * per, oy + dy * s + nyv * per]);
    }
    waxLine(pl, drift(rng, rng.chance(0.5) ? c2 : c3, 0.05),
            { w: rng.r(3.2, 6.6) * wsc, press: rng.r(0.62, 0.94),
              dens: densAt, skit: rng.r(0.04, 0.14),
              alpha: rng.r(0.78, 0.96) });
  }

  // ---- ONE DRAWN THING ------------------------------------------
  // Not weather: a mark somebody meant. A wandering hooked contour
  // the way the orange loops over the roofline in the reference —
  // a cloud, a hill, nothing nameable, drawn in one pull.
  if (rng.chance(0.62)) {
    const cx = rng.r(120, 880), cy2 = rng.r(70, 620);
    const rr = rng.r(70, 230), sq = rng.r(0.42, 0.86);
    const a0 = rng.r(0, TAU), sweep = TAU * rng.r(0.55, 1.02);
    const lump = rng.r(0.10, 0.30);
    const pl = [];
    const nP = 44;
    for (let q = 0; q <= nP; q++) {
      const a = a0 + sweep * q / nP;
      const rq = rr * (1 + lump * Math.sin(a * rng.r(2.6, 3.4) + a0) +
                       0.10 * Math.sin(a * 7.1));
      pl.push([cx + Math.cos(a) * rq, cy2 + Math.sin(a) * rq * sq]);
    }
    // and a tail: the hand kept going past where the shape closed
    const lastA = a0 + sweep;
    pl.push([cx + Math.cos(lastA) * rr * 1.24,
             cy2 + Math.sin(lastA) * rr * sq * 1.3 + rng.r(-40, 60)]);
    waxLine(pl, drift(rng, rng.chance(0.42) ? cP : c1, 0.05),
            { w: rng.r(3.6, 7.0) * wsc, press: rng.r(0.80, 1.06),
              skit: rng.r(0.03, 0.12), alpha: rng.r(0.84, 1.0),
              dens: (x, y) => 0.55 + 0.55 * densAt(x, y) });
  }

  // ---- FINGERED PASSAGES ----------------------------------------
  // Places where a hand dragged the wax sideways. Kept, not cleaned.
  for (let i = 0; i < 2 + Math.floor(rng.f() * 2); i++) {
    const sx = rng.r(60, 940), sy = rng.r(60, 940);
    ctx.globalAlpha = rng.r(0.16, 0.36);
    dryStroke(ctx, rng,
              [[sx, sy], [sx + rng.r(-140, 140), sy + rng.r(-60, 60)],
               [sx + rng.r(-260, 260), sy + rng.r(-90, 90)]],
              drift(rng, mix(rng.chance(0.45) ? cP : c2, milkC, 0.44), 0.05),
              rng.r(50, 110),
              { fade: rng.r(0.5, 1.1), grain: rng.r(0.55, 0.85),
                press: rng.r(0.3, 0.7) });
  }
  ctx.globalAlpha = 1;

  // ---- ONE SCRAWL -----------------------------------------------
  // Handwriting, not weather. A loop, a corner of cross-hatch, a few
  // pressed ticks — part of the picture.
  {
    const sx = rng.r(90, 860), sy = rng.r(90, 860);
    const sc = drift(rng, rng.chance(0.5) ? cP : sink(c2, 0.14), 0.05);
    const kind = rng.f();
    if (kind < 0.40) {
      const loops = 2 + Math.floor(rng.f() * 3);
      const pl = [];
      for (let k = 0; k <= loops * 20; k++) {
        const a = k / 20 * TAU;
        const rq = rng.r(20, 44) * (1 + k / (loops * 30));
        pl.push([sx + Math.cos(a) * rq * 1.3, sy + Math.sin(a) * rq]);
      }
      waxLine(pl, sc, { w: rng.r(3.4, 6.2), press: rng.r(0.72, 1.0),
                        skit: 0.06, alpha: rng.r(0.7, 0.94) });
    } else if (kind < 0.74) {
      for (let k = 0; k < 4 + Math.floor(rng.f() * 5); k++) {
        const tx = sx + rng.r(-56, 56), ty = sy + rng.r(-52, 52);
        waxLine([[tx, ty], [tx + rng.r(-42, 42), ty + rng.r(22, 76)]],
                sc, { w: rng.r(3.2, 6.0), press: rng.r(0.78, 1.06),
                      skit: 0.05, alpha: rng.r(0.7, 0.95) });
      }
    } else {
      const pl = [];
      for (let k = 0; k < 9; k++)
        pl.push([sx + k * rng.r(15, 28),
                 sy + (k % 2 ? -1 : 1) * rng.r(16, 40)]);
      waxLine(pl, sc, { w: rng.r(3.4, 6.0), press: rng.r(0.74, 1.02),
                        skit: 0.08, alpha: rng.r(0.72, 0.95) });
    }
  }

  // ---- THE WEATHER CROWDS THE ANIMAL ----------------------------
  // Not a painted pool: a short family of pulls following the
  // silhouette, pressed harder where it passes closest.
  if (fig) {
    const nA = 5 + Math.floor(rng.f() * 4);
    for (let i = 0; i < nA; i++) {
      const a = rng.r(-0.3, Math.PI + 0.3);
      const rm = rng.r(1.02, 1.30);
      const bx = fig.x + Math.cos(a) * fig.rx * rm;
      const by = fig.y + Math.sin(a) * fig.ry * rm;
      const ta = a + Math.PI / 2 + rng.r(-0.30, 0.30);
      const len = rng.r(120, 340);
      const pl = [];
      for (let q = 0; q <= 16; q++) {
        const s = (q / 16 - 0.5) * len;
        pl.push([bx + Math.cos(ta) * s + rng.r(-2, 2),
                 by + Math.sin(ta) * s + rng.r(-2, 2)]);
      }
      waxLine(pl, drift(rng, sink(rng.chance(0.5) ? c1 : c2, 0.10), 0.05),
              { w: rng.r(2.8, 5.6) * wsc, press: rng.r(0.56, 0.88),
                skit: rng.r(0.06, 0.18), alpha: rng.r(0.60, 0.86) });
    }
  }
  ctx.globalAlpha = 1;
  }

  // ======= FLAT DAYLIGHT (jonpick7 / jonpick21) =======
  // Calm woodblock light. Two or three broad evenly-keyed fields and
  // one big graphic shape carried by a soft broken dark contour.
  function groundDaylight(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig, LG = g.LG;
    const GO = g.GO, board = g.board, deep = g.deep, satUpG = g.satUpG;
    const litX = g.litX, litY = g.litY;
  // ======= FLAT DAYLIGHT (jonpick7) =======
  // Calm woodblock light. Two or three broad fields, quietly and
  // evenly keyed, with only the faintest wood tooth in them, and
  // ONE big graphic shape carried by a soft broken dark contour.
  // This is the ground that holds a violent event in innocent light.
  const sky = LG(deep ? sink(paper, rng.r(0.02, 0.08))
                      : glow(paper, rng.r(0.02, 0.10)));
  let land = LG(satUpG(hueShiftC(sink(paper, deep ? rng.r(0.18, 0.30)
                                                  : rng.r(0.20, 0.34)),
                       (rng.chance(0.62) ? 1 : -1) * rng.r(24, 62)),
                       deep ? 0.14 : 0.40));
  // the two fields must part company: this is a woodblock, and all
  // the drama sits in the shape, so the fields have to be flatly,
  // unmistakably different keys
  // on a night panel the second field goes DOWN, never up: a lifted
  // band under a black sky reads as daylight leaking in
  const part = deep ? 30 : 52;
  const down = deep || lum(land) < lum(sky);
  for (let i = 0; i < 8 && Math.abs(lum(sky) - lum(land)) < part; i++)
    land = down ? sink(land, 0.09) : glow(land, 0.09);
  const hzY = rng.r(560, 830);
  const third = rng.chance(0.45);
  const midY = hzY - rng.r(90, 240);
  const midC = LG(satUpG(hueShiftC(deep ? glow(paper, rng.r(0.08, 0.18))
                                        : sink(paper, rng.r(0.08, 0.15)),
                         (rng.chance(0.5) ? 1 : -1) * rng.r(14, 34)),
                         deep ? 0.08 : 0.24));
  // A FLAT FIELD IS STILL PAINT — but a woodblock field is EVEN, so
  // it is not built out of pulls. The support engine lays each field
  // as one calm coat with its value drifting slowly across the panel
  // and only the faintest long grain in it, and the boundary between
  // two fields is a hand-wobbled edge, never a ruled line. All the
  // drama is left for the shape and the contour.
  {
    const bands = [{ c: sky, y0: -70, y1: hzY + 5,
                     thr: 0.985, hard: 24, jit: 0.03,
                     dr: rng.r(0.12, 0.22), wob: rng.r(3, 11) }];
    if (third) bands.push({ c: midC, y0: midY, y1: hzY + 3,
                            thr: 0.985, hard: 24, jit: 0.03,
                            dr: rng.r(0.10, 0.20), wob: rng.r(6, 20) });
    bands.push({ c: land, y0: hzY - 5, y1: 1070,
                 thr: 0.985, hard: 24, jit: 0.03,
                 dr: rng.r(0.12, 0.24), wob: rng.r(3, 10) });
    // a woodblock field is even, not sterile: one broad soft veil of
    // the same colour half a step away sits inside each field, so the
    // ink reads unevenly loaded across the block
    bands.slice().forEach(bd => {
      // on a night panel the veil works harder: a flat near-black is a
      // dead wall at print scale, and calm is not the same as empty
      bands.push({ c: rng.chance(0.5)
                      ? glow(bd.c, deep ? rng.r(0.12, 0.26) : rng.r(0.05, 0.13))
                      : sink(bd.c, deep ? rng.r(0.08, 0.18) : rng.r(0.05, 0.12)),
                   y0: bd.y0, y1: bd.y1, wob: bd.wob,
                   thr: rng.r(0.42, 0.62), hard: rng.r(1.3, 2.2),
                   jit: rng.r(0.20, 0.36), dr: rng.r(0.06, 0.14) });
    });
    paintSupport(ctx, rng, board, bands,
      { wearAmp: rng.r(0.26, 0.46), contW: 0.28, blotW: 0.20,
        sweepW: 0.38, biteW: 0.14, tooth: rng.r(0.03, 0.06),
        tooth2: rng.r(0.02, 0.04),
        grainV: deep ? rng.r(0.13, 0.22) : rng.r(0.07, 0.13),
        pool: rng.r(0.02, 0.05), fiber: rng.r(10, 22), litX, litY });
    ctx.globalAlpha = 1;
  }
  // the horizon: one soft dark break, broken and re-touched
  {
    const hp = [];
    for (let k = 0; k <= 6; k++)
      hp.push([-40 + k * 180, hzY + rng.r(-9, 9)]);
    ctx.globalAlpha = rng.r(0.44, 0.70);
    brokenRibbon(ctx, rng, hp,
                 mix(sink(land, 0.30), hx('#2a2622'), 0.42),
                 rng.r(10, 20), { wob: 0.3, jit: 1.8, taper: 0.25 });
    ctx.globalAlpha = 1;
  }
  // WOOD TOOTH: the faintest grain inside each field, level, long,
  // countable — the woodblock's own fiber, never a speckle filter
  for (let i = 0; i < 34; i++) {
    const yy = rng.r(-20, 1020);
    const inLand = yy > hzY;
    ctx.globalAlpha = rng.r(0.05, 0.13);
    ribbon(ctx, rng,
           [[rng.r(-40, 700), yy],
            [rng.r(300, 1040), yy + rng.r(-3, 3)]],
           drift(rng, inLand ? (rng.chance(0.5) ? sink(land, 0.10)
                                                : glow(land, 0.10))
                             : (rng.chance(0.5) ? sink(sky, 0.07)
                                                : glow(sky, 0.07)), 0.03),
           rng.r(1.6, 4.4), { taper: 0.4, wob: 0.15, jit: 0.9, step: 16 });
  }
  ctx.globalAlpha = 1;
  // THE ONE BIG SHAPE. A cloud, a hill, a low sun, or a single tree
  // mass: whatever it is, it is BIG, it is graphic, and one soft
  // broken dark line carries it.
  {
    const kind = rng.f();
    const inkC2 = mix(hx('#231f1c'), sink(land, 0.2), rng.r(0.14, 0.34));
    let shape = null, fillC = null;
    if (kind < 0.52) {
      // the cloud: lobes, the reference's own construction
      // the cloud has to CLOSE inside the panel: a lobed mass run off
      // two edges at once is not a cloud, it is a grey smear, and the
      // ones sheet was carrying two of them
      let cw = rng.r(200, 330), ch = rng.r(115, 205);
      const room = Math.max(120, hzY - 70);
      if (ch * 1.32 * 2 > room) ch = room / 2.64;
      if (cw * 1.32 * 2 > 900) cw = 900 / 2.64;
      const mgX = cw * 1.32 + 26, mgY = ch * 1.32 + 30;
      let ccx = rng.chance(0.5) ? rng.r(130, 420) : rng.r(580, 880);
      ccx = Math.max(mgX, Math.min(1000 - mgX, ccx));
      const ccy = Math.max(mgY, Math.min(Math.max(mgY, hzY - mgY * 0.7),
                           rng.r(mgY, Math.max(mgY + 1, hzY - mgY))));
      // a cumulus is a RING OF BUMPS, not an amoeba: the reference's
      // smoke cloud is a chain of round lobes with a cusp between
      // every pair, and the old lobe-and-bulge construction was
      // smoothing itself back into a grey potato.
      const nL = 7 + Math.floor(rng.f() * 6);
      const ph = rng.r(0, Math.PI * 2), amp = rng.r(0.22, 0.36);
      const ph2 = rng.r(0, Math.PI * 2), sw2 = rng.r(1.0, 2.5);
      const pts = [];
      for (let k = 0; k < 132; k++) {
        const a = k / 132 * Math.PI * 2;
        // the lobes disagree in size, the way real weather does
        const bump = Math.abs(Math.sin(a * nL * 0.5 + ph)) *
                     (0.62 + 0.52 * Math.abs(Math.sin(a * sw2 + ph2)));
        const rr = 0.78 + amp * bump
                 + 0.06 * Math.sin(a * 3 + ph * 1.7)
                 + rng.r(-0.012, 0.012);
        pts.push([ccx + Math.cos(a) * cw * rr,
                  ccy + Math.sin(a) * ch * rr]);
      }
      shape = smoothPts(pts, true, 1);
      // on a deep sky the cloud is the light; on a pale one it has to
      // be the weight, or the shape vanishes and only a stray line
      // is left floating in the panel
      const cloudUp = lum(sky) < 168;
      // on a night panel a near-white cloud punches a hole in the
      // picture; the mass stays a real mid value so it reads as
      // weather sitting in front of the dark, not as bare canvas
      const night2 = lum(sky) < 86;
      fillC = LG(cloudUp ? mix(glow(mix(hx('#f2ead6'), sky, 0.30),
                                   rng.r(0.16, 0.34)),
                               sky, night2 ? rng.r(0.06, 0.16) : 0)
                         : satUpG(hueShiftC(sink(sky, rng.r(0.22, 0.36)),
                                  rng.r(-30, 30)), 0.26));
      const gap2 = night2 ? 72 : 42;
      for (let i = 0; i < 10 && Math.abs(lum(fillC) - lum(sky)) < gap2; i++)
        fillC = cloudUp ? glow(fillC, 0.09) : sink(fillC, 0.09);
    } else if (kind < 0.80) {
      // the hill: a broad low mass rising out of the land band
      const hx0 = rng.r(-160, 520), hw = rng.r(620, 1100);
      const hh = rng.r(120, 260);
      const pts = [[hx0, hzY + 40]];
      for (let k = 0; k <= 10; k++) {
        const t = k / 10;
        pts.push([hx0 + hw * t,
                  hzY + 30 - Math.sin(t * Math.PI) * hh + rng.r(-10, 10)]);
      }
      pts.push([hx0 + hw, hzY + 40]);
      shape = smoothPts(resample(pts, true, 10), true, 1);
      fillC = LG(satUpG(hueShiftC(sink(land, rng.r(0.10, 0.22)),
                        rng.r(-24, 24)), 0.22));
    } else {
      // the sun/moon: one flat disc, high and off-axis
      const scx = rng.chance(0.5) ? rng.r(140, 340) : rng.r(660, 880);
      const scy = rng.r(100, 300), sr = rng.r(90, 165);
      shape = blob(rng, scx, scy, sr, sr * rng.r(0.94, 1.06), 22, 0.045);
      fillC = LG(deep ? glow(paper, rng.r(0.34, 0.58))
                      : satUpG(hueShiftC(paper, rng.r(20, 60)), 0.5));
    }
    // WHATEVER the shape is, it has to READ: the woodblock puts all
    // its drama in one silhouette, and a cloud half a value off its
    // sky is a smudge. The shape parts company with the field it
    // sits on before a single stroke is laid.
    {
      const base = shape[0][1] > hzY ? land : sky;
      let up = lum(fillC) >= lum(base);
      for (let i = 0; i < 14 && Math.abs(lum(fillC) - lum(base)) < 56; i++)
        fillC = up ? glow(fillC, 0.10) : sink(fillC, 0.10);
      // if it ran out of headroom going that way, it goes the other
      // way: a shape a value off its field is not a shape
      if (Math.abs(lum(fillC) - lum(base)) < 40) {
        up = !up; fillC = base;
        for (let i = 0; i < 16 && Math.abs(lum(fillC) - lum(base)) < 62; i++)
          fillC = up ? glow(fillC, 0.11) : sink(fillC, 0.11);
      }
    }
    // AND IT STANDS CLEAR OF THE ANIMAL. A cloud parked on the dog is
    // a grey blob behind a head; the woodblock puts its one event
    // BESIDE the figure so both silhouettes survive.
    if (fig) {
      let bx0 = 1e9, bx1 = -1e9;
      shape.forEach(p => { if (p[0] < bx0) bx0 = p[0];
                           if (p[0] > bx1) bx1 = p[0]; });
      const cxS = (bx0 + bx1) / 2, hW = (bx1 - bx0) / 2;
      const need = hW + fig.rx * 1.10;
      if (Math.abs(cxS - fig.x) < need && hW < 460) {
        let hW2 = hW, need2 = need, sc2 = 1;
        // if it cannot get out of the animal's way at this size, it
        // comes down in scale until it can — a smaller shape read
        // clean beats a big one read as a bruise behind a head
        for (let q = 0; q < 3; q++) {
          const lT = fig.x - need2, rT = fig.x + need2;
          if (lT - hW2 > -170 || rT + hW2 < 1170) break;
          sc2 *= 0.74; hW2 *= 0.74; need2 = hW2 + fig.rx * 1.10;
        }
        let cyS = 0;
        shape.forEach(p => { cyS += p[1]; }); cyS /= shape.length;
        if (sc2 !== 1)
          shape = shape.map(p => [cxS + (p[0] - cxS) * sc2,
                                  cyS + (p[1] - cyS) * sc2]);
        const lT = fig.x - need2, rT = fig.x + need2;
        const lOK = lT - hW2 > -170, rOK = rT + hW2 < 1170;
        let tx = cxS;
        if (lOK && (!rOK || cxS <= fig.x)) tx = lT;
        else if (rOK) tx = rT;
        if (tx !== cxS) shape = shape.map(p => [p[0] + tx - cxS, p[1]]);
      }
    }
    // the shape is painted evenly, the way the fields are
    const bb = shape.reduce((a, p) => [Math.min(a[0], p[0]), Math.min(a[1], p[1]),
                                       Math.max(a[2], p[0]), Math.max(a[3], p[1])],
                            [1e9, 1e9, -1e9, -1e9]);
    ctx.save();
    ctx.beginPath(); poly(ctx, shape, true); ctx.clip();
    ctx.globalAlpha = rng.r(0.90, 0.99);
    fillPts(ctx, shape, fillC);
    ctx.globalAlpha = 1;
    const nR = Math.ceil((bb[3] - bb[1]) / 18) + 1;
    for (let i = 0; i < nR; i++) {
      const yy = bb[1] + (i + rng.r(0.1, 0.9)) * (bb[3] - bb[1]) / nR;
      ctx.globalAlpha = rng.r(0.34, 0.60);
      ribbon(ctx, rng,
             [[bb[0] - 40, yy + rng.r(-4, 4)],
              [(bb[0] + bb[2]) / 2, yy + rng.r(-6, 6)],
              [bb[2] + 40, yy + rng.r(-4, 4)]],
             drift(rng, fillC, 0.035), rng.r(24, 40),
             { taper: 0.06, wob: 0.18, jit: 1.2, step: 18,
               load: rng.r(0.75, 1) });
    }
    ctx.globalAlpha = 1;
    ctx.restore();
    // THE CONTOUR: soft, dark, broken, re-touched, thick then thin
    const sn = shape.length;
    const segs = [[0, 0.44], [0.36, 0.78], [0.70, 1.0]];
    segs.forEach((s, si) => {
      const a0 = Math.floor(sn * s[0]), a1 = Math.floor(sn * s[1]);
      const seg = shape.slice(a0, Math.max(a0 + 3, a1));
      if (seg.length < 3) return;
      ctx.globalAlpha = rng.r(0.80, 0.97);
      brokenRibbon(ctx, rng, seg, drift(rng, inkC2, 0.04),
                   rng.r(17, 30) * (si === 1 ? rng.r(0.72, 1.0) : 1),
                   { wob: 0.32, jit: 2.4, taper: 0.18 });
      // re-touched: the hand went back over part of the line
      if (rng.chance(0.6)) {
        const q0 = Math.floor(seg.length * rng.r(0.1, 0.4));
        const q1 = Math.floor(seg.length * rng.r(0.6, 0.95));
        if (q1 - q0 > 3) {
          ctx.globalAlpha = rng.r(0.5, 0.8);
          ribbon(ctx, rng, seg.slice(q0, q1),
                 drift(rng, sink(inkC2, 0.12), 0.04), rng.r(9, 18),
                 { taper: 0.35, wob: 0.4, jit: 2.6, step: 11 });
        }
      }
    });
    ctx.globalAlpha = 1;
  }
  // and one quiet drift so the two corners never match: a single
  // broad breath of light where the sun is
  for (let i = 0; i < 3; i++) {
    ctx.globalAlpha = rng.r(0.10, 0.20);
    dryStroke(ctx, rng,
              [[litX - rng.r(240, 420), litY + rng.r(-40, 40)],
               [litX + rng.r(200, 400), litY + rng.r(-60, 60)]],
              drift(rng, deep ? glow(paper, 0.24) : lift(paper, 0.10), 0.03),
              rng.r(120, 240),
              { fade: 0.8, grain: 0.3, press: 0.3 });
  }
  ctx.globalAlpha = 1;
  }

  // ======= IMPOSSIBLE LIGHT (the immortal's ground alone) =======
  // Four or five ribboned hues crossing one deep panel: the only place
  // the collection breaks the one-chord rule.
  function groundAurora(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig, LG = g.LG;
    const GO = g.GO, board = g.board, deep = g.deep, satUpG = g.satUpG;
    const litX = g.litX, litY = g.litY;
  // ======= IMPOSSIBLE LIGHT (the immortal's ground alone) =======
  // Four or five ribboned hues crossing one deep panel — the only
  // place the collection breaks the one-chord rule, because a
  // superpower is the only thing the palette bends for.
  const night = sink(hueShiftC(paper, rng.r(-16, 16)), rng.r(0.10, 0.26));
  // the impossible light still falls on a real surface: the night is
  // laid as worn coats over the same board every other panel uses, so
  // the immortal belongs to the collection's hand and not to a filter
  paintSupport(ctx, rng, board, [
    { c: sink(hueShiftC(night, rng.r(-40, 40)), rng.r(0.06, 0.20)),
      thr: rng.r(0.93, 0.99), hard: rng.r(2.2, 3.4),
      jit: rng.r(0.10, 0.20), dr: rng.r(0.24, 0.40) },
    { c: glow(hueShiftC(night, rng.r(-30, 30)), rng.r(0.10, 0.26)),
      thr: rng.r(0.66, 0.80), hard: rng.r(2.6, 4.2),
      jit: rng.r(0.12, 0.24), dr: rng.r(0.24, 0.40) },
    { c: night, thr: rng.r(0.40, 0.56), hard: rng.r(4, 8),
      jit: rng.r(0.10, 0.22), dr: rng.r(0.28, 0.46) },
  ], { wearAmp: rng.r(0.90, 1.06), contW: rng.r(0.36, 0.48),
       blotW: rng.r(0.22, 0.32), sweepW: rng.r(0.12, 0.22),
       biteW: rng.r(0.10, 0.18), tooth: rng.r(0.04, 0.08),
       tooth2: rng.r(0.03, 0.06), grainV: rng.r(0.04, 0.08),
       pool: rng.r(0.06, 0.12), fiber: rng.r(12, 24), litX, litY });
  ctx.globalAlpha = 1;
  // the ribbons: broad soft bands of impossible hue sweeping the
  // panel, each built of long dry pulls that follow the band
  // ROUND 905: the aurora chord belongs to the POWER, so two immortals
  // on one sheet cannot share a sky even if they shared a geometry.
  // Fire keeps jonpick25's violet-and-teal sweep. Lightning hangs as
  // a curtain of navy and cadmium. Frost is ice-blue. Flight bursts.
  // Glow is gold-rose. Speed streaks teal-pink.
  const pow = GO.power;
  const fireImm = pow === 'fire';
  const HUES = fireImm
    ? ['#8f7ce8', '#4fd6c0', '#7fd6f2', '#d88ff0', '#6a5ac8', '#48b8a8']
    : pow === 'lightning'
    ? ['#1a3a8a', '#7fd6f2', '#f6e08a', '#bfe6ff', '#4a6ad0', '#ffe08a']
    : pow === 'frost'
    ? ['#8f7ce8', '#a8e8f4', '#d8e8ff', '#6a5ac8', '#7fd6f2', '#e8f4ff']
    : pow === 'flight'
    ? ['#cbb6ff', '#f28fb5', '#f6e08a', '#8f7ce8', '#7fd6f2', '#f2a45e']
    : pow === 'glow'
    ? ['#ffe08a', '#f2a45e', '#f28fb5', '#8f7ce8', '#fff6d8', '#4fd6c0']
    : pow === 'speed'
    ? ['#4fd6c0', '#f28fb5', '#8ff0d8', '#8f7ce8', '#7fd6f2', '#f6e08a']
    : ['#4fd6c0', '#8f7ce8', '#f28fb5', '#f6e08a', '#7fd6f2',
       '#b5f0a0', '#f2a45e', '#d88ff0'];
  const picks = [];
  for (let i = 0; i < 4 + Math.floor(rng.f() * 2); i++)
    picks.push(hx(HUES[(Math.floor(rng.f() * HUES.length) + i * 3) % HUES.length]));
  // ROUND 126: the impossible light had exactly ONE geometry — soft
  // bands sweeping left to right — so twelve immortals in a row read
  // as twelve prints of the same wallpaper. Three geometries now,
  // and the seed commits to one: the SWEEP, the CURTAIN hanging down
  // out of the top of the frame the way a real aurora does, and the
  // BURST radiating out from behind the animal itself.
  const aMode = fireImm || pow === 'speed' ? 'sweep'
              : pow === 'lightning' || pow === 'frost' ? 'curtain'
              : pow === 'flight' || pow === 'glow' ? 'burst'
              : rng.f() < 0.40 ? 'sweep' : rng.f() < 0.55 ? 'curtain'
                                                          : 'burst';
  const bcx = fig ? fig.x + rng.r(-70, 70) : rng.r(300, 700);
  const bcy = fig ? fig.y + rng.r(-70, 70) : rng.r(300, 700);
  // one spine per band, and a perpendicular offset that means the
  // same thing in every geometry
  const spine = (kind, p, off) => {
    if (kind === 'sweep') {
      const y0 = p.a, sl = Math.tan(p.b);
      return [[-160, y0 + off + rng.r(-16, 16)],
              [340, y0 + off + sl * 340 + rng.r(-26, 26)],
              [700, y0 + off + sl * 700 + rng.r(-26, 26)],
              [1160, y0 + off + sl * 1160 + rng.r(-16, 16)]];
    }
    if (kind === 'curtain') {
      // a curtain hangs: it enters the top of the frame, sways, and
      // its foot drifts. The offset moves it sideways.
      const x0 = p.a, sw = p.b;
      return [[x0 + off + rng.r(-10, 10), -180],
              [x0 + off + sw * 0.42 + rng.r(-18, 18), 250],
              [x0 + off + sw + rng.r(-22, 22), 620],
              [x0 + off + sw * 1.5 + rng.r(-14, 14), 1080]];
    }
    // burst: a ray out of the animal, widening as it leaves
    const a = p.a, nx = -Math.sin(a), ny = Math.cos(a);
    const pts = [];
    for (let q = 0; q <= 4; q++) {
      const r2 = 60 + q * 340;
      const sp = off * (0.35 + q * 0.28);
      pts.push([bcx + Math.cos(a) * r2 + nx * sp + rng.r(-14, 14),
                bcy + Math.sin(a) * r2 + ny * sp + rng.r(-14, 14)]);
    }
    return pts;
  };
  picks.forEach((hc, bi) => {
    const par = aMode === 'sweep'
      ? { a: rng.r(-120, 900), b: rng.r(-0.55, 0.55) }
      : aMode === 'curtain'
      ? { a: rng.r(-140, 1080), b: rng.r(-220, 220) }
      : { a: rng.r(0, 6.283), b: 0 };
    const thick = aMode === 'burst' ? rng.r(60, 170) : rng.r(90, 230);
    const nP = 5 + Math.floor(rng.f() * 4);
    for (let i = 0; i < nP; i++) {
      const off = (i / (nP - 1) - 0.5) * thick;
      const a = rng.r(0.20, 0.44) * (1 - Math.abs(off) / thick * 1.05);
      if (a <= 0.03) continue;
      // a ribbon of light is SOFT and broad — the dry-bristle dash
      // train read as scratches, so the band body is one long wet
      // pull and the bristle work is saved for its dry edges
      ctx.globalAlpha = a;
      ribbon(ctx, rng, spine(aMode, par, off),
             drift(rng, mix(hc, night, rng.r(0.16, 0.50)), 0.05),
             rng.r(46, 96),
             { taper: aMode === 'burst' ? 0.5 : 0.1, wob: 0.22, jit: 2,
               step: 22, load: rng.r(0.6, 0.9) });
      ctx.globalAlpha = 1;
    }
    // one hot core along the ribbon's spine, and its dry upper edge
    ctx.globalAlpha = rng.r(0.42, 0.68);
    ribbon(ctx, rng, spine(aMode, par, 0),
           drift(rng, lift(hc, 0.30), 0.04), rng.r(16, 38),
           { taper: aMode === 'burst' ? 0.6 : 0.2, wob: 0.18, jit: 1.6,
             step: 20 });
    ctx.globalAlpha = rng.r(0.24, 0.44);
    dryStroke(ctx, rng, spine(aMode, par, -thick * 0.4),
              drift(rng, mix(hc, night, 0.55), 0.05), rng.r(30, 66),
              { fade: 1.1, grain: 0.6, press: 0.4, step: 7 });
    ctx.globalAlpha = 1;
  });
  // sparks of the same impossible light, scattered where the ribbons
  // cross — small, unblended, countable
  for (let i = 0; i < 60; i++) {
    const c = picks[Math.floor(rng.f() * picks.length) % picks.length];
    ctx.globalAlpha = rng.r(0.28, 0.8);
    dot(ctx, rng.r(0, 1000), rng.r(0, 1000), rng.r(1.6, 6.5),
        drift(rng, lift(c, rng.r(0.1, 0.4)), 0.05));
  }
  ctx.globalAlpha = 1;
  // ...and a handful of real hand STARS (nava03, jonpick25): crossing
  // silver strokes, arm lengths disagreeing, kept clear of the animal
  {
    const starC = mix(hx('#d8dade'), night, rng.r(0.04, 0.18));
    const nS = fireImm ? 6 + Math.floor(rng.f() * 4)
                       : 3 + Math.floor(rng.f() * 4);
    for (let i = 0; i < nS; i++) {
      const sx2 = rng.r(40, 960), sy2 = rng.r(30, 970);
      if (fig && Math.abs(sx2 - fig.x) < fig.rx * 0.9 &&
          Math.abs(sy2 - fig.y) < fig.ry * 0.9) continue;
      starMark(ctx, rng, sx2, sy2, rng.r(9, 22), starC);
    }
    ctx.globalAlpha = 1;
  }
  if (fig) {
    for (let i = 0; i < 8; i++) {
      const a = rng.r(-0.3, Math.PI + 0.3);
      ctx.globalAlpha = rng.r(0.2, 0.4);
      ribbon(ctx, rng,
             [[fig.x + Math.cos(a) * fig.rx * 1.02,
               fig.y + Math.sin(a) * fig.ry * 1.02],
              [fig.x + Math.cos(a + 0.34) * fig.rx * 1.06,
               fig.y + Math.sin(a + 0.34) * fig.ry * 1.06]],
             drift(rng, sink(night, 0.2), 0.05), rng.r(30, 60),
             { end: 1, min: 0.4, wob: 0.5, jit: 2, step: 15 });
    }
    ctx.globalAlpha = 1;
  }
  // ROUND 908: lightning writes on the SKY, not the frame edge.
  // nava01's cadmium zigzag hanging in the open cobalt field, kept
  // clear of the animal so a thumbnail still names the power.
  if (pow === 'lightning') {
    const cad = hx('#f0c21e'), ice = hx('#fbffff');
    const zig = (x0, y0, x1, y1, n) => {
      const pts = [[x0, y0]];
      for (let i = 1; i < n; i++) {
        const t = i / n;
        pts.push([x0 + (x1 - x0) * t + rng.r(-28, 28),
                  y0 + (y1 - y0) * t + rng.r(-12, 12)]);
      }
      pts.push([x1, y1]);
      return pts;
    };
    // a fat cadmium zigzag hanging in the OPEN upper field, not cropped
    // to a frame edge. nava01: yellow leaving the mouth of the sky.
    const xA = fig && fig.x > 500 ? rng.r(120, 340) : rng.r(620, 860);
    const pts = zig(xA, rng.r(-30, 40),
                    xA + rng.r(-90, 90), rng.r(260, 520), 8);
    ctx.globalAlpha = 0.62;
    ribbon(ctx, rng, pts, mix(cad, ice, 0.25), rng.r(36, 58),
           { taper: 0.40, wob: 0.08, jit: 1.1, step: 6 });
    ctx.globalAlpha = 0.95;
    ribbon(ctx, rng, pts, cad, rng.r(16, 26),
           { taper: 0.50, wob: 0.06, jit: 0.9, step: 5 });
    ribbon(ctx, rng, pts, ice, rng.r(5, 9),
           { taper: 0.7, wob: 0.04, jit: 0.7, step: 5 });
    ctx.globalAlpha = 1;
    sprayStroke(ctx, rng, pts, rng.r(28, 44), mix(cad, ice, 0.35),
                { dens: 0.55, a: 0.32, spread: 0.46 });
    spray(ctx, rng, xA + rng.r(-60, 60), rng.r(40, 160), rng.r(80, 140),
          mix(hx('#f4f2ea'), night, 0.08), 1.2,
          { a: 0.55, spread: 0.42, elx: 1.5, ely: 0.7 });
  }
  }

  // ======= SCOURED WASH (jonpick11) — the default language =======
  // Five geological coats over the bare board, then years of handling:
  // long dry pulls, panel seams, scratches, pigment crowding the dog.
  function groundScoured(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig, LG = g.LG;
    const GO = g.GO, board = g.board, deep = g.deep, satUpG = g.satUpG;
    const litX = g.litX, litY = g.litY;
  const nL = 4 + (rng.chance(0.55) ? 1 : 0);
  const spin = rng.chance(0.5) ? 1 : -1;
  const coats = [];
  for (let i = 0; i < nL; i++) {
    const t = i / (nL - 1);
    // the buried coats walk a long way round the hue circle from the
    // one on top: what surfaces has to be a genuinely other colour,
    // or the wearing reads as a value filter
    let c = hueShiftC(paper, spin * rng.r(14, 58) * (1 - t) + rng.r(-12, 12));
    if (i === 0)
      c = deep ? glow(c, rng.r(0.22, 0.44)) : sink(c, rng.r(0.28, 0.48));
    else if (i === 1)
      c = mix(lift(c, deep ? rng.r(0.24, 0.46) : rng.r(0.44, 0.72)),
              board, rng.r(0.08, 0.32));
    else if (i === nL - 1)
      c = deep ? sink(c, rng.r(0.00, 0.12)) : satUpG(c, rng.r(0.12, 0.34));
    else
      c = deep ? glow(c, rng.r(0.04, 0.18)) : sink(c, rng.r(0.03, 0.16));
    coats.push(LG(satUpG(c, deep ? rng.r(0.04, 0.14) : rng.r(0.10, 0.32))));
  }
  // the top coat gives way at a third of the wear, the underpaint
  // only at the very end of it; at the worn-through points the board
  const topT = rng.r(0.34, 0.50), botT = rng.r(0.93, 0.995);
  const cuts = paintSupport(ctx, rng, board,
    coats.map((c, i) => ({
      c,
      thr: botT + (topT - botT) * (i / (nL - 1)),
      // the deep strata surface as soft broad continents, the top
      // coat breaks up granular where the rag bit it
      // even the broad continents break granular at their edge: a
      // soft blob is fog, and fog is not abrasion
      hard: rng.r(3.6, 5.4) + (i / (nL - 1)) * rng.r(2.0, 6.0),
      jit: rng.r(0.09, 0.22),
      dr: rng.r(0.26, 0.46),
    })),
    // continents and long sweeps carry it; the blotch is the middle
    // register underneath them, never the whole surface. Even speckle
    // is the failure the ground bar names by name.
    { wearAmp: rng.r(0.94, 1.12) * (GO.wear || 1), contW: rng.r(0.40, 0.54),
      blotW: rng.r(0.15, 0.24), sweepW: rng.r(0.18, 0.32),
      biteW: rng.r(0.13, 0.21), tooth: rng.r(0.05, 0.09),
      tooth2: rng.r(0.03, 0.06), grainV: rng.r(0.04, 0.09),
      pool: rng.r(0.07, 0.14), fiber: rng.r(14, 28),
      litX, litY,
      panels: 1 });

  // THE SEAM. Where two panels meet the wear stops and starts again,
  // and a hair of shadow collects in the join.
  cuts.forEach(u => {
    const xx = u * 1000;
    ctx.globalAlpha = rng.r(0.20, 0.42);
    dryStroke(ctx, rng,
              [[xx + rng.r(-4, 4), -40], [xx + rng.r(-6, 6), 480],
               [xx + rng.r(-4, 4), 1040]],
              drift(rng, sink(coats[0], rng.r(0.18, 0.40)), 0.05),
              rng.r(4, 11),
              { fade: rng.r(0.5, 1.2), grain: rng.r(0.4, 0.75),
                press: rng.r(0.3, 0.7), step: 8 });
    ctx.globalAlpha = rng.r(0.10, 0.22);
    dryStroke(ctx, rng,
              [[xx + rng.r(6, 20), -40], [xx + rng.r(6, 22), 1040]],
              drift(rng, lift(coats[1], 0.2), 0.05), rng.r(10, 26),
              { fade: 0.9, grain: 0.6, press: 0.4, step: 10 });
    ctx.globalAlpha = 1;
  });

  // THE RAG ITSELF. Three to six pulls the whole width of the panel,
  // dragged in an earlier coat's colour, dry from the first inch —
  // the hand that did the wearing, left on top of what it did.
  const nSw = 3 + Math.floor(rng.f() * 4);
  for (let i = 0; i < nSw; i++) {
    const und = coats[Math.floor(rng.f() * Math.max(1, nL - 1))];
    const yy = rng.r(-60, 1060), tilt = rng.r(-0.09, 0.09);
    ctx.globalAlpha = rng.r(0.16, 0.40);
    dryStroke(ctx, rng,
              [[-170, yy + rng.r(-18, 18)],
               [rng.r(180, 380), yy + tilt * 280 + rng.r(-34, 34)],
               [rng.r(620, 830), yy + tilt * 720 + rng.r(-34, 34)],
               [1170, yy + tilt * 1160 + rng.r(-18, 18)]],
              drift(rng, und, 0.06), rng.r(60, 190),
              { fade: rng.r(0.7, 1.5), grain: rng.r(0.62, 0.92),
                press: rng.r(0.3, 0.8), pAmp: rng.r(0.4, 0.7),
                step: rng.r(6, 10) });
  }
  ctx.globalAlpha = 1;

  // SCRATCHES: a dozen hairline runs where something harder than a
  // rag went across the panel and took the paint down to the board
  for (let i = 0; i < 10 + Math.floor(rng.f() * 12); i++) {
    const yy = rng.r(-20, 1020), x0 = rng.r(-80, 700),
          ln = rng.r(90, 620), tl = rng.r(-0.05, 0.05);
    ctx.globalAlpha = rng.r(0.10, 0.30);
    ribbon(ctx, rng,
           [[x0, yy], [x0 + ln * 0.5, yy + tl * ln * 0.5 + rng.r(-3, 3)],
            [x0 + ln, yy + tl * ln]],
           drift(rng, rng.chance(0.6) ? lift(board, rng.r(0.06, 0.3))
                                      : sink(coats[0], rng.r(0.1, 0.3)), 0.05),
           rng.r(1.1, 3.4),
           { taper: 0.6, wob: 0.2, jit: 1.1, step: 18 });
  }
  ctx.globalAlpha = 1;

  // ONE HANDLED PASSAGE: a place somebody leaned on, rubbed with a
  // thumb, and never cleaned up — jonpick10's kept mistake
  for (let i = 0; i < 1 + Math.floor(rng.f() * 3); i++) {
    const sx = rng.r(70, 930), sy = rng.r(70, 930);
    for (let q = 0; q < 3; q++) {
      ctx.globalAlpha = rng.r(0.08, 0.22);
      dryStroke(ctx, rng,
                [[sx + rng.r(-140, -40), sy + q * 22 + rng.r(-14, 14)],
                 [sx + rng.r(-30, 30), sy + q * 22 + rng.r(-18, 18)],
                 [sx + rng.r(50, 170), sy + q * 22 + rng.r(-14, 14)]],
                drift(rng, mix(coats[nL - 1], board, rng.r(0.3, 0.7)), 0.06),
                rng.r(26, 62),
                { fade: rng.r(0.8, 1.6), grain: rng.r(0.55, 0.9),
                  press: rng.r(0.35, 0.8) });
    }
  }
  ctx.globalAlpha = 1;

  // THE POOL AT THE DOG: where the worn field meets the animal the
  // pigment settles and darkens (jonpick9's crowding)
  if (fig) {
    const poolC = LG(satUpG(sink(paper, deep ? rng.r(0.16, 0.28)
                                            : rng.r(0.12, 0.20)),
                            deep ? 0.10 : 0.24));
    const nh = 7 + Math.floor(rng.f() * 3);
    for (let i = 0; i < nh; i++) {
      const a0 = rng.chance(0.72) ? rng.r(-0.2, Math.PI + 0.2)
                                  : rng.r(Math.PI, Math.PI * 2);
      const span = rng.r(0.20, 0.48);
      const rm = rng.r(1.005, 1.09);
      const seg = [];
      for (let k = 0; k <= 4; k++) {
        const a = a0 + span * k / 4;
        seg.push([fig.x + Math.cos(a) * fig.rx * (rm + rng.r(-0.012, 0.012)),
                  fig.y + Math.sin(a) * fig.ry * (rm + rng.r(-0.012, 0.012))]);
      }
      if (seg[0][1] < -60 || seg[0][1] > 1080) continue;
      ctx.globalAlpha = deep ? rng.r(0.24, 0.44) : rng.r(0.14, 0.28);
      ribbon(ctx, rng, seg, drift(rng, poolC, 0.05), rng.r(30, 66),
             { end: rng.r(0.7, 1.2), min: 0.4, wob: 0.5, jit: 2, step: 14,
               load: rng.r(0.5, 0.8) });
    }
    ctx.globalAlpha = 1;
  }
  }

  // ROUND 132: heaven is a PLACE. This is deliberately separate from
  // groundWhite's support handling: the support remains almost bare and
  // this entire little kingdom is laid on it afterwards, the way Nava
  // puts a complete event over one innocent field. The dog will cover the
  // middle of it later, so the cloud bank and castle feel inhabited rather
  // than printed behind the portrait.
  function paintAngelKingdom(ctx, rng, paper, fig) {
    const white = mix(hx('#fffefa'), paper, 0.02);
    const milk = mix(hx('#f3f4f6'), paper, 0.06);
    const cloudShadow = mix(hx('#8e96a6'), paper, 0.10);
    const castleFill = mix(hx('#eceef2'), paper, 0.06);
    const castleShadow = mix(hx('#6a7180'), paper, 0.08);
    const gold = hx(ANGEL_GOLD);

    // A cloud is stacked aerosol, not a row of vector circles: a broad
    // cool undershadow first, then overlapping dense white cores and a
    // separated fringe where the support breathes through.
    const cloudMass = (cx, cy, rw, front) => {
      spray(ctx, rng, cx, cy + rw * 0.22, rw * 1.10, cloudShadow,
            front ? 1.00 : 0.66,
            { a: front ? 0.40 : 0.26, spread: 0.46,
              elx: 1.72, ely: 0.55, settle: 0.08 });
      const n = front ? 5 : 4;
      for (let i = 0; i < n; i++) {
        const t = n === 1 ? 0 : i / (n - 1) * 2 - 1;
        const rr = rw * rng.r(0.48, 0.76) * (1 - Math.abs(t) * 0.16);
        spray(ctx, rng,
              cx + t * rw * rng.r(0.52, 0.70),
              cy - rr * rng.r(0.06, 0.38), rr,
              i % 2 ? white : milk, front ? 1.85 : 1.25,
              { a: front ? 0.82 : 0.58, spread: 0.34,
                elx: rng.r(1.05, 1.30), ely: rng.r(0.72, 0.94),
                settle: 0.035 });
      }
    };

    // Two high, barely found cloud witnesses keep the upper white from
    // reading as an empty gray gradient while leaving most of it light.
    const highSide = rng.chance(0.5) ? -1 : 1;
    cloudMass(highSide < 0 ? rng.r(90, 230) : rng.r(770, 910),
              rng.r(105, 245), rng.r(66, 104), false);
    if (rng.chance(0.55))
      cloudMass(highSide < 0 ? rng.r(720, 890) : rng.r(110, 280),
                rng.r(280, 410), rng.r(48, 82), false);

    // The castle always exists, but its silhouette changes: one keep,
    // a keep with two flanking towers, or three unequal towers breaking
    // through different levels of cloud. It stays small and softer than
    // the dog. Put it on the side with the most available field.
    const castleSide = fig && fig.x < 500 ? 1 : fig && fig.x > 500 ? -1
                     : (rng.chance(0.5) ? -1 : 1);
    // Put the architecture in the OPEN upper side-field. The previous
    // version planted it at the dog's shoulder line, where a large wing
    // could honestly cover every stone. Heaven may be pale, but the castle
    // is a mandate and must survive at 64 pixels.
    const castleX = castleSide < 0 ? rng.r(70, 175) : rng.r(825, 930);
    // nava04: the kingdom sits IN the cloud bank along the bottom,
    // breaking through it, not hiding in a wingtip. Lower-outer
    // corners are the one place a bust wing does not claim.
    const bankY = rng.r(780, 890);
    const unit = rng.r(62, 92);
    const castleY = bankY - unit * rng.r(0.15, 0.45);
    const towers = rng.pick([1, 2, 3]);
    const towerData = [];
    for (let i = 0; i < towers; i++) {
      const off = towers === 1 ? 0 : (i - (towers - 1) / 2) * unit * 1.18;
      const tw = unit * rng.r(i === Math.floor(towers / 2) ? 0.88 : 0.68,
                              i === Math.floor(towers / 2) ? 1.14 : 0.92);
      const th = unit * rng.r(i === Math.floor(towers / 2) ? 2.4 : 1.55,
                              i === Math.floor(towers / 2) ? 3.45 : 2.55);
      const bx = castleX + off, top = castleY - th;
      const cren = Math.max(3, Math.round(tw / 17));
      const P = [[bx - tw / 2, castleY + unit * 0.26], [bx - tw / 2, top]];
      const step = tw / cren;
      for (let k = 0; k < cren; k++) {
        const x0 = bx - tw / 2 + k * step;
        P.push([x0, top], [x0, top - unit * 0.22],
               [x0 + step * 0.54, top - unit * 0.22],
               [x0 + step * 0.54, top]);
      }
      P.push([bx + tw / 2, top], [bx + tw / 2, castleY + unit * 0.26]);
      paintShape(ctx, rng, P, mix(castleFill, castleShadow, 0.18),
                 { n: 4, szMul: 0.46, drift: 0.04, ang: Math.PI / 2 });
      ctx.globalAlpha = rng.r(0.78, 0.96);
      oilStick(ctx, rng, P.slice(0, -1), mix(hx('#4a5160'), castleShadow, 0.3),
               rng.r(6.5, 10.5),
               { dbl: 0.75, over: 14, tooth: 0.24, wob: 1.8, a: 0.90 });
      ctx.globalAlpha = 1;
      // One door is enough to make a castle. It is sprayed and distant,
      // not architectural rendering.
      spray(ctx, rng, bx, castleY - unit * 0.04, unit * 0.18,
            castleShadow, 1.25,
            { a: 0.50, spread: 0.34, elx: 0.72, ely: 1.40 });
      towerData.push({ bx: bx, top: top, tw: tw, th: th });
    }
    // A connecting wall, sometimes mostly swallowed by the bank.
    if (towerData.length > 1) {
      const x0 = towerData[0].bx, x1 = towerData[towerData.length - 1].bx;
      const wy = castleY - unit * rng.r(0.42, 0.70);
      ctx.globalAlpha = 0.52;
      drawStroke(ctx, rng, [[x0, wy], [(x0 + x1) / 2, wy + rng.r(-5, 7)],
                            [x1, wy]],
                 { color: castleFill, w: unit * 0.34, fade: 0.58,
                   grain: 0.46, press: 0.25 });
      ctx.globalAlpha = 1;
    }

    // Leaf catches exactly one tower edge. It is small and saturated,
    // with no beige field behind it: metal on white.
    const litTower = towerData[rng.pick(towerData.map((_, i) => i))];
    const gx = litTower.bx + castleSide * litTower.tw * 0.46;
    ctx.globalAlpha = 1;
    drawStroke(ctx, rng,
               [[gx, litTower.top - unit * 0.18],
                [gx + castleSide * rng.r(1, 4),
                 litTower.top + litTower.th * rng.r(0.42, 0.72)]],
               { color: gold, w: rng.r(7, 12), fade: 0.42,
                 grain: 0.16, press: 0.22 });
    spray(ctx, rng, gx, litTower.top - unit * 0.10, unit * 0.22, gold, 0.9,
          { a: 0.55, spread: 0.40, elx: 0.7, ely: 1.3 });
    ctx.globalAlpha = 1;

    // One private cloud carries the castle. Laid after the towers, it
    // swallows their feet and sometimes half a gate—the architecture is
    // breaking through heaven, not sitting on an invisible shelf.
    cloudMass(castleX, castleY + unit * 0.34, unit * 1.08, false);

    // The front bank crosses the whole lower field. Different lobe sizes
    // and a wandering baseline prevent sixteen identical cloud skylines.
    let x = rng.r(-90, -20), idx = 0;
    while (x < 1080 && idx++ < 11) {
      const rw = rng.r(70, 126);
      cloudMass(x + rw * 0.72, bankY + rng.r(-28, 42), rw, true);
      x += rw * rng.r(0.94, 1.46);
    }
    // Leaf-bright sparks, small against a large white field.
    for (let i = 0; i < 5; i++) {
      const sx = castleX + rng.r(-1.8, 1.8) * unit;
      const sy = castleY - rng.r(0.4, 3.6) * unit;
      ctx.globalAlpha = rng.r(0.80, 1.0);
      starMark(ctx, rng, sx, sy, rng.r(9, 16), gold);
    }
    ctx.globalAlpha = 1;
  }

  // ======= BARE WHITE SUPPORT (the angel's ground alone) — round 130 ===
  // The highest-key ground in the collection and close to bare white
  // support: the light comes from above and slightly behind, so the
  // edges of the dog dissolve into it. No gold, no ochre, no tan — a
  // beige angel has failed the fate. What little incident there is:
  // the faintest worn breath of cool gray, a whisper of blush, and two
  // soft shadows gathering low where the light cannot reach.
  function groundWhite(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig;
    const GO = g.GO, board = g.board, litX = g.litX;
    const wht = mix(board, hx('#fbfaf7'), rng.r(0.45, 0.75));
    paintSupport(ctx, rng, wht, [
      // cool gray-lilac breath only — the warm blush coat was walking
      // heaven into beige
      { c: mix(hx('#c5c8d2'), hx('#f4f5f7'), rng.r(0.45, 0.70)),
        thr: rng.r(0.955, 0.99), hard: rng.r(2.4, 3.6),
        jit: rng.r(0.06, 0.14), dr: rng.r(0.08, 0.16) },
      { c: mix(hx('#e8eaee'), hx('#f7f7f4'), rng.r(0.30, 0.60)),
        thr: rng.r(0.62, 0.80), hard: rng.r(2.8, 4.2),
        jit: rng.r(0.05, 0.12), dr: rng.r(0.08, 0.14) },
      { c: mix(hx('#f8f7f4'), hx('#fcfbf8'), rng.r(0.30, 0.70)),
        thr: rng.r(0.32, 0.48), hard: rng.r(3.5, 6),
        jit: rng.r(0.04, 0.10), dr: rng.r(0.06, 0.12) },
    ], { wearAmp: rng.r(0.50, 0.70), contW: rng.r(0.42, 0.54),
         blotW: rng.r(0.12, 0.18), sweepW: rng.r(0.18, 0.30),
         biteW: rng.r(0.06, 0.12), tooth: rng.r(0.02, 0.05),
         tooth2: rng.r(0.015, 0.04), grainV: rng.r(0.02, 0.05),
         pool: rng.r(0.03, 0.07), fiber: rng.r(8, 16),
         litX: litX, litY: rng.r(-80, 60) });
    ctx.globalAlpha = 1;
    // the light stands ABOVE AND BEHIND: the panel brightens toward the
    // top with three wide dry sweeps of near-pure white
    for (let i = 0; i < 3; i++) {
      const yy = rng.r(30, 300);
      ctx.globalAlpha = rng.r(0.16, 0.30);
      dryStroke(ctx, rng,
                [[rng.r(-80, 60), yy + rng.r(-20, 20)],
                 [500, yy + rng.r(-30, 30)],
                 [rng.r(940, 1080), yy + rng.r(-20, 20)]],
                hx('#fbfaf6'), rng.r(120, 220),
                { fade: 0.7, grain: 0.3, press: 0.3 });
    }
    // ...and the shadow it cannot reach gathers low in the corners,
    // barely: a breath of cool gray that seats the figure in the light
    [-1, 1].forEach(sd => {
      const cxr = sd < 0 ? rng.r(30, 190) : rng.r(810, 970);
      ctx.globalAlpha = rng.r(0.07, 0.15);
      dryStroke(ctx, rng,
                [[cxr - sd * rng.r(60, 140), rng.r(870, 960)],
                 [cxr + sd * rng.r(160, 320), rng.r(900, 990)]],
                mix(hx('#a8a7b4'), paper, 0.4), rng.r(90, 170),
                { fade: 0.8, grain: 0.4, press: 0.3 });
    });
    ctx.globalAlpha = 1;
    // ROUND 989: the light itself, drawn — a sparse curtain of white and
    // gold-tinted white falling from above the kingdom, and a breath of
    // gold grit where it lands. The sky stays white; the gold is thread.
    lightCurtain(ctx, rng, {
      hues: [mix(hx(ANGEL_GOLD), hx('#fbfaf6'), rng.r(0.52, 0.66)),
             hx('#fbfaf6'), mix(hx('#c5c8d2'), hx('#f4f5f7'), 0.5)],
      dir: Math.PI / 2 + rng.r(-0.22, 0.22),
      cx: Math.max(120, Math.min(880, litX)), cy: 320,
      span: rng.r(440, 560), len: 1100, n: 36 + Math.floor(rng.f() * 12),
      w: [2.4, 6.5], a: [0.10, 0.28], fall: 0.65, bow: 0.04,
      clip: [0, 700], dry: 0.3 });
    gritCloud(ctx, rng, Math.max(80, Math.min(920, litX)), rng.r(40, 140),
              rng.r(50, 90), [mix(hx(ANGEL_GOLD), hx('#fbfaf6'), 0.35),
                              hx('#fbfaf6')], { a: 0.22, dens: 0.6 });
    gritPoints(ctx, rng, 6 + Math.floor(rng.f() * 7),
               [mix(hx(ANGEL_GOLD), hx('#fbfaf6'), 0.25)], fig, 20, 600);
    ctx.globalAlpha = 1;
    paintAngelKingdom(ctx, rng, paper, fig);
  }

  // ======= THE IMMORTAL'S HAND (round 989) ==============================
  // The artist's favourite pictures are the round 980 immortals, and what
  // they have that every other fate's ground lacked is LIGHT INSIDE THE
  // PAINT: a curtain of long parallel translucent streaks in two or three
  // hues at once, each a little different in length and weight, with
  // sprayed grit sitting where the light is. Nothing blended to mud; the
  // depth is strokes showing through strokes. From this round on that is
  // ONE engine every fate's ground routes through. The fate branch picks
  // the weather (hues, direction, loudness); the hand never changes.
  //
  //   lightCurtain(ctx, rng, o)
  //     o.hues   two or three colours the streaks alternate between
  //     o.dir    streak direction in radians (PI/2 falls straight down,
  //              0 runs with a band)
  //     o.cx,cy  centre of the curtain; o.span its width ACROSS the streaks
  //     o.len    streak length scale (default 900: off both edges)
  //     o.n      number of streaks
  //     o.w      [min,max] streak width;  o.a [min,max] alpha
  //     o.clip   optional [y0,y1]: the curtain is confined to a band
  //     o.fall   0..1 how much the streaks crowd the centre (default 0.6)
  //     o.bow    curvature of each streak as a share of its length
  //     o.dry    chance a streak is laid as a dry bristle pull instead
  function lightCurtain(ctx, rng, o) {
    const hues = o.hues;
    const dir = o.dir === undefined ? Math.PI / 2 : o.dir;
    const dx = Math.cos(dir), dy = Math.sin(dir), nx = -dy, ny = dx;
    const cx = o.cx === undefined ? 500 : o.cx;
    const cy = o.cy === undefined ? 500 : o.cy;
    const span = o.span || 400, len = o.len || 900;
    const n = o.n || 60;
    const w = o.w || [3, 10], a = o.a || [0.16, 0.42];
    const fall = o.fall === undefined ? 0.6 : o.fall;
    const bow = o.bow === undefined ? 0.06 : o.bow;
    const dry = o.dry === undefined ? 0.18 : o.dry;
    const gA = ctx.globalAlpha;
    if (o.clip) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(-80, o.clip[0], 1160, o.clip[1] - o.clip[0]);
      ctx.clip();
    }
    for (let i = 0; i < n; i++) {
      // across the span: a hump toward the centre, blended with uniform
      const uT = (rng.f() + rng.f() + rng.f()) / 1.5 - 1;
      const uU = rng.f() * 2 - 1;
      const u = uU * (1 - fall) + uT * fall;
      const off = u * span * 0.5;
      const s0 = (rng.f() - 0.5) * len * 0.9;
      const L = len * rng.r(0.30, 1.0);
      const bw = bow * L * rng.r(-1, 1);
      const pts = [];
      for (let q = 0; q <= 3; q++) {
        const t = q / 3;
        const s = s0 + (t - 0.5) * L;
        const b = Math.sin(t * Math.PI) * bw + rng.r(-3, 3);
        pts.push([cx + dx * s + nx * (off + b), cy + dy * s + ny * (off + b)]);
      }
      const col = drift(rng, hues[Math.floor(rng.f() * hues.length) % hues.length],
                        0.04);
      const wi = rng.r(w[0], w[1]) * (rng.chance(0.12) ? rng.r(1.8, 2.6) : 1);
      const wgt = 1 - Math.abs(u) * fall * 0.55;
      ctx.globalAlpha = gA * rng.r(a[0], a[1]) * wgt;
      if (rng.f() < dry) {
        dryStroke(ctx, rng, pts, col, wi * 1.6,
                  { fade: rng.r(0.8, 1.2), grain: 0.55, press: 0.45,
                    a: 0.8 });
      } else {
        ribbon(ctx, rng, pts, col, wi,
               { taper: 0.15, wob: 0.24, jit: 1.2, step: 16, min: 0.5,
                 load: rng.r(0.5, 0.95),
                 end: rng.chance(0.4) ? rng.r(0.6, 1.3) : 0 });
      }
    }
    ctx.globalAlpha = gA;
    if (o.clip) ctx.restore();
  }

  // gritCloud: sprayed droplets in two hues, dense at a core and thinning
  // to countable separate points well past it. Grit is what makes the
  // streaks read as atmosphere rather than stripes (jonpick38).
  function gritCloud(ctx, rng, x, y, r, hues, o) {
    o = o || {};
    const gA = ctx.globalAlpha;
    const dens = o.dens || 1, a0 = o.a === undefined ? 0.55 : o.a;
    const elx = o.elx || 1, ely = o.ely || 1;
    spray(ctx, rng, x, y, r, hues[0], 1.25 * dens,
          { a: a0, spread: 0.36, elx: elx, ely: ely, settle: 0.05 });
    if (hues[1])
      spray(ctx, rng, x + rng.r(-r * 0.35, r * 0.35), y + rng.r(-r * 0.35, r * 0.35),
            r * 0.72, hues[1], 1.05 * dens,
            { a: a0 * 0.9, spread: 0.42, elx: elx, ely: ely, settle: 0.04 });
    const nP = Math.round(r * 0.40 * dens);
    for (let i = 0; i < nP; i++) {
      const ang = rng.f() * 6.28318, d = r * (0.55 + rng.f() * 1.7);
      const c = hues[Math.floor(rng.f() * hues.length) % hues.length];
      ctx.globalAlpha = gA * rng.r(0.30, 0.92) * a0 * 1.4;
      dot(ctx, x + Math.cos(ang) * d * elx, y + Math.sin(ang) * d * ely,
          rng.r(1.1, 4.0), c);
    }
    ctx.globalAlpha = gA;
  }

  // scattered points across a region, clear of the animal: stars on the
  // immortal, dust or pollen or rain on a living dog
  function gritPoints(ctx, rng, n, hues, fig, y0, y1) {
    const gA = ctx.globalAlpha;
    for (let i = 0; i < n; i++) {
      const px = rng.r(10, 990), py = rng.r(y0 === undefined ? 10 : y0,
                                            y1 === undefined ? 990 : y1);
      if (fig && Math.abs(px - fig.x) < fig.rx * 0.9 &&
          Math.abs(py - fig.y) < fig.ry * 0.9) continue;
      ctx.globalAlpha = gA * rng.r(0.3, 0.95);
      dot(ctx, px, py, rng.r(1.0, 3.6),
          hues[Math.floor(rng.f() * hues.length) % hues.length]);
    }
    ctx.globalAlpha = gA;
  }

  // ======= THE GLYPH CAST (round 989) ===================================
  // A dog's mythology, drawn the way a child draws on a wall: a few oil
  // stick or spray gestures with seeded wobble, unshaded, no interior
  // detail. Nava's cast is sharks and angels; ours is bolts, bones,
  // hydrants, arrows, X-outs, suns and the owner. Rolled per seed from a
  // paint stream, never a census trait. Creatures come from sprayCreature.
  const GLYPH_KINDS = ['bolt', 'bone', 'hydrant', 'arrow', 'xout', 'star',
                       'sun', 'moon', 'cloud', 'heart', 'spiral', 'tally',
                       'ladder', 'paw', 'ball', 'dish', 'eye', 'sword',
                       'flame', 'rain', 'rainbow', 'worm', 'fish', 'grid',
                       'dragon', 'snake', 'rabbit', 'bird'];
  function drawGlyph(ctx, rng, kind, x, y, s, color, opt) {
    opt = opt || {};
    const w = Math.max(3.4, s * (opt.wMul || 0.075));
    const so = { dbl: opt.dbl === undefined ? 0.45 : opt.dbl,
                 over: s * 0.10, tooth: 0.30, wob: Math.max(1.6, s * 0.03),
                 a: opt.a === undefined ? 0.9 : opt.a };
    const stick = (pts, wm) => oilStick(ctx, rng, pts, color, w * (wm || 1), so);
    const P = (ax, ay) => [x + ax * s, y + ay * s];
    if (kind === 'dragon' || kind === 'snake' || kind === 'rabbit' ||
        kind === 'bird') {
      sprayCreature(ctx, rng, kind, x, y, s * 0.8, color);
      return;
    }
    if (kind === 'owner') {
      // the stick person, nava03: the witness that makes the dog huge
      stickWitness(ctx, rng, x, y + s * 0.5, s * 0.95, color);
      return;
    }
    if (kind === 'bolt') {
      stick([P(0.05, -0.55), P(-0.14, -0.10), P(0.06, -0.06),
             P(-0.10, 0.50)], 1.15);
    } else if (kind === 'bone') {
      stick([P(-0.42, 0), P(0.42, 0)], 1.3);
      [-1, 1].forEach(sd => {
        stick([P(sd * 0.42, -0.16), P(sd * 0.52, -0.05), P(sd * 0.42, 0)]);
        stick([P(sd * 0.42, 0.16), P(sd * 0.52, 0.05), P(sd * 0.42, 0)]);
      });
    } else if (kind === 'hydrant') {
      stick([P(-0.16, 0.5), P(-0.16, -0.25), P(-0.06, -0.45), P(0.06, -0.45),
             P(0.16, -0.25), P(0.16, 0.5)]);
      stick([P(-0.34, -0.05), P(0.34, -0.05)], 1.2);
      stick([P(-0.28, 0.5), P(0.28, 0.5)], 1.2);
    } else if (kind === 'arrow') {
      const ang = opt.ang === undefined ? rng.r(-0.6, 0.6) : opt.ang;
      const c = Math.cos(ang), sn = Math.sin(ang);
      const Q = (ax, ay) => [x + (ax * c - ay * sn) * s, y + (ax * sn + ay * c) * s];
      stick([Q(-0.5, 0), Q(0.5, 0)]);
      stick([Q(0.28, -0.20), Q(0.5, 0), Q(0.28, 0.20)]);
    } else if (kind === 'xout') {
      // a mark drawn, struck through and left: a small ring crossed out
      const ring = [];
      for (let k = 0; k <= 8; k++) {
        const a = -0.5 + k / 8 * 6.1;
        ring.push(P(Math.cos(a) * 0.28, Math.sin(a) * 0.26));
      }
      stick(ring, 0.9);
      stick([P(-0.42, -0.40), P(0.44, 0.42)], 1.2);
      stick([P(0.40, -0.44), P(-0.44, 0.40)], 1.2);
    } else if (kind === 'star') {
      // five-point scribble star, one gesture
      const pts = [];
      for (let k = 0; k <= 5; k++) {
        const a = -Math.PI / 2 + k * 4 * Math.PI / 5;
        pts.push(P(Math.cos(a) * 0.5, Math.sin(a) * 0.5));
      }
      stick(pts);
    } else if (kind === 'sun') {
      const ring = [];
      for (let k = 0; k <= 10; k++) {
        const a = k / 10 * 6.4;
        ring.push(P(Math.cos(a) * 0.24, Math.sin(a) * 0.24));
      }
      stick(ring);
      const nR = 6 + Math.floor(rng.f() * 4);
      for (let k = 0; k < nR; k++) {
        const a = k / nR * 6.283 + rng.r(-0.2, 0.2);
        stick([P(Math.cos(a) * 0.32, Math.sin(a) * 0.32),
               P(Math.cos(a) * rng.r(0.46, 0.62), Math.sin(a) * rng.r(0.46, 0.62))],
              0.9);
      }
    } else if (kind === 'moon') {
      const pts = [];
      for (let k = 0; k <= 8; k++) {
        const a = -1.2 + k / 8 * 4.6;
        pts.push(P(Math.cos(a) * 0.36, Math.sin(a) * 0.36));
      }
      for (let k = 8; k >= 0; k--) {
        const a = -1.2 + k / 8 * 4.6;
        pts.push(P(Math.cos(a) * 0.22 + 0.16, Math.sin(a) * 0.24));
      }
      stick(pts);
    } else if (kind === 'cloud') {
      const pts = [];
      for (let k = 0; k <= 5; k++) {
        const a = Math.PI - k / 5 * Math.PI;
        pts.push(P(Math.cos(a) * 0.5 + (k % 2 ? 0 : 0.02),
                   -Math.sin(a) * (k % 2 ? 0.34 : 0.18) - 0.02));
      }
      stick(pts.concat([P(0.5, 0.14), P(-0.5, 0.14), P(-0.5, 0)]));
    } else if (kind === 'heart') {
      stick([P(0, 0.42), P(-0.46, -0.05), P(-0.30, -0.36), P(0, -0.14),
             P(0.30, -0.36), P(0.46, -0.05), P(0, 0.42)]);
    } else if (kind === 'spiral') {
      const pts = [];
      for (let k = 0; k <= 26; k++) {
        const a = k / 26 * 6.283 * 2.4, r = 0.06 + k / 26 * 0.42;
        pts.push(P(Math.cos(a) * r, Math.sin(a) * r));
      }
      stick(pts, 0.9);
    } else if (kind === 'tally') {
      const nT = 4 + Math.floor(rng.f() * 3);
      for (let k = 0; k < nT; k++)
        stick([P(-0.40 + k * 0.17, -0.34 + rng.r(-0.04, 0.04)),
               P(-0.40 + k * 0.17 + rng.r(-0.03, 0.03), 0.34)]);
      if (nT >= 5) stick([P(-0.52, 0.30), P(0.40, -0.30)], 1.1);
    } else if (kind === 'ladder') {
      stick([P(-0.18, 0.6), P(-0.16, -0.6)]);
      stick([P(0.18, 0.6), P(0.16, -0.6)]);
      for (let k = 0; k < 5; k++)
        stick([P(-0.2, -0.5 + k * 0.25), P(0.2, -0.5 + k * 0.25)], 0.9);
    } else if (kind === 'paw') {
      const pad = (ax, ay, r) => spray(ctx, rng, x + ax * s, y + ay * s, r * s,
                                       color, 1.3, { a: 0.85, spread: 0.30 });
      pad(0, 0.14, 0.20);
      pad(-0.26, -0.14, 0.09); pad(-0.09, -0.26, 0.09);
      pad(0.09, -0.26, 0.09); pad(0.26, -0.14, 0.09);
    } else if (kind === 'ball') {
      const ring = [];
      for (let k = 0; k <= 12; k++) {
        const a = k / 12 * 6.5;
        ring.push(P(Math.cos(a) * 0.32, Math.sin(a) * 0.32));
      }
      stick(ring);
      // the seam
      stick([P(-0.28, -0.14), P(-0.08, 0.02), P(0.10, 0.02), P(0.28, -0.14)], 0.8);
    } else if (kind === 'dish') {
      stick([P(-0.5, -0.1), P(-0.4, 0.22), P(0.4, 0.22), P(0.5, -0.1)]);
      stick([P(-0.5, -0.1), P(0.5, -0.1)], 0.9);
      spray(ctx, rng, x, y - s * 0.12, s * 0.18, color, 1.1,
            { a: 0.7, spread: 0.36, elx: 1.4, ely: 0.5 });
    } else if (kind === 'eye') {
      stick([P(-0.5, 0), P(-0.2, -0.26), P(0.2, -0.26), P(0.5, 0),
             P(0.2, 0.26), P(-0.2, 0.26), P(-0.5, 0)]);
      spray(ctx, rng, x, y, s * 0.13, color, 1.3, { a: 0.9, spread: 0.30 });
    } else if (kind === 'sword') {
      stick([P(0, -0.6), P(0.02, 0.28)], 1.2);
      stick([P(-0.22, 0.24), P(0.24, 0.26)], 1.1);
      stick([P(0.02, 0.28), P(0.02, 0.56)], 0.9);
    } else if (kind === 'flame') {
      stick([P(-0.22, 0.5), P(-0.30, 0.05), P(-0.10, -0.24), P(0.0, -0.55),
             P(0.12, -0.20), P(0.30, 0.05), P(0.22, 0.5)]);
      stick([P(-0.06, 0.5), P(-0.10, 0.15), P(0.02, -0.1), P(0.08, 0.15),
             P(0.06, 0.5)], 0.8);
    } else if (kind === 'rain') {
      const nD = 5 + Math.floor(rng.f() * 4);
      for (let k = 0; k < nD; k++) {
        const ax = rng.r(-0.6, 0.6), ay = rng.r(-0.6, 0.6);
        stick([P(ax, ay), P(ax - 0.05, ay + rng.r(0.14, 0.26))], 0.9);
      }
    } else if (kind === 'rainbow') {
      for (let b = 0; b < 3; b++) {
        const pts = [];
        const r = 0.62 - b * 0.12;
        for (let k = 0; k <= 8; k++) {
          const a = Math.PI + k / 8 * Math.PI;
          pts.push(P(Math.cos(a) * r, Math.sin(a) * r * 0.8 + 0.2));
        }
        oilStick(ctx, rng, pts,
                 opt.rainbow ? opt.rainbow[b % opt.rainbow.length] : color,
                 w, so);
      }
    } else if (kind === 'worm') {
      const pts = [];
      for (let k = 0; k <= 9; k++)
        pts.push(P(-0.5 + k / 9, Math.sin(k / 9 * 9.4) * 0.14));
      stick(pts, 1.4);
    } else if (kind === 'fish') {
      stick([P(-0.5, 0), P(-0.16, -0.24), P(0.28, -0.20), P(0.5, 0),
             P(0.28, 0.20), P(-0.16, 0.24), P(-0.5, 0)]);
      stick([P(-0.5, 0), P(-0.7, -0.22), P(-0.7, 0.22), P(-0.5, 0)], 0.9);
    } else { // grid: a hatched patch
      const nH = 4 + Math.floor(rng.f() * 3);
      for (let k = 0; k < nH; k++) {
        stick([P(-0.5, -0.4 + k * 0.8 / (nH - 1)), P(0.5, -0.4 + k * 0.8 / (nH - 1))], 0.8);
        stick([P(-0.4 + k * 0.8 / (nH - 1), -0.5), P(-0.4 + k * 0.8 / (nH - 1), 0.5)], 0.8);
      }
    }
  }

  // Lay the cast around the dog: count by fate, positions in the open
  // fields off the face, never wallpaper, never over the skull.
  //   g.fig    the animal's footprint;  cans  the colours the stream picks
  function paintGlyphCast(ctx, grng, fig, count, cans, opt) {
    opt = opt || {};
    const used = [], pts = [];
    const kinds = opt.kinds || GLYPH_KINDS;
    let placed = 0;
    for (let i = 0; i < count; i++) {
      let kind = kinds[Math.floor(grng.f() * kinds.length) % kinds.length];
      if (used.indexOf(kind) >= 0)
        kind = kinds[Math.floor(grng.f() * kinds.length) % kinds.length];
      used.push(kind);
      const s = grng.r(opt.sMin || 70, opt.sMax || 150);
      // an open field: try a few spots and keep the one farthest from
      // the head and from the glyphs already down
      let best = null, bestD = -1;
      for (let t = 0; t < 7; t++) {
        const px = grng.r(70, 930), py = grng.r(opt.y0 || 60, opt.y1 || 940);
        let dd = 9;
        if (fig) {
          const ddx = Math.abs(px - fig.x) / (fig.rx * 1.15 + s * 0.7);
          const ddy = Math.abs(py - (fig.y - fig.ry * 0.25)) /
                      (fig.ry * 1.05 + s * 0.7);
          dd = Math.max(ddx, ddy);
        }
        pts.forEach(q => {
          dd = Math.min(dd, Math.hypot(px - q[0], py - q[1]) / (s * 1.6));
        });
        if (dd > bestD) { bestD = dd; best = [px, py]; }
      }
      if (!best || bestD < 0.92) continue;
      const col = cans[Math.floor(grng.f() * cans.length) % cans.length];
      const gA = ctx.globalAlpha;
      ctx.globalAlpha = gA * grng.r(0.72, 1.0);
      drawGlyph(ctx, grng, kind, best[0], best[1], s, col,
                { rainbow: opt.rainbow });
      ctx.globalAlpha = gA;
      pts.push(best);
      placed++;
    }
    return placed;
  }

  // ======= BANDED WORLD (nava05, nava10, nava11, jonpick37) — round 989 =
  // The Nava ground and the house language: two or three hand-brushed
  // bands whose edges wander, from the can. ROUND 989: the bands are no
  // longer flat. Each is a CURTAIN of long parallel translucent streaks
  // in two or three hues (the immortal's hand, section 6) with sprayed
  // grit where the light is, so the field has light in it before
  // anything is drawn on it. Everything else is LAID ON: sprayed clouds,
  // drips, silver stars, a scribbled horizon, the glyph cast, one tiny
  // stick-figure witness at the dog's foot.
  //
  // bandHues: the two or three hues a band's curtain alternates between:
  // the band lifted a step, the band turned a few degrees, and a pale
  // light (near-white on a daylight band, a cold milk on a night one)
  function bandHues(rng, col, LG, satUpG, pale) {
    const lit = lum(col) > 150;
    const turn = LG(satUpG(hueShiftC(col, rng.r(-18, 18)), 0.25));
    return [glow(col, lit ? rng.r(0.06, 0.14) : rng.r(0.12, 0.24)),
            lit ? sink(turn, rng.r(0.02, 0.07)) : glow(turn, rng.r(0.08, 0.18)),
            pale || mix(lit ? hx('#f7f5ef') : hx('#dfe7ee'), col,
                        lit ? rng.r(0.30, 0.45) : rng.r(0.40, 0.58))];
  }

  // ======= WORN BANDS (round 1016) ======================================
  // The judge's complaint, twice: the cobalt, green-strip and teal bands
  // were two-value fills with a few streaks laid on, cleaner than round
  // 124's worn ochre and lavender. The r124 floor (direction 6e) is worn
  // paint on an old surface: three or four values in every field, the
  // brush visible, earlier layers surfacing in continents, bare support
  // at the most worn points. So from this round a Nava band is never a
  // fillRect. Every band of a banded or zombie world goes down through
  // paintSupport, the round-124 support engine, as TWO strata confined to
  // the band with a hand-wobbled edge: a BURIED coat (the same band
  // turned a few degrees and a value away, laid first, giving way only
  // at the very worst wear so the kraft board shows there in small
  // continents) and the TOP coat from the can, which the rag has worn
  // back to the buried one across a tenth to a quarter of its area. The
  // sky is laid full-panel first, so where a lower band wears through
  // it is the SKY that surfaces under the grass, the way an earlier
  // idea surfaces in jonpick39's ochre. Then the rag itself (dry pulls
  // in a buried colour), a few scratches to the board, and only then
  // the curtain of streaks and the grit of round 989 over it.
  //   bands: top-down, [{c, y0, y1, wob}]; y0/y1 undefined = full panel
  //   o.wear   how much of the top coat the rag took (0..1, default 0.2)
  //   o.turn   how far the buried coat turns from the top (degrees)
  //   o.rng    a stream for the support noise (default g.rng)
  function wornBands(g, bands, o) {
    o = o || {};
    const ctx = g.ctx, rng = o.rng || g.rng, board = g.board;
    const wear = o.wear === undefined ? 0.2 : o.wear;
    const coats = [];
    const buriedOf = [];
    bands.forEach((b, i) => {
      const col = b.c;
      const lit = lum(col) > 150;
      const sp = rng.chance(0.5) ? 1 : -1;
      // THREE strata per band, as groundScoured lays them: the deepest
      // is a genuinely other value of the band's family, turned a long
      // way and pulled toward the board (the earlier idea surfacing, the
      // milky lavender under jonpick39's ochre); the middle is a second
      // can of nearly the same colour; the top is the colour the band
      // is named for. A buried coat that is only a value filter reads as
      // shading, not as wear.
      const deepC = mix(
        lit ? sink(hueShiftC(col, sp * rng.r(18, 40)), rng.r(0.22, 0.38))
            : lift(hueShiftC(col, sp * rng.r(18, 40)), rng.r(0.30, 0.48)),
        board, lit ? rng.r(0.10, 0.22) : rng.r(0.14, 0.28));
      const midC = hueShiftC(col, -sp * rng.r(0.3, 1) * (o.turn || 22));
      const mid2 = lit ? sink(midC, rng.r(0.08, 0.16)) : glow(midC, rng.r(0.08, 0.18));
      buriedOf.push(rng.chance(0.6) ? deepC : mid2);
      // the wear field is normalised and bell-shaped about 0.5, so a
      // coat's threshold is close to the share of the band it still
      // covers: groundScoured's top coats sit at 0.34-0.50
      const topT = Math.max(0.36, Math.min(0.60, 0.70 - wear * rng.r(0.65, 0.95)));
      const band = b.y0 !== undefined
        ? { y0: b.y0, y1: b.y1 === undefined ? 1060 : b.y1,
            wob: b.wob === undefined ? 12 : b.wob }
        : {};
      // the deepest coat wears through to the board on the sky only at
      // the very worst points; a lower band's is a little more worn so
      // the sky surfaces through the grass
      coats.push(Object.assign({
        c: deepC, thr: i === 0 ? rng.r(0.86, 0.94) : rng.r(0.80, 0.90),
        hard: rng.r(3.4, 5.0), jit: rng.r(0.08, 0.16),
        dr: rng.r(0.20, 0.34) }, band));
      coats.push(Object.assign({
        c: mid2, thr: topT + rng.r(0.16, 0.26),
        hard: rng.r(3.8, 5.6), jit: rng.r(0.09, 0.18),
        dr: lit ? rng.r(0.16, 0.26) : rng.r(0.22, 0.36) }, band));
      coats.push(Object.assign({
        c: col, thr: topT,
        hard: rng.r(4.6, 7.4), jit: rng.r(0.10, 0.22),
        dr: lit ? rng.r(0.12, 0.22) : rng.r(0.18, 0.30) }, band));
    });
    paintSupport(ctx, rng, board, coats, {
      wearAmp: rng.r(0.94, 1.08) * (g.GO.wear || 1),
      contW: rng.r(0.36, 0.48), blotW: rng.r(0.12, 0.20),
      sweepW: rng.r(0.28, 0.42), biteW: rng.r(0.11, 0.18),
      tooth: rng.r(0.05, 0.09), tooth2: rng.r(0.03, 0.06),
      grainV: rng.r(0.04, 0.08), pool: rng.r(0.06, 0.12),
      fiber: rng.r(12, 24), litX: g.litX, litY: g.litY, panels: 1 });
    ctx.globalAlpha = 1;
    // THE RAG: two to four dry pulls the width of the panel in a buried
    // colour, the hand that did the wearing left on top of what it did
    const nSw = 2 + Math.floor(rng.f() * 3);
    for (let i = 0; i < nSw; i++) {
      const bi = Math.floor(rng.f() * bands.length);
      const b = bands[bi];
      const ya = b.y0 === undefined ? -40 : b.y0;
      const yb = b.y1 === undefined ? (bands[bi + 1] ? bands[bi + 1].y0 : 1040) : b.y1;
      if (yb - ya < 60) continue;
      const yy = rng.r(ya + 20, yb - 20), tilt = rng.r(-0.06, 0.06);
      ctx.globalAlpha = rng.r(0.12, 0.30);
      dryStroke(ctx, rng,
                [[-170, yy + rng.r(-14, 14)],
                 [rng.r(180, 380), yy + tilt * 280 + rng.r(-24, 24)],
                 [rng.r(620, 830), yy + tilt * 720 + rng.r(-24, 24)],
                 [1170, yy + tilt * 1160 + rng.r(-14, 14)]],
                drift(rng, buriedOf[bi], 0.06), rng.r(50, 150),
                { fade: rng.r(0.7, 1.4), grain: rng.r(0.62, 0.92),
                  press: rng.r(0.3, 0.8), pAmp: rng.r(0.4, 0.7),
                  step: rng.r(6, 10) });
    }
    // SCRATCHES: a few hairlines down to the board
    const nSc = 4 + Math.floor(rng.f() * 7);
    for (let i = 0; i < nSc; i++) {
      const yy = rng.r(-20, 1020), x0 = rng.r(-80, 700),
            ln = rng.r(90, 520), tl = rng.r(-0.05, 0.05);
      ctx.globalAlpha = rng.r(0.10, 0.26);
      ribbon(ctx, rng,
             [[x0, yy], [x0 + ln * 0.5, yy + tl * ln * 0.5 + rng.r(-3, 3)],
              [x0 + ln, yy + tl * ln]],
             drift(rng, lift(board, rng.r(0.05, 0.28)), 0.05),
             rng.r(1.1, 3.0), { taper: 0.6, wob: 0.2, jit: 1.1, step: 18 });
    }
    ctx.globalAlpha = 1;
  }

  // one band, brushed by hand: base coat, broad loaded passes a breath
  // apart, then the curtain of streaks, then grit where the light is
  function curtainBand(ctx, rng, col, y0, y1, o) {
    o = o || {};
    const yA = Math.max(0, y0), yB = Math.min(1000, y1);
    if (yB - yA < 8) return;
    ctx.globalAlpha = 1;
    if (!o.worn) {
      ctx.fillStyle = css(col);
      ctx.fillRect(0, Math.max(0, y0 - 30), 1000,
                   Math.min(1000, y1 + 30) - Math.max(0, y0 - 30));
    }
    const nP = Math.max(3, Math.round((yB - yA) / rng.r(90, 130)));
    for (let i = 0; i < nP; i++) {
      const yy = yA + (i + rng.r(0.05, 0.95)) * (yB - yA) / nP;
      const c2 = drift(rng, rng.chance(0.5)
                   ? glow(col, rng.r(0.02, 0.07))
                   : sink(col, rng.r(0.015, 0.05)), 0.025);
      ctx.globalAlpha = o.worn ? rng.r(0.14, 0.34) : rng.r(0.30, 0.60);
      ribbon(ctx, rng,
             [[rng.r(-70, 30), yy + rng.r(-8, 8)],
              [rng.r(300, 500), yy + rng.r(-14, 14)],
              [rng.r(970, 1080), yy + rng.r(-8, 8)]],
             c2, rng.r(42, 88),
             { taper: 0.05, wob: 0.14, jit: 1.4, step: 22,
               load: rng.r(0.6, 0.95),
               end: rng.chance(0.3) ? rng.r(0.6, 1.1) : 0 });
    }
    ctx.globalAlpha = 1;
    // THE CURTAIN. With the band (the brush direction) or falling
    // through it as weather; both are long, thin, translucent, and many
    const hues = o.hues;
    const h = yB - yA;
    const loud = o.loud === undefined ? 1 : o.loud;
    if (o.dir === 'fall') {
      const ang = Math.PI / 2 + (o.tilt || 0);
      lightCurtain(ctx, rng, {
        hues: hues, dir: ang, cx: o.cx === undefined ? 500 : o.cx,
        cy: (yA + yB) / 2, span: o.span || 760, len: h * 1.7,
        n: Math.round((30 + h * 0.10) * loud), w: o.w || [2.4, 8.5],
        a: o.a || [0.14, 0.40], fall: 0.55, bow: 0.05, clip: [yA, yB] });
    } else {
      lightCurtain(ctx, rng, {
        hues: hues, dir: (o.tilt || 0), cx: 500, cy: (yA + yB) / 2,
        span: h * 0.96, len: 1500, n: Math.round((10 + h * 0.13) * loud),
        w: o.w || [2.4, 9], a: o.a || [0.14, 0.40], fall: 0.15, bow: 0.02,
        clip: [yA, yB] });
    }
    // grit where the light is
    if (o.grit) {
      const gx = Math.max(60, Math.min(940, o.grit[0]));
      const gy = Math.max(yA + 30, Math.min(yB - 30, o.grit[1]));
      gritCloud(ctx, rng, gx, gy, rng.r(70, 130) * (o.gritR || 1),
                [hues[2], hues[0]], { a: o.gritA || 0.36, dens: 0.9,
                                     elx: rng.r(1.1, 1.7), ely: rng.r(0.6, 0.9) });
      if (rng.chance(0.5))
        gritCloud(ctx, rng, gx + rng.r(-260, 260), gy + rng.r(-90, 90),
                  rng.r(40, 80), [hues[2], hues[1]],
                  { a: (o.gritA || 0.36) * 0.8, dens: 0.8 });
    }
    ctx.globalAlpha = 1;
  }

  // a hand-brushed boundary between two bands: the lower band's top edge
  // wanders, gets one loaded pass, and, wet, drips down into itself
  function bandEdge(ctx, rng, col, yEdge, o) {
    o = o || {};
    const edge = [];
    for (let k = 0; k <= 9; k++)
      edge.push([k * 125 - 60, yEdge + rng.r(-(o.wob || 16), (o.wob || 16))]);
    ctx.globalAlpha = 1;
    if (!o.worn) {
      // (round 1016: a worn band is already down; only the loaded pass
      // along its edge, the dry bristles and the drips go on)
      ctx.fillStyle = css(col);
      ctx.beginPath();
      poly(ctx, edge.concat([[1080, yEdge + 60], [-60, yEdge + 60]]), true);
      ctx.fill();
    }
    ctx.globalAlpha = o.worn ? rng.r(0.40, 0.70) : rng.r(0.55, 0.85);
    ribbon(ctx, rng, edge, drift(rng, col, 0.03), rng.r(20, 38),
           { taper: 0.1, wob: 0.35, jit: 2.2, step: 18 });
    // the dry top of the pass: bristles reaching up into the band above
    ctx.globalAlpha = rng.r(0.35, 0.6);
    dryStroke(ctx, rng, edge.map(p => [p[0], p[1] - rng.r(4, 14)]),
              drift(rng, col, 0.03), rng.r(14, 26),
              { fade: 0.9, grain: 0.6, press: 0.3, a: 0.8 });
    ctx.globalAlpha = 1;
    const nDrip = o.drips === undefined
      ? (rng.chance(0.7) ? 1 + Math.floor(rng.f() * 3) : 0) : o.drips;
    for (let i = 0; i < nDrip; i++)
      sprayDrip(ctx, rng, rng.r(60, 940), yEdge + rng.r(-6, 10),
                sink(col, rng.r(0, 0.12)), rng.r(30, 110), rng.r(3, 6));
    return edge;
  }

  function groundBanded(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig, LG = g.LG;
    const GO = g.GO, deep = g.deep, satUpG = g.satUpG;
    const litX = g.litX, litY = g.litY;
    // ROUND 908: a banded world is a RECIPE, not a hue of the paper.
    // Straight from the can so a sheet of sixteen is not one green strip
    // at one height. Faithful never gets ember (that's the zombie's).
    //   cobalt-grass   nava05 / nava01 — loud cobalt, emerald strip
    //   white-water    jonpick26 / nava11 — pale field over blue water
    //   cream-lone     nava10 — one cream field, stick marks
    //   teal-night     jonpick27 — deep teal, lime grass, stars
    //   lavender-milk  (989) lavender sky over a cool milk-grey strip
    //   mint-slate     (989) mint sky over a pale slate strip
    const loud = (c, t) => LG(satUpG(c, t === undefined ? 0.78 : t));
    let kind, skyC, lowC, lowY = 0, mid = null;
    if (GO.ones) {
      // one-of-ones keep a paper-derived world so the hand-mixed chord
      // of the portrait is not overwritten by a can of cobalt
      const r = rng.f();
      kind = deep ? (r < 0.55 ? 'sky' : 'lone')
                  : r < 0.40 ? 'water' : r < 0.75 ? 'sky' : 'lone';
    } else {
      const r = rng.f();
      if (deep) kind = r < 0.25 ? 'teal-night' : r < 0.70 ? 'cobalt-grass'
                     : 'cream-lone';
      else kind = r < 0.26 ? 'white-water' : r < 0.50 ? 'cobalt-grass'
                : r < 0.66 ? 'cream-lone' : r < 0.78 ? 'teal-night'
                : r < 0.90 ? 'lavender-milk' : 'mint-slate';
    }
    if (kind === 'sky') {
      skyC = loud(deep ? paper : sink(paper, rng.r(0.06, 0.16)),
                  rng.r(0.66, 0.92));
      if (!deep)
        skyC = LG(mix(skyC, hsl(hueOf(skyC)[0], 0.60, 0.52),
                      rng.r(0.30, 0.55)));
      lowC = LG(hx(rng.pick(['#1f8f3e', '#26a04a', '#187a38', '#2f9a44'])));
      lowY = rng.r(770, 880);
    } else if (kind === 'water') {
      skyC = LG(mix(glow(paper, 0.5), hx('#efeee6'), rng.r(0.55, 0.8)));
      lowC = loud(hx(rng.pick(['#2551c0', '#1d47b8', '#2b5cd0', '#1a3fa8'])),
                  0.5);
      lowY = rng.r(600, 780);
    } else if (kind === 'lone') {
      skyC = deep ? LG(satUpG(paper, rng.r(0.2, 0.5)))
                  : LG(mix(paper, hx(rng.pick(
                      ['#e9dfc6', '#ece5d2', '#e5dcc8', '#efe8d6'])),
                      rng.r(0.4, 0.75)));
      lowC = null;
      lowY = 1001;
    } else if (kind === 'cobalt-grass') {
      kind = 'sky';
      skyC = LG(hx(rng.pick(['#2a5cd8', '#1e4fc0', '#3a6ae0', '#2551c0',
                             '#1a48b0'])));
      lowC = LG(hx(rng.pick(['#1f8f3e', '#26a04a', '#187a38', '#2f9a44'])));
      lowY = rng.r(720, 890);
      if (rng.chance(0.28)) {
        mid = { c: LG(sink(hx('#1a1c22'), rng.r(0.0, 0.12))),
                y: lowY - rng.r(110, 220) };
      }
    } else if (kind === 'teal-night') {
      kind = 'sky';
      skyC = LG(hx(rng.pick(['#0d3a38', '#164844', '#0a3030', '#1a4540',
                             '#123c48'])));
      // jonpick27: the grass is LIME against the teal, a full value
      // step, or the strip disappears and the panel reads as night
      lowC = LG(hx(rng.pick(['#5ee06a', '#48d45c', '#62e878', '#3ccb52'])));
      lowY = rng.r(760, 890);
    } else if (kind === 'white-water') {
      kind = 'water';
      skyC = LG(mix(hx('#efeee6'), glow(paper, 0.55), rng.r(0.20, 0.50)));
      lowC = LG(hx(rng.pick(['#2551c0', '#1d47b8', '#2b5cd0', '#1a3fa8'])));
      lowY = rng.r(520, 760);
    } else if (kind === 'lavender-milk') {
      kind = 'sky';
      skyC = LG(hx(rng.pick(['#a99ad8', '#b4a6e0', '#9c8fd0', '#b8aee4'])));
      lowC = LG(hx(rng.pick(['#d8dde4', '#cfd6de', '#dde2e8', '#c9d2dc'])));
      lowY = rng.r(700, 860);
    } else if (kind === 'mint-slate') {
      kind = 'sky';
      skyC = LG(hx(rng.pick(['#8fd8c0', '#7ccfb4', '#9ee0c8', '#86d4bc'])));
      lowC = LG(hx(rng.pick(['#6f7f92', '#7a8a9c', '#66788c', '#84929f'])));
      lowY = rng.r(720, 870);
    } else { // cream-lone
      kind = 'lone';
      skyC = deep
        ? LG(hx(rng.pick(['#1a3048', '#243044', '#152838', '#1c2836'])))
        : LG(hx(rng.pick(['#e9dfc6', '#ece5d2', '#e5dcc8', '#efe8d6',
                          '#f0ead8'])));
      lowC = null;
      lowY = 1001;
    }
    // ---- the bands, each a curtain of light --------------------------
    // the sky's weather: with the brush (nava's band) or falling through
    // it (the immortal's curtain), rolled per piece
    const skyFall = rng.chance(0.42);
    const skyHues = bandHues(rng, skyC, LG, satUpG);
    const skyBot = mid ? mid.y + 16 : (lowC ? lowY + 16 : 1030);
    // ROUND 1016 (restored in the weathered round): the bands go down
    // FIRST as worn paint (wornBands), the r124 surface under the Nava
    // composition, from their own stream so the support noise never
    // moves a stroke laid after it
    {
      const wb = [{ c: skyC }];
      if (mid) wb.push({ c: mid.c, y0: mid.y, y1: lowC ? lowY : 1060, wob: 14 });
      if (lowC) wb.push({ c: lowC, y0: lowY, wob: 12 });
      const seedW = (GO.seed | 0);
      wornBands(g, wb, {
        wear: rng.r(0.16, 0.32),
        rng: R((Math.imul(seedW ^ 0x5bd1e995, 0x1b873593) ^
                (seedW >>> 7) ^ 0x7f4a7c15) >>> 0) });
    }
    curtainBand(ctx, rng, skyC, -30, skyBot, {
      hues: skyHues, dir: skyFall ? 'fall' : 'with', worn: true,
      tilt: skyFall ? rng.r(-0.32, 0.32) : rng.r(-0.05, 0.05),
      cx: skyFall ? litX + rng.r(-80, 80) : 500,
      grit: [litX, litY < 500 ? litY : rng.r(60, 260)],
      gritA: lum(skyC) > 150 ? 0.30 : 0.40 });
    if (mid) {
      bandEdge(ctx, rng, mid.c, mid.y, { drips: 0, worn: true });
      curtainBand(ctx, rng, mid.c, mid.y + 22, lowY + 16,
                  { hues: bandHues(rng, mid.c, LG, satUpG), dir: 'with',
                    a: [0.10, 0.30], loud: 0.7, worn: true });
    }
    if (lowC) {
      bandEdge(ctx, rng, lowC, lowY, { worn: true });
      curtainBand(ctx, rng, lowC, lowY + 18, 1010,
                  { hues: bandHues(rng, lowC, LG, satUpG), dir: 'with',
                    tilt: rng.r(-0.04, 0.04), loud: 0.85, worn: true });
    }
    // a few points of dust or pollen or rain in the sky
    gritPoints(ctx, rng, 6 + Math.floor(rng.f() * 14),
               [skyHues[2], glow(skyHues[0], 0.1)], fig, 20,
               Math.min(960, skyBot - 40));
    // ---- under-marks: an earlier idea showing through ---------------
    if (rng.chance(0.40)) {
      // a scoured patch: the field scrubbed back toward pale
      const px = rng.chance(0.5) ? rng.r(80, 320) : rng.r(680, 920);
      const py = rng.r(80, Math.min(700, skyBot - 60));
      for (let i = 0; i < 3; i++) {
        ctx.globalAlpha = rng.r(0.12, 0.26);
        dryStroke(ctx, rng,
                  [[px - rng.r(90, 180), py + rng.r(-30, 30)],
                   [px + rng.r(90, 180), py + rng.r(-30, 30)]],
                  drift(rng, skyHues[2], 0.04), rng.r(40, 90),
                  { fade: 0.9, grain: 0.5, press: 0.3 });
      }
      ctx.globalAlpha = 1;
    }
    if (rng.chance(0.30)) {
      // a fingerprint of colour left from an earlier idea
      const fc = LG(hx(rng.pick(['#2a5cd8', '#1f8f8a', '#8fd8c0', '#a99ad8'])));
      ctx.globalAlpha = rng.r(0.30, 0.55);
      spray(ctx, rng, rng.chance(0.5) ? rng.r(60, 260) : rng.r(740, 940),
            rng.r(120, 880), rng.r(22, 44), fc, 1.3,
            { a: 0.6, spread: 0.34, elx: rng.r(0.8, 1.4), ely: rng.r(0.8, 1.4) });
      ctx.globalAlpha = 1;
    }
    // ---- what gets laid ON the world ---------------------------------
    if (kind === 'water') {
      // nava11's waves: scribbled zigzag crests in the water's own deep
      const crest = sink(lowC, rng.r(0.18, 0.3));
      const nW = 2 + Math.floor(rng.f() * 3);
      for (let i = 0; i < nW; i++) {
        const wy = lowY + rng.r(30, 320);
        if (wy > 980) continue;
        const zz = [];
        const x0 = rng.r(-40, 300), x1 = x0 + rng.r(380, 760);
        const nZ = 4 + Math.floor(rng.f() * 4);
        for (let k = 0; k <= nZ * 2; k++)
          zz.push([x0 + (x1 - x0) * k / (nZ * 2),
                   wy + (k % 2 ? -1 : 1) * rng.r(14, 34)]);
        oilStick(ctx, rng, zz, crest, rng.r(9, 15),
                 { dbl: 0.2, over: 30, tooth: 0.3, wob: 3 });
      }
    }
    // sprayed clouds: the nava04 bank — a soft white mass with a dark
    // sprayed under-shadow, never a brushed puff
    if (rng.chance(kind === 'lone' ? 0.45 : 0.68)) {
      const nC = 1 + (rng.chance(0.4) ? 1 : 0);
      for (let i = 0; i < nC; i++) {
        let cx2 = rng.chance(0.5) ? rng.r(90, 330) : rng.r(650, 910);
        const cy2 = rng.r(70, 260);
        const cw2 = rng.r(70, 150);
        // the cloud stands clear of the animal: sprayed haze landing on
        // a skull reads as dandruff, not weather
        if (fig && Math.abs(cx2 - fig.x) < fig.rx * 1.35 + cw2 &&
            cy2 > fig.y - fig.ry * 1.8)
          cx2 = fig.x > 500 ? rng.r(70, Math.max(90, fig.x - fig.rx * 1.5 - cw2))
                            : rng.r(Math.min(910, fig.x + fig.rx * 1.5 + cw2), 940);
        if (cx2 < 40 || cx2 > 960) continue;
        const cloudC = lum(skyC) > 168
          ? mix(hx('#8b8f96'), skyC, rng.r(0.15, 0.4))
          : mix(hx('#f4f2ea'), skyC, rng.r(0.06, 0.2));
        const shadC = sink(cloudC, rng.r(0.3, 0.5));
        // the under-shadow first, then the body over it
        spray(ctx, rng, cx2 + rng.r(-10, 10), cy2 + cw2 * 0.34, cw2 * 1.05,
              shadC, 1.1, { a: 0.5, spread: 0.42, elx: 1.5, ely: 0.6 });
        for (let b = 0; b < 3; b++)
          spray(ctx, rng, cx2 + rng.r(-cw2, cw2) * 0.7,
                cy2 + rng.r(-cw2, cw2) * 0.26, cw2 * rng.r(0.55, 0.85),
                cloudC, 1.5, { a: 0.75, spread: 0.4, elx: 1.3, ely: 0.7 });
      }
    }
    // silver stars on a dark sky (nava03)
    if (lum(skyC) < 130 && rng.chance(0.72)) {
      const starC = mix(hx('#cfd3d8'), skyC, rng.r(0.05, 0.22));
      const nS = 4 + Math.floor(rng.f() * 6);
      for (let i = 0; i < nS; i++) {
        const sx2 = rng.r(40, 960), sy2 = rng.r(30, (mid ? mid.y : lowY) - 60);
        if (fig && Math.abs(sx2 - fig.x) < fig.rx * 0.85 &&
            Math.abs(sy2 - fig.y) < fig.ry * 0.85) continue;
        starMark(ctx, rng, sx2, sy2, rng.r(11, 26), starC);
      }
    }
    // a scribbled horizon (oil stick over the band edge, chance move)
    if (lowC && rng.chance(0.4)) {
      const hzC = rng.chance(0.5) ? sink(lowC, 0.4)
                : LG(satUpG(hueShiftC(lowC, rng.r(-40, 40)), 0.5));
      const seg = [];
      const x0 = rng.r(-30, 260);
      for (let k = 0; k <= 5; k++)
        seg.push([x0 + k * rng.r(90, 150), lowY + rng.r(-14, 14)]);
      oilStick(ctx, rng, seg, hzC, rng.r(7, 12),
               { dbl: 0.65, over: 40, tooth: 0.4, wob: 4 });
    }
    // grass blades drawn one gesture each (nava06's green strokes)
    if (kind === 'sky' && lum(lowC) < 190 && rng.chance(0.66)) {
      const bladeC = rng.chance(0.5) ? sink(lowC, rng.r(0.2, 0.35))
                                     : glow(lowC, rng.r(0.2, 0.4));
      const nB = 4 + Math.floor(rng.f() * 6);
      for (let i = 0; i < nB; i++) {
        const bx = rng.r(30, 970);
        const by = lowY + rng.r(-4, 60);
        oilStick(ctx, rng,
                 [[bx, Math.min(990, by + rng.r(20, 50))],
                  [bx + rng.r(-14, 14), by - rng.r(26, 70)]],
                 bladeC, rng.r(4, 7),
                 { dbl: 0.15, over: 8, tooth: 0.3, wob: 1.6 });
      }
    }
    // marks along the bottom (nava10's black sticks): short countable
    // oil-stick gestures walking the lower edge
    if (kind === 'lone' && rng.chance(0.7)) {
      const mkC = LG(mix(hx('#26211c'), skyC, rng.r(0.06, 0.2)));
      const nM = 3 + Math.floor(rng.f() * 4);
      let mx2 = rng.r(40, 220);
      for (let i = 0; i < nM && mx2 < 960; i++) {
        oilStick(ctx, rng,
                 [[mx2, rng.r(880, 960)],
                  [mx2 + rng.r(-16, 30), rng.r(800, 866)]],
                 mkC, rng.r(5, 9), { dbl: 0.3, over: 14, tooth: 0.35 });
        mx2 += rng.r(90, 260);
      }
    }
    // the witness: one tiny stick figure at the dog's foot, which is
    // what makes the dog enormous (nava03)
    if (fig && rng.chance(0.30)) {
      const wSd = rng.chance(0.5) ? -1 : 1;
      let wx2 = fig.x + wSd * (fig.rx * rng.r(1.06, 1.3));
      wx2 = Math.max(60, Math.min(940, wx2));
      const wy2 = Math.min(965, Math.max(lowY + rng.r(20, 80),
                                         fig.y + fig.ry * rng.r(0.8, 0.95)));
      const wC = lum(skyC) < 110 && wy2 < lowY
        ? mix(hx('#e8e6da'), skyC, 0.15)
        : LG(mix(hx('#221d18'), skyC, 0.08));
      stickWitness(ctx, rng, wx2, wy2, rng.r(60, 100), wC);
    }
    g.skyC = skyC;
    g.skyBot = skyBot;
  }

  // ======= ZOMBIE WORLD (round 989): candy death, the 966 world ========
  // The artist named round 966's zombie backgrounds the best so far
  // (jonpick36): a sour-yellow sky over a black band, two black stick
  // glyphs and a drift of pink spray left in the yellow; a cobalt sky
  // over a black band over a green field, a hot-pink spray burst and one
  // scribbled green mark. Bright, uneven, hand-brushed candy bands with
  // one dark band for the piece to push against, one or two Nava events
  // laid on, no skull wallpaper, no burnt night, no embers, no smoke.
  // ROUND 989 paints those bands with the immortal's hand: each a
  // curtain of streaks in two or three candy hues, grit where the light
  // is. The colours never go through the zombie temperature clamp: the
  // candy is the point.
  function groundZombie(g) {
    const ctx = g.ctx, rng = g.rng, fig = g.fig;
    const GO = g.GO;
    const CANDY = {
      sour:      ['#e8c21a', '#f0c81e', '#f2c92a', '#e6b813', '#f4d02c'],
      cobalt:    ['#2a5cd8', '#1e4fc0', '#2551c0', '#3a6ae0', '#2447c8'],
      coral:     ['#ff5a4a', '#f64c3c', '#ff6a55', '#fa5240'],
      lime:      ['#a4e838', '#8fe03a', '#b0ec44', '#96e030'],
      tangerine: ['#ff7a1e', '#f96e10', '#ff8a2a', '#fb7418'],
      magenta:   ['#c8288e', '#b8207e', '#d43098', '#c02a88'],
      green:     ['#1f8f3e', '#26a04a', '#2f9a44', '#1c8a3a'],
    };
    const r = rng.f();
    const skyK = r < 0.30 ? 'sour' : r < 0.58 ? 'cobalt' : r < 0.70 ? 'coral'
               : r < 0.82 ? 'tangerine' : r < 0.92 ? 'magenta' : 'lime';
    const skyC = hx(rng.pick(CANDY[skyK]));
    const black = mix(hx('#0e0a0c'), hx('#16121a'), rng.r(0, 1));
    // the layout: black at the bottom (tile 1), black in the middle over
    // a candy field (tile 2), or a thin black foot under a candy strip
    const lay = rng.f();
    const layout = lay < 0.40 ? 'foot' : lay < 0.82 ? 'mid' : 'thin';
    let blackY, fieldY = 1001, fieldC = null;
    if (layout === 'foot') {
      blackY = rng.r(620, 800);
    } else if (layout === 'mid') {
      blackY = rng.r(520, 700);
      fieldY = blackY + rng.r(130, 240);
    } else {
      blackY = rng.r(800, 880);
      fieldY = 1001;
    }
    // the field under the black: a second candy, never the sky's
    const fieldPool = ['green', 'lime', 'magenta', 'tangerine', 'coral', 'sour']
      .filter(k => k !== skyK && !(skyK === 'lime' && k === 'green')
                   && !(skyK === 'coral' && k === 'tangerine')
                   && !(skyK === 'tangerine' && k === 'coral'));
    if (layout === 'mid') fieldC = hx(rng.pick(CANDY[rng.pick(fieldPool)]));
    let stripC = null, stripY = 0;
    if (layout === 'thin') {
      stripC = hx(rng.pick(CANDY[rng.pick(fieldPool)]));
      stripY = blackY - rng.r(90, 170);
    }
    // candy hues for a curtain: the band lifted, the band turned, and a
    // pale candy light (never through the clamp)
    const candyHues = (col) => {
      const lit = lum(col) > 150;
      return [glow(col, lit ? rng.r(0.05, 0.12) : rng.r(0.12, 0.24)),
              hueShiftC(col, rng.r(-16, 16)),
              mix(lit ? hx('#fff6dc') : hx('#e8ecf6'), col,
                  lit ? rng.r(0.25, 0.40) : rng.r(0.35, 0.55))];
    };
    const litX = g.litX, litY = g.litY;
    const skyFall = rng.chance(0.38);
    const skyBot = stripC ? stripY + 16 : blackY + 16;
    // THE WEATHERED ROUND: the candy bands are worn paint (round 1016's
    // wornBands), and the dead world is the MOST worn surface in the
    // collection (Jon, 2026-09-02: 1016's zombies had a nice weathered
    // look, go more in that direction): the rag took a quarter to a
    // half of every top coat, the black band wearing back to the candy
    {
      const wb = [{ c: skyC }];
      if (stripC) wb.push({ c: stripC, y0: stripY, y1: blackY, wob: 14 });
      wb.push({ c: black, y0: blackY, y1: fieldC ? fieldY : 1060, wob: 18 });
      if (fieldC) wb.push({ c: fieldC, y0: fieldY, wob: 12 });
      const seedW = (GO.seed | 0);
      wornBands(g, wb, {
        wear: rng.r(0.26, 0.48), turn: 20,
        rng: R((Math.imul(seedW ^ 0x5bd1e995, 0x1b873593) ^
                (seedW >>> 7) ^ 0x7f4a7c15) >>> 0) });
    }
    curtainBand(ctx, rng, skyC, -30, skyBot, {
      hues: candyHues(skyC), dir: skyFall ? 'fall' : 'with', worn: true,
      tilt: skyFall ? rng.r(-0.3, 0.3) : rng.r(-0.05, 0.05),
      cx: skyFall ? litX : 500,
      grit: [litX, litY < 500 ? litY : rng.r(60, 240)], gritA: 0.34,
      a: [0.16, 0.44] });
    if (stripC) {
      bandEdge(ctx, rng, stripC, stripY, { drips: 0, worn: true });
      curtainBand(ctx, rng, stripC, stripY + 18, blackY + 16,
                  { hues: candyHues(stripC), dir: 'with', loud: 0.8, worn: true });
    }
    // the black band: hand-brushed, its top edge ragged and dry
    bandEdge(ctx, rng, black, blackY, { wob: 20, drips: 0, worn: true });
    curtainBand(ctx, rng, black, blackY + 18, fieldC ? fieldY + 16 : 1010, {
      hues: [glow(black, rng.r(0.06, 0.12)), mix(black, hx('#3a3044'), 0.4),
             mix(black, skyC, rng.r(0.10, 0.20))],
      dir: 'with', a: [0.10, 0.28], loud: 0.7, worn: true });
    // the black drips DOWN into whatever is below it
    {
      const nDrip = 1 + Math.floor(rng.f() * 3);
      const dripY = fieldC ? fieldY : Math.min(960, blackY + 200);
      if (fieldC) {
        bandEdge(ctx, rng, fieldC, fieldY, { wob: 14, drips: 0, worn: true });
        curtainBand(ctx, rng, fieldC, fieldY + 18, 1010,
                    { hues: candyHues(fieldC), dir: 'with', loud: 0.85,
                      worn: true });
        for (let i = 0; i < nDrip; i++)
          sprayDrip(ctx, rng, rng.r(60, 940), fieldY + rng.r(-8, 6),
                    black, rng.r(40, 130), rng.r(3, 6.5));
      } else {
        for (let i = 0; i < nDrip; i++)
          sprayDrip(ctx, rng, rng.r(60, 940), blackY + rng.r(-14, -2),
                    black, rng.r(30, 90), rng.r(3, 6));
      }
    }
    // grit in the sky: pale candy dust
    gritPoints(ctx, rng, 8 + Math.floor(rng.f() * 14),
               [mix(hx('#fff6dc'), skyC, 0.3), hx('#f4f2ea')], fig, 20,
               Math.min(960, skyBot - 40));
    // ---- the Nava events (966) --------------------------------------
    const pink = hx(rng.pick(['#ff3fa4', '#f2409a', '#ff52b0', '#e8388f']));
    // the hot-pink spray burst, off the dog
    if (rng.chance(0.82)) {
      const sd = fig && fig.x < 500 ? 1 : -1;
      const bx = sd > 0 ? rng.r(640, 920) : rng.r(80, 360);
      const by = rng.r(90, Math.min(760, skyBot + 120));
      const br = rng.r(60, 130);
      spray(ctx, rng, bx, by, br, pink, 1.5,
            { a: 0.62, spread: 0.40, settle: 0.10 });
      spray(ctx, rng, bx + rng.r(-br * 0.3, br * 0.3), by + rng.r(-br * 0.3, br * 0.3),
            br * 0.45, glow(pink, 0.2), 1.8, { a: 0.72, spread: 0.30 });
      if (rng.chance(0.5)) {
        // the drift: the can kept moving
        sprayStroke(ctx, rng,
                    [[bx, by], [bx + sd * rng.r(-200, -60), by + rng.r(-120, 120)],
                     [bx + sd * rng.r(-420, -220), by + rng.r(-60, 60)]],
                    rng.r(24, 40), pink, { dens: 0.6, a: 0.32, spread: 0.5 });
      }
      if (rng.chance(0.4))
        sprayDrip(ctx, rng, bx + rng.r(-br * 0.4, br * 0.4), by + br * 0.3,
                  pink, rng.r(50, 140), rng.r(3, 5.5));
    }
    // one scribbled mark in a colour from another can
    if (rng.chance(0.55)) {
      const mk = hx(rng.pick(['#2aa04a', '#a4e838', '#2a5cd8', '#ff7a1e',
                              '#f4f2ea']));
      const sd = fig && fig.x < 500 ? 1 : -1;
      oilScribble(ctx, rng, sd > 0 ? rng.r(680, 900) : rng.r(100, 320),
                  rng.r(Math.max(120, blackY - 200), Math.min(900, blackY + 240)),
                  rng.r(60, 120), rng.r(40, 90), mk, rng.r(7, 12),
                  { tooth: 0.3, a: 0.85 });
    }
    // stick witness for scale, nava03, far off at the dog's foot
    if (rng.chance(0.55)) {
      const sd = fig && fig.x < 500 ? 1 : -1;
      const wx = sd > 0 ? rng.r(60, 200) : rng.r(800, 940);
      const wy = rng.r(Math.max(600, blackY + 60), 955);
      stickWitness(ctx, rng, wx, wy, rng.r(56, 100),
                   wy > blackY && !(fieldC && wy > fieldY)
                     ? hx('#f4f2ea') : hx('#14100c'));
    }
    g.skyC = skyC;
    g.skyBot = skyBot;
    g.blackY = blackY;
  }

  // ======= VAMPIRE SKY (round 908, light 989) ==========================
  // One hue, near-black to a cold pale moon. No second color anywhere.
  // Continents of the SAME hue, never a hue-shifted underpaint. ROUND
  // 989: a curtain of the same hue's values falls through the night, and
  // the grit is sparse and cold. The whole piece is driven through the
  // one-hue LUT at the end, so nothing here can leak a second colour.
  function groundVampire(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig;
    const GO = g.GO, board = g.board, litX = g.litX, litY = g.litY;
    const night = sink(paper, rng.r(0.10, 0.26));
    paintSupport(ctx, rng, board, [
      { c: sink(night, rng.r(0.18, 0.34)), thr: rng.r(0.90, 0.98),
        hard: rng.r(2.0, 3.4), jit: rng.r(0.10, 0.20), dr: rng.r(0.16, 0.30) },
      { c: glow(night, rng.r(0.06, 0.16)), thr: rng.r(0.58, 0.74),
        hard: rng.r(2.4, 4.0), jit: rng.r(0.10, 0.22), dr: rng.r(0.18, 0.32) },
      { c: night, thr: rng.r(0.28, 0.46), hard: rng.r(3.6, 6.2),
        jit: rng.r(0.08, 0.18), dr: rng.r(0.20, 0.36) },
    ], { wearAmp: rng.r(0.92, 1.10) * (GO.wear || 1),
         contW: rng.r(0.40, 0.54), blotW: rng.r(0.16, 0.26),
         sweepW: rng.r(0.14, 0.24), biteW: rng.r(0.10, 0.16),
         tooth: rng.r(0.04, 0.08), tooth2: rng.r(0.03, 0.06),
         grainV: rng.r(0.04, 0.08), pool: rng.r(0.06, 0.12),
         fiber: rng.r(10, 20), litX: litX, litY: litY });
    ctx.globalAlpha = 1;
    // the pale cold highlight: a moon, opposite the animal, same hue
    const moonC = glow(mix(night, hx('#d8dee8'), 0.35), rng.r(0.20, 0.45));
    const mx = fig && fig.x < 500 ? rng.r(700, 900) : rng.r(90, 300);
    const my = rng.r(55, 150);
    const mr = rng.r(70, 125);
    // the curtain: moonlight falling in the one hue's values, a column
    // hung from the moon's side, thin and cold
    const pale = mix(night, hx('#dfe6f0'), rng.r(0.40, 0.58));
    lightCurtain(ctx, rng, {
      hues: [glow(night, rng.r(0.22, 0.34)), pale, glow(night, rng.r(0.10, 0.18))],
      dir: Math.PI / 2 + rng.r(-0.28, 0.28), cx: mx + rng.r(-60, 60), cy: 520,
      span: rng.r(420, 640), len: 1500, n: 56 + Math.floor(rng.f() * 30),
      w: [2.2, 7.5], a: [0.12, 0.34], fall: 0.7, bow: 0.05 });
    gritCloud(ctx, rng, mx + rng.r(-40, 40), my + mr * rng.r(0.6, 1.4), mr * 1.1,
              [pale, glow(night, 0.25)], { a: 0.30, dens: 0.7 });
    gritPoints(ctx, rng, 6 + Math.floor(rng.f() * 8), [pale], fig, 20, 900);
    spray(ctx, rng, mx, my, mr * 1.35, mix(moonC, night, 0.45), 0.9,
          { a: 0.40, spread: 0.48, elx: 1.05, ely: 1.00 });
    paintShape(ctx, rng, blob(rng, mx, my, mr, mr * rng.r(0.92, 1.06), 18, 0.05),
               moonC, { n: 5, szMul: 0.55, drift: 0.03 });
    spray(ctx, rng, mx - mr * 0.22, my - mr * 0.22, mr * 0.42,
          glow(moonC, 0.25), 1.1, { a: 0.45, spread: 0.36 });
    // a few same-hue stars — they remap with the nocturne
    if (rng.chance(0.72)) {
      const nS = 3 + Math.floor(rng.f() * 4);
      for (let i = 0; i < nS; i++) {
        const sx2 = rng.r(40, 960), sy2 = rng.r(30, 420);
        if (fig && Math.abs(sx2 - fig.x) < fig.rx * 0.9 &&
            Math.abs(sy2 - fig.y) < fig.ry * 0.9) continue;
        starMark(ctx, rng, sx2, sy2, rng.r(8, 16),
                 mix(moonC, night, rng.r(0.15, 0.45)));
      }
    }
    g.pale = pale;
  }

  // ground language name -> its painter
  const GROUND_LANGS = {
    crayon: groundCrayon, daylight: groundDaylight,
    aurora: groundAurora, scoured: groundScoured, banded: groundBanded,
    white: groundWhite, zombie: groundZombie, vampire: groundVampire,
  };

  // ======= THE LIGHT AND THE CAST, per fate (round 989) ================
  // After the language has laid its field, the shared engine gives it
  // light (a curtain and grit, in the fate's weather) where the language
  // did not already build its bands from them, then lays the glyph cast
  // from its own paint stream. Faithful is turned down (zero to two
  // glyphs, daylight hues); the fates are louder.
  function worldLight(g) {
    const ctx = g.ctx, rng = g.rng, paper = g.paper, fig = g.fig, LG = g.LG;
    const GO = g.GO, deep = g.deep, litX = g.litX, litY = g.litY;
    const fate = GO.fate || 'faithful';
    const L = g.lang;
    // ---- the curtain, for the languages that laid one field --------
    if (fate === 'faithful' && L !== 'banded') {
      const hues = deep
        ? [glow(paper, rng.r(0.22, 0.34)),
           LG(glow(hueShiftC(paper, rng.r(-26, 26)), rng.r(0.26, 0.40))),
           mix(hx('#e6ecf2'), paper, rng.r(0.35, 0.50))]
        : [LG(mix(lift(paper, rng.r(0.10, 0.20)), hx('#dfe7ee'), rng.r(0.25, 0.45))),
           // faithful daylight is COOL: the second thread leans toward a
           // cobalt, teal or lavender can even on cream paper
           LG(mix(lift(paper, rng.r(0.04, 0.12)),
                  hx(rng.pick(['#2a5cd8', '#1f8f8a', '#8fd8c0', '#a99ad8',
                               '#7fb0e0'])), rng.r(0.40, 0.62))),
           mix(hx('#f7f5ef'), paper, rng.r(0.25, 0.40))];
      const crayon = L === 'crayon';
      const falling = rng.chance(0.62);
      lightCurtain(ctx, rng, {
        hues: hues,
        dir: falling ? Math.PI / 2 + rng.r(-0.30, 0.30) : rng.r(-0.35, 0.35),
        cx: falling ? litX + rng.r(-60, 60) : 500,
        cy: falling ? 500 : Math.max(200, Math.min(800, litY + rng.r(-100, 100))),
        span: falling ? rng.r(440, 640) : rng.r(360, 560), len: 1500,
        n: Math.round((crayon ? 40 : 64) * rng.r(0.85, 1.25)),
        w: [2.4, crayon ? 6.5 : 8.5],
        a: crayon ? [0.10, 0.26] : [0.12, 0.34], fall: 0.6, bow: 0.05,
        dry: crayon ? 0.35 : 0.18 });
      gritCloud(ctx, rng, Math.max(60, Math.min(940, litX)),
                Math.max(50, Math.min(950, litY)), rng.r(70, 130),
                [hues[2], hues[0]], { a: crayon ? 0.24 : 0.32, dens: 0.85,
                                     elx: rng.r(1.0, 1.6), ely: rng.r(0.6, 1.0) });
      gritPoints(ctx, rng, 6 + Math.floor(rng.f() * 12), [hues[2], hues[0]],
                 fig, 20, 960);
      ctx.globalAlpha = 1;
    }
    // ---- the glyph cast, from its own stream -------------------------
    const seed = GO.seed | 0;
    const grng = R((Math.imul(seed ^ 0x7f4a7c15, 0x9e3779b1) ^
                    (seed >>> 5) ^ 0x3c6ef372) >>> 0);
    if (GO.ones || GO.quiet) return;
    const gf = grng.f();
    let count, cans, kinds, y0 = 60, y1 = 940, sMin = 70, sMax = 150;
    if (fate === 'faithful') {
      // LOOSEN (2026-09-02): the faithful world is no longer turned down
      // to a whisper; zero to four marks, a third of the sheet at three or more
      count = gf < 0.10 ? 0 : gf < 0.36 ? 1 : gf < 0.66 ? 2 : gf < 0.90 ? 3 : 4;
      const skyC = g.skyC || paper;
      const dark = lum(skyC) < 120;
      const ink = mix(hx('#221d18'), skyC, 0.08);
      cans = dark ? [hx('#f4f2ea'), hx('#f4f2ea'), hx('#7fd6f2'), hx('#f6e08a')]
                  : [ink, ink, LG(hx('#2a5cd8')), LG(hx('#1f8f8a')), hx('#f4f2ea')];
      kinds = GLYPH_KINDS.concat(['owner', 'owner']);
    } else if (fate === 'zombie') {
      count = 1 + (gf < 0.55 ? 1 : 0) + (grng.f() < 0.35 ? 1 : 0)
              + (grng.f() < 0.20 ? 1 : 0);
      cans = [hx('#14100c'), hx('#14100c'), hx('#ff3fa4'), hx('#f4f2ea'),
              hx('#a4e838'), hx('#2a5cd8')];
      kinds = GLYPH_KINDS.concat(['owner']);
      sMin = 80; sMax = 190;
    } else if (fate === 'angel') {
      count = gf < 0.40 ? 0 : gf < 0.80 ? 1 : 2;
      cans = [hx(ANGEL_GOLD), hx(ANGEL_GOLD), hx('#9aa0ac')];
      kinds = ['star', 'cloud', 'heart', 'moon', 'sun', 'rain', 'ladder',
               'arrow', 'bone', 'paw', 'bird', 'owner'];
      y1 = 640; sMin = 60; sMax = 120;
    } else if (fate === 'vampire') {
      count = gf < 0.55 ? 0 : 1;
      cans = [g.pale || mix(paper, hx('#dfe6f0'), 0.5)];
      kinds = ['moon', 'star', 'bolt', 'xout', 'arrow', 'eye', 'sword',
               'snake', 'bird', 'owner', 'tally', 'spiral'];
      sMin = 60; sMax = 130;
    } else { // immortal: round 980's world is left alone; one small
             // mark at most, and usually none
      count = gf < 0.62 ? 0 : 1;
      cans = [hx('#f4f2ea'), hx('#4fd6c0'), hx('#e84fa0'), hx('#f6e08a')];
      kinds = ['star', 'bolt', 'arrow', 'xout', 'spiral', 'eye', 'sword',
               'owner', 'moon', 'sun', 'tally', 'bird', 'snake', 'flame'];
      sMin = 60; sMax = 130;
    }
    if (count > 0)
      paintGlyphCast(ctx, grng, fig, count, cans,
                     { kinds: kinds, y0: y0, y1: y1, sMin: sMin, sMax: sMax,
                       rainbow: [hx('#e84fa0'), hx('#f6e08a'), hx('#4fd6c0')] });
    ctx.globalAlpha = 1;
  }

  function paintGround(ctx, rng, paper, fig, leg, lang, gopt) {
    const LG = leg || (c => c);
    const GO = gopt || {};
    // the support under everything is warm kraft board — except at night,
    // where the thing showing through the worn paint is not cream paper
    // but the cold blue-black under-layer of the panel itself (round 124:
    // the verdict caught the vampire standing on warm brown)
    const board = GO.board ||
      hx(rng.pick(['#d8c7a2', '#dccfae', '#cfc09c',
                   '#e0d2b2', '#d4c6a6']));
    ctx.fillStyle = css(board);
    ctx.fillRect(0, 0, 1000, 1000);
    const deep = lum(paper) < 120;
    const satUpG = (c, t) => {
      const r2 = c[0] / 255, g2 = c[1] / 255, b2 = c[2] / 255;
      const mx2 = Math.max(r2, g2, b2), mn2 = Math.min(r2, g2, b2);
      return mix(c, hsl(hueOf(c)[0], 0.5, (mx2 + mn2) / 2), t);
    };
    const L = lang || 'scoured';
    // the light corner: every language keys its drift to one point
    const litX = rng.chance(0.5) ? rng.r(90, 400) : rng.r(600, 910);
    const litY = rng.chance(0.62) ? rng.r(20, 250) : rng.r(700, 960);

    // ROUND 908: fate FIRST, then language inside the branch.
    // ROUND 989: the zombie support is candy cream; its world is the 966
    // candy bands and the kraft-through-char oxblood is gone with the
    // burnt night.
    const fate = GO.fate;
    const boardZ = fate === 'zombie'
      ? mix(hx('#f4e6c0'), hx('#efe0b0'), rng.r(0.2, 0.7))
      : board;
    if (fate === 'zombie') {
      ctx.fillStyle = css(boardZ);
      ctx.fillRect(0, 0, 1000, 1000);
    }
    const bag = {
      ctx: ctx, rng: rng, paper: paper, fig: fig, LG: LG, GO: GO,
      board: boardZ, deep: deep, satUpG: satUpG, litX: litX, litY: litY,
      lang: L,
    };
    if (fate === 'zombie') groundZombie(bag);
    else if (fate === 'angel') groundWhite(bag);
    else if (fate === 'vampire') groundVampire(bag);
    else if (fate === 'immortal') groundAurora(bag);
    else (GROUND_LANGS[L] || groundScoured)(bag);
    worldLight(bag);
  }

  // ------------------------------------------------------------- skulls
  // Linked parameter bundles: head ratio, muzzle, eye placement, ears vary
  // together so each archetype is a different animal, not a reskin.
  // THE SKULL IS WIDE AND SQUARE (the brief's hard mandate): every
  // archetype is a broad rounded rectangle — high forehead, soft-square
  // jaw, cheeks filling the corners — and the eyes are BIG and pushed
  // OUT toward the sides, almost under the ears. The tall narrow oval
  // and the close-set bead are both named failures now.
  const ARCH = [
    { name: 'hound',                                  // the longest face left
      hw: [235, 280], asp: [0.98, 1.10], cheek: [0.05, 0.11], crown: [0.05, 0.11],
      chin: [0.04, 0.10], mzW: [0.42, 0.50], mzY: [0.50, 0.58], mzH: [0.26, 0.32],
      eyeSp: [0.40, 0.50], eyeY: [-0.32, -0.22], eyeR: [0.096, 0.120],
      ears: ['long', 'long', 'drop'], eyeStyle: 'bead', neck: [0.52, 0.62],
      muz: ['long', 'long', 'offset', 'bare'] },
    { name: 'mastiff',                                // wide flat face
      hw: [300, 345], asp: [0.80, 0.92], cheek: [0.12, 0.20], crown: [0.10, 0.16],
      chin: [0.00, 0.05], mzW: [0.50, 0.60], mzY: [0.50, 0.58], mzH: [0.22, 0.27],
      eyeSp: [0.44, 0.54], eyeY: [-0.14, -0.02], eyeR: [0.088, 0.110],
      ears: ['drop', 'drop', 'fold'], eyeStyle: 'bead', neck: [0.62, 0.74],
      muz: ['pushed', 'pushed', 'round', 'bare'] },
    { name: 'spitz',                                  // broad wedge + pricked ears
      hw: [255, 300], asp: [0.90, 1.02], cheek: [0.09, 0.15], crown: [0.04, 0.09],
      chin: [-0.05, 0.00], mzW: [0.38, 0.46], mzY: [0.46, 0.54], mzH: [0.22, 0.28],
      eyeSp: [0.42, 0.52], eyeY: [-0.22, -0.12], eyeR: [0.095, 0.120],
      ears: ['prick', 'prick', 'fold', 'drop'], eyeStyle: 'open', neck: [0.50, 0.60],
      muz: ['bare', 'bare', 'long', 'offset'] },
    { name: 'pup',                                    // huge square baby skull
      hw: [300, 350], asp: [0.90, 1.04], cheek: [0.11, 0.17], crown: [0.02, 0.07],
      chin: [0.02, 0.08], mzW: [0.32, 0.40], mzY: [0.44, 0.52], mzH: [0.18, 0.23],
      eyeSp: [0.42, 0.52], eyeY: [-0.14, -0.02], eyeR: [0.105, 0.130],
      ears: ['drop', 'drop', 'long', 'fold'], eyeStyle: 'open', neck: [0.46, 0.56],
      muz: ['round', 'bare', 'pushed'] },
    { name: 'terrier',                                // scruffy, bearded
      hw: [255, 300], asp: [0.94, 1.06], cheek: [0.07, 0.13], crown: [0.08, 0.14],
      chin: [0.06, 0.13], mzW: [0.44, 0.52], mzY: [0.52, 0.60], mzH: [0.24, 0.30],
      eyeSp: [0.40, 0.50], eyeY: [-0.26, -0.16], eyeR: [0.092, 0.115],
      ears: ['fold', 'fold', 'drop', 'drop'], eyeStyle: 'bead', neck: [0.54, 0.66],
      muz: ['round', 'offset', 'long', 'bare'] },
  ];
  const ARCH_BY = {};
  ARCH.forEach(a => { ARCH_BY[a.name] = a; });

  // ======================================================================
  // ROUND 124: THE BREED STREAM (the round's mandate: THE DOG TYPE ROUND)
  // The sheet read as one dog in different colours because muzzle, ear
  // and coat were all drawn late off the MAIN rng stream, downstream of
  // pose and palette, from per-archetype lists that overlapped almost
  // completely. So a breed is now a first-class BUNDLE rolled off its own
  // hashed stream before anything else happens — fourteen dogs that are
  // different ANIMALS inside the house wide-square skull:
  //   muz   'pushed' (flat, in the face) 'round' (short blunt) 'bare'
  //         (medium) 'long' (a real tapered snout dropping past the jaw)
  //   ear   'button' (tiny rounded, low, close) 'prick' 'tall' (narrow
  //         shepherd points well above the skull) 'fold' 'drop'
  //         'long' (heavy lappets hanging past the jaw)
  //   coat  'smooth' 'plush' 'shag' (long, hanging, fringed silhouette)
  //         'wiry' (broken, tufted) 'curly' (a scalloped outline)
  //   bld   'squat' 'compact' 'low' 'leggy' 'tiny'
  //   furn  face furniture that FOLLOWS from the choice, so the type is
  //         legible at 64px: jowls, beard, brow wrinkles, a topknot, an
  //         underbite with one tooth showing, cheek ruff, brow tufts
  const BREEDS = [
    { n: 'brachy',  a: 'mastiff', muz: 'pushed', ear: ['button', 'fold', 'button'],
      coat: ['smooth', 'smooth', 'plush'], bld: 'squat',
      furn: ['jowl', 'wrinkle', 'underbite'], w: 1.0 },
    { n: 'bully',   a: 'mastiff', muz: 'pushed', ear: ['prick', 'tall', 'fold'],
      coat: ['smooth', 'smooth'], bld: 'squat', furn: ['jowl', 'wrinkle'], w: 0.9 },
    { n: 'shepherd', a: 'spitz', muz: 'long',   ear: ['tall', 'tall', 'prick'],
      coat: ['plush', 'plush', 'shag'], bld: 'leggy', furn: [], w: 1.0 },
    { n: 'hound',   a: 'hound',  muz: 'long',   ear: ['long', 'long'],
      coat: ['smooth'], bld: 'low', furn: ['jowl'], w: 1.0 },
    { n: 'spitzy',  a: 'spitz',  muz: 'round',  ear: ['prick', 'prick', 'tall'],
      coat: ['plush', 'plush'], bld: 'compact', furn: ['ruff'], w: 1.0 },
    { n: 'terrier', a: 'terrier', muz: 'bare',  ear: ['fold', 'fold', 'prick'],
      coat: ['wiry', 'wiry'], bld: 'compact', furn: ['beard', 'browtuft'], w: 1.0 },
    { n: 'schnauz', a: 'terrier', muz: 'round', ear: ['fold', 'button'],
      coat: ['wiry'], bld: 'compact', furn: ['beard', 'browtuft', 'ruff'], w: 0.8 },
    { n: 'poodle',  a: 'hound',   muz: 'bare',  ear: ['long', 'long', 'drop'],
      coat: ['curly', 'curly'], bld: 'leggy', furn: ['topknot'], w: 0.9 },
    { n: 'sheepdog', a: 'pup',    muz: 'round', ear: ['drop', 'long'],
      coat: ['shag', 'shag'], bld: 'squat', furn: ['browtuft', 'beard'], w: 0.9 },
    { n: 'corgi',   a: 'spitz',   muz: 'bare',  ear: ['tall', 'tall', 'prick'],
      coat: ['plush'], bld: 'low', furn: ['ruff'], w: 0.9 },
    { n: 'sight',   a: 'hound',   muz: 'long',  ear: ['fold', 'fold', 'button'],
      coat: ['smooth', 'smooth'], bld: 'leggy', furn: [], w: 0.8 },
    { n: 'pupp',    a: 'pup',     muz: 'round', ear: ['drop', 'drop', 'fold'],
      coat: ['plush', 'smooth'], bld: 'tiny', furn: [], w: 1.1 },
    { n: 'chow',    a: 'mastiff', muz: 'round', ear: ['button', 'button', 'prick'],
      coat: ['shag', 'plush'], bld: 'squat', furn: ['ruff', 'wrinkle'], w: 0.8 },
    { n: 'dachs',   a: 'hound',   muz: 'long',  ear: ['long', 'long', 'drop'],
      coat: ['smooth', 'wiry'], bld: 'low', furn: [], w: 0.9 },
  ];

  // ======================================================================
  // THE FEELING (round 122's mandate: THE EXPRESSION ROUND)
  // The dogs wore one face. Ten feelings now exist and the seed picks one
  // as deliberately as it picks the pose, and every one of them moves
  // FIVE things at once: the brow line, the arc of the lid across the
  // eye, the mouth, the tongue, and the set of the ears. What never
  // moves is the eye itself — big, wet and wide-set through all ten —
  // because the feeling is carried by what FRAMES the eye. That is the
  // whole Nara lesson: one construction, ten interior lives.
  //   brow   + the outer end lifts, - it drives down
  //   browIn + the INNER end drops toward the nose (anger, sulk, effort)
  //          - the inner end lifts (the sad brow, the pleading brow —
  //            the single most legible sorrow mark a face owns)
  //   lid    how far the upper lid of fur comes down over the glass
  //   lidLo  how far the lower lid pushes UP into it: the squint, and
  //          the crescent a real smile makes of an eye
  //   ears   'up' 'down' 'back' 'split' 'neutral'
  //   cock   how far the whole skull tips over
  // gaze is 2d: [past-your-shoulder, up/down]; sq = lower-lid squint
  const MOODS = [
    { name: 'deadpan', brow: 0.00, browIn: 0.00, lid: 0.10, lidLo: 0.00,
      gaze: [0.00, 0.04], sq: 0.00, mouth: 'flat',   ears: 'neutral', cock: 0.02 },
    { name: 'suspect', brow: -0.42, browIn: 0.60, lid: 0.28, lidLo: 0.18,
      gaze: [0.82, 0.02], sq: 0.16, mouth: 'flat',   ears: 'back',    cock: 0.07 },
    { name: 'smug',    brow: 0.34, browIn: 0.28, lid: 0.30, lidLo: 0.12,
      gaze: [0.58, 0.10], sq: 0.10, mouth: 'smirk',  ears: 'split',   cock: 0.10 },
    { name: 'weepy',   brow: 0.66, browIn: -0.90, lid: 0.00, lidLo: 0.26,
      gaze: [0.14, -0.24], sq: 0.00, mouth: 'wobble', ears: 'down',   cock: 0.05 },
    { name: 'curious', brow: 0.44, browIn: -0.18, lid: 0.02, lidLo: 0.00,
      gaze: [0.22, -0.06], sq: 0.00, mouth: 'o',     ears: 'split',   cock: 0.24 },
    { name: 'bark',    brow: 0.36, browIn: 0.38, lid: 0.05, lidLo: 0.16,
      gaze: [0.00, -0.08], sq: 0.00, mouth: 'bark',  ears: 'back',    cock: 0.04 },
    { name: 'sulk',    brow: -0.26, browIn: 0.85, lid: 0.20, lidLo: 0.08,
      gaze: [0.12, 0.26], sq: 0.06, mouth: 'pout',   ears: 'down',    cock: 0.03 },
    { name: 'smile',   brow: 0.28, browIn: -0.28, lid: 0.04, lidLo: 0.24,
      gaze: [0.05, 0.10], sq: 0.00, mouth: 'smile',  ears: 'neutral', cock: 0.06 },
    { name: 'sleepy',  brow: 0.12, browIn: -0.08, lid: 0.44, lidLo: 0.05,
      gaze: [0.00, 0.16], sq: 0.00, mouth: 'jowl',   ears: 'down',    cock: 0.13 },
    { name: 'delight', brow: 0.60, browIn: -0.32, lid: 0.00, lidLo: 0.04,
      gaze: [0.00, -0.04], sq: 0.00, mouth: 'grin',  ears: 'up',      cock: 0.04 },
  ];

  // ROUND 133: the five dispositions, read back off whichever mood
  // record survived the overrides. A disposition is a BROW SETTING
  // first; the mood carries the mouth, ears and head angle that agree
  // with it.
  const DISPO_OF = {
    deadpan: 'deadpan', suspect: 'wary', smug: 'wary', weepy: 'sulky',
    curious: 'dreamy', bark: 'sweet', sulk: 'sulky', smile: 'sweet',
    sleepy: 'dreamy', delight: 'sweet',
  };

  const lobe = (a, c, k) => {
    let d = Math.abs(a - c);
    d = Math.min(d, Math.PI * 2 - d);
    return Math.exp(-(d * d) / (2 * k * k));
  };

  // THE HEAD KINDS (the ugly-cute round, 2026-09-02): the dome was the
  // anchor; these are the other skulls. a runs y-down: -PI/2 is the crown,
  // PI/2 the chin, 0 and PI the cheeks.
  function headKindMod(kind, a, s) {
    const up = Math.max(0, -Math.sin(a)), dn = Math.max(0, Math.sin(a)), sideK = Math.abs(Math.cos(a));
    const diag = Math.pow(Math.sin(2 * a), 2);
    switch (kind) {
      case 'potato':   return 1 + 0.10 * Math.sin(3 * a + s * 6.28) + 0.06 * Math.cos(2 * a + s * 3);
      case 'loaf':     return 1 - 0.18 * Math.pow(up, 3) + 0.10 * diag * up + 0.05 * dn;
      case 'pear':     return 1 - 0.14 * up + 0.16 * dn * (0.4 + 0.6 * sideK);
      case 'brick':    return 1 - 0.14 * Math.pow(up, 4) - 0.08 * Math.pow(dn, 4) + 0.15 * diag;
      case 'mushroom': return 1 + 0.16 * up * (0.5 + 0.5 * sideK) - 0.14 * dn * sideK;
      case 'smudge':   return 1 + 0.13 * Math.sin(2 * a + s * 6.28) + 0.09 * Math.sin(5 * a - s * 4) * (0.5 + 0.5 * dn);
    }
    return 1;
  }
  function headOutline(rng, D) {
    if (D.profilePaint && D.prof) return profileOutline(rng, D);
    const n = 56;
    const noise = smoothArr(Array.from({ length: n }, () => rng.f() * 2 - 1), 3, true);
    const pts = [];
    for (let i = 0; i < n; i++) {
      const a = i / n * Math.PI * 2;               // y-down; PI/2 = chin
      let m = 1 + noise[i] * 0.028;
      m += D.cheek * (lobe(a, Math.PI * 0.28, 0.5) + lobe(a, Math.PI * 0.72, 0.5));
      m += D.chin * lobe(a, Math.PI * 0.5, 0.42);
      m -= D.crown * lobe(a, -Math.PI * 0.5, 0.9);
      // THE SQUARE READ: four corner lobes push the contour out at the
      // diagonals — high forehead corners, filled cheek corners — while
      // the chin center flattens a touch, so the skull is a broad
      // rounded rectangle, never a lollipop circle
      m += D.sqr * (lobe(a, Math.PI * 0.30, 0.42) + lobe(a, Math.PI * 0.70, 0.42) +
                    lobe(a, -Math.PI * 0.28, 0.44) + lobe(a, -Math.PI * 0.72, 0.44));
      m -= D.sqr * 0.4 * lobe(a, Math.PI * 0.5, 0.26);
      m += D.asym * (lobe(a, Math.PI * 0.05, 0.6) - lobe(a, Math.PI * 0.95, 0.6));
      if (D.headKind) m *= headKindMod(D.headKind, a, D.headSeed || 0.5);
      pts.push([D.hcx + Math.cos(a) * D.hrx * m,
                D.hcy + Math.sin(a) * D.hry * m]);
    }
    return smoothPts(pts, true, 1);
  }

  // ---------------------------------------- the seventy-five portraits
  // seeds 1-75: ICONS as dogs, published under a bare year and
  // nothing else, painted in the same hand as everyone else. The old
  // archetypes (and every comic-book character among them) are gone.
  // coat/paper chosen by eye (the chord loop is skipped); robe recolors
  // the bust body while the head keeps the coat

  // ==== 142_haring: Astra 2026-09-07 ====
// ---- 142 1982 the barking dog -------------------------------------------
function outlineClosed142(ctx, rng, pts, color, width) {
  ribbon(ctx, rng, pts.concat([pts[0]]), color, width,
         { taper: 0.02, wob: 0.08, jit: 0.45 });
}

function motionDash142(ctx, rng, x, y, a, len, color, width) {
  ribbon(ctx, rng,
         [[x - Math.cos(a) * len * 0.5, y - Math.sin(a) * len * 0.5],
          [x + Math.cos(a) * len * 0.5, y + Math.sin(a) * len * 0.5]],
         color, width, { taper: 0.04, wob: 0.08, jit: 0.45 });
}

function filledOutlined142(ctx, rng, pts, fill, ink, width) {
  paintShape(ctx, rng, pts, fill, { n: 7, szMul: 0.82, drift: 0.015 });
  paintShape(ctx, rng, pts, fill, { n: 5, szMul: 0.72, drift: 0.01 });
  outlineClosed142(ctx, rng, pts, ink, width);
}

function onesBehindHaring142(env) {
  const ctx = env.ctx, rng = env.rng;
  const red0 = hx('#ff291d');
  const red = env.state === 'zombie' ? sink(red0, 0.25) : red0;
  const yellow = env.state === 'zombie' ? sink(hx('#ffe11a'), 0.25) : hx('#ffe11a');
  const black = hx('#11100e');
  const lw = 25;
  const sd = env.D.headSX < 500 ? 1 : -1;

  // A saturated wall puts a hard colour behind the cream coat; two passes survive the kit.
  wBackFill(env, red, -20, 1020, 1);
  wBackFill(env, red, -20, 1020, 0.88);

  // One huge barking dog occupies the open upper side, clear of the real dog's head.
  const dx = sd > 0 ? 742 : 258;
  const dogBody142 = [[dx - sd * 145, 224], [dx + sd * 184, 224],
                      [dx + sd * 184, 350], [dx + sd * 132, 350],
                      [dx + sd * 128, 425], [dx + sd * 76, 425],
                      [dx + sd * 69, 350], [dx - sd * 42, 350],
                      [dx - sd * 48, 425], [dx - sd * 101, 425],
                      [dx - sd * 96, 322], [dx - sd * 145, 296]];
  outlineClosed142(ctx, rng, dogBody142, black, lw);

  const dogHead142 = [[dx - sd * 145, 248], [dx - sd * 196, 172],
                      [dx - sd * 150, 58], [dx - sd * 91, 120],
                      [dx - sd * 26, 79], [dx + sd * 44, 113],
                      [dx - sd * 4, 160], [dx + sd * 75, 200],
                      [dx - sd * 14, 245]];
  outlineClosed142(ctx, rng, dogHead142, black, lw);
  dot(ctx, dx - sd * 107, 145, 14, black);
  ribbon(ctx, rng, [[dx - sd * 4, 160], [dx - sd * 4, 204]], black, lw,
         { taper: 0.02, wob: 0.08, jit: 0.45 });

  for (let k142 = 0; k142 < 3; k142++) {
    motionDash142(ctx, rng, dx + sd * (118 + k142 * 7), 137 + k142 * 52,
                  sd > 0 ? -0.1 + k142 * 0.1 : Math.PI + 0.1 - k142 * 0.1,
                  68, black, 20);
  }

  // A large crawling radiant baby on the opposite top corner, filled hot yellow twice.
  const bx = sd > 0 ? 155 : 845;
  const babyHead142 = blob(rng, bx, 105, 55, 53, 20, 0.025);
  filledOutlined142(ctx, rng, babyHead142, yellow, black, lw);
  const babyBody142 = smoothPts(resample([
    [bx - 59, 154], [bx + 48, 151], [bx + 88, 219],
    [bx + 44, 252], [bx + 8, 207], [bx - 55, 215]
  ], true, 8), true, 1);
  filledOutlined142(ctx, rng, babyBody142, yellow, black, lw);
  ribbon(ctx, rng, [[bx - 45, 202], [bx - 101, 260], [bx - 61, 286]],
         black, lw, { taper: 0.03, wob: 0.08, jit: 0.45 });
  ribbon(ctx, rng, [[bx + 43, 196], [bx + 102, 184], [bx + 121, 225]],
         black, lw, { taper: 0.03, wob: 0.08, jit: 0.45 });
  ribbon(ctx, rng, [[bx - 14, 213], [bx - 12, 292], [bx + 39, 296]],
         black, lw, { taper: 0.03, wob: 0.08, jit: 0.45 });
  dot(ctx, bx - 20, 100, 8, black);
  dot(ctx, bx + 20, 100, 8, black);
  for (let k142 = 0; k142 < 10; k142++) {
    const a142 = k142 / 10 * Math.PI * 2;
    motionDash142(ctx, rng, bx + Math.cos(a142) * 104,
                  159 + Math.sin(a142) * 110, a142, 57, black, 19);
  }

  // One added Haring signature: a bold radiant heart high between the figures.
  const hx142 = 500, hy142 = 132;
  const heart142 = smoothPts(resample([
    [hx142, hy142 + 117], [hx142 - 92, hy142 + 28],
    [hx142 - 80, hy142 - 31], [hx142 - 39, hy142 - 49],
    [hx142, hy142 - 12], [hx142 + 39, hy142 - 49],
    [hx142 + 80, hy142 - 31], [hx142 + 92, hy142 + 28]
  ], true, 10), true, 1);
  filledOutlined142(ctx, rng, heart142, yellow, black, lw);
  for (let k142 = 0; k142 < 6; k142++) {
    const a142 = -Math.PI + k142 * Math.PI / 5;
    motionDash142(ctx, rng, hx142 + Math.cos(a142) * 132,
                  hy142 + 29 + Math.sin(a142) * 112, a142, 52, black, 18);
  }

  // A few large edge marks, with no visual confetti behind the portrait.
  const zigzags142 = [[38, 474, 1], [865, 472, -1], [432, 373, 1]];
  zigzags142.forEach((z142) => {
    ribbon(ctx, rng, [[z142[0], z142[1]], [z142[0] + 28, z142[1] - 24 * z142[2]],
                      [z142[0] + 57, z142[1] + 24 * z142[2]],
                      [z142[0] + 86, z142[1] - 24 * z142[2]],
                      [z142[0] + 114, z142[1]]], black, 21,
           { taper: 0.03, wob: 0.08, jit: 0.45 });
  });
}

function sideHaringTee142(K) {
  const white = hx('#fff8e8');
  sGarment(K, white, { hem: 0.72, n: 11 });
  sCollar(K, hx('#11100e'), -0.02, 0.15);
}

function ewOneHaringRounds142(h) {
  const ctx = h.ctx, rng = h.rng, D = h.D;
  const black = hx('#11100e');
  const gr = Math.max(D.eyeR * 1.7, D.hrx * 0.205);
  [-1, 1].forEach((sd142) => {
    const gx142 = D.hcx + sd142 * D.hrx * 0.45;
    const ring142 = [];
    for (let k142 = 0; k142 <= 28; k142++) {
      const a142 = k142 / 28 * Math.PI * 2;
      ring142.push([gx142 + Math.cos(a142) * gr,
                    D.hcy + Math.sin(a142) * gr * 0.95]);
    }
    ribbon(ctx, rng, ring142, black, Math.max(10, D.lineW * 1.2),
           { taper: 0.01, wob: 0.035, jit: 0.4 });
  });
  ribbon(ctx, rng,
         [[D.hcx - D.hrx * 0.245, D.hcy], [D.hcx + D.hrx * 0.245, D.hcy]],
         black, Math.max(9, D.lineW), { taper: 0.03, wob: 0.035, jit: 0.4 });
}

const ROW_142 = {
  coat: '#f0dfbd', paper: '#ff291d', robe: '#fff8e8', mood: 1,
  frame: 'small', eye: 'button', ear: 'drop', pose: 'stand',
  eyewear: ewOneHaringRounds142,
  behind: onesBehindHaring142, side: sideHaringTee142
}; // 142 1982 the barking dog


  // ==== 143_munch: Astra 2026-09-07 ====
// ---- 143 1893 the scream -----------------------------------------------
function onesBehindScream143(env) {
  const ctx = env.ctx, rng = env.rng, D = env.D;
  const F = onesFrame();
  const dead = env.state === 'zombie';
  const tone = c => dead ? sink(c, 0.25) : c;

  // Fewer, hotter, much broader sky ribbons: the Munch read has to survive paint.
  const orange = tone(hx('#f06a18'));
  const red = tone(hx('#d52b24'));
  const yellow = tone(hx('#ffc52d'));
  const coral = tone(hx('#f0442b'));
  const plum = tone(hx('#832536'));
  wBackFill(env, orange, -30, 470, 1);
  wBackFill(env, orange, -30, 470, 0.92);

  const skyBands = [coral, red, yellow, plum, coral, yellow, red];
  for (let k = 0; k < skyBands.length; k++) {
    const y = 30 + k * 62;
    const wave = 22 + (k % 3) * 8;
    const pts = [
      [F.x0 - 45, y + rng.r(-7, 7)],
      [F.x0 + F.w * 0.20, y - wave],
      [F.x0 + F.w * 0.42, y + wave * 0.62],
      [F.x0 + F.w * 0.63, y - wave * 0.72],
      [F.x0 + F.w * 0.82, y + wave],
      [F.x1 + 45, y + rng.r(-7, 7)]
    ];
    ribbon(ctx, rng, pts, skyBands[k], 52 + (k % 2) * 14,
      { taper: 0.01, wob: 0.55, jit: 2.1 });
    ctx.globalAlpha = 0.82;
    ribbon(ctx, rng, pts, skyBands[k], 34 + (k % 2) * 10,
      { taper: 0.01, wob: 0.42, jit: 1.7 });
    ctx.globalAlpha = 1;
  }

  // A solid blue-black field guarantees contrast behind the cream head.
  const abyss = tone(hx('#081f3d'));
  const cobalt = tone(hx('#07517a'));
  const teal = tone(hx('#087488'));
  const violet = tone(hx('#303052'));
  wBackFill(env, abyss, 405, 1025, 1);
  wBackFill(env, abyss, 405, 1025, 0.96);

  const ridge = [
    [F.x0 - 30, 500], [F.x0 + F.w * 0.12, 438],
    [F.x0 + F.w * 0.29, 472], [F.x0 + F.w * 0.44, 410],
    [F.x0 + F.w * 0.62, 468], [F.x0 + F.w * 0.79, 420],
    [F.x1 + 30, 462], [F.x1 + 30, 548], [F.x0 - 30, 548]
  ];
  const ridgePts = smoothPts(resample(ridge, true, 14), true, 1);
  paintShape(ctx, rng, ridgePts, tone(hx('#152b31')),
    { n: 10, szMul: 0.9, drift: 0.025 });
  paintShape(ctx, rng, ridgePts, tone(hx('#152b31')),
    { n: 8, szMul: 0.75, drift: 0.02 });

  const water = [cobalt, abyss, teal, violet, cobalt];
  for (let k = 0; k < water.length; k++) {
    const y = 515 + k * 105;
    const bend = 28 + k * 4;
    const pts = [
      [F.x0 - 45, y],
      [F.x0 + F.w * 0.22, y - bend],
      [F.x0 + F.w * 0.46, y + bend],
      [F.x0 + F.w * 0.70, y - bend * 0.65],
      [F.x1 + 45, y + bend * 0.35]
    ];
    ribbon(ctx, rng, pts, water[k], 92,
      { taper: 0.01, wob: 0.48, jit: 2.2 });
    ctx.globalAlpha = 0.72;
    ribbon(ctx, rng, pts, water[k], 58,
      { taper: 0.01, wob: 0.38, jit: 1.7 });
    ctx.globalAlpha = 1;
  }

  // The bridge occupies the open side, leaving the dog's head against dark water.
  const open = D.headSX < 500 ? 1 : -1;
  const nearX = open > 0 ? F.x1 + 55 : F.x0 - 55;
  const farX = 500 + open * 20;
  const deck = open > 0 ? [
    [nearX, 1030], [nearX - 465, 1030], [farX - 78, 560], [farX + 32, 535]
  ] : [
    [nearX, 1030], [nearX + 465, 1030], [farX + 78, 560], [farX - 32, 535]
  ];
  const wood = tone(hx('#a94c2f'));
  paintShape(ctx, rng, deck, wood, { n: 13, szMul: 1.0, drift: 0.035 });
  paintShape(ctx, rng, deck, wood, { n: 9, szMul: 0.8, drift: 0.025 });
  shadowEdge(ctx, rng, deck, tone(hx('#21151d')), 11, { p: 0.85 });

  const rail = tone(hx('#29151e'));
  const railHi = tone(hx('#71332e'));
  const lowRail = [[nearX, 972], [500 + open * 245, 716], [farX, 545]];
  const highRail = [[nearX, 735], [500 + open * 235, 620], [farX, 505]];
  ribbon(ctx, rng, lowRail, rail, 38, { taper: 0.40, wob: 0.14, jit: 1.3 });
  ribbon(ctx, rng, highRail, rail, 36, { taper: 0.44, wob: 0.14, jit: 1.3 });
  ribbon(ctx, rng, highRail, railHi, 12, { taper: 0.48, wob: 0.1, jit: 0.8 });
  for (let k = 1; k <= 3; k++) {
    const t = k / 4;
    const x = nearX + (farX - nearX) * t;
    const y0 = 735 + (505 - 735) * t;
    const y1 = 972 + (545 - 972) * t;
    ribbon(ctx, rng, [[x, y1 + 22], [x, y0 - 22]], rail,
      27 - t * 12, { taper: 0.16, wob: 0.12, jit: 0.9 });
  }
}

function sideLongDarkCoat143(K) {
  const navy = hx('#07182b');
  sGarment(K, navy, {
    hem: 1.0,
    n: 14,
    collar: hx('#020d19'),
    collarH: 0.38,
    lapel: hx('#17334c'),
    buttons: { c: hx('#b06b36'), n: 3, r: Math.max(5, K.D.hrx * 0.045) }
  });
}

function sfScreamPaws143(env) {
  const ctx = env.ctx, rng = env.rng, D = env.D;
  const hr = D.hrx * D.figS;
  const navy = hx('#07182b');
  const pawColor = env.coat;
  const contour = sink(env.line, 0.22);
  const cheekY = D.headSY + hr * 0.18;

  // The missing signature detail: one huge, dark open scream mouth.
  const mouth = blob(rng, D.headSX, D.headSY + hr * 0.72,
    hr * 0.15, hr * 0.22, 15, 0.08, 0);   // lower and smaller than Astra's round two, so the eye stays a dog's (Jon's desk, 2026-09-07)
  paintShape(ctx, rng, mouth, hx('#120f18'), { n: 10, szMul: 0.72, drift: 0.015 });
  paintShape(ctx, rng, mouth, hx('#120f18'), { n: 7, szMul: 0.6, drift: 0.01 });
  shadowEdge(ctx, rng, mouth, hx('#02040a'), Math.max(10, hr * 0.07), { p: 0.9 });

  [-1, 1].forEach(sd => {
    const px = D.headSX + sd * hr * 0.82;
    ribbon(ctx, rng, [
      [D.headSX + sd * hr * 0.50, D.headSY + hr * 1.58],
      [D.headSX + sd * hr * 0.94, D.headSY + hr * 0.86],
      [px, cheekY + hr * 0.14]
    ], navy, Math.max(38, hr * 0.32), { taper: 0.14, wob: 0.20, jit: 1.2 });

    const paw = blob(rng, px, cheekY, hr * 0.27, hr * 0.40,
      15, 0.10, sd * 0.07);
    paintShape(ctx, rng, paw, pawColor, { n: 11, szMul: 0.72, drift: 0.02 });
    paintShape(ctx, rng, paw, pawColor, { n: 7, szMul: 0.60, drift: 0.015 });
    shadowEdge(ctx, rng, paw, contour, Math.max(10, hr * 0.065), { p: 0.92 });

    for (let k = -1; k <= 1; k++) {
      const tx = px + k * hr * 0.105;
      ribbon(ctx, rng, [[tx, cheekY - hr * 0.35],
        [tx - sd * hr * 0.018, cheekY - hr * 0.23]], contour,
      Math.max(8, hr * 0.052), { taper: 0.25, wob: 0.08, jit: 0.35 });
    }
  });
}

const ROW_143 = { coat: '#f0d8b8', paper: '#f05a24', robe: '#07182b', mood: 8,
  frame: 'small', eye: 'wide', ear: 'drop', pose: 'stand', freehands: true,
  behind: onesBehindScream143, side: sideLongDarkCoat143, front: sfScreamPaws143 }; // 143 1893 the scream


  // ==== 144_dali: Astra 2026-09-07 ====
// ---- 144 1931 Salvador Dali: The Persistence of Memory -----------------

function paintMeltingWatch144(env, cx, cy, rx, ry, droop, tilt) {
  const ctx = env.ctx, rng = env.rng;
  const gold = hx('#ed8f18');
  const face = hx('#ffd34e');
  const ink = hx('#2b1812');
  const pts = [];
  const n = 24;

  // An ellipse whose lower half has forgotten that it should be round.
  for (let k = 0; k < n; k++) {
    const a = k / n * Math.PI * 2;
    const lower = Math.max(0, Math.sin(a));
    const pinch = 1 - lower * 0.18;
    const x0 = Math.cos(a) * rx * pinch;
    const y0 = Math.sin(a) * ry + lower * lower * droop;
    const x = cx + x0 * Math.cos(tilt) - y0 * Math.sin(tilt);
    const y = cy + x0 * Math.sin(tilt) + y0 * Math.cos(tilt);
    pts.push([x, y]);
  }
  const soft = smoothPts(resample(pts, true, 8), true, 2);
  paintShape(ctx, rng, soft, gold, { n: 8, szMul: 0.78, drift: 0.025 });
  paintShape(ctx, rng, soft, gold, { n: 5, szMul: 0.72, drift: 0.02 });
  shadowEdge(ctx, rng, soft, ink, 11, { p: 0.9, th: 0.48 });

  const inner = blob(rng, cx, cy + droop * 0.20, rx * 0.78, ry * 0.69, 20, 0.045, tilt);
  paintShape(ctx, rng, inner, face, { n: 7, szMul: 0.66, drift: 0.02 });
  paintShape(ctx, rng, inner, face, { n: 4, szMul: 0.6, drift: 0.015 });
  shadowEdge(ctx, rng, inner, ink, 8, { p: 0.9, th: 0.5 });

  // Hours are thumbprints; the hands are two short strips of dark paint.
  for (let k = 0; k < 12; k++) {
    const a = k / 12 * Math.PI * 2 + tilt;
    const tx = cx + Math.cos(a) * rx * 0.59;
    const ty = cy + droop * 0.18 + Math.sin(a) * ry * 0.48;
    dot(ctx, tx, ty, Math.max(5, rx * 0.052), ink);
  }
  const hy = cy + droop * 0.18;
  ribbon(ctx, rng, [[cx, hy], [cx + rx * 0.26, hy - ry * 0.17]], ink,
    Math.max(7, rx * 0.065), { taper: 0.5, wob: 0.12, jit: 0.5 });
  ribbon(ctx, rng, [[cx, hy], [cx - rx * 0.10, hy - ry * 0.34]], ink,
    Math.max(7, rx * 0.06), { taper: 0.55, wob: 0.12, jit: 0.5 });
  dot(ctx, cx, hy, Math.max(6, rx * 0.065), ink);
}

function onesBehindDali144(env) {
  const ctx = env.ctx, rng = env.rng;
  const F = onesFrame();
  const open = env.D.headSX < 500 ? 1 : -1;
  const dim = env.state === 'zombie' ? 0.25 : 0;
  const blue = sink(hx('#65c5e5'), dim);
  const pale = sink(hx('#d4df9a'), dim);
  const yellow = sink(hx('#ffc83d'), dim);
  const sea = sink(hx('#3586aa'), dim);
  const earth = sink(hx('#75402d'), dim);
  const ochre = sink(hx('#d87820'), dim);
  const dark = sink(hx('#342820'), dim);

  // The room becomes a bleached, banded Catalan afternoon.
  wBackFill(env, blue, -20, 285, 1);
  wBackFill(env, blue, -20, 285, 0.72);
  wBackFill(env, pale, 275, 370, 1);
  wBackFill(env, yellow, 360, 430, 1);
  // The darker sea band is deliberately behind the cream head.
  wBackFill(env, sea, 420, 535, 1);
  wBackFill(env, sea, 420, 535, 0.7);
  wBackFill(env, earth, 525, 1020, 1);
  wBackFill(env, earth, 525, 1020, 0.68);
  ctx.globalAlpha = 0.28;
  for (let k = 0; k < 13; k++) {
    const y = 545 + k * 34 + rng.r(-7, 7);
    ribbon(ctx, rng, [[F.x0, y], [F.x1, y + rng.r(-12, 12)]],
      k % 2 ? hx('#9a6840') : hx('#5d4032'), rng.r(6, 13),
      { taper: 0.12, wob: 0.22, jit: 1.3 });
  }
  ctx.globalAlpha = 1;

  // Low cliffs sit beyond the head, bright at their sunward edges.
  const cliffX = 500 + open * 390;
  const cliffs = open > 0
    ? [[690, 530], [720, 486], [760, 502], [800, 445], [842, 468], [890, 406], [936, 450], [1020, 430], [1020, 548]]
    : [[310, 530], [280, 486], [240, 502], [200, 445], [158, 468], [110, 406], [64, 450], [-20, 430], [-20, 548]];
  paintShape(ctx, rng, smoothPts(resample(cliffs, true, 11), true, 1), ochre,
    { n: 8, szMul: 0.75, drift: 0.04 });
  paintShape(ctx, rng, smoothPts(resample(cliffs, true, 11), true, 1), ochre,
    { n: 5, szMul: 0.7, drift: 0.025 });
  for (let k = 0; k < 7; k++) {
    const x = cliffX + open * rng.r(-145, 120);
    ribbon(ctx, rng, [[x, 455 + rng.r(-32, 48)], [x - open * rng.r(10, 35), 525]],
      rng.pick([hx('#e2ad55'), hx('#86502d'), hx('#c9873a')]), rng.r(7, 14),
      { taper: 0.35, wob: 0.25, jit: 1.1 });
  }

  // A black ledge, just solid enough to make the second clock sag.
  const bx = 500 + open * 350;
  const block = [[bx - 104, 610], [bx + 80, 602], [bx + 88, 716],
    [bx - 112, 725], [bx - 124, 644]];
  paintShape(ctx, rng, block, hx('#141318'), { n: 10, szMul: 0.82, drift: 0.02 });
  paintShape(ctx, rng, block, hx('#141318'), { n: 5, szMul: 0.75, drift: 0.015 });
  ctx.globalAlpha = 0.38;
  ribbon(ctx, rng, [[bx - 98, 619], [bx + 67, 611]], hx('#725d48'), 10,
    { taper: 0.18, wob: 0.15, jit: 0.7 });
  ctx.globalAlpha = 1;

  // The dead tree is a bent arm on the same open stage.
  const tx = 500 + open * 405;
  ribbon(ctx, rng, [[tx, 790], [tx - open * 10, 595], [tx - open * 5, 360]], dark, 42,
    { taper: 0.36, wob: 0.28, jit: 1.5 });
  ribbon(ctx, rng, [[tx - open * 5, 420], [tx + open * 80, 402], [tx + open * 145, 414]], dark, 27,
    { taper: 0.58, wob: 0.26, jit: 1.2 });
  ribbon(ctx, rng, [[tx - open * 18, 600], [tx + open * 48, 557]], sink(dark, 0.08), 17,
    { taper: 0.65, wob: 0.2, jit: 1 });

  // Two impossible pocket watches: one over wood, one over stone.
  paintMeltingWatch144(env, tx + open * 105, 397, 112, 56, 105, open * 0.05);
  paintMeltingWatch144(env, bx - open * 18, 594, 132, 64, 122, open * 0.08);
}

