  // ==== 145_lichtenstein: Astra 2026-09-07 ====
function onesBehindComicBurst145(env) {
  const ctx = env.ctx, rng = env.rng, F = onesFrame();
  const red = hx('#e51f2b');
  const yellow = hx('#ffdf12');
  const blue = hx('#1456c4');
  const black = hx('#000000');
  const white = hx('#ffffff');
  const zombie = env.state === 'zombie';
  const sd = env.D.headSX < 500 ? 1 : -1;

  // Keep the upper wall like a pale comics page, but give the cream dog a
  // hard blue panel to stand against. Every broad field gets two paint loads.
  const page = zombie ? sink(blue, 0.48) : white;
  const dogPanel = zombie ? sink(blue, 0.28) : blue;
  wBackFill(env, page, -20, 820, 0.98);
  wBackFill(env, page, -20, 820, 0.82);
  wBackFill(env, dogPanel, 355, 820, 0.98);
  wBackFill(env, dogPanel, 355, 820, 0.88);

  // One mechanically even Ben-Day screen across the full hero width. On the
  // blue panel, white and hot red dots keep the screen legible behind the dog.
  ctx.globalAlpha = 0.94;
  const pitch = 25;
  const radius = 9;
  let row = 0;
  for (let y = 8; y <= 800; y += pitch) {
    let col = 0;
    for (let x = F.x0 + 8; x <= F.x1; x += pitch) {
      let color;
      if (y < 355) color = (row + col) % 5 === 0 ? blue : red;
      else color = (row + col) % 4 === 0 ? yellow : ((row + col) % 2 ? white : red);
      dot(ctx, x, y, radius, color);
      col++;
    }
    row++;
  }
  ctx.globalAlpha = 1;

  // A large empty speech balloon, high and clear of the head.
  const bx = 500 - sd * 315;
  const by = 176;
  const bubble = smoothPts(resample([
    [bx - 166, by - 66],
    [bx - 96, by - 112],
    [bx + 35, by - 116],
    [bx + 150, by - 72],
    [bx + 176, by + 2],
    [bx + 132, by + 76],
    [bx + 38, by + 98],
    [bx - 68, by + 87],
    [bx - 126, by + 48],
    [bx - 140, by + 130],
    [bx - 76, by + 68],
    [bx - 169, by + 25]
  ], true, 12), true, 2);
  paintShape(ctx, rng, bubble, white, { n: 11, szMul: 0.78, drift: 0.008 });
  paintShape(ctx, rng, bubble, white, { n: 5, szMul: 0.68, drift: 0.006 });
  ribbon(ctx, rng, bubble.concat([bubble[0]]), black, 17,
         { taper: 0.01, wob: 0.06, jit: 0.45 });

  // The open side carries a single huge, blunt WHAAM-like star: fewer spikes,
  // broader valleys and thick black contours survive the physical paint pass.
  const ex = 500 + sd * 365;
  const ey = 433;
  const burst = [];
  const burstN = 16;
  for (let k = 0; k < burstN; k++) {
    const a = -Math.PI / 2 + k / burstN * Math.PI * 2;
    const rr = k % 2 === 0 ? rng.r(202, 224) : rng.r(105, 126);
    burst.push([ex + Math.cos(a) * rr, ey + Math.sin(a) * rr * 0.90]);
  }
  paintShape(ctx, rng, burst, yellow, { n: 13, szMul: 0.84, drift: 0.015 });
  paintShape(ctx, rng, burst, yellow, { n: 6, szMul: 0.74, drift: 0.012 });
  ribbon(ctx, rng, burst.concat([burst[0]]), black, 18,
         { taper: 0.01, wob: 0.06, jit: 0.55 });

  const inner = [];
  const innerN = 12;
  for (let k = 0; k < innerN; k++) {
    const a = -Math.PI / 2 + k / innerN * Math.PI * 2;
    const rr = k % 2 === 0 ? rng.r(120, 139) : rng.r(59, 75);
    inner.push([ex + Math.cos(a) * rr, ey + Math.sin(a) * rr * 0.87]);
  }
  paintShape(ctx, rng, inner, red, { n: 11, szMul: 0.76, drift: 0.012 });
  paintShape(ctx, rng, inner, red, { n: 5, szMul: 0.66, drift: 0.01 });
  ribbon(ctx, rng, inner.concat([inner[0]]), black, 13,
         { taper: 0.01, wob: 0.06, jit: 0.5 });

  // Four broad action marks are enough; narrow decorative strokes disappear.
  ctx.globalAlpha = 0.98;
  for (let k = 0; k < 4; k++) {
    const a = -1.02 + k * 0.68;
    const r0 = 239 + rng.r(-5, 5);
    const r1 = 292 + rng.r(-7, 7);
    ribbon(ctx, rng,
      [[ex + Math.cos(a) * r0, ey + Math.sin(a) * r0 * 0.9],
       [ex + Math.cos(a) * r1, ey + Math.sin(a) * r1 * 0.9]],
      k % 2 ? red : yellow, rng.r(12, 16),
      { taper: 0.14, wob: 0.05, jit: 0.45 });
  }
  ctx.globalAlpha = 1;
}

