  // ==== 146_mondrian: Astra 2026-09-07 ====
// ---- 146 1930 the grid -----------------------------------------------
function onesBehindMondrianGrid146(env) {
  const ctx = env.ctx;
  const rng = env.rng;
  const F = onesFrame();

  // The physical kit mutes colour, so this version starts brighter. In the
  // zombie fate the canvas drops a quarter-step, while the red still gives
  // the green dog a dark, chromatic silhouette.
  const dim = env.state === 'zombie' ? 0.25 : 0;
  const white = sink(hx('#fffaf0'), dim);
  const red = sink(hx('#ef241c'), dim);
  const blue = sink(hx('#0647c7'), dim);
  const yellow = sink(hx('#ffd51a'), dim);
  const black = hx('#111113');

  wBackFill(env, white, -20, 1020, 1);

  // One enormous red cell is the stage for the cream head and jacket. The
  // smaller primaries stay at the frame edges, where the dog cannot eat them.
  const redCell146 = [[126, 194], [818, 194], [818, 748], [126, 748]];
  const blueCell146 = [[F.x0 + 6, 778], [98, 778], [98, 956], [F.x0 + 6, 956]];
  const yellowCell146 = [[850, 194], [928, 194], [928, 748], [850, 748]];

  // Two separately loaded passes keep the fields solid after translation.
  paintShape(ctx, rng, redCell146, red, { n: 7, szMul: 0.92, drift: 0.012 });
  paintShape(ctx, rng, redCell146, red, { n: 6, szMul: 0.88, drift: 0.01 });
  paintShape(ctx, rng, blueCell146, blue, { n: 7, szMul: 0.9, drift: 0.012 });
  paintShape(ctx, rng, blueCell146, blue, { n: 6, szMul: 0.86, drift: 0.01 });
  paintShape(ctx, rng, yellowCell146, yellow, { n: 7, szMul: 0.9, drift: 0.012 });
  paintShape(ctx, rng, yellowCell146, yellow, { n: 6, szMul: 0.86, drift: 0.01 });

  // A reduced, bolder grid. Its broad central cell deliberately has no line
  // through the dog's head or torso.
  ribbon(ctx, rng, [[112, -20], [112, 1020]], black, 25,
    { taper: 0.01, wob: 0.035, jit: 0.18 });
  ribbon(ctx, rng, [[834, -20], [834, 1020]], black, 27,
    { taper: 0.01, wob: 0.035, jit: 0.18 });
  ribbon(ctx, rng, [[944, -20], [944, 1020]], black, 24,
    { taper: 0.01, wob: 0.035, jit: 0.18 });

  ribbon(ctx, rng, [[F.x0, 178], [F.x1, 178]], black, 26,
    { taper: 0.01, wob: 0.035, jit: 0.18 });
  ribbon(ctx, rng, [[F.x0, 764], [F.x1, 764]], black, 28,
    { taper: 0.01, wob: 0.035, jit: 0.18 });
  ribbon(ctx, rng, [[F.x0, 970], [F.x1, 970]], black, 24,
    { taper: 0.01, wob: 0.035, jit: 0.18 });
}

function sideMondrianSuit146(K) {
  const suit = hx('#292b38');
  const ink = hx('#101016');
  const D = K.D;
  const ctx = K.ctx;
  const rng = K.rng;
  const bd = K.bd;

  sGarment(K, suit, {
    hem: 1.0,
    n: 11,
    lapel: ink,
    buttons: {
      c: hx('#050508'),
      n: 2,
      r: Math.max(4, D.hrx * 0.045)
    }
  });
  sChestVShirt(K, hx('#fff9ec'));

  // The enlarged bow survives the paint kit and reads as formal portraiture.
  const cx = D.hcx - bd * D.hrx * 0.02;
  const cy = D.hcy + D.hry * 0.98;
  const bw = D.hrx * 0.18;
  const bh = D.hrx * 0.105;
  paintShape(ctx, rng, blob(rng, cx - bw * 0.66, cy, bw, bh, 9, 0.08, -0.12),
    ink, { n: 6, szMul: 0.7, drift: 0.015 });
  paintShape(ctx, rng, blob(rng, cx + bw * 0.66, cy, bw, bh, 9, 0.08, 0.12),
    ink, { n: 6, szMul: 0.7, drift: 0.015 });
  dot(ctx, cx, cy, bh * 0.72, hx('#050508'));

  // One new signature detail: a tiny Mondrian-primary pocket square.
  const px = cx + bd * D.hrx * 0.58;
  const py = cy + D.hry * 0.33;
  const pw = Math.max(8, D.hrx * 0.09);
  paintShape(ctx, rng,
    [[px - pw, py + pw * 0.25], [px - pw * 0.65, py - pw],
     [px, py - pw * 0.3], [px + pw * 0.65, py - pw],
     [px + pw, py + pw * 0.25]],
    hx('#ef241c'), { n: 5, szMul: 0.65, drift: 0.01 });
  ribbon(ctx, rng, [[px, py - pw * 0.28], [px, py + pw * 0.3]],
    hx('#ffd51a'), Math.max(5, pw * 0.28),
    { taper: 0.02, wob: 0.03, jit: 0.1 });
}

