  // ==== 147_matisse: Astra 2026-09-07 ====
// ---- 147 1953 the cut-outs ---------------------------------------------
function paintFrondMatisse147(ctx147, rng147, cx147, cy147, height147, width147,
                              angle147, color147, flip147) {
  const outline147 = [
    [-0.08, 0.52], [-0.10, 0.31], [-0.42, 0.43], [-0.55, 0.29],
    [-0.47, 0.13], [-0.15, 0.08], [-0.12, -0.05],
    [0.40, 0.08], [0.52, -0.07], [0.44, -0.22], [0.10, -0.24],
    [0.08, -0.36], [-0.30, -0.27], [-0.44, -0.40],
    [-0.30, -0.54], [-0.03, -0.47], [0, -0.62],
    [0.15, -0.48], [0.18, -0.25], [0.17, -0.04], [0.13, 0.22],
    [0.08, 0.52],
  ].map(point147 => {
    const x147 = point147[0] * width147 * flip147;
    const y147 = point147[1] * height147;
    return [
      cx147 + x147 * Math.cos(angle147) - y147 * Math.sin(angle147),
      cy147 + x147 * Math.sin(angle147) + y147 * Math.cos(angle147),
    ];
  });
  const paperCut147 = smoothPts(resample(outline147, true, 9), true, 2);
  paintShape(ctx147, rng147, paperCut147, color147,
             { n: 9, szMul: 0.82, drift: 0.015 });
  paintShape(ctx147, rng147, paperCut147, color147,
             { n: 9, szMul: 0.82, drift: 0.015 });
}

function paintBlueFigureMatisse147(ctx147, rng147, cx147, cy147, face147,
                                    color147) {
  const scale147 = 150;
  const outline147 = [
    [-0.11, -0.96], [0.08, -1.04], [0.25, -0.91], [0.30, -0.70],
    [0.17, -0.54], [-0.01, -0.51], [0.27, -0.33], [0.57, -0.09],
    [0.47, 0.10], [0.12, -0.03], [0.27, 0.22], [0.61, 0.42],
    [0.52, 0.61], [0.11, 0.55], [-0.08, 0.36], [-0.23, 0.69],
    [-0.53, 0.96], [-0.75, 0.80], [-0.50, 0.35], [-0.27, 0.06],
    [-0.56, -0.15], [-0.47, -0.43], [-0.24, -0.58], [-0.31, -0.80],
    [-0.25, -0.98],
  ].map(point147 => [
    cx147 + face147 * point147[0] * scale147,
    cy147 + point147[1] * scale147,
  ]);
  const nude147 = smoothPts(resample(outline147, true, 8), true, 2);
  paintShape(ctx147, rng147, nude147, color147,
             { n: 9, szMul: 0.84, drift: 0.015 });
  paintShape(ctx147, rng147, nude147, color147,
             { n: 9, szMul: 0.84, drift: 0.015 });
}

function onesBehindCutoutsMatisse147(env147) {
  const ctx147 = env147.ctx;
  const rng147 = env147.rng;
  const frame147 = onesFrame();
  const dark147 = env147.state === 'zombie' ? 0.25 : 0;
  const tone147 = color147 => dark147 ? sink(color147, dark147) : color147;
  const cream147 = tone147(hx('#fff4d8'));
  const blue147 = tone147(hx('#064ed0'));
  const green147 = tone147(hx('#00a84f'));
  const orange147 = tone147(hx('#ff641e'));
  const magenta147 = tone147(hx('#ec1767'));
  const yellow147 = tone147(hx('#ffdc12'));

  wBackFill(env147, cream147, -20, 825, 1);

  // One broad sheet of coral paper sits exactly behind the pale dog.
  const headLeft147 = env147.D.headSX < 500;
  const fieldX0147 = headLeft147 ? env147.D.headSX - 185 : env147.D.headSX - 455;
  const fieldX1147 = headLeft147 ? env147.D.headSX + 455 : env147.D.headSX + 185;
  const field147 = smoothPts(resample([
    [Math.max(frame147.x0 + 45, fieldX0147), env147.D.headSY - 205],
    [Math.min(frame147.x1 - 45, fieldX1147), env147.D.headSY - 185],
    [Math.min(frame147.x1 - 30, fieldX1147 + 18), 825],
    [Math.max(frame147.x0 + 30, fieldX0147 - 16), 825],
  ], true, 12), true, 1);
  paintShape(ctx147, rng147, field147, orange147,
             { n: 10, szMul: 0.90, drift: 0.012 });
  paintShape(ctx147, rng147, field147, orange147,
             { n: 10, szMul: 0.90, drift: 0.012 });

  const fronds147 = [
    [frame147.x0 + 105, 180, 360, 190, -0.30, blue147, 1],
    [frame147.x0 + frame147.w * 0.39, 155, 320, 175, 0.38, yellow147, -1],
    [frame147.x1 - 105, 175, 390, 195, 0.24, green147, -1],
    [frame147.x0 + 100, 540, 410, 205, 0.12, magenta147, 1],
    [frame147.x1 - 85, 555, 400, 205, -0.18, yellow147, -1],
  ];
  for (let index147 = 0; index147 < fronds147.length; index147++) {
    const frond147 = fronds147[index147];
    paintFrondMatisse147(ctx147, rng147, frond147[0], frond147[1],
                         frond147[2], frond147[3], frond147[4],
                         frond147[5], frond147[6]);
  }

  // The body runs away from the head; put the Blue Nude on the open side.
  const open147 = headLeft147 ? -1 : 1;
  const figureX147 = open147 < 0 ? frame147.x0 + 205 : frame147.x1 - 205;
  paintBlueFigureMatisse147(ctx147, rng147, figureX147, 580, -open147, blue147);
}

