  // ==== 148_klimt: Astra 2026-09-07 ====
// ---- 148 1908 the gold -----------------------------------------------
function onesBehindGoldenKiss148(env) {
  const ctx = env.ctx;
  const rng = env.rng;
  const F = onesFrame();
  const sd = env.D.headSX < 500 ? 1 : -1;
  const dim = env.state === 'zombie' ? 0.25 : 0;
  const gold = sink(hx('#d49a16'), dim);
  const deepGold = sink(hx('#8f5414'), dim);
  const leafGold = sink(hx('#f1bf24'), dim);
  const black = sink(hx('#17120e'), dim);
  const white = sink(hx('#fff0c4'), dim);
  const cobalt = sink(hx('#164fa3'), dim);
  const moss = sink(hx('#477a32'), dim);
  const red = sink(hx('#c72d2a'), dim);

  // A saturated, double-laid gold-leaf wall.
  wBackFill(env, gold, -20, 1020, 0.98);
  wBackFill(env, drift(rng, gold, 0.025), -20, 1020, 0.48);
  for (let k = 0; k < 34; k++) {
    const x = rng.r(F.x0 - 30, F.x1 + 30);
    const y = rng.r(-10, 900);
    const patch = blob(rng, x, y, rng.r(42, 105), rng.r(24, 64), 9, 0.18, rng.r(-0.4, 0.4));
    ctx.globalAlpha = rng.r(0.2, 0.38);
    paintShape(ctx, rng, patch, drift(rng, deepGold, 0.07), { n: 3, szMul: 0.72, drift: 0.04 });
  }
  ctx.globalAlpha = 1;

  // A dark gold aureole keeps the cream dog legible and turns the room into an icon.
  const halo = smoothPts(resample(blob(
    rng,
    env.D.headSX + sd * 85,
    env.D.headSY - 22,
    370,
    250,
    13,
    0.12,
    0
  ), true, 16), true, 2);
  ctx.globalAlpha = 0.92;
  paintShape(ctx, rng, halo, deepGold, { n: 7, szMul: 0.9, drift: 0.035 });
  paintShape(ctx, rng, halo, drift(rng, deepGold, 0.035), { n: 6, szMul: 0.82, drift: 0.025 });
  ctx.globalAlpha = 1;

  // The Kiss: one great cloak on the open side, with two bowed faces touching above it.
  const cloakX = 500 + sd * 315;
  const cloak = smoothPts(resample([
    [cloakX - 190, 748],
    [cloakX - 188, 250],
    [cloakX - 150, 166],
    [cloakX - 82, 112],
    [cloakX + 35, 92],
    [cloakX + 128, 132],
    [cloakX + 178, 218],
    [cloakX + 190, 748]
  ], true, 12), true, 2);
  paintShape(ctx, rng, cloak, gold, { n: 8, szMul: 0.92, drift: 0.035 });
  paintShape(ctx, rng, cloak, drift(rng, gold, 0.025), { n: 7, szMul: 0.84, drift: 0.025 });
  shadowEdge(ctx, rng, cloak, black, 10, { p: 0.7 });

  ctx.save();
  ctx.beginPath();
  poly(ctx, cloak, true);
  ctx.clip();

  // His half: a sparse grid of large black-and-white rectangles.
  for (let row = 0; row < 6; row++) {
    for (let col = 0; col < 3; col++) {
      const x = cloakX - 145 + col * 55 + rng.r(-7, 7);
      const y = 300 + row * 72 + rng.r(-7, 7);
      const w = rng.r(30, 48);
      const h = rng.r(25, 43);
      const tile = [
        [x - w / 2, y - h / 2], [x + w / 2, y - h / 2],
        [x + w / 2, y + h / 2], [x - w / 2, y + h / 2]
      ];
      ctx.globalAlpha = 0.96;
      paintShape(ctx, rng, tile, (row + col) % 3 === 0 ? white : black, { n: 4, szMul: 0.62, drift: 0.02 });
    }
  }

  // Her half: flower-roundels and gold spirals, kept large enough for real paint.
  const jewels = [cobalt, moss, red, white];
  for (let k = 0; k < 18; k++) {
    const x = cloakX + rng.r(12, 158);
    const y = rng.r(280, 700);
    const r = rng.r(17, 28);
    const c = jewels[k % jewels.length];
    ctx.globalAlpha = 0.98;
    dot(ctx, x, y, r, c);
    dot(ctx, x, y, r * 0.43, k % 3 === 0 ? black : leafGold);
  }
  for (let k = 0; k < 8; k++) {
    ctx.globalAlpha = 0.9;
    scribbleKnot(ctx, rng, cloakX + rng.r(18, 155), rng.r(310, 690), rng.r(24, 34), leafGold, 4);
  }
  ctx.globalAlpha = 1;
  ctx.restore();

  // Two pale profiles make the embrace read instantly rather than as a decorated door.
  const faceY = 202;
  const faceA = blob(rng, cloakX - sd * 28, faceY, 42, 57, 10, 0.1, sd * 0.2);
  const faceB = blob(rng, cloakX + sd * 30, faceY + 13, 39, 53, 10, 0.1, -sd * 0.18);
  paintShape(ctx, rng, faceA, white, { n: 7, szMul: 0.78, drift: 0.025 });
  paintShape(ctx, rng, faceA, white, { n: 5, szMul: 0.7, drift: 0.02 });
  paintShape(ctx, rng, faceB, white, { n: 7, szMul: 0.78, drift: 0.025 });
  paintShape(ctx, rng, faceB, white, { n: 5, szMul: 0.7, drift: 0.02 });
  ribbon(ctx, rng, [
    [cloakX - sd * 62, faceY - 40],
    [cloakX - sd * 34, faceY - 78],
    [cloakX + sd * 5, faceY - 60]
  ], black, 26, { taper: 0.14, wob: 0.28, jit: 1.4 });
  ribbon(ctx, rng, [
    [cloakX + sd * 2, faceY - 42],
    [cloakX + sd * 46, faceY - 56],
    [cloakX + sd * 68, faceY - 20]
  ], deepGold, 24, { taper: 0.12, wob: 0.25, jit: 1.2 });

  // Fewer, larger floating tesserae survive the paint kit.
  for (let k = 0; k < 14; k++) {
    const x = rng.r(F.x0 + 35, F.x1 - 35);
    const y = rng.r(45, 580);
    if (Math.abs(x - cloakX) < 215) continue;
    const s = rng.r(17, 30);
    const tile = [
      [x - s, y - s], [x + s, y - s * 0.8],
      [x + s * 0.88, y + s], [x - s * 0.84, y + s * 0.86]
    ];
    ctx.globalAlpha = rng.r(0.72, 0.95);
    paintShape(ctx, rng, tile, rng.chance(0.55) ? leafGold : deepGold, { n: 4, szMul: 0.58, drift: 0.035 });
  }
  ctx.globalAlpha = 1;

  // A heavier flower meadow anchors the dog; no sub-eight-pixel stems.
  wBackFill(env, sink(hx('#66752b'), dim), 778, 870, 0.82);
  const meadow = [leafGold, cobalt, red, white];
  for (let k = 0; k < 72; k++) {
    const x = rng.r(F.x0, F.x1);
    const y = rng.r(785, 862);
    const r = rng.r(7, 14);
    ctx.globalAlpha = rng.r(0.84, 1);
    if (k % 4 === 0) {
      ribbon(ctx, rng, [[x, y + r], [x + rng.r(-4, 4), 873]], sink(moss, dim), rng.r(8, 11), { taper: 0.32, wob: 0.25, jit: 0.6 });
    }
    dot(ctx, x, y, r, sink(meadow[k % meadow.length], dim));
  }
  ctx.globalAlpha = 1;
}

