// Klimt was famously photographed holding a cat: one blunt silhouette, well clear of the dog.
function sfKlimtCat148(env) {
  const ctx = env.ctx;
  const rng = env.rng;
  const S = sScreen(env);
  const right = env.D.headSX < 500;
  const x = right ? 905 : 95;
  const gy = S.ground + 2;
  const ink = env.state === 'zombie' ? sink(hx('#17120e'), 0.25) : hx('#17120e');
  const body = blob(rng, x, gy - 52, 48, 66, 10, 0.12, right ? -0.12 : 0.12);
  const head = blob(rng, x + (right ? -10 : 10), gy - 126, 38, 36, 9, 0.1, 0);
  paintShape(ctx, rng, body, ink, { n: 7, szMul: 0.72, drift: 0.02 });
  paintShape(ctx, rng, head, ink, { n: 6, szMul: 0.7, drift: 0.02 });
  paintShape(ctx, rng, [
    [x - 35, gy - 145], [x - 28, gy - 184], [x - 5, gy - 151]
  ], ink, { n: 5, szMul: 0.62, drift: 0.02 });
  paintShape(ctx, rng, [
    [x + 8, gy - 151], [x + 31, gy - 181], [x + 30, gy - 140]
  ], ink, { n: 5, szMul: 0.62, drift: 0.02 });
  ribbon(ctx, rng, [
    [x + (right ? 35 : -35), gy - 55],
    [x + (right ? 82 : -82), gy - 96],
    [x + (right ? 68 : -68), gy - 145]
  ], ink, 17, { taper: 0.3, wob: 0.35, jit: 1 });
  dot(ctx, x - 13, gy - 130, 5, hx('#f1bf24'));
  dot(ctx, x + 11, gy - 130, 5, hx('#f1bf24'));
}

