  // ==== 149_hockney: Astra 2026-09-07 ====
// ---- 149 1967 the splash -----------------------------------------------
function onesBehindBiggerSplash149(env) {
  const ctx = env.ctx, rng = env.rng;
  const F = onesFrame();
  // Match the painter's established open-side sign used by the Hokusai block.
  const open = env.D.headSX < 500 ? 1 : -1;
  const dead = env.state === 'zombie' ? 0.25 : 0;
  const sky0 = hx('#72c7f2');
  const house0 = hx('#f0aa91');
  const pool0 = hx('#159fdf');
  const glass0 = hx('#174f59');
  const palm0 = hx('#075749');
  const white0 = hx('#fffbed');
  const yellow0 = hx('#efb526');
  const sky = dead ? sink(sky0, dead) : sky0;
  const house = dead ? sink(house0, dead) : house0;
  const pool = dead ? sink(pool0, dead) : pool0;
  const glass = dead ? sink(glass0, dead) : glass0;
  const palm = dead ? sink(palm0, dead) : palm0;
  const white = dead ? sink(white0, 0.18) : white0;
  const yellow = dead ? sink(yellow0, dead) : yellow0;

  // Saturated double-painted bands stay flat and solid after the physical kit.
  wBackFill(env, sky, -30, 328, 1);
  wBackFill(env, sky, -30, 328, 0.82);

  // Two deliberately oversized palms, entirely above the dog's silhouette.
  const palmXs = open > 0
    ? [F.x0 + F.w * 0.16, F.x0 + F.w * 0.29]
    : [F.x1 - F.w * 0.16, F.x1 - F.w * 0.29];
  palmXs.forEach((px, i) => {
    const crownY = 104 + i * 60;
    const lean = open * (i ? -18 : 12);
    ribbon(ctx, rng,
      [[px, 334], [px - lean * 0.2, 264], [px - lean * 0.65, 184], [px - lean, crownY]],
      yellow, i ? 16 : 19, { taper: 0.16, wob: 0.12, jit: 1.1 });
    const cx = px - lean;
    for (let k = 0; k < 7; k++) {
      const a = -2.92 + k * 0.50 + rng.r(-0.07, 0.07);
      const len = rng.r(92, 146);
      ribbon(ctx, rng,
        [[cx, crownY],
         [cx + Math.cos(a) * len * 0.54, crownY + Math.sin(a) * len * 0.30 + 8],
         [cx + Math.cos(a) * len, crownY + Math.sin(a) * len * 0.48 + 14]],
        palm, rng.r(12, 18), { taper: 0.72, wob: 0.20, jit: 1.1 });
    }
    dot(ctx, cx, crownY, 22, palm);
  });

  // The low modernist house is one unmistakable slab and one broad window.
  wBackFill(env, house, 328, 518, 1);
  wBackFill(env, house, 328, 518, 0.82);
  ribbon(ctx, rng, [[F.x0, 330], [F.x1, 330]], glass, 13,
    { taper: 0.01, wob: 0.035, jit: 0.5 });
  const window = [
    [F.x0 + F.w * 0.12, 382], [F.x1 - F.w * 0.06, 382],
    [F.x1 - F.w * 0.06, 476], [F.x0 + F.w * 0.12, 476]
  ];
  paintShape(ctx, rng, window, glass, { n: 10, szMul: 0.86, drift: 0.018 });
  paintShape(ctx, rng, window, glass, { n: 7, szMul: 0.76, drift: 0.012 });
  // Only three heavy mullions: fine architectural lines disappeared in paint.
  for (let k = 1; k <= 3; k++) {
    const x = F.x0 + F.w * (0.12 + k * 0.205);
    ribbon(ctx, rng, [[x, 386], [x, 472]], house, 10,
      { taper: 0.02, wob: 0.035, jit: 0.5 });
  }
  paintShape(ctx, rng, [
    [F.x0 + 12, 360], [F.x0 + F.w * 0.10, 360],
    [F.x0 + F.w * 0.10, 518], [F.x0 + 12, 518]
  ], lift(house, 0.12), { n: 8, szMul: 0.78, drift: 0.015 });

  // Strong blue behind the cream dog prevents its body from dissolving.
  wBackFill(env, pool, 518, 824, 1);
  wBackFill(env, pool, 518, 824, 0.84);
  ribbon(ctx, rng, [[F.x0, 516], [F.x1, 516]], white, 11,
    { taper: 0.01, wob: 0.035, jit: 0.5 });
  ribbon(ctx, rng, [[F.x0, 541], [F.x1, 541]], white, 9,
    { taper: 0.01, wob: 0.04, jit: 0.6 });

  // Put the board and the entire burst on the empty side, clear of the dog.
  const splashX = 500 + open * 385;
  const boardEdgeX = open > 0 ? F.x1 + 20 : F.x0 - 20;
  const boardTipX = splashX + open * 30;
  ribbon(ctx, rng,
    [[boardEdgeX, 574], [(boardEdgeX + boardTipX) * 0.5, 573], [boardTipX, 579]],
    yellow, 23, { taper: 0.04, wob: 0.06, jit: 0.6 });
  ribbon(ctx, rng,
    [[boardEdgeX, 568], [(boardEdgeX + boardTipX) * 0.5, 568], [boardTipX, 574]],
    lift(yellow, 0.30), 9, { taper: 0.08, wob: 0.04, jit: 0.4 });

  // THE SPLASH: fewer marks, each broad enough to survive the paint transfer.
  spray(ctx, rng, splashX, 606, 132, white, 0.82,
    { a: 0.82, spread: 0.92, ely: 1.30 });
  for (let k = 0; k < 18; k++) {
    const a = rng.r(-2.76, -0.38);
    const len = rng.r(112, 282);
    const sx = splashX + rng.r(-30, 30);
    const ex = splashX + Math.cos(a) * len;
    const ey = 610 + Math.sin(a) * len;
    const mx = splashX + Math.cos(a) * len * 0.55 + rng.r(-20, 20);
    const my = 602 + Math.sin(a) * len * 0.56 - rng.r(8, 24);
    ctx.globalAlpha = rng.r(0.84, 1);
    ribbon(ctx, rng, [[sx, 618], [mx, my], [ex, ey]],
      k % 5 === 0 ? lift(pool, 0.82) : white, rng.r(10, 20),
      { taper: 0.78, wob: 0.34, jit: 1.4 });
    if (k % 2 === 0) dot(ctx, ex + rng.r(-8, 8), ey + rng.r(-6, 7), rng.r(6, 12), white);
  }
  ctx.globalAlpha = 1;
  for (let k = 0; k < 5; k++) {
    const y = 632 + k * 18;
    ctx.globalAlpha = 0.78 - k * 0.08;
    brokenRibbon(ctx, rng,
      [[splashX - 118 - k * 8, y], [splashX, y + rng.r(-4, 4)],
       [splashX + 118 + k * 8, y]],
      white, rng.r(8, 13), { taper: 0.48, wob: 0.22, jit: 1.0 });
  }
  ctx.globalAlpha = 1;
}

