  // ==== 151_magritte: Astra 2026-09-07 ====
// ---- 151 1964 the apple -----------------------------------------------
function onesBehindCumulusApple151(env) {
  const ctx = env.ctx, rng = env.rng, D = env.D;
  const F = onesFrame();
  const dead151 = env.state === 'zombie';
  const tone151 = c => dead151 ? sink(c, 0.25) : c;
  const skyTop151 = tone151(hx('#287fe0'));
  const skyMid151 = tone151(hx('#459ee8'));
  const skyLow151 = tone151(hx('#78bdf0'));
  const cloudWhite151 = tone151(hx('#fffdf2'));
  const cloudShade151 = tone151(hx('#7298bd'));
  const sea151 = tone151(hx('#397568'));
  const seaLight151 = tone151(hx('#66a797'));
  const wall151 = tone151(hx('#c7472e'));
  const brickDark151 = tone151(hx('#7d2924'));
  const floor151 = tone151(hx('#365a78'));
  const apple151 = tone151(hx('#55b529'));
  const appleDark151 = tone151(hx('#216f20'));
  const stem151 = tone151(hx('#4c2b17'));

  // Saturated stepped sky, loaded twice so the physical kit keeps it blue.
  [[-20, 235, skyTop151], [225, 470, skyMid151], [460, 705, skyLow151]].forEach(b151 => {
    wBackFill(env, b151[2], b151[0], b151[1], 1);
    wBackFill(env, b151[2], b151[0], b151[1], 0.88);
  });

  // Six large, blunt cumulus emblems stay above the dog's head and body.
  const clouds151 = [
    [55, 105, 104, 0.92],
    [315, 282, 132, 1.04],
    [610, 112, 106, 0.88],
    [900, 285, 138, 1.04],
    [90, 510, 112, 0.94],
    [430, 470, 104, 0.86]
  ];
  clouds151.forEach((c151, ci151) => {
    const cx151 = c151[0], cy151 = c151[1], cr151 = c151[2], spread151 = c151[3];
    const lobes151 = ci151 % 2 ? 4 : 3;
    for (let j151 = 0; j151 < lobes151; j151++) {
      const t151 = j151 / (lobes151 - 1);
      const x151 = cx151 + (t151 - 0.5) * cr151 * 1.72 * spread151 + rng.r(-4, 4);
      const y151 = cy151 - Math.sin(t151 * Math.PI) * cr151 * 0.38 + rng.r(-3, 3);
      const lobe151 = blob(rng, x151, y151, cr151 * rng.r(0.54, 0.72),
        cr151 * rng.r(0.34, 0.50), 14, 0.08);
      paintShape(ctx, rng, lobe151, cloudWhite151, { n: 5, szMul: 0.76, drift: 0.018 });
      paintShape(ctx, rng, lobe151, cloudWhite151, { n: 3, szMul: 0.62, drift: 0.012 });
    }
    ctx.globalAlpha = 0.46;
    ribbon(ctx, rng,
      [[cx151 - cr151 * 0.82 * spread151, cy151 + cr151 * 0.20],
       [cx151 - cr151 * 0.08, cy151 + cr151 * 0.33],
       [cx151 + cr151 * 0.78 * spread151, cy151 + cr151 * 0.20]],
      cloudShade151, Math.max(14, cr151 * 0.18),
      { taper: 0.22, wob: 0.24, jit: 1.0 });
    ctx.globalAlpha = 1;
  });

  // Sea, parapet, and a dark blue floor hold the cream dog in contrast.
  wBackFill(env, sea151, 700, 780, 1);
  wBackFill(env, sea151, 700, 780, 0.9);
  for (let j151 = 0; j151 < 4; j151++) {
    ctx.globalAlpha = 0.42;
    ribbon(ctx, rng,
      [[F.x0, 714 + j151 * 17], [F.x1, 711 + j151 * 17 + rng.r(-2, 2)]],
      seaLight151, 8, { taper: 0.02, wob: 0.20, jit: 0.7 });
  }
  ctx.globalAlpha = 1;
  wBackFill(env, wall151, 780, 834, 1);
  wBackFill(env, wall151, 780, 834, 0.88);
  ribbon(ctx, rng, [[F.x0, 784], [F.x1, 784]], brickDark151, 10,
    { taper: 0.02, wob: 0.12, jit: 0.6 });
  ribbon(ctx, rng, [[F.x0, 829], [F.x1, 829]], brickDark151, 9,
    { taper: 0.02, wob: 0.12, jit: 0.6 });
  for (let x151 = F.x0 + 40; x151 < F.x1; x151 += 128) {
    ribbon(ctx, rng, [[x151, 788], [x151, 828]], brickDark151, 8,
      { taper: 0.05, wob: 0.18, jit: 0.6 });
  }
  wBackFill(env, floor151, 834, 1020, 1);
  wBackFill(env, floor151, 834, 1020, 0.86);

  // Three distant apples are bold punctuation, not hairline details.
  [[170, 333, 17], [792, 390, 15], [946, 92, 13]].forEach(a151 => {
    const farApple151 = blob(rng, a151[0], a151[1], a151[2], a151[2] * 0.94, 11, 0.10);
    paintShape(ctx, rng, farApple151, apple151, { n: 5, szMul: 0.58, drift: 0.02 });
    ribbon(ctx, rng,
      [[a151[0], a151[1] - a151[2] * 0.65], [a151[0] + 2, a151[1] - a151[2] * 1.24]],
      stem151, 8, { taper: 0.28, jit: 0.25 });
  });

  // THE APPLE: 40% larger, solid, and wholly on the open side of the face.
  const hr151 = D.hrx * D.figS;
  const sd151 = D.headSX >= 500 ? 1 : -1;
  const ar151 = 120;
  const wantedX151 = D.headSX + sd151 * hr151 * 2.2;
  const ax151 = Math.max(F.x0 + ar151 + 12, Math.min(F.x1 - ar151 - 12, wantedX151));
  const ay151 = D.headSY - hr151 * 0.20;
  const appleBody151 = blob(rng, ax151, ay151, ar151, ar151 * 0.95, 24, 0.08);
  paintShape(ctx, rng, appleBody151, apple151, { n: 10, szMul: 0.88, drift: 0.025 });
  paintShape(ctx, rng, appleBody151, apple151, { n: 7, szMul: 0.72, drift: 0.018 });
  ctx.globalAlpha = 0.48;
  ribbon(ctx, rng,
    [[ax151 - sd151 * ar151 * 0.70, ay151 + ar151 * 0.18],
     [ax151 - sd151 * ar151 * 0.30, ay151 + ar151 * 0.56],
     [ax151 + sd151 * ar151 * 0.08, ay151 + ar151 * 0.66]],
    appleDark151, 24, { taper: 0.28, wob: 0.22, jit: 1.0 });
  ctx.globalAlpha = 1;
  ribbon(ctx, rng,
    [[ax151, ay151 - ar151 * 0.78], [ax151 - sd151 * 10, ay151 - ar151 * 1.20]],
    stem151, 17, { taper: 0.28, wob: 0.10, jit: 0.6 });
  const leaf151 = blob(rng, ax151 + sd151 * 48, ay151 - ar151 * 1.02,
    54, 24, 14, 0.08, sd151 * 0.34);
  paintShape(ctx, rng, leaf151, appleDark151, { n: 6, szMul: 0.62, drift: 0.02 });
  paintShape(ctx, rng, leaf151, appleDark151, { n: 3, szMul: 0.52, drift: 0.015 });
  shadowEdge(ctx, rng, appleBody151, sink(apple151, 0.38), 9, { p: 0.52 });
}

