// One extra Magritte signature: the pipe, painted as a blunt readable silhouette.
function sfMagrittePipe151(env) {
  const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env);
  const open151 = S.open, s151 = S.s;
  const mx151 = S.mouth[0] + open151 * D.hrx * 0.08 * s151;
  const my151 = S.mouth[1] + D.hry * 0.05 * s151;
  const len151 = Math.max(62, D.hrx * 0.62 * s151);
  const tip151 = [mx151 + open151 * len151, my151 + len151 * 0.24];
  ribbon(ctx, rng, [[mx151, my151], tip151], hx('#3d2418'), 12,
    { taper: 0.05, wob: 0.10, jit: 0.5 });
  const bowl151 = blob(rng, tip151[0] + open151 * 8, tip151[1] - 8, 23, 27, 12, 0.08);
  paintShape(ctx, rng, bowl151, hx('#4b2919'), { n: 6, szMul: 0.62, drift: 0.02 });
  shadowEdge(ctx, rng, bowl151, hx('#1b1210'), 8, { p: 0.55 });
}

