    const body=r.pick(FABLE_HOUSE_BODY),roof=r.pick(FABLE_HOUSE_ROOF);
    const lean=r.r(-0.04,0.04);            // the whole house leans a little, as a child draws it
    const P=(x,y)=>[x+(410-y)*lean,y];
    astraFoot(B,190);
