  // 41 the quotation marks: a boxy white jacket, one bright orange panel,
  // the yellow industrial belt with its black lettering, a quoted word on
  // the flank, an orange tag at the near forepaw
  function hwOneShortBlack(h) { wHairCap(h, hx('#141014'), { top: 0.76, brow: 0.52, w: 1.0, strands: 4 }); }
  function ewOneClearFrames(h) { wGlasses(h, { frame: hx('#141014'), r: 1.45, minR: 0.15, square: true, wMul: 0.09, lensA: 0 }); wBeard(h, 'chin', hx('#1e1614'), { len: 0.16, w: 0.9 }); }
  function sideQuotes(K) {
    const white = hx('#f2f0ea'), orange = K.D.robeC || hx('#f07020'), jet = hx('#141014');
    // the white jacket, black diagonals across its back half
    sGarment(K, white, { hem: 0.94, n: 10, collar: orange, collarH: 0.22, pattern: (K2, clip) => {
      const b = sBox(clip); const ctx = K2.ctx, rng = K2.rng;
      const x0 = b.x0 + b.w * 0.48;
      ctx.save(); ctx.beginPath(); ctx.rect(x0, b.y0 - 10, b.w, b.h + 20); ctx.clip();
      for (let k = 0; k < 7; k++) { const x = x0 + k * (b.w * 0.52 / 6); ctx.globalAlpha = 0.9; ribbon(ctx, rng, [[x - b.h * 0.5, b.y1], [x + b.h * 0.5, b.y0]], jet, Math.max(4, b.h * 0.07), { taper: 0.03, wob: 0.1, jit: 0.8 }); }
      ctx.globalAlpha = 1; ctx.restore(); } });
    // the yellow industrial belt with its black lettering, hanging long
    sSash(K, hx('#f0c020'), { t0: 0.0, v0: 0.72, t1: 0.98, v1: 0.74, w: Math.max(8, K.D.hry * 0.12) });
    const a = K.P(0.06, 0.73, 0), b = K.P(0.92, 0.73, 0);
    for (let k = 0; k < 6; k++) { const t = 0.05 + k * 0.17; const x = a[0] + (b[0] - a[0]) * t, y = a[1] + (b[1] - a[1]) * t; K.ctx.globalAlpha = 0.9; ribbon(K.ctx, K.rng, [[x - K.D.hrx * 0.04, y - 3], [x + K.D.hrx * 0.04, y + 3]], jet, 2.2, { taper: 0.1, jit: 0.4 }); }
    K.ctx.globalAlpha = 1;
    const tail = K.P(0.98, 0.74, 0);
    ribbon(K.ctx, K.rng, [tail, [tail[0] + K.bd * K.D.hrx * 0.1, tail[1] + K.D.hry * 0.35]], hx('#f0c020'), Math.max(7, K.D.hry * 0.1), { taper: 0.1, jit: 0.8 });
    // the quoted word, printed on the white, big
    const q = K.P(0.14, 0.30, 0);
    scrawlLine(K.ctx, K.rng, '"DOG"', q[0], q[1] + K.D.hry * 0.16, Math.max(14, K.D.hry * 0.30), jet, 'print', {});
  }
  function sideFrontQuotes(K) {
    // the orange zip tie on the near forepaw
    const ft = (K.g.nearFeet || [])[0]; if (!ft) return;
    const legW = K.f.legW;
    ribbon(K.ctx, K.rng, [[ft[0] - legW * 0.9, ft[1] - legW * 1.6], [ft[0] + legW * 0.9, ft[1] - legW * 1.7]], hx('#f07020'), Math.max(3, legW * 0.28), { taper: 0.05, jit: 0.5 });
    ribbon(K.ctx, K.rng, [[ft[0] + legW * 0.8, ft[1] - legW * 1.65], [ft[0] + legW * 1.9, ft[1] - legW * 1.2]], hx('#f07020'), Math.max(3, legW * 0.24), { taper: 0.4, jit: 0.5 });
  }
