  // ======================================================================
  // THE ROWS ON THE SIDE BODY. Batch three: seeds 51 to 75.
  // ======================================================================
  // things set down on the ground in front of the forepaws
  function sGroundSpot(env, k) {   // a point on the ground k head-widths out past the forefoot
    const D = env.D, S = sScreen(env), s = S.s;
    return { x: sClamp(S.foreFoot[0] + S.open * D.hrx * (k === undefined ? 1.1 : k) * s, 90, 910), y: S.ground, S: S, s: s, open: S.open };
  }
  function sfCigar(env) {              // the fat lit cigar in the corner of the mouth, smoke
    const ctx = env.ctx, rng = env.rng, D = env.D, s = D.figS, cx = D.headSX, cy = D.headSY, sd = -(D.bodyDir || 1);
    const mx = cx + sd * D.hrx * 0.10 * s, my = cy + D.hry * 0.60 * s;
    const cl = Math.max(60, D.hrx * 0.95 * s), cw = Math.max(12, D.hrx * 0.16 * s);
    ribbon(ctx, rng, [[mx, my], [mx + sd * cl * 0.5, my + cl * 0.12], [mx + sd * cl, my + cl * 0.20]], hx('#3a2414'), cw, { taper: 0.02, wob: 0.08, jit: 0.6, end: 0.9 });
    ribbon(ctx, rng, [[mx + sd * cl * 0.62, my + cl * 0.10], [mx + sd * cl * 0.72, my + cl * 0.15]], hx('#d8b04a'), cw * 0.9, { taper: 0.05, jit: 0.4 });
    dot(ctx, mx + sd * cl, my + cl * 0.20, cw * 0.5, hx('#f06a2a'));
    dot(ctx, mx + sd * cl, my + cl * 0.20, cw * 0.28, hx('#f8d060'));
    spray(ctx, rng, mx + sd * cl * 1.15, my - cl * 0.5, cl * 0.6, hx('#d8d8d0'), 0.6, { a: 0.28, spread: 0.6, ely: 1.8 });
  }
  // the great ruff, over the head: a wheel of pleats along the jaw's edge,
  // after the head is painted (the in-body ruff sits under it)
  function sfRuff(env, opt) {
    opt = opt || {};
    const ctx = env.ctx, rng = env.rng, D = env.D, s = D.figS, cx = D.headSX, cy = D.headSY;
    const color = opt.color || hx('#fbf8f2');
    const rx = D.hrx * (opt.rx || 1.02) * s, ry = D.hry * (opt.ry || 0.98) * s;
    const rr0 = Math.max(9, D.hrx * (opt.r || 0.15) * s);
    const n = opt.n || 12;
    for (let k = 0; k <= n; k++) {
      const a = Math.PI * (0.08 + 0.84 * k / n);
      const px = cx + Math.cos(a) * rx, py = cy + Math.sin(a) * ry;
      const rr = rr0 * rng.r(0.8, 1.1);
      paintShape(ctx, rng, blob(rng, px + rng.r(-2, 2), py + rng.r(-2, 2), rr, rr * 0.82, 10, 0.2), color, { n: 3, szMul: 0.5 });
      ctx.globalAlpha = 0.4; dot(ctx, px, py + rr * 0.1, rr * 0.22, sink(color, 0.35)); ctx.globalAlpha = 1;
    }
    ctx.globalAlpha = 0.5;
    ribbon(ctx, rng, Array.from({ length: 7 }, (_, i) => { const a = Math.PI * (0.1 + 0.8 * i / 6); return [cx + Math.cos(a) * rx * 0.92, cy + Math.sin(a) * ry * 0.92]; }), sink(color, 0.3), Math.max(2, rr0 * 0.12), { taper: 0.2, jit: 0.6 });
    ctx.globalAlpha = 1;
  }
  function sfSkullRuff(env) { sfSkullOnGround(env); sfRuff(env); }
  function sfBalloonRuff(env) { sfBalloon(env); sfRuff(env, { r: 0.13, n: 14 }); }
  function sfGandhiStaff(env) { sfStaff(env, { up: 1.3, dx: 1.15, w: 0.07, lean: 12, color: hx('#8a6a40') }); }
  function sfShadow(env) {             // five o'clock shadow on the muzzle
    const D = env.D, s = D.figS;
    spray(env.ctx, env.rng, D.headSX, D.headSY + D.hry * 0.7 * s, D.hrx * 0.6 * s, hx('#3a3230'), 0.5, { a: 0.14, spread: 0.6 });
  }
  function sfBagAndCorgi(env) {        // the handbag set down by the forepaws; the corgi sitting behind, looking up
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, S = sScreen(env), s = S.s, open = S.open;
    const bw = Math.max(34, D.hrx * 0.40 * s), bx = sClamp(S.foreFoot[0] + open * (D.hrx * 0.5 * s + bw), 80, 920), by = S.ground - bw * 0.75;
    const bag = [[bx - bw, by - bw * 0.6], [bx + bw, by - bw * 0.6], [bx + bw * 1.1, by + bw * 0.75], [bx - bw * 1.1, by + bw * 0.75]];
    const bs = smoothPts(resample(bag, true, 6), true, 1);
    paintShape(ctx, rng, bs, hx('#1a1a1e'), { n: 5, szMul: 0.6 });
    ribbon(ctx, rng, [[bx - bw * 0.6, by - bw * 0.6], [bx, by - bw * 1.5], [bx + bw * 0.6, by - bw * 0.6]], hx('#1a1a1e'), Math.max(4, bw * 0.12), { taper: 0.1, jit: 0.6 });
    dot(ctx, bx, by - bw * 0.45, Math.max(4, bw * 0.12), hx('#d8b040'));
    shadowEdge(ctx, rng, bs, mix(line, hx('#1a1a1e'), 0.5), 3, { p: 0.5 });
    const kx = sClamp(S.rump[0] - open * D.hrx * 1.1 * s, 100, 900), kr = Math.max(44, D.hrx * 0.5 * s);
    wSmallBeast(env, kx, S.ground - kr * 0.9, kr, hx('#d8904a'), { sd: open, headC: hx('#d8904a'), muzzle: hx('#f8f4ea') });
    fillPts(ctx, blob(rng, kx - open * kr * 0.3, S.ground - kr * 0.25, kr * 0.65, kr * 0.35, 10, 0.1), hx('#f8f4ea'));
  }
  function sfKite(env) {               // the kite string held in his teeth, the key a third of the way up
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, S = sScreen(env);
    const cx = D.headSX, sd = S.open;
    const kx = sd > 0 ? 830 : 170, ky = 150;
    const gx = S.mouth[0] + sd * D.hrx * 0.25 * S.s, gy = S.mouth[1];
    ribbon(ctx, rng, [[gx, gy], [(gx + kx) / 2 + sd * 30, (gy + ky) / 2 + 40], [kx, ky + 90]], hx('#e8e4d8'), 3, { taper: 0.05, wob: 0.15, jit: 0.8 });
    const keyX = gx + (kx - gx) * 0.32, keyY = gy + (ky - gy) * 0.32 + 30;
    ribbon(ctx, rng, [[keyX, keyY], [keyX, keyY + 44]], hx('#c8a040'), 6, { taper: 0.1, jit: 0.4 });
    drawStroke(ctx, rng, [[keyX - 12, keyY - 8], [keyX + 12, keyY - 8], [keyX + 12, keyY + 8], [keyX - 12, keyY + 8], [keyX - 12, keyY - 8]], { color: hx('#c8a040'), w: 5, fade: 0.4, grain: 0.2, press: 0.25 });
    ribbon(ctx, rng, [[keyX, keyY + 36], [keyX + 10, keyY + 36]], hx('#c8a040'), 5, { taper: 0.1, jit: 0.4 });
    const kite = [[kx, ky - 90], [kx + 70, ky], [kx, ky + 90], [kx - 70, ky]];
    paintShape(ctx, rng, kite, hx('#e8d8b0'), { n: 5, szMul: 0.6, drift: 0.05 });
    ribbon(ctx, rng, [[kx, ky - 90], [kx, ky + 90]], hx('#6a4a30'), 4, { taper: 0.1, jit: 0.5 });
    ribbon(ctx, rng, [[kx - 70, ky], [kx + 70, ky]], hx('#6a4a30'), 4, { taper: 0.1, jit: 0.5 });
    shadowEdge(ctx, rng, kite, mix(line, hx('#e8d8b0'), 0.45), 3.5, { p: 0.5 });
    for (let k = 0; k < 3; k++) fillPts(ctx, blob(rng, kx + rng.r(-12, 12), ky + 120 + k * 40, 14, 8, 8, 0.2), hx('#c8342c'));
    void cx;
  }
  function sfCakeOnGround(env) {       // the plate and the wedge set down by the forepaws
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, G = sGroundSpot(env, 1.2);
    const px = G.x, py = G.y - 30, k = Math.max(0.7, G.s);
    fillPts(ctx, blob(rng, px, py + 30 * k, 70 * k, 14 * k, 14, 0.06), hx('#f4f4f0'));
    const wedge = [[px - 60 * k, py + 26 * k], [px + 60 * k, py + 26 * k], [px + 20 * k, py - 50 * k], [px - 20 * k, py - 50 * k]];
    paintShape(ctx, rng, wedge, hx('#f8e8c8'), { n: 4, szMul: 0.55 });
    [0.25, 0.55].forEach(t => ribbon(ctx, rng, [[px - 60 * k + t * 40 * k, py + 26 * k - t * 80 * k], [px + 60 * k - t * 40 * k, py + 26 * k - t * 80 * k]], hx('#e86a8a'), 8 * k, { taper: 0.05, jit: 0.6 }));
    paintShape(ctx, rng, [[px - 22 * k, py - 50 * k], [px + 22 * k, py - 50 * k], [px + 16 * k, py - 66 * k], [px - 16 * k, py - 66 * k]], hx('#f4a8c0'), { n: 3, szMul: 0.5 });
    dot(ctx, px, py - 72 * k, 9 * k, hx('#c8202a'));
    shadowEdge(ctx, rng, wedge, mix(line, hx('#f8e8c8'), 0.45), 3.5, { p: 0.5 });
  }
  function sfSkullOnGround(env) {      // the skull on the ground, regarded
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, G = sGroundSpot(env, 1.15);
    const kr = Math.max(36, D.hrx * 0.40 * G.s), kx = G.x, ky = G.y - kr * 1.05;
    const skull = blob(rng, kx, ky, kr, kr * 1.05, 16, 0.08);
    paintShape(ctx, rng, skull, hx('#ece6d8'), { n: 5, szMul: 0.6, drift: 0.04 });
    paintShape(ctx, rng, [[kx - kr * 0.5, ky + kr * 0.7], [kx + kr * 0.5, ky + kr * 0.7], [kx + kr * 0.4, ky + kr * 1.05], [kx - kr * 0.4, ky + kr * 1.05]], hx('#ece6d8'), { n: 3, szMul: 0.5 });
    [-0.36, 0.36].forEach(k => fillPts(ctx, blob(rng, kx + k * kr, ky - kr * 0.1, kr * 0.26, kr * 0.28, 10, 0.1), hx('#2a2420')));
    fillPts(ctx, [[kx - kr * 0.1, ky + kr * 0.35], [kx + kr * 0.1, ky + kr * 0.35], [kx, ky + kr * 0.15]], hx('#2a2420'));
    for (let k = -2; k <= 2; k++) ribbon(ctx, rng, [[kx + k * kr * 0.18, ky + kr * 0.72], [kx + k * kr * 0.18, ky + kr * 1.0]], hx('#8a8070'), 2, { taper: 0.1, jit: 0.4 });
    shadowEdge(ctx, rng, skull, mix(line, hx('#ece6d8'), 0.45), 4, { p: 0.5 });
  }
  function sfEggsGlass(env) {          // the glass of raw eggs on the step beside him
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, G = sGroundSpot(env, 1.3);
    const ex = G.x, ey = G.y - 40, k = Math.max(0.7, G.s);
    const glass = [[ex - 34 * k, ey - 90 * k], [ex + 34 * k, ey - 90 * k], [ex + 28 * k, ey + 40 * k], [ex - 28 * k, ey + 40 * k]];
    paintShape(ctx, rng, glass, hx('#e8f0f0'), { n: 4, szMul: 0.55 });
    fillPts(ctx, [[ex - 30 * k, ey - 40 * k], [ex + 30 * k, ey - 40 * k], [ex + 27 * k, ey + 36 * k], [ex - 27 * k, ey + 36 * k]], hx('#f0e8c0'));
    for (let j = 0; j < 4; j++) dot(ctx, ex + rng.r(-14, 14) * k, ey - 20 * k + j * 14 * k, 11 * k, hx('#f0b030'));
    shadowEdge(ctx, rng, glass, mix(line, hx('#a8b0b0'), 0.5), 3, { p: 0.5 });
    void D;
  }
  function sfCompassOnGround(env) {    // the compass open on the ground, its needle wandering
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, G = sGroundSpot(env, 1.15);
    const k = Math.max(0.7, G.s), px = G.x, py = G.y - 36 * k, sd = G.open;
    const box = blob(rng, px, py, 48 * k, 36 * k, 14, 0.06);
    paintShape(ctx, rng, box, hx('#4a3020'), { n: 4, szMul: 0.55 });
    fillPts(ctx, blob(rng, px, py, 34 * k, 24 * k, 14, 0.04), hx('#f4ecd8'));
    paintShape(ctx, rng, [[px - 46 * k, py - 28 * k], [px + 46 * k, py - 28 * k], [px + 40 * k, py - 78 * k], [px - 40 * k, py - 74 * k]], hx('#4a3020'), { n: 3, szMul: 0.5 });
    ribbon(ctx, rng, [[px, py], [px + sd * 22 * k, py - 12 * k]], hx('#c8202a'), 3.5, { taper: 0.6, jit: 0.4 });
    ribbon(ctx, rng, [[px, py], [px - sd * 22 * k, py + 12 * k]], hx('#1a1418'), 3.5, { taper: 0.6, jit: 0.4 });
    shadowEdge(ctx, rng, box, mix(line, hx('#4a3020'), 0.4), 3, { p: 0.5 });
    void D;
  }
  function sfIdolWhip(env) {           // the golden idol standing on the ground before him; the whip coiled by his hind feet
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, S = sScreen(env), G = sGroundSpot(env, 1.25);
    const k = Math.max(0.7, G.s), ix = G.x, iy = G.y - 50 * k;
    const gold = hx('#d8b040');
    const idol = blob(rng, ix, iy - 30 * k, 30 * k, 36 * k, 12, 0.08);
    paintShape(ctx, rng, idol, gold, { n: 4, szMul: 0.55 });
    paintShape(ctx, rng, [[ix - 26 * k, iy], [ix + 26 * k, iy], [ix + 22 * k, iy + 46 * k], [ix - 22 * k, iy + 46 * k]], gold, { n: 3, szMul: 0.5 });
    [-1, 1].forEach(q => dot(ctx, ix + q * 11 * k, iy - 34 * k, 5 * k, hx('#2a2420')));
    ribbon(ctx, rng, [[ix - 10 * k, iy - 14 * k], [ix + 10 * k, iy - 14 * k]], hx('#2a2420'), 3, { taper: 0.2, jit: 0.4 });
    shadowEdge(ctx, rng, idol, mix(line, gold, 0.4), 3, { p: 0.5 });
    const wx = sClamp(S.rump[0] - S.open * D.hrx * 0.6 * S.s, 80, 920), wy = S.ground - 20;
    for (let j = 0; j < 3; j++) {
      const ring = [];
      for (let q = 0; q <= 18; q++) { const a = q / 18 * Math.PI * 2; ring.push([wx + Math.cos(a) * (40 + j * 8) * k, wy + Math.sin(a) * (22 + j * 5) * k]); }
      ribbon(ctx, rng, ring, hx('#4a3020'), 6, { taper: 0.05, wob: 0.2, jit: 0.8 });
    }
  }
  function sfChocolatesOnGround(env) { // the box of chocolates open on the ground in front of him
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, S = sScreen(env), s = S.s, open = S.open;
    const bw = Math.max(90, D.hrx * 0.95 * s), bh = bw * 0.34;
    const bx = sClamp(S.foreFoot[0] + open * (D.hrx * 0.5 * s + bw), 110, 890), by = S.ground - bh;
    const box = [[bx - bw, by - bh], [bx + bw, by - bh], [bx + bw, by + bh], [bx - bw, by + bh]];
    paintShape(ctx, rng, box, hx('#8a2a2a'), { n: 6, szMul: 0.7, drift: 0.04 });
    fillPts(ctx, [[bx - bw + 10, by - bh + 10], [bx + bw - 10, by - bh + 10], [bx + bw - 10, by + bh - 10], [bx - bw + 10, by + bh - 10]], hx('#5a2a18'));
    for (let k = 0; k < 7; k++) for (let j = 0; j < 2; j++) {
      const cxk = bx - bw + 26 + k * (bw * 2 - 52) / 6, cyk = by - bh * 0.35 + j * bh * 0.7;
      dot(ctx, cxk, cyk, bh * 0.24, (k + j) % 3 ? hx('#3a1c10') : hx('#8a5a3a'));
      dot(ctx, cxk - 3, cyk - 3, bh * 0.07, hx('#a87a5a'));
    }
    shadowEdge(ctx, rng, box, mix(line, hx('#8a2a2a'), 0.4), 4, { p: 0.5 });
  }
  function sfCaneTicket(env) {         // the cane planted; the golden ticket in his teeth
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, S = sScreen(env), s = S.s, open = S.open;
    const st = sfStaff(env, { up: 0.1, dx: 1.25, w: 0.06, lean: 4, color: hx('#2a2020') });
    dot(ctx, st.tx, st.top, Math.max(9, D.hrx * 0.12 * s), hx('#c8a040'));
    const tx = S.mouth[0] + open * D.hrx * 0.5 * s, ty = S.mouth[1] + D.hry * 0.05 * s;
    const w = Math.max(30, D.hrx * 0.5 * s), h = w * 0.55;
    const tick = [[tx - open * w * 0.1, ty - h * 0.35], [tx + open * w, ty - h * 0.55], [tx + open * w * 1.02, ty + h * 0.5], [tx - open * w * 0.1, ty + h * 0.45]];
    paintShape(ctx, rng, tick, hx('#e8c040'), { n: 5, szMul: 0.6, drift: 0.04 });
    ctx.globalAlpha = 0.5; ribbon(ctx, rng, [[tx + open * w * 0.2, ty - h * 0.1], [tx + open * w * 0.8, ty - h * 0.15]], lift(hx('#e8c040'), 0.5), 4, { taper: 0.4, jit: 0.6 }); ctx.globalAlpha = 1;
    shadowEdge(ctx, rng, tick, mix(line, hx('#e8c040'), 0.45), 3, { p: 0.5 });
  }
  function sfBalloon(env) {            // a red balloon on a string tied to the tail
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line, g = D.standGeo, s = D.figS;
    if (!g || !g.tcl || !g.tcl.length) return;
    const tip = figToScreen(D, g.tcl[g.tcl.length - 1][0], g.tcl[g.tcl.length - 1][1]);
    const bx = sClamp(tip[0] + (D.bodyDir || 1) * D.hrx * 0.6 * s, 80, 920), by = Math.max(90, tip[1] - D.hry * 2.4 * s);
    ribbon(ctx, rng, [tip, [(tip[0] + bx) / 2 + rng.r(-10, 10), (tip[1] + by) / 2], [bx, by + D.hrx * 0.5 * s]], hx('#e8e4d8'), 2.5, { taper: 0.05, wob: 0.2, jit: 0.8 });
    const r = Math.max(40, D.hrx * 0.5 * s);
    const bal = blob(rng, bx, by, r, r * 1.15, 16, 0.05);
    paintShape(ctx, rng, bal, hx('#c8202a'), { n: 6, szMul: 0.6, drift: 0.04 });
    ctx.globalAlpha = 0.5; fillPts(ctx, blob(rng, bx - r * 0.35, by - r * 0.4, r * 0.22, r * 0.3, 10, 0.1), hx('#f4b0b0')); ctx.globalAlpha = 1;
    fillPts(ctx, [[bx - r * 0.12, by + r * 1.12], [bx + r * 0.12, by + r * 1.12], [bx, by + r * 0.98]], hx('#c8202a'));
    shadowEdge(ctx, rng, bal, mix(line, hx('#c8202a'), 0.4), 3.5, { p: 0.5 });
  }
  function sfBlondeOnGround(env) {     // the tiny blonde standing on the ground before the great face, arms up
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env), s = S.s, open = S.open;
    const px = sClamp(S.mouth[0] + open * D.hrx * 1.05 * s, 60, 940), py = S.ground - 30;
    const fig = [[px - 12, py - 10], [px + 12, py - 10], [px + 10, py + 30], [px - 10, py + 30]];
    paintShape(ctx, rng, fig, hx('#f4f0e6'), { n: 3, szMul: 0.5 });
    dot(ctx, px, py - 22, 12, hx('#f0d8c0'));
    fillPts(ctx, blob(rng, px, py - 30, 14, 9, 10, 0.15), hx('#f0d060'));
    [-1, 1].forEach(k => ribbon(ctx, rng, [[px + k * 10, py - 4], [px + k * 22, py - 30]], hx('#f0d8c0'), 4, { taper: 0.3, jit: 0.4 }));
    ctx.globalAlpha = 0.3; fillPts(ctx, blob(rng, px, py + 32, 24, 6, 10, 0.1), hx('#2a2a30')); ctx.globalAlpha = 1;
  }
  function sfWheel(env) {              // the ship's wheel standing on the deck before him; whistled notes
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env), s = S.s, open = S.open;
    const wr = Math.max(70, D.hrx * 0.8 * s);
    const cx = sClamp(S.mouth[0] + open * (D.hrx * 0.7 * s + wr * 0.9), 90, 910), wy = S.ground - wr * 1.15;
    const wood = hx('#3a3a3a');
    ribbon(ctx, rng, [[cx, wy], [cx, S.ground + 4]], wood, Math.max(8, wr * 0.1), { taper: 0.05, jit: 0.5 });
    const ring = [];
    for (let j = 0; j <= 40; j++) { const a = j / 40 * Math.PI * 2; ring.push([cx + Math.cos(a) * wr, wy + Math.sin(a) * wr]); }
    ribbon(ctx, rng, ring, wood, Math.max(10, wr * 0.13), { taper: 0.02, wob: 0.15, jit: 0.8 });
    for (let k = 0; k < 8; k++) {
      const a = k / 8 * Math.PI * 2;
      ribbon(ctx, rng, [[cx, wy], [cx + Math.cos(a) * wr * 1.28, wy + Math.sin(a) * wr * 1.28]], wood, Math.max(6, wr * 0.07), { taper: 0.1, jit: 0.6 });
      dot(ctx, cx + Math.cos(a) * wr * 1.3, wy + Math.sin(a) * wr * 1.3, Math.max(7, wr * 0.09), wood);
    }
    dot(ctx, cx, wy, Math.max(12, wr * 0.16), wood);
    const nx = D.headSX + open * D.hrx * 1.2 * s;
    for (let k = 0; k < 3; k++) {
      const x0 = nx + open * k * 34, y0 = D.headSY - D.hry * (0.8 + k * 0.35) * s;
      dot(ctx, x0, y0, 9, hx('#1a1a1a'));
      ribbon(ctx, rng, [[x0 + 8, y0], [x0 + 8, y0 - 40]], hx('#1a1a1a'), 4, { taper: 0.1, jit: 0.3 });
      ribbon(ctx, rng, [[x0 + 8, y0 - 40], [x0 + 26, y0 - 32]], hx('#1a1a1a'), 4, { taper: 0.5, jit: 0.3 });
    }
  }

  // ---- body pieces for this batch
  function sPatKnit(color) {           // fine horizontal knit rows
    return (K, clip) => { sPatStripes(color, 9, 0, Math.max(2, K.D.hry * 0.02))(K, clip); };
  }
  function sBrooch(K, color) {
    const p = K.P(0.06, 0.28, 0), D = K.D;
    dot(K.ctx, p[0], p[1], Math.max(5, D.hrx * 0.07), color);
    for (let k = 0; k < 6; k++) { const a = k / 6 * Math.PI * 2; dot(K.ctx, p[0] + Math.cos(a) * D.hrx * 0.08, p[1] + Math.sin(a) * D.hrx * 0.08, Math.max(2, D.hrx * 0.025), hx('#f8f4ea')); }
  }
  function sDogTags(K) {
    const ctx = K.ctx, rng = K.rng, D = K.D, c = K.chest;
    sNeckBand(K, hx('#b8b8b0'), { w: Math.max(2.5, D.hrx * 0.03) });
    [-1, 1].forEach(sd => fillPts(ctx, [[c[0] + sd * 6 - D.hrx * 0.05, c[1] + D.hry * 0.05], [c[0] + sd * 6 + D.hrx * 0.05, c[1] + D.hry * 0.05], [c[0] + sd * 6 + D.hrx * 0.05, c[1] + D.hry * 0.22], [c[0] + sd * 6 - D.hrx * 0.05, c[1] + D.hry * 0.22]], hx('#c8c8c0')));
    void rng;
  }

  // ---- the rows
  function sideEmperor(K) {            // 51 the small emperor: navy coat, white facings, red sash, gold epaulette
    const navy = K.D.robeC || hx('#1c2a4a');
    sGarment(K, navy, { hem: 1.0, n: 9, lapel: hx('#b82028'), collar: hx('#b82028'), collarH: 0.22, buttons: { c: hx('#d8b040'), n: 6 } });
    sSash(K, hx('#f4f0e6'), { t0: 0.0, v0: 0.05, t1: 0.8, v1: 0.9, w: Math.max(8, K.D.hry * 0.13) });
    sChestVShirt(K, hx('#f4f0e6'));
    sEpaulette(K, hx('#d8b040'));
    // the Legion's star on the breast
    const st = K.P(0.10, 0.45, 0); dot(K.ctx, st[0], st[1], Math.max(4, K.D.hrx * 0.05), hx('#d8b040')); dot(K.ctx, st[0], st[1], Math.max(2, K.D.hrx * 0.022), hx('#f4f0e6'));
  }
  function sideWildHair(K) {           // 52 the wild hair: a grey-brown knitted sweater
    const sw = K.D.robeC || hx('#8a7a68');
    sGarment(K, sw, { hem: 1.0, n: 9, pattern: sPatKnit(sink(sw, 0.12)) });
    sNeckBand(K, sw, { w: K.D.hrx * 0.22 });
  }
  function sideOvercoat(K) {           // 53 the bowler: the black overcoat, white shirt, navy bow tie with dots
    const jet = K.D.robeC || hx('#1c1c22');
    sGarment(K, jet, { hem: 1.0, n: 9, lapel: hx('#2c2c34'), buttons: { c: hx('#3a3a44'), n: 3 } });
    sChestVShirt(K, hx('#f4f0e6'));
    sBowTie(K, hx('#1c2a5a'));
    for (let k = 0; k < 5; k++) dot(K.ctx, K.D.hcx - K.bd * K.D.hrx * 0.02 + K.rng.r(-1, 1) * K.D.hrx * 0.18, K.D.hcy + K.D.hry * 1.0 + K.rng.r(-1, 1) * K.D.hrx * 0.08, 2.2, hx('#f4f0e6'));
  }
  function sideShawl(K) {              // 54 the round glasses: the white shawl, one shoulder bare
    const white = K.D.robeC || hx('#f4efe4');
    sGarment(K, white, { t0: 0.18, t1: 1.0, hem: 1.0, over: 6, n: 9, ragged: true });
    sSash(K, white, { t0: 0.0, v0: 0.6, t1: 0.5, v1: 0.05, w: Math.max(12, K.D.hry * 0.26), a: 0.97 });
    sFringe(K, sink(white, 0.15), 0.3, 0.95, 1.0, K.D.hry * 0.12);
  }
  function sideRoyalCoat(K) {          // 55 the coronation: the pale blue coat, white buttons, three strands of pearls, a brooch
    const blue = K.D.robeC || hx('#a8c4e0');
    sGarment(K, blue, { hem: 1.0, n: 9, collar: true, collarH: 0.2, buttons: { c: hx('#f4f0e6'), n: 4 } });
    [0.10, 0.16, 0.22].forEach(w => sNeckBand(K, hx('#f8f4ea'), { kind: 'pearls', w: K.D.hrx * w }));
    sBrooch(K, hx('#d8b040'));
  }
  function sideSafariJacket(K) {       // 56 the rough rider: the safari jacket, pockets, belt, brown tie
    const kh = K.D.robeC || hx('#a89060');
    sGarment(K, kh, { hem: 1.0, n: 9, collar: true, collarH: 0.22, buttons: { c: hx('#6a4a30'), n: 4 } });
    sPocket(K, 0.20, 0.40, kh, { flap: sink(kh, 0.12), button: hx('#6a4a30') });
    sPocket(K, 0.44, 0.40, kh, { flap: sink(kh, 0.12), button: hx('#6a4a30') });
    sBelt(K, sink(kh, 0.25), { t: 0.6, w: Math.max(6, K.D.hry * 0.09), buckle: hx('#c8a040') });
    sChestVShirt(K, hx('#e8e0c8'));
    sTie(K, hx('#4a3020'), { w: 0.09, len: 0.55 });
  }
  function sideCrewneck(K) {           // 57 the sailing sweater: navy crewneck, ribbed neck
    const navy = K.D.robeC || hx('#1c2a48');
    sGarment(K, navy, { hem: 1.0, n: 9, pattern: sPatKnit(lift(navy, 0.18)) });
    sNeckBand(K, lift(navy, 0.25), { w: K.D.hrx * 0.2 });
  }
  function sideDarkSuit(K) {           // 58 the double V: dark suit, white shirt, maroon tie
    const suit = K.D.robeC || hx('#22242c');
    sGarment(K, suit, { hem: 1.0, n: 9, lapel: sink(suit, 0.2) });
    sChestVShirt(K, hx('#f4f0e6'));
    sTie(K, hx('#7a2a3a'), { w: 0.12, len: 0.75 });
  }
  function sideKiteCoat(K) {           // 59 the kite: a brown colonial coat, cravat, buttons
    const brown = K.D.robeC || hx('#6a4a30');
    sGarment(K, brown, { hem: 1.0, n: 9, lapel: lift(brown, 0.15), buttons: { c: hx('#c8a040'), n: 5 } });
    sChestVShirt(K, hx('#f4f0e6'));
    sNeckBand(K, hx('#f4f0e6'), { w: K.D.hrx * 0.14 });
  }
  function sideGownPannier(K) {        // 60 the wig: pink silk to the ground, a pale stomacher with blue bows, a ruff
    const silk = hx('#e494bc');
    sGarment(K, silk, { hem: 1.0, n: 10, pattern: (K2, clip) => { const b = sBox(clip); const ctx = K2.ctx, rng = K2.rng; for (let k = 0; k < 6; k++) { ctx.globalAlpha = 0.3; ribbon(ctx, rng, [[b.x0 + b.w * (0.1 + k * 0.15), b.y0], [b.x0 + b.w * (0.12 + k * 0.15), b.y1]], lift(silk, 0.4), Math.max(3, b.h * 0.04), { taper: 0.2, wob: 0.3, jit: 1 }); } ctx.globalAlpha = 1; } });
    // the stomacher panel with bows down it
    const a = K.P(0.08, 0.15, 0), b = K.P(0.30, 0.15, 0), c = K.P(0.27, 0.85, 0), d = K.P(0.11, 0.85, 0);
    paintShape(K.ctx, K.rng, [a, b, c, d], hx('#f6ecdc'), { n: 4, szMul: 0.6 });
    shadowEdge(K.ctx, K.rng, [a, b, c, d], mix(K.line, silk, 0.4), 3, { p: 0.5 });
    for (let k = 0; k < 3; k++) { const p = K.P(0.19, 0.28 + k * 0.22, 0); [-1, 1].forEach(sd => fillPts(K.ctx, blob(K.rng, p[0] + sd * K.D.hrx * 0.09, p[1], K.D.hrx * 0.09, K.D.hry * 0.05, 10, 0.15, sd * 0.3), hx('#6aa0d8'))); dot(K.ctx, p[0], p[1], Math.max(3, K.D.hrx * 0.03), sink(hx('#6aa0d8'), 0.2)); }
    sNeckBand(K, hx('#fbf8f2'), { kind: 'ruff', w: K.D.hrx * 0.2 });
  }
  function sideFrontGownPannier(K) {   // the pannier skirt to the floor, hiding the legs
    const silk = hx('#e494bc');
    sSkirt(K, silk, { pannier: 0.6, lift: 0.42, stripes: lift(silk, 0.35), hemBand: hx('#f6ecdc') });
  }
  function sideRuffDoublet(K) {        // 61 the ruff: dark doublet, gold buttons, the great white ruff
    sGarment(K, K.D.robeC || hx('#2a2422'), { hem: 1.0, n: 9, buttons: { c: hx('#c8a040'), n: 5 }, pattern: sPatStripes(lift(hx('#2a2422'), 0.12), 4, Math.PI / 2, Math.max(2.5, K.D.hry * 0.025)) });
    sNeckBand(K, hx('#fbf8f2'), { kind: 'ruff', w: K.D.hrx * 0.34 });
  }
  function sideNavySuit(K) {           // 62 the ears: navy suit, white shirt, red tie, flag pin
    const navy = K.D.robeC || hx('#1c2a5a');
    sGarment(K, navy, { hem: 1.0, n: 9, lapel: sink(navy, 0.15) });
    sChestVShirt(K, hx('#f4f0e6'));
    sTie(K, hx('#c8202a'), { w: 0.11, len: 0.7 });
    const p = K.P(0.05, 0.22, 0); dot(K.ctx, p[0], p[1], Math.max(3, K.D.hrx * 0.04), hx('#c8202a')); dot(K.ctx, p[0] - 2, p[1] - 2, Math.max(1.5, K.D.hrx * 0.018), hx('#2a4a9a'));
  }
