  // ======================================================================
  // THE SIDE KIT, batch four (J 2026-09-02): rows 101 to 116, the painters,
  // the builders and the athletes, built on the four-legged body from the
  // start. Painters stand in a ground painted in their manner (never a copy
  // of a painting); jerseys carry nothing; the thing that was held stands on
  // the ground or rides in the teeth.
  // ======================================================================

  // run fn in SCREEN space from inside a figure-space painter (sideBehind,
  // side, sideFront): undo beginFigure, draw, restore
  function sInScreen(K, fn) {
    const ctx = K.ctx, D = K.D;
    ctx.save();
    ctx.translate(500, 800);
    ctx.scale(1 / D.figS, 1 / D.figS);
    ctx.rotate(-D.figRot);
    ctx.translate(-(500 + D.figX), -800);
    fn(ctx);
    ctx.restore();
  }
  // the ground line under the feet, in screen y
  function sGroundScreen(K) { return figToScreen(K.D, K.D.hcx, K.g.groundY)[1]; }
  // the figure's screen extent: [x0, x1] of the whole animal, and its top y
  function sFigureBox(K) {
    const D = K.D, g = K.g;
    const pts = [figToScreen(D, D.hcx - D.hrx * 1.3, D.hcy - D.hry * 1.3), figToScreen(D, D.hcx + D.hrx * 1.3, D.hcy - D.hry * 1.3),
                 figToScreen(D, g.rumpX + (D.bodyDir || 1) * D.hrx * 0.6, g.rumpY), figToScreen(D, D.hcx, g.groundY)];
    let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
    pts.forEach(p => { x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]); });
    return { x0: x0, x1: x1, y0: y0, y1: y1, cx: (x0 + x1) / 2 };
  }
  // a slab the animal stands on, behind the body and over the ground: a
  // platform, a table, a bench, a plinth, a bridge deck. Drawn from
  // sideBehind. opt.x0/x1 screen edges (default the whole width), opt.h the
  // slab's face height, opt.legs = [x...] posts down to the canvas foot
  function sSlabUnder(K, color, opt) {
    opt = opt || {};
    const rng = K.rng, D = K.D;
    const gy = sGroundScreen(K) + (opt.drop || 4);
    const x0 = opt.x0 === undefined ? -20 : opt.x0, x1 = opt.x1 === undefined ? 1020 : opt.x1;
    const h = opt.h === undefined ? 70 : opt.h;
    sInScreen(K, ctx => {
      const top = [[x0, gy], [x1, gy], [x1, gy + h], [x0, gy + h]];
      paintShape(ctx, rng, top, color, { n: 7, szMul: 0.9, drift: 0.04 });
      if (opt.edge !== false) { ctx.globalAlpha = 0.7; ribbon(ctx, rng, [[x0, gy + 2], [x1, gy + 2]], opt.edgeC || lift(color, 0.25), Math.max(4, h * 0.08), { taper: 0.02, wob: 0.2, jit: 1 }); ctx.globalAlpha = 1; }
      shadowEdge(ctx, rng, top, mix(K.line, color, 0.4), 4, { p: 0.5 });
      (opt.legs || []).forEach(lx => paintShape(ctx, rng, [[lx - (opt.legW || 22), gy + h], [lx + (opt.legW || 22), gy + h], [lx + (opt.legW || 22), 1010], [lx - (opt.legW || 22), 1010]], sink(color, 0.2), { n: 4, szMul: 0.7 }));
      if (opt.fill) paintShape(ctx, rng, [[x0, gy + h], [x1, gy + h], [x1, 1010], [x0, 1010]], opt.fill, { n: 6, szMul: 0.9, drift: 0.03 });
      void D;
    });
    return gy;
  }
  // a harness: a chest strap, a belly strap, a strap along the back
  function sHarness(K, color, opt) {
    opt = opt || {};
    const ctx = K.ctx, rng = K.rng, D = K.D;
    const w = opt.w || Math.max(6, D.hry * 0.09);
    sBelt(K, color, { t: opt.t0 === undefined ? 0.16 : opt.t0, w: w });
    sBelt(K, color, { t: opt.t1 === undefined ? 0.5 : opt.t1, w: w, buckle: opt.buckle });
    const a = K.P(0.10, 0.0, 3), b = K.P(0.56, 0.0, 3);
    ribbon(ctx, rng, [a, [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2 - 2], b], color, w * 0.9, { taper: 0.05, wob: 0.1, jit: 1 });
    if (opt.ring) { const m = K.P(0.16, 0.0, 4); dot(ctx, m[0], m[1], w * 0.7, opt.ring); dot(ctx, m[0], m[1], w * 0.35, sink(opt.ring, 0.4)); }
    if (opt.handle) {
      // the rigid guide handle standing up off the back
      const p = K.P(0.34, 0.0, 6);
      ribbon(ctx, rng, [[p[0] - D.hrx * 0.22, p[1]], [p[0] - D.hrx * 0.28, p[1] - D.hry * 0.55], [p[0] + D.hrx * 0.28, p[1] - D.hry * 0.55], [p[0] + D.hrx * 0.22, p[1]]], color, w * 0.7, { taper: 0.02, jit: 0.8 });
    }
  }
  // a ball: on the ground by the forepaws (default), or in the air at
  // (opt.up hry above the mouth, opt.dx hrx out in the open)
  function sfBall(env, opt) {
    opt = opt || {};
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env), s = S.s, open = S.open;
    const r = Math.max(30, D.hrx * (opt.r || 0.42) * s);
    let x, y;
    if (opt.up) { x = sClamp(S.mouth[0] + open * D.hrx * (opt.dx === undefined ? 1.2 : opt.dx) * s, r + 20, 980 - r); y = Math.max(r + 20, D.headSY - D.hry * opt.up * s); }
    else { x = sClamp(S.foreFoot[0] + open * (D.hrx * (opt.dx === undefined ? 0.9 : opt.dx) * s + r), r + 20, 980 - r); y = S.ground - r * 0.9; }
    const col = opt.color || hx('#d8702a'), seam = opt.seam || hx('#2a1c14');
    const b = blob(rng, x, y, r, r, 18, 0.05);
    paintShape(ctx, rng, b, col, { n: 6, szMul: 0.6, drift: 0.05 });
    if (opt.kind === 'football') {
      // the panelled ball: black patches
      for (let k = 0; k < 5; k++) { const a = k / 5 * Math.PI * 2 + 0.4; const px = x + Math.cos(a) * r * 0.55, py = y + Math.sin(a) * r * 0.55; paintShape(ctx, rng, blob(rng, px, py, r * 0.2, r * 0.2, 6, 0.08), seam, { n: 2, szMul: 0.5 }); }
      paintShape(ctx, rng, blob(rng, x, y, r * 0.2, r * 0.2, 6, 0.08), seam, { n: 2, szMul: 0.5 });
    } else if (opt.kind === 'golf') {
      for (let k = 0; k < 14; k++) { ctx.globalAlpha = 0.35; dot(ctx, x + rng.r(-r * 0.7, r * 0.7), y + rng.r(-r * 0.7, r * 0.7), Math.max(1.5, r * 0.06), sink(col, 0.3)); }
      ctx.globalAlpha = 1;
    } else {
      // the basketball's seams: one round, two arcs
      ribbon(ctx, rng, [[x - r * 0.98, y], [x, y + 2], [x + r * 0.98, y]], seam, Math.max(2.5, r * 0.06), { taper: 0.05, jit: 0.6 });
      ribbon(ctx, rng, [[x, y - r * 0.98], [x + 2, y], [x, y + r * 0.98]], seam, Math.max(2.5, r * 0.06), { taper: 0.05, jit: 0.6 });
      [-1, 1].forEach(sd => { const arc = []; for (let j = 0; j <= 10; j++) { const a = -0.9 + j / 10 * 1.8; arc.push([x + sd * (r * 0.55 + Math.cos(a) * r * 0.45), y + Math.sin(a) * r * 0.9]); } ribbon(ctx, rng, arc, seam, Math.max(2.5, r * 0.06), { taper: 0.1, jit: 0.6 }); });
    }
    shadowEdge(ctx, rng, b, mix(env.line, col, 0.35), 3.5, { p: 0.5 });
    if (opt.up && opt.trail !== false) {
      // the arc it came on, faint
      ctx.globalAlpha = 0.28;
      const start = [S.mouth[0] - open * D.hrx * 0.2 * s, S.mouth[1]];
      ribbon(ctx, rng, [start, [(start[0] + x) / 2, Math.min(start[1], y) - r * 1.2], [x - open * r * 0.6, y - r * 0.4]], hx('#3a3230'), 3, { taper: 0.3, wob: 0.3, jit: 1.2 });
      ctx.globalAlpha = 1;
    }
    if (!opt.up) { ctx.globalAlpha = 0.25; fillPts(ctx, blob(rng, x, y + r * 0.95, r * 1.1, r * 0.22, 12, 0.1), hx('#2a2a30')); ctx.globalAlpha = 1; }
    return { x: x, y: y, r: r };
  }
  // a cigarette or brush in the corner of the mouth
  function sfInMouth(env, opt) {
    opt = opt || {};
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env), s = S.s, open = S.open;
    const mx = S.mouth[0] + open * D.hrx * 0.10 * s, my = S.mouth[1] + D.hry * 0.02 * s;
    const L = Math.max(40, D.hrx * (opt.len || 0.7) * s), w = Math.max(5, D.hrx * (opt.w || 0.07) * s);
    const dy = opt.droop === undefined ? 0.35 : opt.droop;
    const tip = [mx + open * L, my + L * dy];
    ribbon(ctx, rng, [[mx, my], tip], opt.color || hx('#f4f0e6'), w, { taper: 0.02, jit: 0.5 });
    if (opt.kind === 'cigarette') {
      ribbon(ctx, rng, [[mx + open * L * 0.7, my + L * dy * 0.7], tip], hx('#d8a860'), w, { taper: 0.02, jit: 0.4 });
      dot(ctx, tip[0], tip[1], w * 0.55, hx('#f06a2a'));
      spray(ctx, rng, tip[0] + open * 20, tip[1] - 60, 40, hx('#c8c8c0'), 0.5, { a: 0.22, spread: 0.6, ely: 2.0 });
    }
    if (opt.kind === 'brush') {
      const bl = L * 0.3;
      ribbon(ctx, rng, [tip, [tip[0] + open * bl, tip[1] + bl * dy]], opt.bristle || hx('#2a3a8a'), w * 1.3, { taper: 0.6, jit: 0.8 });
    }
    return tip;
  }
  // a confetti fall over the whole picture
  function sfConfetti(env, cols, n) {
    const ctx = env.ctx, rng = env.rng;
    for (let k = 0; k < (n || 120); k++) {
      ctx.globalAlpha = rng.r(0.6, 1);
      const x = rng.r(0, 1000), y = rng.r(0, 1000), r = rng.r(4, 9);
      const c = cols[k % cols.length];
      if (k % 2) fillPts(ctx, [[x - r, y - r * 0.5], [x + r, y - r * 0.7], [x + r * 0.8, y + r * 0.5], [x - r * 0.9, y + r * 0.6]], c);
      else dot(ctx, x, y, r * 0.7, c);
    }
    ctx.globalAlpha = 1;
  }
  // a crowd of stick people along a line
  // a wide haze without the can's cost: spray's droplet count grows with the
  // square of its radius (r 600 = twenty thousand fat circles, six seconds),
  // so a haze over the field is laid as a ring of small clouds instead
  function sfHaze(ctx, rng, cx, cy, r, color, dens, opt) {
    opt = opt || {};
    const rr = r * 0.28, ely = opt.ely || 1;
    const ring = [[0, 0], [-0.55, -0.35], [0.55, -0.35], [-0.55, 0.35], [0.55, 0.35], [0, -0.6], [0, 0.6]];
    ring.forEach(q => spray(ctx, rng, cx + q[0] * r, cy + q[1] * r * ely, rr, color, dens, { a: opt.a, spread: opt.spread === undefined ? 0.7 : opt.spread, elx: opt.elx, ely: ely }));
  }
  function sfCrowd(env, y, x0, x1, n, h, color, opt) {
    opt = opt || {};
    const ctx = env.ctx, rng = env.rng;
    for (let k = 0; k < n; k++) {
      const x = x0 + (x1 - x0) * (k + rng.r(0.2, 0.8)) / n;
      ctx.globalAlpha = opt.a || 0.85;
      stickWitness(ctx, rng, x, y + rng.r(-6, 6), h * rng.r(0.8, 1.15), color);
    }
    ctx.globalAlpha = 1;
  }

  // ---- 101 1889 the bandaged ear ----------------------------------------
  function hwOneStrawHat(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    wBrimHat(h, hx('#e0c060'), { brow: 0.52, brim: 1.7, h: 0.5, w: 0.98, band: hx('#c8a040'), bandW: 0.08 });
    // the bandage: a white band down from under the hat over one ear and under the jaw
    const sd = -(D.bodyDir || 1);
    ctx.globalAlpha = 0.96;
    ribbon(ctx, rng, [[D.hcx + sd * D.hrx * 0.55, D.hcy - D.hry * 0.55], [D.hcx + sd * D.hrx * 1.02, D.hcy - D.hry * 0.05], [D.hcx + sd * D.hrx * 0.9, D.hcy + D.hry * 0.6], [D.hcx + sd * D.hrx * 0.3, D.hcy + D.hry * 1.05]], hx('#f6f2e8'), D.hry * 0.22, { taper: 0.05, wob: 0.15, jit: 1.2 });
    ctx.globalAlpha = 1;
  }
  function ewOneRedBeard(h) { wBeard(h, 'chin', hx('#c8642a'), { len: 0.3, w: 0.84 }); wMustache(h, 'walrus', hx('#c8642a'), { w: 0.28 }); }
  function onesBehindStarryNight(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#1c2a5a'), -20, 1020, 0.95);
    // swirling strokes, short and stacked, the way the sky was brushed
    for (let k = 0; k < 160; k++) {
      const x = rng.r(-20, 1020), y = rng.r(-20, 760), L = rng.r(30, 90), a = Math.sin(y * 0.006 + x * 0.003) * 1.4 + rng.r(-0.4, 0.4);
      ctx.globalAlpha = rng.r(0.35, 0.8);
      ribbon(ctx, rng, [[x, y], [x + Math.cos(a) * L * 0.5, y + Math.sin(a) * L * 0.5 + rng.r(-6, 6)], [x + Math.cos(a) * L, y + Math.sin(a) * L]], rng.pick([hx('#2a4a9a'), hx('#4a7ac8'), hx('#8ab0e0'), hx('#1a2244'), hx('#e8d060')]), rng.r(5, 11), { taper: 0.3, wob: 0.3, jit: 1.2 });
    }
    ctx.globalAlpha = 1;
    // the stars: yellow with a halo of rings
    for (let k = 0; k < 7; k++) {
      const x = rng.r(60, 940), y = rng.r(60, 420), r = rng.r(16, 34);
      for (let j = 3; j >= 1; j--) { ctx.globalAlpha = 0.22; dot(ctx, x, y, r * (1 + j * 0.5), hx('#e8d060')); }
      ctx.globalAlpha = 1; dot(ctx, x, y, r, hx('#f4e080')); dot(ctx, x - r * 0.2, y - r * 0.2, r * 0.45, hx('#fbf4c0'));
    }
    // the ground: a dark blue-green field brushed the same way
    for (let k = 0; k < 60; k++) { ctx.globalAlpha = rng.r(0.5, 0.9); ribbon(ctx, rng, [[rng.r(-20, 1020), rng.r(760, 1020)], [rng.r(-20, 1020), rng.r(760, 1020)]], rng.pick([hx('#1c3a3a'), hx('#2a4a3a'), hx('#3a5a5a')]), rng.r(6, 14), { taper: 0.3, wob: 0.3, jit: 1.5 }); }
    ctx.globalAlpha = 1;
  }
  function sideBlueSmock(K) {          // the blue smock, buttons up the belly edge
    const blue = hx('#3a5a9a');
    sGarment(K, blue, { hem: 1.0, n: 9, collar: true, collarH: 0.18, buttons: { c: hx('#e8dcc0'), n: 4, r: Math.max(3, K.D.hrx * 0.035) } });
  }
  function sfSunflowers(env) {         // the vase of sunflowers on the ground before the muzzle
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env), s = S.s, open = S.open;
    const vx = sClamp(S.mouth[0] + open * D.hrx * 1.25 * s, 80, 920), gy = S.ground + 4;
    const vh = Math.max(90, D.hry * 0.9 * s), vw = vh * 0.42;
    const vase = [[vx - vw * 0.8, gy - vh], [vx + vw * 0.8, gy - vh], [vx + vw, gy - vh * 0.5], [vx + vw * 0.7, gy], [vx - vw * 0.7, gy], [vx - vw, gy - vh * 0.5]];
    paintShape(ctx, rng, smoothPts(resample(vase, true, 8), true, 1), hx('#e8d880'), { n: 5, szMul: 0.6 });
    shadowEdge(ctx, rng, vase, mix(env.line, hx('#e8d880'), 0.4), 3.5, { p: 0.5 });
    for (let k = 0; k < 7; k++) {
      const fx = vx + rng.r(-vw * 1.3, vw * 1.3), fy = gy - vh - rng.r(vh * 0.2, vh * 0.9), fr = vh * rng.r(0.16, 0.24);
      ribbon(ctx, rng, [[vx + rng.r(-vw * 0.3, vw * 0.3), gy - vh + 4], [fx, fy]], hx('#4a6a3a'), Math.max(3, fr * 0.16), { taper: 0.1, jit: 0.8 });
      for (let j = 0; j < 12; j++) { const a = j / 12 * Math.PI * 2; paintShape(ctx, rng, blob(rng, fx + Math.cos(a) * fr * 0.8, fy + Math.sin(a) * fr * 0.8, fr * 0.32, fr * 0.2, 8, 0.15, a), rng.chance(0.3) ? hx('#e8a020') : hx('#f4c830'), { n: 2, szMul: 0.5 }); }
      dot(ctx, fx, fy, fr * 0.42, hx('#5a3a1a')); dot(ctx, fx, fy, fr * 0.3, hx('#8a5a2a'));
    }
  }

  // ---- 102 1939 the flower crown ----------------------------------------
  function hwOneFlowerCrown(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    wHairCap(h, hx('#1c1414'), { top: 0.82, brow: 0.52, w: 1.04, strands: 5, part: 0 });
    // the braids wound up over the crown, then the flowers along them
    const y0 = D.hcy - D.hry * 0.86;
    ribbon(ctx, rng, [[D.hcx - D.hrx * 0.95, D.hcy - D.hry * 0.45], [D.hcx - D.hrx * 0.5, y0 - D.hry * 0.06], [D.hcx + D.hrx * 0.5, y0 - D.hry * 0.06], [D.hcx + D.hrx * 0.95, D.hcy - D.hry * 0.45]], hx('#1c1414'), D.hry * 0.2, { taper: 0.1, wob: 0.3, jit: 1.5 });
    for (let k = 0; k < 9; k++) {
      const t = k / 8, a = Math.PI * (1.08 + t * 0.84);
      const fx = D.hcx + Math.cos(a) * D.hrx * 0.98, fy = D.hcy + Math.sin(a) * D.hry * 0.95 - D.hry * 0.02, fr = D.hrx * rng.r(0.13, 0.2);
      const col = rng.pick([hx('#d83a5a'), hx('#f07a9a'), hx('#e8b0c0'), hx('#c82a3a'), hx('#f0a040')]);
      for (let j = 0; j < 6; j++) { const b = j / 6 * Math.PI * 2; paintShape(ctx, rng, blob(rng, fx + Math.cos(b) * fr * 0.55, fy + Math.sin(b) * fr * 0.55, fr * 0.45, fr * 0.35, 8, 0.15, b), col, { n: 2, szMul: 0.5 }); }
      dot(ctx, fx, fy, fr * 0.3, hx('#f4e080'));
      if (k % 3 === 1) paintShape(ctx, rng, blob(rng, fx + fr * 0.9, fy + fr * 0.4, fr * 0.5, fr * 0.25, 8, 0.15, 0.6), hx('#3a7a3a'), { n: 2, szMul: 0.5 });
    }
  }
  function ewOneMonobrow(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const y = (h.eyy !== undefined ? h.eyy : wEyeY(D)) - D.eyeR * 1.9;
    ribbon(ctx, rng, [[D.hcx - D.hrx * 0.7, y + D.hry * 0.04], [D.hcx, y - D.hry * 0.03], [D.hcx + D.hrx * 0.7, y + D.hry * 0.04]], hx('#1c1414'), Math.max(6, D.hry * 0.09), { taper: 0.5, wob: 0.2, jit: 1 });
  }
  function onesBehindLeaves(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#5a7a4a'), -20, 1020, 0.9);
    for (let k = 0; k < 26; k++) {
      const x = rng.r(-40, 1040), y = rng.r(-40, 1040), L = rng.r(120, 260), a = rng.r(-1.2, 1.2);
      const leaf = [[x, y], [x + Math.cos(a - 0.35) * L * 0.5, y + Math.sin(a - 0.35) * L * 0.5], [x + Math.cos(a) * L, y + Math.sin(a) * L], [x + Math.cos(a + 0.35) * L * 0.5, y + Math.sin(a + 0.35) * L * 0.5]];
      ctx.globalAlpha = rng.r(0.6, 0.95);
      paintShape(ctx, rng, smoothPts(resample(leaf, true, 10), true, 1), rng.pick([hx('#2a5a2a'), hx('#3a7a3a'), hx('#6a9a4a'), hx('#1c4a2a')]), { n: 5, szMul: 0.7, drift: 0.05 });
      ribbon(ctx, rng, [[x, y], [x + Math.cos(a) * L, y + Math.sin(a) * L]], hx('#8ab060'), 3, { taper: 0.4, jit: 0.6 });
    }
    ctx.globalAlpha = 1;
  }
  function sideEmbroideredDress(K) {   // the long dress: teal with red and yellow embroidery, a hem band
    const teal = hx('#1c5a5a');
    sGarment(K, teal, { hem: 1.0, n: 9, pattern: (K2, clip) => { const b = sBox(clip); const ctx = K2.ctx, rng = K2.rng; for (let k = 0; k < 14; k++) { const x = rng.r(b.x0, b.x1), y = rng.r(b.y0 + b.h * 0.2, b.y1); const c = rng.pick([hx('#d83a5a'), hx('#f0a040'), hx('#f4e080'), hx('#e86a9a')]); for (let j = 0; j < 5; j++) { const a = j / 5 * Math.PI * 2; dot(ctx, x + Math.cos(a) * 7, y + Math.sin(a) * 7, 4, c); } dot(ctx, x, y, 3, hx('#f4e080')); } } });
    sNeckBand(K, hx('#f4f0e6'), { w: K.D.hrx * 0.16, kind: 'ruff' });
  }
  function sideFrontEmbroideredDress(K) { sSkirt(K, hx('#1c5a5a'), { pannier: 0.3, lift: 0.5, stripes: hx('#d83a5a'), hemBand: hx('#f0a040') }); }
  function sfMonkeyAndParrot(env) {    // the small monkey riding the rump, the green parrot on the ground
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env), s = S.s, open = S.open, bd = S.bd;
    const mr = Math.max(22, D.hrx * 0.24 * s);
    const mx = S.rump[0] - bd * mr * 0.4, my = S.rump[1] - mr * 1.1;
    wSmallBeast(env, mx, my, mr, hx('#5a3a24'), { sd: -bd, ears: true, muzzle: hx('#d8b090') });
    ribbon(ctx, rng, [[mx + bd * mr * 0.9, my + mr * 0.6], [mx + bd * mr * 1.6, my - mr * 0.4], [mx + bd * mr * 1.3, my - mr * 1.2]], hx('#5a3a24'), Math.max(4, mr * 0.18), { taper: 0.3, wob: 0.3, jit: 1 });
    // the parrot: a green teardrop with a red head, on the ground in the open
    const px = sClamp(S.foreFoot[0] + open * D.hrx * 1.5 * s, 60, 940), py = S.ground - 4, pr = Math.max(26, D.hrx * 0.3 * s);
    const body = [[px, py - pr * 2.2], [px + open * pr * 0.7, py - pr * 1.4], [px + open * pr * 0.5, py - pr * 0.2], [px, py], [px - open * pr * 0.5, py - pr * 0.4], [px - open * pr * 0.6, py - pr * 1.5]];
    paintShape(ctx, rng, smoothPts(resample(body, true, 8), true, 1), hx('#3a9a3a'), { n: 5, szMul: 0.6 });
    paintShape(ctx, rng, blob(rng, px + open * pr * 0.1, py - pr * 2.2, pr * 0.42, pr * 0.4, 10, 0.1), hx('#d83a2a'), { n: 3, szMul: 0.5 });
    ribbon(ctx, rng, [[px + open * pr * 0.45, py - pr * 2.2], [px + open * pr * 0.8, py - pr * 2.0]], hx('#f0d040'), Math.max(4, pr * 0.16), { taper: 0.7, jit: 0.4 });
    dot(ctx, px + open * pr * 0.2, py - pr * 2.3, Math.max(2.5, pr * 0.08), hx('#1c1814'));
    ribbon(ctx, rng, [[px - open * pr * 0.4, py - pr * 0.5], [px - open * pr * 1.2, py + pr * 0.1]], hx('#2a6ab0'), Math.max(5, pr * 0.2), { taper: 0.6, jit: 0.6 });
  }

  // ---- 103 1907 the striped shirt ---------------------------------------
  function onesBehindShards(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#c8b090'), -20, 1020, 0.9);
    const cols = [hx('#c86a4a'), hx('#e8a080'), hx('#5a7a8a'), hx('#8a9aa8'), hx('#d8c8a8'), hx('#3a3a44'), hx('#e8d8c0')];
    for (let k = 0; k < 22; k++) {
      const x = rng.r(-40, 1040), y = rng.r(-40, 1040), L = rng.r(120, 340);
      const a = rng.r(0, Math.PI * 2), b = a + rng.r(0.5, 1.4);
      const tri = [[x, y], [x + Math.cos(a) * L, y + Math.sin(a) * L], [x + Math.cos(b) * L * rng.r(0.5, 1), y + Math.sin(b) * L * rng.r(0.5, 1)]];
      ctx.globalAlpha = rng.r(0.6, 0.95);
      paintShape(ctx, rng, tri, cols[k % cols.length], { n: 5, szMul: 0.8, drift: 0.04 });
      shadowEdge(ctx, rng, tri, hx('#3a3030'), 3.5, { p: 0.6 });
    }
    ctx.globalAlpha = 1;
  }
  function sideSailorStripes(K) {      // the white shirt with navy horizontal stripes
    const white = hx('#f0ece0');
    sGarment(K, white, { hem: 1.0, n: 9, pattern: sPatStripes(hx('#1c2a4a'), 7, 0, Math.max(4, K.D.hry * 0.055)) });
    sNeckBand(K, hx('#1c2a4a'), { w: K.D.hrx * 0.12 });
  }
  function sfCigaretteOnly(env) { sfInMouth(env, { kind: 'cigarette', len: 0.6, w: 0.06, droop: 0.25 }); }

  // ---- 104 1965 the polka dots ------------------------------------------
  function hwOneRedBob(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const red = hx('#d8302a');
    wHairCap(h, red, { top: 0.86, brow: 0.62, w: 1.1, strands: 6, n: 8 });
    // the blunt sides falling straight to the jaw
    [-1, 1].forEach(sd => { const f = [[D.hcx + sd * D.hrx * 0.7, D.hcy - D.hry * 0.7], [D.hcx + sd * D.hrx * 1.14, D.hcy - D.hry * 0.4], [D.hcx + sd * D.hrx * 1.16, D.hcy + D.hry * 0.55], [D.hcx + sd * D.hrx * 0.86, D.hcy + D.hry * 0.55], [D.hcx + sd * D.hrx * 0.86, D.hcy - D.hry * 0.2]]; paintShape(ctx, rng, smoothPts(resample(f, true, 8), true, 1), red, { n: 5, szMul: 0.6, drift: 0.04 }); });
    ribbon(ctx, rng, [[D.hcx - D.hrx * 0.9, D.hcy - D.hry * 0.5], [D.hcx + D.hrx * 0.9, D.hcy - D.hry * 0.5]], red, D.hry * 0.1, { taper: 0.05, jit: 0.8 });
  }
  function onesEyeDots(EY) {           // white dots across the dog's own head
    const ctx = EY.ctx, rng = EY.rng, D = EY.D;
    for (let k = 0; k < 16; k++) { const a = rng.r(0, Math.PI * 2), rr = rng.r(0.2, 0.95); const x = D.hcx + Math.cos(a) * D.hrx * rr, y = D.hcy + Math.sin(a) * D.hry * rr; if (Math.abs(y - wEyeY(D)) < D.eyeR * 1.6 && Math.abs(Math.abs(x - D.hcx) - wExo(D)) < D.eyeR * 1.6) continue; ctx.globalAlpha = 0.9; dot(ctx, x, y, D.hrx * rng.r(0.03, 0.06), hx('#f6f2ea')); }
    ctx.globalAlpha = 1;
  }
  function onesBehindDotField(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#e8c020'), -20, 1020, 0.95);
    for (let k = 0; k < 220; k++) { ctx.globalAlpha = rng.r(0.7, 1); dot(ctx, rng.r(-10, 1010), rng.r(-10, 1010), rng.r(4, 16), hx('#1c1814')); }
    ctx.globalAlpha = 1;
    // the pumpkin: a fat yellow lobed thing, black dots, low at one side
    const px = 500 - (env.D.bodyDir || 1) * 330, py = 720, pr = 150;   // on the open side, before the face
    const body = blob(rng, px, py, pr * 1.15, pr * 0.85, 22, 0.08);
    paintShape(ctx, rng, body, hx('#f0d040'), { n: 8, szMul: 0.8, drift: 0.04 });
    for (let k = -2; k <= 2; k++) { ctx.globalAlpha = 0.35; ribbon(ctx, rng, [[px + k * pr * 0.42, py - pr * 0.8], [px + k * pr * 0.5, py + pr * 0.8]], hx('#c8a020'), 8, { taper: 0.3, wob: 0.2, jit: 1 }); }
    ctx.globalAlpha = 1;
    for (let k = 0; k < 40; k++) { const a = rng.r(0, Math.PI * 2), rr = rng.r(0, 0.9); dot(ctx, px + Math.cos(a) * pr * 1.1 * rr, py + Math.sin(a) * pr * 0.8 * rr, rng.r(4, 12) * (1 - rr * 0.4), hx('#1c1814')); }
    ribbon(ctx, rng, [[px, py - pr * 0.85], [px + 6, py - pr * 1.15]], hx('#4a3a1a'), 14, { taper: 0.2, jit: 0.8 });
    shadowEdge(ctx, rng, body, hx('#8a6a10'), 4, { p: 0.5 });
  }
  function sideRedDotDress(K) {
    const red = hx('#d8302a');
    sGarment(K, red, { hem: 1.0, n: 9, pattern: sPatDots(hx('#f6f2ea'), 40, Math.max(3, K.D.hrx * 0.045)) });
  }
  function sideFrontRedDotDress(K) {
    // the dots continue down the legs
    const D = K.D, ctx = K.ctx, rng = K.rng;
    (D.legPolys || []).forEach(lp => { ctx.save(); ctx.beginPath(); poly(ctx, lp, true); ctx.clip(); let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9; lp.forEach(q => { x0 = Math.min(x0, q[0]); x1 = Math.max(x1, q[0]); y0 = Math.min(y0, q[1]); y1 = Math.max(y1, q[1]); }); for (let k = 0; k < 8; k++) dot(ctx, rng.r(x0, x1), rng.r(y0, y1), Math.max(2.5, D.hrx * 0.035), hx('#1c1814')); ctx.restore(); });
  }

  // ---- 105 1831 the great wave ------------------------------------------
  function onesBehindGreatWave(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#e8dcc0'), -20, 1020, 0.95);
    // the small white-capped mountain far behind, then the wave over everything
    const sd = env.D.headSX < 500 ? 1 : -1;
    const mx = 500 - sd * 120;
    paintShape(ctx, rng, [[mx - 140, 560], [mx, 400], [mx + 140, 560]], hx('#5a6a8a'), { n: 4, szMul: 0.7 });
    paintShape(ctx, rng, [[mx - 48, 455], [mx, 400], [mx + 48, 455], [mx + 20, 470], [mx - 25, 465]], hx('#f8f6f0'), { n: 3, szMul: 0.5 });
    // the wave: a great blue mass rising on the open side and curling over
    const wx = 500 + sd * 420;
    const crest = [[wx - sd * 60, 1020], [wx - sd * 40, 700], [wx, 420], [wx - sd * 160, 200], [wx - sd * 420, 120], [wx - sd * 640, 210], [wx - sd * 560, 260], [wx - sd * 380, 250], [wx - sd * 230, 330], [wx - sd * 140, 520], [wx - sd * 180, 760], [wx - sd * 260, 1020]];
    const wv = smoothPts(resample(crest, true, 14), true, 2);
    paintShape(ctx, rng, wv, hx('#2a4a8a'), { n: 12, szMul: 0.9, drift: 0.04 });
    for (let k = 0; k < 24; k++) { ctx.globalAlpha = 0.5; ribbon(ctx, rng, [[wx - sd * rng.r(40, 200), rng.r(400, 1000)], [wx - sd * rng.r(200, 560), rng.r(180, 700)]], rng.pick([hx('#1c3a6a'), hx('#4a7ab8'), hx('#e8f0f8')]), rng.r(4, 10), { taper: 0.4, wob: 0.3, jit: 1.5 }); }
    ctx.globalAlpha = 1;
    // the clawed foam along the crest
    for (let k = 0; k < 16; k++) {
      const t = k / 15, cx = wx - sd * (160 + 480 * t), cy = 200 + Math.sin(t * Math.PI) * -70 + t * 60;
      const claw = [[cx, cy], [cx - sd * 30, cy + 40], [cx - sd * 8, cy + 70 + rng.r(0, 30)], [cx + sd * 14, cy + 30]];
      paintShape(ctx, rng, smoothPts(resample(claw, true, 6), true, 1), hx('#f8f6f0'), { n: 3, szMul: 0.5 });
      for (let j = 0; j < 4; j++) dot(ctx, cx + rng.r(-40, 20) * sd, cy + rng.r(40, 110), rng.r(3, 7), hx('#f8f6f0'));
    }
    shadowEdge(ctx, rng, wv, hx('#10203a'), 5, { p: 0.5 });
    // the water under the animal
    wBackFill(env, hx('#2a4a8a'), 880, 1020, 0.85);
    for (let k = 0; k < 10; k++) { ctx.globalAlpha = 0.6; ribbon(ctx, rng, [[rng.r(-20, 1020), rng.r(880, 1010)], [rng.r(-20, 1020), rng.r(880, 1010)]], hx('#e8f0f8'), rng.r(3, 6), { taper: 0.5, wob: 0.4, jit: 1.5 }); }
    ctx.globalAlpha = 1;
  }
  function sideKimono(K) {             // the blue kimono with white wave marks and a wide dark obi
    const indigo = hx('#2a3a7a');
    sGarment(K, indigo, { hem: 1.0, n: 9, pattern: (K2, clip) => { const b = sBox(clip); const ctx = K2.ctx, rng = K2.rng; for (let k = 0; k < 9; k++) { const x = rng.r(b.x0, b.x1), y = rng.r(b.y0, b.y1); ctx.globalAlpha = 0.8; ribbon(ctx, rng, [[x - 14, y + 6], [x - 4, y - 8], [x + 8, y - 2], [x + 16, y - 12]], hx('#f0f4f8'), 3, { taper: 0.3, jit: 0.6 }); } ctx.globalAlpha = 1; } });
    sBelt(K, hx('#1c1c28'), { t: 0.5, w: Math.max(14, K.D.hry * 0.24) });
    sBelt(K, hx('#c8342c'), { t: 0.5, w: Math.max(4, K.D.hry * 0.06) });
    sCollar(K, lift(indigo, 0.2), -0.02, 0.2);
  }
  function sfBrushInMouth(env) { sfInMouth(env, { kind: 'brush', len: 0.9, w: 0.06, droop: -0.15, color: hx('#c8a060'), bristle: hx('#1c2a5a') }); }

  // ---- 106 1503 the folded paws -----------------------------------------
