  function sfStubble(env) { const D = env.D, s = D.figS; spray(env.ctx, env.rng, D.headSX, D.headSY + D.hry * 0.72 * s, D.hrx * 0.55 * s, hx('#8a8a88'), 0.5, { a: 0.16, spread: 0.6 }); }
