    const body = [[rx - 26, 640], [rx - 26, 130], [rx, 40], [rx + 26, 130], [rx + 26, 640]];
    paintShape(ctx, rng, body, hx('#f4f4f0'), { n: 8, szMul: 0.7, ang: Math.PI / 2 });
    [-1, 1].forEach(s2 => paintShape(ctx, rng, [[rx + s2 * 26, 560], [rx + s2 * 60, 640], [rx + s2 * 26, 640]], hx('#e8e8e4'), { n: 3, szMul: 0.5 }));
    ribbon(ctx, rng, [[rx - 26, 300], [rx + 26, 300]], hx('#1c1c22'), 6, { taper: 0.05, jit: 0.4 });
