    for (let k = 0; k < 3; k++) { ctx.globalAlpha = 0.4; ribbon(ctx, rng, [[kx + sd * D.hrx * 0.3, ky - D.hry * 0.2 + k * 6], [kx + sd * D.hrx * 1.4, ky + D.hry * (0.2 + k * 0.06)]], k % 2 ? lift(brown, 0.3) : sink(brown, 0.2), 3, { taper: 0.4, jit: 0.8 }); }
