  function sfLogoShot(env) { sfBall(env, { up: 2.4, dx: 2.2, r: 0.42 }); }
  // ======================================================================
  // THE SIDE KIT, batch five and six (J 2026-09-02): rows 76 to 100, the
  // famous dogs, each in its own scene on the four-legged body. The scene's
  // floor (platform, table, grave, plinth, step, curb, bench, helmet, basket)
  // is a slab drawn behind the body at the ground line; the thing the story
  // needs stands on the ground or hangs where the story puts it.
  // ======================================================================

  // a second dog on the same canvas from a hidden row (the couch idea made
  // general): idx counts past the couch row (2, 3, 4...), the seed is the
  // partner's own, opt.fade washes it toward the paper (the copy)
  function onesPartner(idx, seed, opt) {
    opt = opt || {};
    return function (env) {
      // the copy: the ground is remembered before the partner is painted and
      // the finished partner is blended back toward it, so the same drawing
      // stands there fainter, mark for mark, with no box around it
      let before = null;
      if (opt.fade) before = env.ctx.getImageData(0, 0, env.ctx.canvas.width, env.ctx.canvas.height);
      const env2 = { canvas: env.canvas, seed: seed, state: env.FATE || env.state };
      FORCE_ONE = ONES_MAX + idx;
      try { designDog(env2); } finally { FORCE_ONE = 0; }
      const D2 = env2.D;
      D2.gLang = 'daylight'; D2.hiKey = false; D2.earInk = 'none'; D2.earInkSide = 1;
      D2.patchC = mix(D2.inkC, env2.coat, 0.20);
      env2.jawY = D2.hcy + D2.hry * (1 + D2.chin * 0.7);
      beginFigure(env2);
      paintBody(env2);
      paintHead(env2);
      paintEars(env2);
      paintContour(env2);
      paintHeadwear(env2);
      paintFace(env2);
      paintEyes(env2);
      paintEyewear(env2);
      paintNeck(env2);
      endFigure(env2);
      const row = ONES_CFG[ONES_MAX + idx];
      if (row && row.front) row.front(env2);
      if (before) {
        const ctx = env.ctx, after = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);
        const a = after.data, b = before.data, f = opt.fade;
        for (let i = 0; i < a.length; i += 4) {
          if (a[i] === b[i] && a[i + 1] === b[i + 1] && a[i + 2] === b[i + 2]) continue;
          a[i] += (b[i] - a[i]) * f; a[i + 1] += (b[i + 1] - a[i + 1]) * f; a[i + 2] += (b[i + 2] - a[i + 2]) * f;
        }
        ctx.putImageData(after, 0, 0);
      }
    };
  }
  // a hanging thing from above: a rope or wire from y=0 down to (x, y)
  function sfHangLine(env, x, y, color, w) { ribbon(env.ctx, env.rng, [[x + env.rng.r(-3, 3), -10], [x, y]], color || hx('#3a3a3a'), w || 3, { taper: 0.02, jit: 0.5 }); }
  // rain over the whole picture, slanting
  function sfRain(env, n, color, opt) {
    opt = opt || {};
    const ctx = env.ctx, rng = env.rng;
    const slant = opt.slant === undefined ? 0.18 : opt.slant;
    for (let k = 0; k < n; k++) { const x = rng.r(-60, 1060), y = rng.r(-40, 1000), L = rng.r(60, 160); ctx.globalAlpha = rng.r(0.15, opt.a || 0.45); ribbon(ctx, rng, [[x, y], [x + L * slant, y + L]], color || hx('#dce4ea'), rng.r(1.5, 3), { taper: 0.4, jit: 0.4 }); }
    ctx.globalAlpha = 1;
  }
  // snow over the whole picture
  function sfSnow(env, n, r) {
    const ctx = env.ctx, rng = env.rng;
    for (let k = 0; k < n; k++) { ctx.globalAlpha = rng.r(0.35, 0.95); dot(ctx, rng.r(-10, 1010), rng.r(-10, 1010), rng.r(2, r || 7), hx('#fbfbf8')); }
    ctx.globalAlpha = 1;
  }
  // a small figure of a thing lying on the ground at the forepaws
  function sfAtPaws(env, dx, fn) {
    const D = env.D, S = sScreen(env), s = S.s, open = S.open;
    const x = sClamp(S.foreFoot[0] + open * D.hrx * dx * s, 60, 940), gy = S.ground + 4;
    fn(x, gy, s, open, S);
  }

  // ---- 76 1935 the station ----------------------------------------------
  function onesBehindStation(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, sd = -(D.bodyDir || 1);
    wBackFill(env, hx('#b8bec4'), -20, 1020, 0.95);
    // the canopy: a dark band with a dripping edge, its posts
    paintShape(ctx, rng, [[-20, -20], [1020, -20], [1020, 150], [-20, 150]], hx('#3a3a40'), { n: 6, szMul: 1.0, drift: 0.03 });
    [140, 860].forEach(x => paintShape(ctx, rng, [[x - 14, 140], [x + 14, 140], [x + 14, 720], [x - 14, 720]], hx('#3a3a40'), { n: 4, szMul: 0.7 }));
    // the clock, past nine
    const cx = 500 + sd * 200, cy = 250, r = 74;
    dot(ctx, cx, cy, r + 8, hx('#2a2a30')); dot(ctx, cx, cy, r, hx('#f4f2ea'));
    for (let k = 0; k < 12; k++) { const a = k / 12 * Math.PI * 2; dot(ctx, cx + Math.cos(a) * r * 0.82, cy + Math.sin(a) * r * 0.82, 3, hx('#2a2a30')); }
    ribbon(ctx, rng, [[cx, cy], [cx - r * 0.55, cy - r * 0.05]], hx('#2a2a30'), 6, { taper: 0.3, jit: 0.4 });
    ribbon(ctx, rng, [[cx, cy], [cx + r * 0.3, cy - r * 0.7]], hx('#2a2a30'), 4, { taper: 0.3, jit: 0.4 });
    ribbon(ctx, rng, [[cx, cy - r - 8], [cx, 150]], hx('#2a2a30'), 8, { taper: 0.02, jit: 0.4 });
    // the empty bench, far back on the open side
    const bx = 500 + sd * 330, by = 600;
    paintShape(ctx, rng, [[bx - 130, by], [bx + 130, by], [bx + 130, by + 26], [bx - 130, by + 26]], hx('#4a3a2c'), { n: 4, szMul: 0.6 });
    paintShape(ctx, rng, [[bx - 130, by - 60], [bx + 130, by - 60], [bx + 130, by - 38], [bx - 130, by - 38]], hx('#4a3a2c'), { n: 4, szMul: 0.6 });
    [-110, 110].forEach(dx => ribbon(ctx, rng, [[bx + dx, by + 26], [bx + dx, by + 90]], hx('#2a2a30'), 8, { taper: 0.05, jit: 0.4 }));
    sfSnow(env, 160, 6);
  }
  function sideBehindPlatform(K) { sSlabUnder(K, hx('#9a9a98'), { h: 60, edgeC: hx('#e8e8e4'), fill: hx('#4a4a48') }); }
  function sfNewspaperSnow(env) {
    const ctx = env.ctx, rng = env.rng;
    sfAtPaws(env, 1.1, (x, gy, s) => {
      const w = Math.max(40, 60 * s), h = w * 0.55;
      const np = [[x - w, gy - h], [x + w * 0.9, gy - h * 1.1], [x + w, gy - 2], [x - w * 0.9, gy]];
      paintShape(ctx, rng, np, hx('#ece8dc'), { n: 4, szMul: 0.55 });
      for (let k = 0; k < 4; k++) { ctx.globalAlpha = 0.5; ribbon(ctx, rng, [[x - w * 0.7, gy - h * 0.8 + k * h * 0.22], [x + w * 0.6, gy - h * 0.8 + k * h * 0.22]], hx('#6a6a68'), 2, { taper: 0.1, jit: 0.4 }); }
      ctx.globalAlpha = 1; shadowEdge(ctx, rng, np, hx('#6a6a68'), 2.5, { p: 0.5 });
    });
    sfSnow(env, 90, 5);
  }

  // ---- 77 1957 the capsule ----------------------------------------------
  function onesBehindCapsuleWindow(env) {
    const ctx = env.ctx, rng = env.rng;
    // the window's view: black space, the blue curve of the planet low, stars
    wBackFill(env, hx('#06080e'), -20, 1020, 1);
    for (let k = 0; k < 140; k++) { ctx.globalAlpha = rng.r(0.3, 1); dot(ctx, rng.r(0, 1000), rng.r(0, 800), rng.r(1.5, 4), hx('#f4f4f8')); }
    ctx.globalAlpha = 1;
    const planet = blob(rng, 500, 1380, 780, 640, 30, 0.02);
    paintShape(ctx, rng, planet, hx('#2a5aa8'), { n: 12, szMul: 1.0, drift: 0.03 });
    for (let k = 0; k < 30; k++) { ctx.globalAlpha = 0.5; paintShape(ctx, rng, blob(rng, rng.r(100, 900), rng.r(760, 1000), rng.r(30, 90), rng.r(14, 30), 12, 0.15), rng.pick([hx('#f4f4f8'), hx('#8ab8e8'), hx('#3a8a5a')]), { n: 3, szMul: 0.6 }); }
    ctx.globalAlpha = 1;
    ctx.globalAlpha = 0.5; ribbon(ctx, rng, [[-20, 745], [500, 715], [1020, 745]], hx('#a8d0f8'), 10, { taper: 0.3, wob: 0.2, jit: 1.2 }); ctx.globalAlpha = 1;
  }
  function sidePaddedHarness(K) {
    sHarness(K, hx('#5a4a3a'), { w: Math.max(7, K.D.hry * 0.1), ring: hx('#c8c8c0'), t0: 0.14, t1: 0.46 });
    // the padded seat's back behind the rump: a grey-green cushion
    const p = K.P(0.9, 0.3, 0);
    paintShape(K.ctx, K.rng, blob(K.rng, p[0] + K.bd * K.D.hrx * 0.3, p[1], K.D.hrx * 0.3, K.D.hry * 0.5, 12, 0.1), hx('#6a7a6a'), { n: 4, szMul: 0.6 });
  }
  function sfPorthole(env) {           // the riveted capsule wall with its round window, the dog inside it
    const ctx = env.ctx, rng = env.rng, D = env.D, S = sScreen(env);
    const cx = (S.mouth[0] + S.rump[0]) / 2, cy = (D.headSY - D.hry * 0.9 * S.s + S.ground) / 2;
    const r = Math.max(Math.abs(S.rump[0] - S.mouth[0]) * 0.75 + D.hrx * 1.1 * S.s, (S.ground - (D.headSY - D.hry * 1.2 * S.s)) * 0.62);
    // the wall: everything outside the circle
    ctx.save();
    ctx.beginPath(); ctx.rect(-20, -20, 1040, 1040); ctx.arc(cx, cy, r, 0, Math.PI * 2, true); ctx.clip('evenodd');
    paintShape(ctx, rng, [[-20, -20], [1020, -20], [1020, 1020], [-20, 1020]], hx('#7a7a78'), { n: 14, szMul: 1.1, drift: 0.03 });
    for (let k = 0; k < 6; k++) { ctx.globalAlpha = 0.35; ribbon(ctx, rng, [[-20, rng.r(0, 1000)], [1020, rng.r(0, 1000)]], hx('#5a5a58'), rng.r(6, 16), { taper: 0.1, wob: 0.1, jit: 1 }); }
    ctx.globalAlpha = 1;
    ctx.restore();
    // the ring and its rivets
    const ring = []; for (let j = 0; j <= 48; j++) { const a = j / 48 * Math.PI * 2; ring.push([cx + Math.cos(a) * (r + 18), cy + Math.sin(a) * (r + 18)]); }
    ribbon(ctx, rng, ring, hx('#4a4a48'), 40, { taper: 0.02, wob: 0.05, jit: 0.8 });
    for (let j = 0; j < 20; j++) { const a = j / 20 * Math.PI * 2; dot(ctx, cx + Math.cos(a) * (r + 18), cy + Math.sin(a) * (r + 18), 9, hx('#2a2a28')); dot(ctx, cx + Math.cos(a) * (r + 18) - 2, cy + Math.sin(a) * (r + 18) - 2, 4, hx('#a8a8a0')); }
    ctx.globalAlpha = 0.25; ribbon(ctx, rng, [[cx - r * 0.7, cy - r * 0.55], [cx - r * 0.3, cy - r * 0.85]], hx('#f4f4f8'), 12, { taper: 0.6, jit: 1 }); ctx.globalAlpha = 1;
    // the air hose from the harness ring out to the wall
    const h0 = [S.back[0] + S.bd * D.hrx * 0.2 * S.s, S.back[1] + D.hry * 0.2 * S.s];
    ribbon(ctx, rng, [h0, [h0[0] + S.bd * r * 0.3, h0[1] - r * 0.2], [cx + S.bd * r * 0.95, cy - r * 0.3]], hx('#8a8a88'), 9, { taper: 0.05, wob: 0.2, jit: 1 });
  }

