    paintShape(ctx, rng, [[lx - 26, ly - 30], [lx + 26, ly - 30], [lx + 20, ly + 26], [lx - 20, ly + 26]], hx('#1c1c20'), { n: 3, szMul: 0.5 });
    ctx.globalAlpha = 0.3; ctx.beginPath(); ctx.rect(lx - 26, ly - 30, 52, 56); ctx.fillStyle = css(hx('#f8e090')); ctx.fill(); ctx.globalAlpha = 1;
