    for (let k = 0; k < 200; k++) { ctx.globalAlpha = rng.r(0.2, 0.6); dot(ctx, rng.r(-10, 1010), rng.r(-10, 1010), rng.r(1.5, 5), hx('#9a9490')); }
    ctx.globalAlpha = 1;
