  function sfStuddedCollarChain(env) { // the bronze-studded collar, the chain to the ring in the wall
    const ctx = env.ctx, rng = env.rng, D = env.D, s = D.figS, cx = D.headSX, cy = D.headSY, bd = D.bodyDir || 1;
    const rx = D.hrx * 0.98 * s, ry = D.hry * 0.96 * s;
    const arc = []; for (let j = 0; j <= 12; j++) { const a = Math.PI * (0.18 + 0.64 * j / 12); arc.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry]); }
    ribbon(ctx, rng, arc, hx('#5a4a30'), Math.max(10, D.hry * 0.14 * s), { taper: 0.02, wob: 0.05, jit: 0.8 });
    for (let j = 1; j < 12; j += 2) dot(ctx, arc[j][0], arc[j][1], Math.max(4, D.hrx * 0.05 * s), hx('#a87a30'));
    // the chain: links sagging away to a ring set in the wall at the frame's edge
    const wx = bd > 0 ? 40 : 960, wy = cy - D.hry * 0.4 * s;
    const p0 = arc[bd > 0 ? 11 : 1];
    const n = 16;
    for (let k = 0; k <= n; k++) { const t = k / n; const x = p0[0] + (wx - p0[0]) * t, y = p0[1] + (wy - p0[1]) * t + Math.sin(t * Math.PI) * 120; ctx.globalAlpha = 0.95; const ring = []; for (let j = 0; j <= 10; j++) { const a = j / 10 * Math.PI * 2; ring.push([x + Math.cos(a) * 9, y + Math.sin(a) * 6]); } ribbon(ctx, rng, ring, hx('#6a6058'), 3.5, { taper: 0.02, jit: 0.4 }); }
    ctx.globalAlpha = 1;
    const wall = []; for (let j = 0; j <= 14; j++) { const a = j / 14 * Math.PI * 2; wall.push([wx + Math.cos(a) * 20, wy + Math.sin(a) * 20]); }
    ribbon(ctx, rng, wall, hx('#7a7068'), 7, { taper: 0.02, jit: 0.5 });
    paintShape(ctx, rng, [[wx - 30, wy - 60], [wx + 30, wy - 60], [wx + 30, wy - 22], [wx - 30, wy - 22]], hx('#4a4644'), { n: 3, szMul: 0.5 });
  }

