    const dx = cx < 500 ? 820 : 175;
    const dy = 908;
    const dr = 78;
    const shell = hx('#f7f6f1'), panel = hx('#2a2a30'), orange = hx('#e0782a');
    const body = blob(rng, dx, dy, dr, dr * 0.92, 16, 0.08);
    paintShape(ctx, rng, body, shell, { n: 5, szMul: 0.55, drift: 0.03 });
