    [[0.1, 0.2, 0.34], [-0.45, -0.25, 0.22], [0.5, 0.35, 0.18]].forEach(q => {
      const ring = [];
      for (let j = 0; j <= 14; j++) { const a = j / 14 * 6.283; ring.push([dx + q[0] * dr + Math.cos(a) * dr * q[2], dy + q[1] * dr + Math.sin(a) * dr * q[2] * 0.85]); }
      ctx.globalAlpha = 0.9;
      ribbon(ctx, rng, ring, orange, Math.max(4, dr * 0.09), { taper: 0.05, wob: 0.1, jit: 0.6, closed: true });
      ctx.globalAlpha = 1;
    });
