    const hd = blob(rng, dx, dy - dr * 1.05, dr * 0.55, dr * 0.42, 12, 0.06);
    paintShape(ctx, rng, hd, shell, { n: 3, szMul: 0.5, drift: 0.03 });
    ribbon(ctx, rng, [[dx - dr * 0.5, dy - dr * 0.86], [dx + dr * 0.5, dy - dr * 0.86]], orange, Math.max(3, dr * 0.07), { taper: 0.1, jit: 0.5 });
    shadowEdge(ctx, rng, hd, mix(line, shell, 0.3), 4, { p: 0.55 });
    // a single dark circular lens, tilted up toward the dog
