    ribbon(ctx, rng, [[D.hcx - w, my], [D.hcx + w, my]], metal, Math.max(2.5, D.hry * 0.02), { taper: 0.05, jit: 0.5 });
    for (let k = -3; k <= 3; k++) dot(ctx, D.hcx + k * w * 0.3, my, Math.max(2, D.hry * 0.016), metal);
    ctx.globalAlpha = 1;
