    wBackFill(env, hx('#141a2a'), -20, 1020, 0.55);
    spray(ctx, rng, 120, 250, 380, hx('#8ac8f0'), 0.6, { a: 0.20, spread: 0.9, elx: 1.4 });
    // the couch: a long low back with two sagging cushions, arms at both ends
