    const gy = Math.min(900, cy + D.hry * 2.0 * s), gx = cx + sd * D.hrx * 0.4 * s;
    const body = blob(rng, gx, gy, Math.max(90, D.hrx * 0.85 * s), Math.max(70, D.hry * 0.62 * s), 18, 0.12, sd * 0.25);
    paintShape(ctx, rng, body, hx('#c8702a'), { n: 7, szMul: 0.7, drift: 0.06 });
