  function onesFrontFlex(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    [-1, 1].forEach(sd => {
      const sx = cx + sd * D.hrx * 1.05 * s, sy = cy + D.hry * 1.5 * s;
      const ex = cx + sd * D.hrx * 1.9 * s, ey = cy + D.hry * 1.55 * s;
      const fx = cx + sd * D.hrx * 1.75 * s, fy = cy + D.hry * 0.55 * s;
      drawStroke(ctx, rng, [[sx, sy], [ex, ey]], { color: env.coat, w: Math.max(34, D.hrx * 0.34 * s), fade: 0.5, grain: 0.24, press: 0.3 });
      drawStroke(ctx, rng, [[ex, ey], [fx, fy]], { color: env.coat, w: Math.max(30, D.hrx * 0.30 * s), fade: 0.5, grain: 0.24, press: 0.3 });
      fillPts(ctx, blob(rng, (ex + sx) / 2, ey - D.hry * 0.12 * s, D.hrx * 0.30 * s, D.hry * 0.22 * s, 12, 0.1), lift(env.coat, 0.08));
      wPaw(env, fx, fy, Math.max(24, D.hrx * 0.24 * s));
    });
  }

  // ---- 39 1979 the tam -------------------------------------------------
  function hwOneDreadsTam(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const dread = hx('#2a1a10');
    for (let k = 0; k < 16; k++) {
      const t = k / 15 * 2 - 1;
      const x0 = D.hcx + t * D.hrx * 1.02, y0 = D.hcy - D.hry * 0.55 + Math.abs(t) * D.hry * 0.2;
      ctx.globalAlpha = 0.95;
      ribbon(ctx, rng, [[x0, y0], [x0 + t * D.hrx * 0.2 + rng.r(-10, 10), y0 + D.hry * 0.9], [x0 + t * D.hrx * 0.35 + rng.r(-14, 14), D.hcy + D.hry * rng.r(1.3, 1.9)]],
             k % 3 ? dread : lift(dread, 0.15), D.hrx * rng.r(0.06, 0.09), { taper: 0.25, wob: 0.4, jit: 1.4, step: 12 });
    }
    ctx.globalAlpha = 1;
    const tam = wDome(h, hx('#2a7a3a'), { brow: 0.50, h: 0.9, w: 1.18, sag: 0.02, n: 9 });
    const y0 = wBrowY(D, 0.50);
    [[hx('#f0c828'), 0.30], [hx('#c8202a'), 0.55]].forEach(bd => {
      ctx.globalAlpha = 0.95;
      ribbon(ctx, rng, [[D.hcx - D.hrx * 1.1, y0 - D.hry * 0.9 * bd[1] + D.hry * 0.2], [D.hcx, y0 - D.hry * 0.9 * bd[1] - D.hry * 0.05], [D.hcx + D.hrx * 1.1, y0 - D.hry * 0.9 * bd[1] + D.hry * 0.2]],
             bd[0], D.hry * 0.12, { taper: 0.05, wob: 0.25, jit: 1.2 });
    });
    ctx.globalAlpha = 1;
    void tam;
  }
  function onesBodyDenim(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const den = D.robeC || hx('#5a78a0');
    wClip(b, () => {
      for (let k = 0; k < 10; k++) {
        ctx.globalAlpha = 0.25;
        ribbon(ctx, rng, [[D.hcx - b.shWl, b.jawY + 60 + k * 60], [D.hcx + b.shWr, b.jawY + 70 + k * 60]], lift(den, 0.35), 6, { taper: 0.2, wob: 0.3, jit: 1.5 });
      }
      ctx.globalAlpha = 1;
    });
    wShirtV(b, hx('#f4efe0'), 180, D.neckW * 0.5);
    wButtons(b, hx('#d8d0b8'), 3, { y0: 200, gap: 110, r: 8 });
  }

  // ---- 40 1970 the bat -------------------------------------------------
  function hwOneLongBlack(h) { wHairCap(h, hx('#141018'), { top: 0.86, brow: 0.5, w: 1.04, strands: 6 }); wHairSides(h, hx('#141018'), 1.7, { w: 1.28 }); }
  function ewOnePurpleRounds(h) { wGlasses(h, { frame: hx('#2a2226'), lens: hx('#6a3a9a'), lensA: 0.62, r: 1.35, minR: 0.14 }); }
  function onesFrontCrossBat(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    // the cross on a chain
    const cyc = Math.min(920, cy + D.hry * 1.75 * s), gold = hx('#c8a040');
    ribbon(ctx, rng, [[cx - D.hrx * 0.5 * s, cy + D.hry * 1.05 * s], [cx, cyc - D.hry * 0.4 * s], [cx + D.hrx * 0.5 * s, cy + D.hry * 1.05 * s]], gold, 4, { taper: 0.05, wob: 0.2, jit: 1 });
    const cw = Math.max(12, D.hrx * 0.10 * s), ch = Math.max(40, D.hry * 0.42 * s);
    paintShape(ctx, rng, [[cx - cw * 0.45, cyc - ch * 0.5], [cx + cw * 0.45, cyc - ch * 0.5], [cx + cw * 0.45, cyc + ch * 0.5], [cx - cw * 0.45, cyc + ch * 0.5]], gold, { n: 3, szMul: 0.5 });
    paintShape(ctx, rng, [[cx - cw * 1.6, cyc - ch * 0.15], [cx + cw * 1.6, cyc - ch * 0.15], [cx + cw * 1.6, cyc + ch * 0.05], [cx - cw * 1.6, cyc + ch * 0.05]], gold, { n: 3, szMul: 0.5 });
    // the bat, in the mouth: two dark wings either side of the muzzle
    const mx = cx, my = cy + D.hry * 0.72 * s, bw = Math.max(60, D.hrx * 0.7 * s);
    const bat = hx('#1c1618');
    [-1, 1].forEach(sd => {
      const wing = [[mx + sd * bw * 0.1, my], [mx + sd * bw * 0.5, my - bw * 0.35], [mx + sd * bw * 1.0, my - bw * 0.25],
                    [mx + sd * bw * 0.85, my + bw * 0.05], [mx + sd * bw * 0.95, my + bw * 0.3], [mx + sd * bw * 0.6, my + bw * 0.2], [mx + sd * bw * 0.45, my + bw * 0.42], [mx + sd * bw * 0.15, my + bw * 0.2]];
      paintShape(ctx, rng, smoothPts(resample(wing, true, 5), true, 1), bat, { n: 4, szMul: 0.55, drift: 0.04 });
    });
    fillPts(ctx, blob(rng, mx, my + bw * 0.05, bw * 0.16, bw * 0.24, 10, 0.1), bat);
    [-1, 1].forEach(sd => { dot(ctx, mx + sd * bw * 0.06, my - bw * 0.02, Math.max(2, bw * 0.03), hx('#e83030')); });
    void line;
  }

  // ---- 41 2009 the supermodel ------------------------------------------
  function hwOneBigBlonde(h) { wTallWig(h, hx('#f0c860'), { h: 2.4, lean: 0.06 }); }
  function onesEyeLashes(EY) {
    const ctx = EY.ctx, rng = EY.rng, D = EY.D;
    const exo = EY.exo !== undefined ? EY.exo : wExo(D), eyy = EY.eyy !== undefined ? EY.eyy : wEyeY(D);
    const r = EY.rr0 || D.eyeR * 1.3;
    [-1, 1].forEach(sd => {
      for (let k = 0; k < 5; k++) {
        const a = -Math.PI * 0.85 + k / 4 * Math.PI * 0.7;
        const x0 = D.hcx + sd * exo + Math.cos(a) * r * 1.02, y0 = eyy + Math.sin(a) * r * 1.02;
        ribbon(ctx, rng, [[x0, y0], [x0 + Math.cos(a) * r * 0.55 + sd * r * 0.1, y0 + Math.sin(a) * r * 0.6]], hx('#161216'), Math.max(2.5, r * 0.09), { taper: 0.7, jit: 0.6 });
      }
    });
  }
  function onesBodyGown(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const gown = D.robeC || hx('#d84a7a');
    wSequins(b, lift(gown, 0.5), 120, { r: 4.5, h: 800 });
    wClip(b, () => {
      ctx.globalAlpha = 0.5;
      ribbon(ctx, rng, [[D.hcx - b.shWl * 0.7, b.jawY + 30], [D.hcx, b.jawY + 110], [D.hcx + b.shWr * 0.7, b.jawY + 30]], sink(gown, 0.3), 8, { taper: 0.2, jit: 1 });
      ctx.globalAlpha = 1;
    });
  }
  function onesFrontHipHand(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const hx0 = cx + sd * D.hrx * 1.25 * s, hy = Math.min(960, cy + D.hry * 2.4 * s);
    drawStroke(ctx, rng, [[cx + sd * D.hrx * 0.9 * s, cy + D.hry * 1.4 * s], [cx + sd * D.hrx * 1.75 * s, cy + D.hry * 1.95 * s], [hx0, hy]],
               { color: env.coat, w: Math.max(22, D.hrx * 0.22 * s), fade: 0.5, grain: 0.24, press: 0.3 });
    wPaw(env, hx0, hy, Math.max(22, D.hrx * 0.2 * s));
  }

  // ---- 42 1996 the crocodile hunter ------------------------------------
  function hwOneShortBlond(h) { wHairCap(h, hx('#e0c078'), { top: 0.80, brow: 0.5, w: 1.0, part: -1, strands: 5 }); }
  function onesBodyKhaki(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const kh = D.robeC || hx('#b8a06a');
    wShirtV(b, lift(kh, 0.15), 120, D.neckW * 0.45);
    [-1, 1].forEach(sd => {
      const px = D.hcx + sd * D.neckW * 0.95, py = b.jawY + 230;
      const pocket = [[px - 44, py - 40], [px + 44, py - 40], [px + 40, py + 50], [px - 40, py + 50]];
      paintShape(ctx, rng, pocket, sink(kh, 0.08), { n: 3, szMul: 0.5 });
      shadowEdge(ctx, rng, pocket, mix(b.line, kh, 0.35), 3, { p: 0.5 });
      dot(ctx, px, py - 30, 6, sink(kh, 0.3));
    });
    wButtons(b, sink(kh, 0.3), 3, { y0: 140, gap: 100, r: 7 });
    void ctx;
  }
  function onesFrontCroc(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const green = hx('#4a7a3a'), belly = hx('#b8c890');
    // J 2026-09-02: the crocodile lies on the ground at his feet, out to
    // the open side, not across his chest
    const gC = D.childGeo;
    const groundS = gC ? 800 + (gC.groundY - 800) * s : 900;
    const y = Math.min(945, groundS - 30 * s), x0 = cx + sd * D.hrx * 0.9 * s;
    const len = Math.max(240, Math.min(sd > 0 ? 960 - x0 : x0 - 40, D.hrx * 3.2 * s));
    const bodyPts = [];
    for (let j = 0; j <= 20; j++) {
      const t = j / 20;
      bodyPts.push([x0 + sd * t * len, y - Math.sin(t * Math.PI) * 78]);
    }
    for (let j = 20; j >= 0; j--) {
      const t = j / 20;
      bodyPts.push([x0 + sd * t * len, y + Math.sin(t * Math.PI) * 66 + 6]);
    }
    const bs = smoothPts(bodyPts, true, 1);
    paintShape(ctx, rng, bs, green, { n: 8, szMul: 0.8, drift: 0.06 });
    ctx.globalAlpha = 0.6;
    ribbon(ctx, rng, [[x0 + sd * len * 0.15, y + 30], [x0 + sd * len * 0.75, y + 34]], belly, 36, { taper: 0.3, wob: 0.3, jit: 1.2 });
    ctx.globalAlpha = 1;
    for (let k = 0; k < 9; k++) {
      const t = 0.12 + k * 0.08;
      ribbon(ctx, rng, [[x0 + sd * t * len, y - Math.sin(t * Math.PI) * 72], [x0 + sd * t * len + sd * 4, y - Math.sin(t * Math.PI) * 72 - 30]], sink(green, 0.35), 8, { taper: 0.7, jit: 0.6 });
    }
    // the snout at the far end, jaws open a crack, one eye up
    const sx = x0 + sd * len, sy = y;
    paintShape(ctx, rng, [[sx - sd * 90, sy - 56], [sx + sd * 60, sy - 36], [sx + sd * 64, sy + 16], [sx - sd * 90, sy + 44]], green, { n: 4, szMul: 0.5 });
    ribbon(ctx, rng, [[sx - sd * 74, sy - 4], [sx + sd * 58, sy - 10]], hx('#2a1a10'), 4, { taper: 0.2, jit: 0.5 });
    for (let k = 0; k < 6; k++) dot(ctx, sx - sd * 64 + sd * k * 22, sy - 6, 4.5, hx('#f4f0e0'));
    dot(ctx, sx - sd * 62, sy - 48, 10, hx('#f0d040'));
    dot(ctx, sx - sd * 62, sy - 48, 4.5, hx('#1a1410'));
    shadowEdge(ctx, rng, bs, mix(line, green, 0.35), 6, { p: 0.5 });
    // one arm reaching down to hold its jaws shut
    wArm(env, x0 + sd * len * 0.82, y - 60 * s, Math.max(16, D.hrx * 0.24 * s));
    wPaw(env, x0 + sd * len * 0.84, y - 50 * s, Math.max(16, D.hrx * 0.22 * s));
  }

  // ---- 43 1968 the cardigan --------------------------------------------
  function hwOneNeatGrey(h) { wHairCap(h, hx('#9a9088'), { top: 0.78, brow: 0.52, w: 0.98, part: 1, strands: 6 }); }
  function onesBodyCardigan(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const red = D.robeC || hx('#c8342c');
    wShirtV(b, hx('#f4f0e6'), 150, D.neckW * 0.42);
    wTie(b, hx('#2a3a6a'), 220, hx('#1a2a4a'));
    wClip(b, () => {
      ctx.globalAlpha = 0.7;
      ribbon(ctx, rng, [[D.hcx, b.jawY + 150], [D.hcx + rng.r(-3, 3), 1520]], hx('#c8c0b0'), 7, { taper: 0.05, jit: 0.8 });
      for (let k = 0; k < 24; k++) dot(ctx, D.hcx + rng.r(-2, 2), b.jawY + 160 + k * 55, 2.5, hx('#8a8078'));
      ctx.globalAlpha = 1;
      [-1, 1].forEach(sd => {
        ribbon(ctx, rng, [[D.hcx + sd * D.neckW * 0.35, b.jawY + 40], [D.hcx + sd * D.neckW * 0.55, b.jawY + 400]], sink(red, 0.25), 10, { taper: 0.1, jit: 1 });
      });
    });
  }
  function onesFrontTrolley(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const sd = D.headSX < 500 ? 1 : -1;
    const tx = sd > 0 ? 790 : 210, ty = 905;
    // a track, then the little red trolley
    ribbon(ctx, rng, [[tx - 200, ty + 40], [tx + 200, ty + 42]], hx('#5a4a3a'), 5, { taper: 0.05, jit: 0.6 });
    for (let k = -4; k <= 4; k++) ribbon(ctx, rng, [[tx + k * 44, ty + 32], [tx + k * 44, ty + 50]], hx('#5a4a3a'), 4, { taper: 0.1, jit: 0.4 });
    const car = [[tx - 78, ty - 52], [tx + 78, ty - 52], [tx + 84, ty + 22], [tx - 84, ty + 22]];
    paintShape(ctx, rng, car, hx('#c8342c'), { n: 5, szMul: 0.6, drift: 0.04 });
    paintShape(ctx, rng, [[tx - 90, ty - 60], [tx + 90, ty - 60], [tx + 84, ty - 48], [tx - 84, ty - 48]], hx('#f0d040'), { n: 3, szMul: 0.5 });
    for (let k = -1; k <= 1; k++) fillPts(ctx, [[tx + k * 44 - 14, ty - 40], [tx + k * 44 + 14, ty - 40], [tx + k * 44 + 14, ty - 10], [tx + k * 44 - 14, ty - 10]], hx('#e8e8e0'));
    [-1, 1].forEach(es => { dot(ctx, tx + es * 50, ty + 26, 12, hx('#2a2624')); dot(ctx, tx + es * 50, ty + 26, 5, hx('#a8a8a0')); });
    ribbon(ctx, rng, [[tx, ty - 60], [tx + 6, ty - 92]], hx('#2a2624'), 3, { taper: 0.2, jit: 0.4 });
    shadowEdge(ctx, rng, car, mix(line, hx('#c8342c'), 0.4), 3.5, { p: 0.5 });
  }

  // ---- 44 1956 the pompadour at the piano ------------------------------
  function hwOneTallPompadour(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const jet = hx('#141014');
    wHairSides(h, jet, 0.55, { w: 1.08 });
    const by0 = D.hcy - D.hry * 0.62;
    let wave = [[D.hcx - D.hrx * 0.9, by0 + D.hry * 0.3], [D.hcx - D.hrx * 0.86, by0 - D.hry * 0.4], [D.hcx - D.hrx * 0.5, by0 - D.hry * 1.05],
                [D.hcx + D.hrx * 0.05, by0 - D.hry * 1.25], [D.hcx + D.hrx * 0.62, by0 - D.hry * 1.0], [D.hcx + D.hrx * 1.0, by0 - D.hry * 0.3],
                [D.hcx + D.hrx * 1.02, by0 + D.hry * 0.2], [D.hcx + D.hrx * 0.3, by0 + D.hry * 0.22], [D.hcx - D.hrx * 0.4, by0 + D.hry * 0.34]];
    wave = smoothPts(resample(wave, true, 10), true, 2);
    paintShape(ctx, rng, wave, jet, { under: 0.9, n: 10, szMul: 0.8, flow: 'dome', center: [D.hcx, by0 + D.hry * 0.5], cJit: D.hrx * 0.3, drift: 0.05 });
    for (let k = 0; k < 4; k++) {
      ctx.globalAlpha = rng.r(0.25, 0.45);
      ribbon(ctx, rng, [[D.hcx - D.hrx * 0.7 + k * D.hrx * 0.12, by0 + D.hry * 0.15], [D.hcx - D.hrx * 0.1 + k * D.hrx * 0.15, by0 - D.hry * (0.7 + k * 0.1)], [D.hcx + D.hrx * (0.5 + k * 0.1), by0 - D.hry * 0.5]],
             lift(jet, 0.4), D.hry * 0.05, { taper: 0.4, wob: 0.3, jit: 1.4, step: 9 });
    }
    ctx.globalAlpha = 1;
    if (D.inked) inkPath(ctx, rng, wave, D.inkC, D.lineW * 0.8, { aMul: 0.8 });
  }
  function ewOnePencil(h) { wMustache(h, 'pencil', hx('#1a1414')); }
  function onesBodyGoldJacket(b) {
    const D = b.D;
    const gold = D.robeC || hx('#c0a030');
    wShirtV(b, hx('#f4f0e6'), 200, D.neckW * 0.5);
    wLapels(b, sink(gold, 0.15), { w: 0.9, len: 300 });
    wSequins(b, lift(gold, 0.4), 110, { r: 4 });
    wBowTie(b, hx('#1a1414'), { y: 52, w: 0.55 });
  }

  // ---- 45 1967 the burning guitar --------------------------------------
  function hwOneAfroBand(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    wHairMass(h, hx('#1c1410'), { up: 0.62, rx: 1.55, ry: 1.25, lobes: 16, mag: 0.14 });
    const y0 = wBrowY(D, 0.48);
    ribbon(ctx, rng, [[D.hcx - D.hrx * 1.1, y0 + D.hry * 0.08], [D.hcx, y0 - D.hry * 0.02], [D.hcx + D.hrx * 1.1, y0 + D.hry * 0.08]], hx('#c83a8a'), D.hry * 0.13, { taper: 0.05, wob: 0.25, jit: 1.3 });
    ctx.globalAlpha = 0.5;
    for (let k = 0; k < 6; k++) dot(ctx, D.hcx + (k - 2.5) * D.hrx * 0.36, y0 + D.hry * 0.02, 4, hx('#f0d060'));
    ctx.globalAlpha = 1;
  }
  function onesBodyFringe(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const vel = D.robeC || hx('#7a3a8a');
    wShirtV(b, hx('#e8c860'), 240, D.neckW * 0.5);
    [-1, 1].forEach(sd => {
      const x0 = D.hcx + sd * (sd < 0 ? b.shWl : b.shWr) * 0.9;
      for (let k = 0; k < 9; k++) {
        ctx.globalAlpha = 0.9;
        ribbon(ctx, rng, [[x0 + sd * k * 6, b.jawY + 300 + k * 12], [x0 + sd * k * 8 + rng.r(-4, 4), b.jawY + 520 + k * 14]], sink(vel, 0.2), 5, { taper: 0.5, jit: 0.8 });
      }
    });
    ctx.globalAlpha = 1;
  }
  function onesFrontBurningGuitar(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const sd = D.headSX < 500 ? 1 : -1;
    const gx = sd > 0 ? 720 : 280, gy = 900;
    const body = blob(rng, gx, gy, 120, 78, 18, 0.12, 0.1);
    paintShape(ctx, rng, body, hx('#f4f0e6'), { n: 6, szMul: 0.7, drift: 0.05 });
    fillPts(ctx, blob(rng, gx, gy, 22, 20, 10, 0.1), hx('#1a1410'));
    wStick(env, gx + sd * 90, gy - 14, gx + sd * 330, gy - 70, hx('#3a2418'), 14);
    shadowEdge(ctx, rng, body, mix(line, hx('#8a8070'), 0.5), 5, { p: 0.55 });
    for (let k = 0; k < 6; k++) wFlame(env, gx + rng.r(-110, 110), gy - 30 + rng.r(-10, 10), rng.r(40, 90));
    spray(ctx, rng, gx, gy - 140, 160, hx('#3a3030'), 0.4, { a: 0.18, spread: 0.8, ely: 1.5 });
    // kneeling: both arms down to the guitar
    wArm(env, gx - sd * 60, gy - 20, Math.max(22, D.hrx * 0.22 * D.figS));
    wPaw(env, gx - sd * 60, gy - 24, Math.max(22, D.hrx * 0.2 * D.figS));
  }

  // ---- 46 2008 the beehive ---------------------------------------------
  function hwOneBeehive(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const jet = hx('#141014');
    wHairSides(h, jet, 0.9, { w: 1.14 });
    wTallWig(h, jet, { h: 2.2, lean: -0.05 });
    // a small bow tucked at the base
    ctx.globalAlpha = 0.95;
    [-1, 1].forEach(sd => fillPts(ctx, blob(rng, D.hcx + sd * D.hrx * 0.14 + D.hrx * 0.6, D.hcy - D.hry * 0.62, D.hrx * 0.12, D.hry * 0.07, 10, 0.1, sd * 0.3), hx('#e83a6a')));
    ctx.globalAlpha = 1;
  }
  function ewOneWings(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const exo = h.exo, eyy = h.eyy, r = D.eyeR * (D.eyeMul || 1.3);
    [-1, 1].forEach(sd => {
      const x0 = D.hcx + sd * exo;
      ribbon(ctx, rng, [[x0 - sd * r * 0.8, eyy - r * 0.9], [x0 + sd * r * 0.7, eyy - r * 1.02], [x0 + sd * r * 1.75, eyy - r * 1.55]],
             hx('#100c10'), Math.max(4, r * 0.16), { taper: 0.55, wob: 0.15, jit: 0.8 });
      ribbon(ctx, rng, [[x0 - sd * r * 0.5, eyy + r * 0.75], [x0 + sd * r * 0.8, eyy + r * 0.62]], hx('#100c10'), Math.max(2.5, r * 0.08), { taper: 0.5, jit: 0.6 });
    });
  }
  function onesFrontTattooArms(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    [-1, 1].forEach(sd => {
      const ax = cx + sd * D.hrx * 1.2 * s;
      for (let k = 0; k < 5; k++) {
        const y = cy + D.hry * (1.5 + k * 0.28) * s;
        if (y > 980) break;
        ctx.globalAlpha = 0.7;
        const kind = (k + (sd > 0 ? 1 : 0)) % 3;
        if (kind === 0) ribbon(ctx, rng, [[ax - 14, y], [ax, y - 12], [ax + 14, y], [ax, y + 12], [ax - 14, y]], hx('#2a2a3a'), 3, { taper: 0.1, jit: 0.5 });
        else if (kind === 1) { for (let j = 0; j < 4; j++) dot(ctx, ax + Math.cos(j / 4 * Math.PI * 2) * 9, y + Math.sin(j / 4 * Math.PI * 2) * 9, 4, hx('#2a2a3a')); }
        else ribbon(ctx, rng, [[ax - 16, y + 6], [ax - 6, y - 8], [ax + 6, y + 8], [ax + 16, y - 6]], hx('#2a2a3a'), 3, { taper: 0.2, jit: 0.5 });
      }
    });
    ctx.globalAlpha = 1;
  }

  // ---- 47 1992 the lifeguard -------------------------------------------
  function hwOneBlowout(h) {
    const D = h.D;
    wHairMass(h, hx('#f0d070'), { up: 0.35, rx: 1.5, ry: 1.2, lobes: 14, mag: 0.16 });
    wHairSides(h, hx('#f0d070'), 1.4, { w: 1.34 });
    void D;
  }
  function onesBehindBeach(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#88c4e8'), -20, 560, 0.85);
    wBackFill(env, hx('#2a7ab8'), 540, 700, 0.9);
    for (let k = 0; k < 7; k++) {
      ctx.globalAlpha = 0.7;
      ribbon(ctx, rng, [[rng.r(-20, 700), 560 + k * 20], [rng.r(300, 1020), 566 + k * 20]], hx('#f4fbff'), rng.r(4, 9), { taper: 0.5, wob: 0.4, jit: 1.5 });
    }
    ctx.globalAlpha = 1;
    wBackFill(env, hx('#e8d0a0'), 690, 1020, 0.95);
    dot(ctx, 820, 120, 60, hx('#fff4c0'));
  }
  function onesFrontFloat(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const red = hx('#d8202a');
    const fx = cx + sd * D.hrx * 1.45 * s, fy = Math.min(900, cy + D.hry * 2.0 * s);
    const fw = Math.max(26, 50 * s), fh = Math.max(90, 170 * s);
    const fl = [[fx - fw, fy - fh], [fx + fw, fy - fh], [fx + fw * 1.1, fy + fh], [fx - fw * 1.1, fy + fh]];
    const fs = smoothPts(resample(fl, true, 8), true, 2);
    paintShape(ctx, rng, fs, red, { n: 6, szMul: 0.7, drift: 0.05 });
    ctx.globalAlpha = 0.4;
    ribbon(ctx, rng, [[fx - fw * 0.4, fy - fh * 0.9], [fx - fw * 0.5, fy + fh * 0.9]], lift(red, 0.4), Math.max(5, 12 * s), { taper: 0.3, jit: 1 });
    ctx.globalAlpha = 1;
    shadowEdge(ctx, rng, fs, mix(line, red, 0.4), 4, { p: 0.5 });
    wArm(env, fx, fy - fh * 0.25, Math.max(16, D.hrx * 0.22 * s));
    wPaw(env, fx, fy - fh * 0.28, Math.max(16, D.hrx * 0.2 * s));
  }
  // J 2026-09-02: the red bikini over the bust the body paints, and the
  // bottoms at the seat; skin everywhere else
  function onesBodyBikini(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const red = hx('#d8202a');
    const bg = D.bustGeo, g = D.childGeo;
    if (bg) {
      [-1, 1].forEach(sd => {
        const bx = D.hcx + sd * bg.br * 0.92, by = bg.by;
        const cup = [[bx - sd * bg.br * 0.15, by - bg.br * 0.9], [bx + sd * bg.br * 0.95, by - bg.br * 0.1],
                     [bx + sd * bg.br * 0.75, by + bg.br * 0.85], [bx - sd * bg.br * 0.75, by + bg.br * 0.75]];
        paintShape(ctx, rng, smoothPts(resample(cup, true, 6), true, 1), red, { n: 5, szMul: 0.6, drift: 0.04 });
      });
      ribbon(ctx, rng, [[D.hcx - bg.br * 1.9, by0(bg)], [D.hcx, by0(bg) + bg.br * 0.2], [D.hcx + bg.br * 1.9, by0(bg)]],
             red, Math.max(3, bg.br * 0.09), { taper: 0.1, wob: 0.15, jit: 1 });
      ribbon(ctx, rng, [[D.hcx - bg.br * 0.3, by0(bg) - bg.br * 0.9], [D.hcx - bg.br * 1.1, by0(bg) - bg.br * 2.0]], red, Math.max(3, bg.br * 0.08), { taper: 0.1, jit: 0.8 });
      ribbon(ctx, rng, [[D.hcx + bg.br * 0.3, by0(bg) - bg.br * 0.9], [D.hcx + bg.br * 1.1, by0(bg) - bg.br * 2.0]], red, Math.max(3, bg.br * 0.08), { taper: 0.1, jit: 0.8 });
    }
    if (g) {
      const sy = g.ty + g.tryy * 0.62, w = g.trx;
      paintShape(ctx, rng, [[D.hcx - w * 0.95, sy], [D.hcx + w * 0.95, sy], [D.hcx + w * 0.55, sy + g.tryy * 0.42], [D.hcx - w * 0.55, sy + g.tryy * 0.42]],
                 red, { n: 5, szMul: 0.6, drift: 0.04 });
    }
    function by0(q) { return q.by + q.br * 0.25; }
  }

  // ---- 48 2011 the accordion -------------------------------------------
  function hwOneBrownCurls(h) { wHairMass(h, hx('#5a3a22'), { up: 0.3, rx: 1.35, ry: 1.0, lobes: 14, mag: 0.17 }); wHairSides(h, hx('#5a3a22'), 1.3, { w: 1.28 }); }
  function onesBodyHawaiian(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const shirt = D.robeC || hx('#e05a3a');
    wClip(b, () => {
      for (let k = 0; k < 14; k++) {
        const fx = D.hcx + rng.r(-b.shWl, b.shWr), fy = b.jawY + rng.r(60, 700), fr = rng.r(18, 34);
        for (let p = 0; p < 5; p++) fillPts(ctx, blob(rng, fx + Math.cos(p / 5 * Math.PI * 2) * fr * 0.7, fy + Math.sin(p / 5 * Math.PI * 2) * fr * 0.7, fr * 0.45, fr * 0.45, 8, 0.1), rng.chance(0.5) ? hx('#f0e060') : hx('#f8f4e8'));
        dot(ctx, fx, fy, fr * 0.28, hx('#c8342c'));
        for (let p = 0; p < 3; p++) fillPts(ctx, blob(rng, fx + rng.r(-fr, fr), fy + rng.r(-fr, fr), fr * 0.6, fr * 0.25, 8, 0.15, rng.r(-1, 1)), hx('#2a7a3a'));
      }
    });
    wShirtV(b, lift(shirt, 0.6), 110, D.neckW * 0.4);
  }
  function onesFrontAccordion(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    const ay = Math.min(880, cy + D.hry * 1.85 * s), w = Math.max(150, D.hrx * 1.5 * s);
    const bellows = [[cx - w * 0.5, ay - 70], [cx + w * 0.5, ay - 90], [cx + w * 0.5, ay + 90], [cx - w * 0.5, ay + 70]];
    paintShape(ctx, rng, bellows, hx('#c82a2a'), { n: 6, szMul: 0.7, drift: 0.04 });
    for (let k = 0; k < 9; k++) {
      const t = (k + 0.5) / 9;
      ctx.globalAlpha = 0.8;
      ribbon(ctx, rng, [[cx - w * 0.5 + t * w, ay - 70 - t * 20], [cx - w * 0.5 + t * w, ay + 70 + t * 20]], k % 2 ? hx('#f4f0e6') : hx('#1a1414'), 5, { taper: 0.05, jit: 0.6 });
    }
    ctx.globalAlpha = 1;
    [-1, 1].forEach(sd => {
      const bx = cx + sd * w * 0.62;
      const box = [[bx - 26, ay - 100], [bx + 26, ay - 100], [bx + 26, ay + 100], [bx - 26, ay + 100]];
      paintShape(ctx, rng, box, hx('#1a1a1e'), { n: 4, szMul: 0.55 });
      if (sd > 0) for (let k = 0; k < 8; k++) fillPts(ctx, [[bx - 18, ay - 88 + k * 22], [bx + 2, ay - 88 + k * 22], [bx + 2, ay - 72 + k * 22], [bx - 18, ay - 72 + k * 22]], k % 3 === 1 ? hx('#1a1a1e') : hx('#f4f4f0'));
      else for (let k = 0; k < 12; k++) dot(ctx, bx + rng.r(-12, 12), ay - 80 + k * 15, 4, hx('#f4f4f0'));
      shadowEdge(ctx, rng, box, mix(line, hx('#1a1a1e'), 0.4), 3, { p: 0.4 });
      wPaw(env, bx, ay - 110, Math.max(20, D.hrx * 0.2 * s));
    });
    shadowEdge(ctx, rng, bellows, mix(line, hx('#c82a2a'), 0.4), 4, { p: 0.5 });
  }

  // ---- 49 1863 the stovepipe -------------------------------------------
  function hwOneStovepipe(h) {
    wHairSides(h, hx('#2a2020'), 0.75, { w: 1.1 });
    wTopHat(h, hx('#141216'), { brow: 0.55, h: 1.75, w: 0.88, flare: 1.04, brim: 1.3, band: hx('#2e2a2c') });
  }
  function ewOneChinBeard(h) { wBeard(h, 'chin', hx('#1e1614'), { len: 0.36, w: 0.96 }); }
  function onesBodyFrockCoat(b) {
    wShirtV(b, hx('#f4f0e6'), 180, b.D.neckW * 0.5);
    wBowTie(b, hx('#141216'), { y: 60, w: 0.58 });
    wLapels(b, sink(b.D.robeC || hx('#1a1a1e'), 0.2), { w: 0.95, len: 360 });
  }

  // ---- 50 1776 the general ---------------------------------------------
  function hwOnePowderedWig(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const wig = hx('#ece6da');
    wHairCap(h, wig, { top: 0.80, brow: 0.50, w: 1.06, strands: 5 });
    // side rolls: two sausage curls above each ear
    [-1, 1].forEach(sd => {
      for (let k = 0; k < 2; k++) {
        const rx = D.hcx + sd * D.hrx * 0.98, ry = D.hcy - D.hry * 0.2 + k * D.hry * 0.26;
        const roll = blob(rng, rx, ry, D.hrx * 0.30, D.hry * 0.12, 12, 0.08);
        paintShape(ctx, rng, roll, wig, { n: 3, szMul: 0.55 });
        shadowEdge(ctx, rng, roll, mix(h.line, wig, 0.4), 3, { p: 0.5 });
      }
    });
    // the queue with a black ribbon, off one shoulder
    ribbon(ctx, rng, [[D.hcx + D.hrx * 0.7, D.hcy + D.hry * 0.1], [D.hcx + D.hrx * 0.85, D.hcy + D.hry * 0.9]], wig, D.hrx * 0.12, { taper: 0.3, jit: 1 });
    ribbon(ctx, rng, [[D.hcx + D.hrx * 0.72, D.hcy + D.hry * 0.5], [D.hcx + D.hrx * 1.0, D.hcy + D.hry * 0.62]], hx('#1a1a1e'), 6, { taper: 0.2, jit: 0.6 });
  }
  function onesBodyBlueCoat(b) {
    const D = b.D;
    wShirtV(b, hx('#f4f0e6'), 200, D.neckW * 0.45);
    wRuff(b, hx('#f4f0e6'), { y: 40, w: 0.5, n: 3, r: 0.22 });
    wLapels(b, hx('#e8d8b0'), { w: 0.9, len: 340 });
    wButtons(b, hx('#d8b040'), 5, { y0: 110, gap: 90, r: 10, x: -D.neckW * 0.55 });
    wButtons(b, hx('#d8b040'), 5, { y0: 110, gap: 90, r: 10, x: D.neckW * 0.55 });
    wEpaulettes(b, hx('#d8b040'));
  }
  function onesBehindRiver(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    wBackFill(env, hx('#8a9ab0'), -20, 560, 0.8);
    wBackFill(env, hx('#4a6080'), 540, 1020, 0.95);
    // ice slabs on the water
    for (let k = 0; k < 9; k++) {
      const ix = rng.r(20, 980), iy = rng.r(600, 980), iw = rng.r(50, 140), ih = rng.r(14, 30);
      const slab = [[ix - iw, iy], [ix + iw, iy - 6], [ix + iw * 0.8, iy + ih], [ix - iw * 0.9, iy + ih + 4]];
      paintShape(ctx, rng, slab, hx('#e8ecf0'), { n: 3, szMul: 0.6 });
    }
    // the bow of the boat under the figure, a dark hull rising to a point
    const sd = D.headSX < 500 ? 1 : -1;
    const hull = [[D.headSX - sd * 420, 1020], [D.headSX + sd * 300, 1020], [D.headSX + sd * 380, 860], [D.headSX + sd * 200, 870], [D.headSX - sd * 300, 900]];
    paintShape(ctx, rng, hull, hx('#4a3424'), { n: 7, szMul: 0.8, drift: 0.05 });
    shadowEdge(ctx, rng, hull, mix(line, hx('#4a3424'), 0.4), 6, { p: 0.5 });
    // snow in the air
    for (let k = 0; k < 40; k++) { ctx.globalAlpha = rng.r(0.4, 0.8); dot(ctx, rng.r(0, 1000), rng.r(0, 700), rng.r(2, 5), hx('#fbfbf8')); }
    ctx.globalAlpha = 1;
  }

  // ---- 51 1804 the small emperor ---------------------------------------
  function hwOneBicorne(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const black = hx('#141216');
    wHairCap(h, hx('#3a2a20'), { top: 0.76, brow: 0.52, w: 1.0, strands: 4 });
    const y0 = wBrowY(D, 0.56);
    let hat = [[D.hcx - D.hrx * 1.75, y0 - D.hry * 0.55], [D.hcx - D.hrx * 1.1, y0 - D.hry * 0.95], [D.hcx, y0 - D.hry * 0.72],
               [D.hcx + D.hrx * 1.1, y0 - D.hry * 0.95], [D.hcx + D.hrx * 1.75, y0 - D.hry * 0.55], [D.hcx + D.hrx * 1.0, y0 + D.hry * 0.02], [D.hcx - D.hrx * 1.0, y0 + D.hry * 0.02]];
    hat = smoothPts(resample(hat, true, 8), true, 1);
    paintShape(ctx, rng, hat, black, { under: 0.92, n: 9, szMul: 0.8, drift: 0.04 });
    // the tricolour cockade
    dot(ctx, D.hcx + D.hrx * 0.5, y0 - D.hry * 0.5, D.hrx * 0.13, hx('#c8202a'));
    dot(ctx, D.hcx + D.hrx * 0.5, y0 - D.hry * 0.5, D.hrx * 0.09, hx('#f4f0e6'));
    dot(ctx, D.hcx + D.hrx * 0.5, y0 - D.hry * 0.5, D.hrx * 0.05, hx('#2a3a8a'));
    shadowEdge(ctx, rng, hat, mix(h.line, black, 0.3), Math.max(3.5, D.lineW * 0.7), { p: 0.5 });
  }
  function onesBodyEmperor(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    wShirtV(b, hx('#f4f0e6'), 160, D.neckW * 0.42);
    wLapels(b, hx('#f4f0e6'), { w: 0.8, len: 260 });
    wSash(b, hx('#c8202a'), 1, { w: 0.34 });
    wEpaulettes(b, hx('#d8b040'));
    // the tucked paw: a fur blob disappearing into the coat opening
    const px = D.hcx - D.neckW * 0.2, py = b.jawY + 330;
    const paw = blob(rng, px, py, D.neckW * 0.42, D.neckW * 0.3, 12, 0.1, 0.4);
    paintShape(ctx, rng, paw, b.coat, { n: 4, szMul: 0.55 });
    shadowEdge(ctx, rng, paw, mix(b.line, b.coat, 0.3), 4, { p: 0.5 });
    ctx.globalAlpha = 0.8;
    ribbon(ctx, rng, [[px + D.neckW * 0.1, py - D.neckW * 0.3], [px + D.neckW * 0.4, py + D.neckW * 0.35]], sink(D.robeC || hx('#1c2a4a'), 0.3), 8, { taper: 0.2, jit: 0.8 });
    ctx.globalAlpha = 1;
  }

  // ---- 52 1951 the wild hair -------------------------------------------
  function hwOneWildWhite(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const white = hx('#ecebe6');
    // J 2026-09-02: one big soft white cloud of hair, flyaways up and to
    // the sides, nothing below the ear line
    const m = wHairMass(h, white, { up: 0.62, rx: 1.42, ry: 1.12, lobes: 9, mag: 0.26 });
    for (let k = 0; k < 14; k++) {
      const a = Math.PI * (1.08 + k / 13 * 0.84) + rng.r(-0.06, 0.06);
      const x0 = D.hcx + Math.cos(a) * D.hrx * 1.15, y0 = D.hcy - D.hry * 0.62 + Math.sin(a) * D.hry * 0.9;
      ctx.globalAlpha = 0.85;
      ribbon(ctx, rng, [[x0 - Math.cos(a) * D.hrx * 0.2, y0 - Math.sin(a) * D.hry * 0.2],
                        [x0 + Math.cos(a) * D.hrx * rng.r(0.3, 0.55), y0 + Math.sin(a) * D.hry * rng.r(0.3, 0.6)]],
             k % 3 ? white : sink(white, 0.12), D.hrx * rng.r(0.10, 0.16), { taper: 0.45, wob: 0.4, jit: 1.6, end: 0.2 });
    }
    ctx.globalAlpha = 1;
    void m;
  }
  function ewOneWhiteWalrus(h) { wMustache(h, 'walrus', hx('#dcdad4'), { w: 0.36 }); }
  function onesFrontTongue(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    const ty = cy + D.hry * 0.86 * s, tw = Math.max(26, D.hrx * 0.24 * s), tl = Math.max(50, D.hry * 0.45 * s);
    const tongue = [[cx - tw, ty - tl * 0.1], [cx + tw, ty - tl * 0.1], [cx + tw * 0.9, ty + tl * 0.7], [cx, ty + tl], [cx - tw * 0.9, ty + tl * 0.7]];
    const ts = smoothPts(resample(tongue, true, 6), true, 1);
    paintShape(ctx, rng, ts, hx('#e87a8a'), { n: 5, szMul: 0.6, drift: 0.05 });
    ctx.globalAlpha = 0.5;
    ribbon(ctx, rng, [[cx, ty], [cx + 2, ty + tl * 0.85]], sink(hx('#e87a8a'), 0.3), 4, { taper: 0.3, jit: 0.6 });
    ctx.globalAlpha = 1;
    shadowEdge(ctx, rng, ts, mix(line, hx('#e87a8a'), 0.4), 3.5, { p: 0.5 });
  }

  // ---- 53 1940 the bowler ----------------------------------------------
  function hwOneBowler(h) { wDome(h, hx('#141216'), { brow: 0.58, h: 0.78, w: 0.98, brim: 1.32, brimH: 0.09, band: hx('#2a2628'), sag: 0.04 }); }
  function onesBodyOvercoat(b) {
    wShirtV(b, hx('#f4f0e6'), 150, b.D.neckW * 0.44);
    wBowTie(b, hx('#1c2a5a'), { y: 54, w: 0.6, dots: hx('#f4f0e6') });
    wLapels(b, sink(b.D.robeC || hx('#1c1c22'), 0.15), { w: 1.0, len: 380 });
  }
  function onesFrontCigarV(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    // the V: a paw raised beside the head, two toes up
    const vx = cx + sd * D.hrx * 1.45 * s, vy = cy + D.hry * 0.3 * s;
    wArm(env, vx, vy + D.hry * 0.3 * s, Math.max(16, D.hrx * 0.24 * s));
    const pr = Math.max(18, D.hrx * 0.24 * s);
    wPaw(env, vx, vy, pr);
    [-0.35, 0.35].forEach(k => ribbon(ctx, rng, [[vx + k * pr * 1.1, vy - pr * 0.4], [vx + k * pr * 1.8, vy - pr * 1.9]], env.coat, pr * 0.42, { taper: 0.3, jit: 0.8 }));
    // THE CIGAR (J 2026-09-02): fat, dark, lit, jammed in the corner of
    // the red mouth, drawn last so nothing covers it; a curl of smoke
    const mx = cx - sd * D.hrx * 0.10 * s, my = cy + D.hry * 0.60 * s;
    const cl = Math.max(60, D.hrx * 0.95 * s), cw = Math.max(12, D.hrx * 0.16 * s);
    ribbon(ctx, rng, [[mx, my], [mx - sd * cl * 0.5, my + cl * 0.12], [mx - sd * cl, my + cl * 0.20]], hx('#3a2414'), cw, { taper: 0.02, wob: 0.08, jit: 0.6, end: 0.9 });
    ribbon(ctx, rng, [[mx - sd * cl * 0.62, my + cl * 0.10], [mx - sd * cl * 0.72, my + cl * 0.15]], hx('#d8b04a'), cw * 0.9, { taper: 0.05, jit: 0.4 });
    dot(ctx, mx - sd * cl, my + cl * 0.20, cw * 0.5, hx('#f06a2a'));
    dot(ctx, mx - sd * cl, my + cl * 0.20, cw * 0.28, hx('#f8d060'));
    spray(ctx, rng, mx - sd * cl * 1.15, my - cl * 0.5, cl * 0.6, hx('#d8d8d0'), 0.6, { a: 0.28, spread: 0.6, ely: 1.8 });
    void line;
  }

  // ---- 54 1930 the round glasses ---------------------------------------
  function ewOneWireRounds(h) { wGlasses(h, { frame: hx('#3a3630'), r: 1.5, minR: 0.15, wMul: 0.08, wMin: 2.6 }); }
  function onesBodyShawl(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const white = D.robeC || hx('#f4efe4');
    wClip(b, () => {
      // one shoulder bare: skin on the right, the cloth crossing from the left
      paintShape(ctx, rng, [[D.hcx, b.jawY + 10], [D.hcx + b.shWr, b.jawY + 10], [D.hcx + b.shWr, b.jawY + 400], [D.hcx + D.neckW * 0.3, b.jawY + 420]], b.coat, { n: 5, szMul: 0.65 });
      ribbon(ctx, rng, [[D.hcx - b.shWl * 0.9, b.jawY + 60], [D.hcx + D.neckW * 0.2, b.jawY + 300], [D.hcx + b.shWr * 0.9, b.jawY + 560]], sink(white, 0.06), D.neckW * 0.9, { taper: 0.05, wob: 0.2, jit: 1.5 });
      for (let k = 0; k < 5; k++) { ctx.globalAlpha = 0.25; ribbon(ctx, rng, [[D.hcx - b.shWl * 0.8 + k * 30, b.jawY + 80 + k * 10], [D.hcx + b.shWr * 0.8 - k * 10, b.jawY + 560 - k * 20]], sink(white, 0.3), 3, { taper: 0.3, jit: 1 }); }
      ctx.globalAlpha = 1;
    });
  }
  function onesFrontStaff(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const sx = Math.max(80, Math.min(920, cx + sd * D.hrx * 1.5 * s));
    wStick(env, sx, 1010, sx + rng.r(-6, 6), Math.max(40, cy - D.hry * 1.2 * s), hx('#8a6a40'), Math.max(10, D.hrx * 0.08 * s));
    const gy = cy + D.hry * 1.1 * s;
    wArm(env, sx, gy, Math.max(22, D.hrx * 0.22 * s));
    wPaw(env, sx, gy, Math.max(24, D.hrx * 0.22 * s));
    void ctx;
  }

  // ---- 55 1953 the coronation ------------------------------------------
  function hwOneGreyCurls(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const grey = hx('#b8b0a8');
    for (let k = 0; k < 9; k++) {
      const t = k / 8 * 2 - 1;
      const cx = D.hcx + t * D.hrx * 1.0, cy = D.hcy - D.hry * 0.62 + Math.abs(t) * D.hry * 0.28;
      paintShape(ctx, rng, blob(rng, cx, cy, D.hrx * 0.2, D.hry * 0.16, 12, 0.14), grey, { n: 3, szMul: 0.55 });
    }
  }
  function onesBodyRoyalCoat(b) {
    const D = b.D;
    wButtons(b, hx('#f4f0e6'), 4, { y0: 130, gap: 100, r: 10 });
    // three strands of pearls
    const ctx = b.ctx, rng = b.rng;
    for (let k = 0; k < 3; k++) {
      const ry = 50 + k * 26, n = 12 + k * 3;
      for (let j = 0; j <= n; j++) {
        const t = j / n * 2 - 1;
        dot(ctx, D.hcx + t * D.neckW * 0.7, b.jawY + 20 + Math.sin((t + 1) / 2 * Math.PI) * ry, 7, hx('#f8f4ea'));
      }
    }
    void rng;
  }
  function onesFrontCorgi(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    // the handbag on the arm
    const bx = cx + sd * D.hrx * 1.35 * s, by = Math.min(900, cy + D.hry * 2.0 * s);
    wArm(env, bx, by - 70, Math.max(22, D.hrx * 0.22 * s));
    const bag = [[bx - 48, by - 30], [bx + 48, by - 30], [bx + 54, by + 40], [bx - 54, by + 40]];
    const bs = smoothPts(resample(bag, true, 6), true, 1);
    paintShape(ctx, rng, bs, hx('#1a1a1e'), { n: 5, szMul: 0.6 });
    ribbon(ctx, rng, [[bx - 30, by - 30], [bx, by - 78], [bx + 30, by - 30]], hx('#1a1a1e'), 6, { taper: 0.1, jit: 0.6 });
    dot(ctx, bx, by - 22, 6, hx('#d8b040'));
    shadowEdge(ctx, rng, bs, mix(line, hx('#1a1a1e'), 0.5), 3, { p: 0.5 });
    wPaw(env, bx, by - 72, Math.max(22, D.hrx * 0.2 * s));
    // the corgi, sitting at the foot on the other side, looking up
    const kx = Math.max(110, Math.min(890, cx - sd * 300)), ky = 900;
    wSmallBeast(env, kx, ky, 62, hx('#d8904a'), { sd: sd, headC: hx('#d8904a'), muzzle: hx('#f8f4ea') });
    fillPts(ctx, blob(rng, kx - sd * 20, ky + 40, 40, 22, 10, 0.1), hx('#f8f4ea'));
  }

  // ---- 56 1912 the rough rider -----------------------------------------
  function hwOneSafari(h) { wBrimHat(h, hx('#b8a070'), { brow: 0.56, h: 0.68, w: 0.9, brim: 1.7, band: hx('#6a4a30'), bandW: 0.08 }); }
  function ewOnePinceNez(h) {
    wGlasses(h, { frame: hx('#c8a040'), r: 1.2, minR: 0.12, wMul: 0.07, wMin: 2.4 });
    wMustache(h, 'thick', hx('#4a3020'), { w: 0.40 });
    const ctx = h.ctx, rng = h.rng, D = h.D;
    ribbon(ctx, rng, [[D.hcx + h.exo * 1.3, h.eyy], [D.hcx + D.hrx * 1.05, D.hcy + D.hry * 0.3], [D.hcx + D.hrx * 0.9, D.hcy + D.hry * 0.9]], hx('#1a1a1e'), 2.2, { taper: 0.05, wob: 0.3, jit: 0.8 });
  }
  function onesBodySafariJacket(b) {
    const D = b.D;
    wShirtV(b, hx('#e8e0c8'), 120, D.neckW * 0.4);
    wTie(b, hx('#4a3020'), 160);
    wButtons(b, hx('#6a4a30'), 4, { y0: 200, gap: 90, r: 8 });
    const ctx = b.ctx, rng = b.rng;
    [-1, 1].forEach(sd => {
      const px = D.hcx + sd * D.neckW * 0.9, py = b.jawY + 250;
      const pocket = [[px - 40, py - 30], [px + 40, py - 30], [px + 36, py + 50], [px - 36, py + 50]];
      paintShape(ctx, rng, pocket, sink(D.robeC || hx('#a89060'), 0.1), { n: 3, szMul: 0.5 });
      shadowEdge(ctx, rng, pocket, mix(b.line, D.robeC || hx('#a89060'), 0.35), 3, { p: 0.5 });
    });
  }

  // ---- 57 1961 the sailing sweater -------------------------------------
  function hwOneSidePart(h) { wHairCap(h, hx('#6a4a2c'), { top: 0.92, brow: 0.50, w: 1.04, part: 1, strands: 7, n: 9 }); }
  function ewOneDarkSquares(h) { wGlasses(h, { frame: hx('#1a1a1e'), lens: hx('#1c1c22'), lensA: 0.88, square: true, r: 1.5, minR: 0.16 }); }
  function onesBodyCrewneck(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const navy = D.robeC || hx('#1c2a48');
    wClip(b, () => {
      ribbon(ctx, rng, [[D.hcx - D.neckW * 0.7, b.jawY + 30], [D.hcx, b.jawY + 70], [D.hcx + D.neckW * 0.7, b.jawY + 30]], lift(navy, 0.25), 18, { taper: 0.1, wob: 0.2, jit: 1 });
      for (let k = 0; k < 6; k++) { ctx.globalAlpha = 0.18; ribbon(ctx, rng, [[D.hcx - b.shWl, b.jawY + 120 + k * 80], [D.hcx + b.shWr, b.jawY + 128 + k * 80]], lift(navy, 0.4), 4, { taper: 0.2, jit: 1 }); }
      ctx.globalAlpha = 1;
    });
  }
  function onesBehindSailboat(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    wBackFill(env, hx('#a8cce8'), -20, 620, 0.8);
    wBackFill(env, hx('#2a68a8'), 600, 1020, 0.9);
    for (let k = 0; k < 8; k++) { ctx.globalAlpha = 0.6; ribbon(ctx, rng, [[rng.r(-20, 800), 640 + k * 40], [rng.r(200, 1020), 646 + k * 40]], hx('#e8f4ff'), rng.r(3, 7), { taper: 0.5, wob: 0.4, jit: 1.5 }); }
    ctx.globalAlpha = 1;
    const sd = D.headSX < 500 ? 1 : -1;
    const bx = sd > 0 ? 760 : 240, by = 640;
    const hull = [[bx - 150, by], [bx + 150, by], [bx + 120, by + 50], [bx - 120, by + 50]];
    paintShape(ctx, rng, hull, hx('#f4f0e6'), { n: 5, szMul: 0.6 });
    wStick(env, bx, by, bx, by - 330, hx('#6a4a30'), 8);
    paintShape(ctx, rng, [[bx + 4, by - 320], [bx + 130, by - 20], [bx + 4, by - 20]], hx('#fbfaf6'), { n: 5, szMul: 0.6 });
    paintShape(ctx, rng, [[bx - 4, by - 280], [bx - 100, by - 20], [bx - 4, by - 20]], hx('#f0ecdc'), { n: 4, szMul: 0.6 });
    shadowEdge(ctx, rng, hull, mix(line, hx('#8a8070'), 0.5), 4, { p: 0.5 });
  }

  // ---- 58 1969 the double V --------------------------------------------
  function hwOneWidowsPeak(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const cap = wHairCap(h, hx('#2a2220'), { top: 0.78, brow: 0.62, w: 1.02, strands: 5 });
    // the peak dives down the middle of the forehead
    paintShape(ctx, rng, [[D.hcx - D.hrx * 0.35, D.hcy - D.hry * 0.62], [D.hcx + D.hrx * 0.35, D.hcy - D.hry * 0.62], [D.hcx, D.hcy - D.hry * 0.36]], hx('#2a2220'), { n: 3, szMul: 0.5 });
    void cap;
  }
  function onesBodyDarkSuit(b) {
    wShirtV(b, hx('#f4f0e6'), 190, b.D.neckW * 0.48);
    wTie(b, hx('#7a2a3a'), 260);
    wLapels(b, sink(b.D.robeC || hx('#22242c'), 0.2), { w: 0.95, len: 360 });
  }
  function onesFrontDoubleV(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    [-1, 1].forEach(sd => {
      const vx = cx + sd * D.hrx * 1.75 * s, vy = cy - D.hry * 0.5 * s;
      drawStroke(ctx, rng, [[cx + sd * D.hrx * 0.9 * s, cy + D.hry * 1.5 * s], [cx + sd * D.hrx * 1.9 * s, cy + D.hry * 0.9 * s], [vx, vy + D.hry * 0.3 * s]],
                 { color: D.robeC || hx('#22242c'), w: Math.max(30, D.hrx * 0.3 * s), fade: 0.5, grain: 0.24, press: 0.3 });
      const pr = Math.max(24, D.hrx * 0.22 * s);
      wPaw(env, vx, vy, pr);
      [-0.35, 0.35].forEach(k => ribbon(ctx, rng, [[vx + k * pr * 1.1, vy - pr * 0.4], [vx + k * pr * 1.8, vy - pr * 1.9]], env.coat, pr * 0.42, { taper: 0.3, jit: 0.8 }));
    });
    // five o'clock shadow
    spray(ctx, rng, cx, cy + D.hry * 0.7 * s, D.hrx * 0.6 * s, hx('#3a3230'), 0.5, { a: 0.14, spread: 0.6 });
  }

  // ---- 59 1752 the kite ------------------------------------------------
  function hwOneBaldLong(h) {
    const D = h.D;
    wHairSides(h, hx('#b8b0a4'), 1.1, { w: 1.2 });
    // a fringe of hair round the back, the crown bare
    const ctx = h.ctx, rng = h.rng;
    ribbon(ctx, rng, [[D.hcx - D.hrx * 1.0, D.hcy - D.hry * 0.3], [D.hcx - D.hrx * 0.9, D.hcy - D.hry * 0.62], [D.hcx + D.hrx * 0.9, D.hcy - D.hry * 0.62], [D.hcx + D.hrx * 1.0, D.hcy - D.hry * 0.3]], hx('#b8b0a4'), D.hry * 0.14, { taper: 0.4, wob: 0.3, jit: 1.2 });
  }
  function ewOneBifocals(h) {
    wGlasses(h, { frame: hx('#3a3630'), r: 1.3, minR: 0.13, wMul: 0.08, wMin: 2.6 });
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const gr = Math.max(D.eyeR * 1.3, D.hrx * 0.13);
    [-1, 1].forEach(sd => ribbon(ctx, rng, [[D.hcx + sd * h.exo - gr * 0.9, h.eyy + gr * 0.25], [D.hcx + sd * h.exo + gr * 0.9, h.eyy + gr * 0.25]], hx('#3a3630'), 2.2, { taper: 0.1, jit: 0.4 }));
  }
  function onesBehindStorm(env) {
    const ctx = env.ctx, rng = env.rng;
    wBackFill(env, hx('#2a3048'), -20, 1020, 0.6);
    for (let k = 0; k < 3; k++) {
      const x0 = rng.r(100, 900);
      const bolt = [[x0, 0], [x0 - 40, 140], [x0 + 20, 150], [x0 - 50, 330]];
      ctx.globalAlpha = 0.9;
      ribbon(ctx, rng, bolt, hx('#f4f0c8'), 7, { taper: 0.4, jit: 0.8 });
    }
    ctx.globalAlpha = 1;
    for (let k = 0; k < 60; k++) { ctx.globalAlpha = 0.35; ribbon(ctx, rng, [[rng.r(0, 1000), rng.r(0, 900)], [rng.r(0, 1000) - 20, rng.r(0, 900) + 50]], hx('#c8d0e0'), 2, { taper: 0.5, jit: 0.4 }); }
    ctx.globalAlpha = 1;
  }
  function onesFrontKite(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const kx = sd > 0 ? 830 : 170, ky = 150;
    const gx = cx + sd * D.hrx * 1.3 * s, gy = cy + D.hry * 0.9 * s;
    // the string, with the key tied a third of the way up
    ribbon(ctx, rng, [[gx, gy], [(gx + kx) / 2 + sd * 30, (gy + ky) / 2 + 40], [kx, ky + 90]], hx('#e8e4d8'), 3, { taper: 0.05, wob: 0.15, jit: 0.8 });
    const keyX = gx + (kx - gx) * 0.32, keyY = gy + (ky - gy) * 0.32 + 30;
    ribbon(ctx, rng, [[keyX, keyY], [keyX, keyY + 44]], hx('#c8a040'), 6, { taper: 0.1, jit: 0.4 });
    drawStroke(ctx, rng, [[keyX - 12, keyY - 8], [keyX + 12, keyY - 8], [keyX + 12, keyY + 8], [keyX - 12, keyY + 8], [keyX - 12, keyY - 8]], { color: hx('#c8a040'), w: 5, fade: 0.4, grain: 0.2, press: 0.25 });
    ribbon(ctx, rng, [[keyX, keyY + 36], [keyX + 10, keyY + 36]], hx('#c8a040'), 5, { taper: 0.1, jit: 0.4 });
    // the kite
    const kite = [[kx, ky - 90], [kx + 70, ky], [kx, ky + 90], [kx - 70, ky]];
    paintShape(ctx, rng, kite, hx('#e8d8b0'), { n: 5, szMul: 0.6, drift: 0.05 });
    ribbon(ctx, rng, [[kx, ky - 90], [kx, ky + 90]], hx('#6a4a30'), 4, { taper: 0.1, jit: 0.5 });
    ribbon(ctx, rng, [[kx - 70, ky], [kx + 70, ky]], hx('#6a4a30'), 4, { taper: 0.1, jit: 0.5 });
    shadowEdge(ctx, rng, kite, mix(line, hx('#e8d8b0'), 0.45), 3.5, { p: 0.5 });
    for (let k = 0; k < 3; k++) fillPts(ctx, blob(rng, kx + rng.r(-12, 12), ky + 120 + k * 40, 14, 8, 8, 0.2), hx('#c8342c'));
    wArm(env, gx, gy, Math.max(22, D.hrx * 0.22 * s));
    wPaw(env, gx, gy, Math.max(24, D.hrx * 0.22 * s));
  }

  // ---- 60 1789 the wig with a ship in it -------------------------------
  function hwOneShipWig(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    const r = wTallWig(h, hx('#f0ece4'), { h: 2.4, lean: 0.04 });
    const sy = r.top + D.hry * 0.55, sx = D.hcx + D.hrx * 0.1;
    const hull = [[sx - D.hrx * 0.5, sy], [sx + D.hrx * 0.5, sy], [sx + D.hrx * 0.4, sy + D.hry * 0.18], [sx - D.hrx * 0.4, sy + D.hry * 0.18]];
    paintShape(ctx, rng, hull, hx('#5a3a24'), { n: 4, szMul: 0.55 });
    [-0.25, 0.05, 0.3].forEach((t, i) => {
      const mx = sx + t * D.hrx;
      ribbon(ctx, rng, [[mx, sy], [mx, sy - D.hry * (0.5 + (i === 1 ? 0.15 : 0))]], hx('#3a2418'), 3, { taper: 0.1, jit: 0.4 });
      paintShape(ctx, rng, [[mx + 2, sy - D.hry * (0.48 + (i === 1 ? 0.15 : 0))], [mx + D.hrx * 0.16, sy - D.hry * 0.1], [mx + 2, sy - D.hry * 0.08]], hx('#fbfaf4'), { n: 3, szMul: 0.5 });
    });
    ribbon(ctx, rng, [[sx - D.hrx * 0.4, sy + D.hry * 0.04], [sx + D.hrx * 0.4, sy + D.hry * 0.04]], hx('#c8a040'), 2.5, { taper: 0.1, jit: 0.4 });
    // a blue ribbon at the base
    ribbon(ctx, rng, [[D.hcx - D.hrx * 0.9, D.hcy - D.hry * 0.62], [D.hcx, D.hcy - D.hry * 0.7], [D.hcx + D.hrx * 0.9, D.hcy - D.hry * 0.62]], hx('#7ab0e0'), D.hry * 0.08, { taper: 0.1, wob: 0.2, jit: 1 });
  }
  function onesBodyGownPannier(b) {
    const ctx = b.ctx, rng = b.rng, D = b.D;
    const silk = D.robeC || hx('#d8b8d0');
    wRuff(b, hx('#fbf8f2'), { y: 36, w: 0.7, n: 5, r: 0.2 });
    wClip(b, () => {
      // a stomacher with bows down the front
      paintShape(ctx, rng, [[D.hcx - D.neckW * 0.5, b.jawY + 80], [D.hcx + D.neckW * 0.5, b.jawY + 80], [D.hcx + D.neckW * 0.25, b.jawY + 520], [D.hcx - D.neckW * 0.25, b.jawY + 520]], lift(silk, 0.3), { n: 4, szMul: 0.6 });
      for (let k = 0; k < 4; k++) {
        const by = b.jawY + 140 + k * 100;
        [-1, 1].forEach(sd => fillPts(ctx, blob(rng, D.hcx + sd * 22, by, 22, 12, 10, 0.15, sd * 0.3), hx('#7ab0e0')));
        dot(ctx, D.hcx, by, 7, sink(hx('#7ab0e0'), 0.2));
      }
    });
  }
  function onesFrontCake(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const px = cx + sd * D.hrx * 1.5 * s, py = cy + D.hry * 1.3 * s;
    wArm(env, px, py + 20, Math.max(22, D.hrx * 0.22 * s));
    // a plate, then the wedge, layers showing on the cut face
    fillPts(ctx, blob(rng, px, py + 34, 70, 14, 14, 0.06), hx('#f4f4f0'));
    const wedge = [[px - 60, py + 30], [px + 60, py + 30], [px + 20, py - 50], [px - 20, py - 50]];
    paintShape(ctx, rng, wedge, hx('#f8e8c8'), { n: 4, szMul: 0.55 });
    [0.25, 0.55].forEach(t => ribbon(ctx, rng, [[px - 60 + t * 40, py + 30 - t * 80], [px + 60 - t * 40, py + 30 - t * 80]], hx('#e86a8a'), 8, { taper: 0.05, jit: 0.6 }));
    paintShape(ctx, rng, [[px - 22, py - 50], [px + 22, py - 50], [px + 16, py - 66], [px - 16, py - 66]], hx('#f4a8c0'), { n: 3, szMul: 0.5 });
    dot(ctx, px, py - 72, 9, hx('#c8202a'));
    shadowEdge(ctx, rng, wedge, mix(line, hx('#f8e8c8'), 0.45), 3.5, { p: 0.5 });
    wPaw(env, px - sd * 30, py + 34, Math.max(22, D.hrx * 0.2 * s));
  }

  // ---- 61 1600 the ruff ------------------------------------------------
  function hwOneHighForehead(h) {
    const ctx = h.ctx, rng = h.rng, D = h.D;
    wHairSides(h, hx('#5a3a24'), 0.65, { w: 1.14 });
    ribbon(ctx, rng, [[D.hcx - D.hrx * 1.0, D.hcy - D.hry * 0.25], [D.hcx - D.hrx * 0.95, D.hcy - D.hry * 0.7], [D.hcx + D.hrx * 0.95, D.hcy - D.hry * 0.7], [D.hcx + D.hrx * 1.0, D.hcy - D.hry * 0.25]], hx('#5a3a24'), D.hry * 0.16, { taper: 0.4, wob: 0.3, jit: 1.2 });
    // the quill behind one ear
    ribbon(ctx, rng, [[D.hcx + D.hrx * 0.95, D.hcy], [D.hcx + D.hrx * 1.4, D.hcy - D.hry * 0.9]], hx('#f4f0e6'), D.hrx * 0.09, { taper: 0.6, jit: 0.8 });
    ribbon(ctx, rng, [[D.hcx + D.hrx * 0.95, D.hcy], [D.hcx + D.hrx * 1.4, D.hcy - D.hry * 0.9]], hx('#8a8070'), 2, { taper: 0.6, jit: 0.4 });
  }
  function ewOneGoateeThin(h) { wBeard(h, 'goatee', hx('#4a3020'), { len: 0.26 }); wMustache(h, 'pencil', hx('#4a3020')); }
  function onesBodyRuffDoublet(b) {
    wRuff(b, hx('#fbf8f2'), { y: 44, w: 1.45, n: 9, r: 0.30 });
    wButtons(b, hx('#c8a040'), 5, { y0: 180, gap: 80, r: 7 });
  }
  function onesFrontSkull(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D, line = env.line;
    const s = D.figS, cx = D.headSX, cy = D.headSY, sd = cx > 500 ? -1 : 1;
    const kx = cx + sd * D.hrx * 1.55 * s, ky = cy - D.hry * 0.1 * s, kr = Math.max(40, D.hrx * 0.42 * s);
    wArm(env, kx, ky + kr * 1.1, Math.max(22, D.hrx * 0.22 * s));
    const skull = blob(rng, kx, ky, kr, kr * 1.05, 16, 0.08);
    paintShape(ctx, rng, skull, hx('#ece6d8'), { n: 5, szMul: 0.6, drift: 0.04 });
    paintShape(ctx, rng, [[kx - kr * 0.5, ky + kr * 0.7], [kx + kr * 0.5, ky + kr * 0.7], [kx + kr * 0.4, ky + kr * 1.1], [kx - kr * 0.4, ky + kr * 1.1]], hx('#ece6d8'), { n: 3, szMul: 0.5 });
    [-0.36, 0.36].forEach(k => fillPts(ctx, blob(rng, kx + k * kr, ky - kr * 0.1, kr * 0.26, kr * 0.28, 10, 0.1), hx('#2a2420')));
    fillPts(ctx, [[kx - kr * 0.1, ky + kr * 0.35], [kx + kr * 0.1, ky + kr * 0.35], [kx, ky + kr * 0.15]], hx('#2a2420'));
    for (let k = -2; k <= 2; k++) ribbon(ctx, rng, [[kx + k * kr * 0.18, ky + kr * 0.72], [kx + k * kr * 0.18, ky + kr * 1.05]], hx('#8a8070'), 2, { taper: 0.1, jit: 0.4 });
    shadowEdge(ctx, rng, skull, mix(line, hx('#ece6d8'), 0.45), 4, { p: 0.5 });
    wPaw(env, kx, ky + kr * 1.1, Math.max(24, D.hrx * 0.22 * s));
  }

  // ---- 62 2012 the ears, in the poster palette -------------------------
