  function onesFrontPinch(env) {
    const ctx = env.ctx, rng = env.rng, D = env.D;
    const s = D.figS, cx = D.headSX, cy = D.headSY;
    [-1, 1].forEach(sd => {
      const px = cx + sd * D.hrx * 1.5 * s, py = cy + D.hry * 1.5 * s;
      drawStroke(ctx, rng, [[cx + sd * D.hrx * 0.9 * s, cy + D.hry * 1.7 * s], [px, py]], { color: D.robeC || hx('#1c2438'), w: Math.max(28, D.hrx * 0.28 * s), fade: 0.5, grain: 0.24, press: 0.3 });
      const pr = Math.max(24, D.hrx * 0.22 * s);
      wPaw(env, px, py, pr);
      // the pinch: two toes meeting at a point
      ribbon(ctx, rng, [[px - sd * pr * 0.2, py - pr * 0.5], [px + sd * pr * 0.9, py - pr * 1.1]], env.coat, pr * 0.4, { taper: 0.4, jit: 0.6 });
      ribbon(ctx, rng, [[px + sd * pr * 0.2, py + pr * 0.2], [px + sd * pr * 0.9, py - pr * 1.0]], env.coat, pr * 0.4, { taper: 0.4, jit: 0.6 });
    });
  }

  // ---- 64 1976 the steps -----------------------------------------------
