    ribbon(ctx, rng, [[px, py], [px + sd * 22, py - 14]], hx('#c8202a'), 3.5, { taper: 0.6, jit: 0.4 });
    ribbon(ctx, rng, [[px, py], [px - sd * 22, py + 14]], hx('#1a1418'), 3.5, { taper: 0.6, jit: 0.4 });
    shadowEdge(ctx, rng, box, mix(line, hx('#4a3020'), 0.4), 3, { p: 0.5 });
    wPaw(env, px - sd * 30, py + 30, Math.max(22, D.hrx * 0.2 * s));
