    [-1, 1].forEach(sd => fillPts(ctx, [[D.hcx + sd * 8 - 12, b.jawY + 170], [D.hcx + sd * 8 + 12, b.jawY + 170], [D.hcx + sd * 8 + 12, b.jawY + 212], [D.hcx + sd * 8 - 12, b.jawY + 212]], hx('#c8c8c0')));
