      const p = axis[i];
      const q = axis[Math.min(axis.length - 1, i + 1)];
      const r = axis[Math.max(0, i - 1)];
      let tx = q[0] - r[0], ty = q[1] - r[1];
      const tl = Math.hypot(tx, ty) || 1;
