    const Ly = S && typeof pencilLayerFor === 'function' ? pencilLayerFor(S, cols.base, 0.50) : null;
    if (Ly && typeof pencilSyncTransform === 'function') pencilSyncTransform(Ly, ctx);
    const cc = Ly ? Ly.ctx : ctx;
