      const i0 = Math.floor(t0 * (axis.length - 1));
      const i1 = Math.max(i0 + 3, Math.ceil(t1 * (axis.length - 1)));
      const pts = axis.slice(i0, i1 + 1).map(p => [p[0] + nx * off, p[1] + ny * off]);
