  // ==== ELEV:motif helpers end ====
  function floraPalette(nr, field, coat) {
    const out = [], names = [], used = {};
    const take = (lib, need) => {
      const L = floraShuffle(nr, lib);
      for (let i = 0; i < L.length; i++) {
        if (used[L[i][0]]) continue;
        const c = hx(L[i][1]);
        if (floraStandsOff(c, field, need) && floraStandsOff(c, coat, need)) {
          out.push(c); names.push(L[i][0]); used[L[i][0]] = 1; return true;
        }
      }
      return false;
    };
    take(FLORA_WARM, 40) || take(FLORA_WARM, 28);
    take(FLORA_COOL, 40) || take(FLORA_COOL, 28);
    take(FLORA_WARM, 36) || take(FLORA_COOL, 36);
    if (nr.f() < 0.75) take(FLORA_PALE, 40) || take(FLORA_PALE, 28);
    if (out.length < 4) take(FLORA_COOL, 28) || take(FLORA_WARM, 28);
    if (out.length < 2) {
      let c = elevComplement(field);
      c = lum(field) > 128 ? sink(c, 0.45) : lift(c, 0.45);
      out.push(c); names.push('complement');
    }
    let leaf = null;
    const G = FLORA_GREENS.map(g => hx(g[1])).filter(c => Math.abs(lum(c) - lum(field)) >= 45)
      .sort((a, b) => Math.abs(lum(b) - lum(field)) - Math.abs(lum(a) - lum(field)));
    if (G.length) leaf = G[Math.floor(nr.f() * Math.min(3, G.length))];
    if (!leaf) leaf = lum(field) > 120 ? hx('#3a1f3f') : hx('#c9b8a0');
    const dark = lum(field) < 95;
    const pales = out.map(c => lift(mix(c, hx('#f4ead3'), 0.28), 0.1));
    const shades = out.map(c => sink(c, 0.3));
    return {
      blooms: out, names: names, leaf: leaf, stem: sink(leaf, 0.22),
      graphite: dark ? mix(hx('#1a1410'), field, 0.25) : mix(hx('#1a1410'), elevComplement(field), 0.2),
      stamen: nr.f() < 0.6 ? hx('#f2d36b') : hx('#2a1e1a'),
      dark: dark ? mix(hx('#2a1e1a'), field, 0.3) : hx('#2a1e1a'),
      pales: pales, shades: shades,
    };
  }
  // the pencils: a main pencil (the first bloom colour), a shadow pencil (deeper and cooler, or a
  // brown, laid on the shadow side of every petal; on a dark ground it is a pale laid on the LIT
  // side instead, so it reads), an accent (the green, for stems and leaves), and the dark pencil
  // of the scribbled centres (a pale on dark grounds)
  function floraPencils(nr, pal, ground) {
    const main = pal.blooms[0];
    const darkG = lum(ground) < 95;
    const h = hueOf(main)[0], warm = h < 75 || h > 320;
    let shadow, mode;
    if (darkG) {
      shadow = lift(mix(main, hx('#efe6cf'), 0.35), 0.3); mode = 'light';
    } else {
      const to = nr.f() < (warm ? 0.55 : 0.3) ? hx('#4a3128') : hx('#22264f');
      shadow = mix(sink(main, 0.3), to, 0.45); mode = 'shadow';
      for (let i = 0; i < 4 && Math.abs(lum(shadow) - lum(ground)) < 30; i++) shadow = sink(shadow, 0.2);
    }
    const centre = darkG ? shadow : pal.dark;
    const pale = lift(mix(main, hx('#efe6cf'), 0.4), 0.18);
    return {
      main: main, shadow: shadow, mode: mode, accent: pal.leaf, dark: centre,
      second: pal.blooms.length > 1 ? pal.blooms[1] : null,
      pale: pale, tip: pal.pales && pal.pales[0] ? pal.pales[0] : pale,
      leafPale: lift(pal.leaf, 0.22), leafDark: sink(pal.leaf, 0.24),
    };
  }

  // ---- the pencil -----------------------------------------------------
  // one coloured-pencil stroke: a sliver that swells in the middle and thins to nothing at
  // both ends (the pressure), wavering a little off its line; pigment sits heavier in the
  // middle (a narrower core at 40% odds). One or two fills; the paper shows between strokes.
  function toilePencil(ctx, rng, x0, y0, x1, y1, col, w, a, opt) {
    opt = opt || {};
    const dx = x1 - x0, dy = y1 - y0, L = Math.hypot(dx, dy);
    if (L < 1.2) return;
    toileStrokeCount++;
    const o = { rng: rng, a: a * ctx.globalAlpha, wav: opt.wav, tip: opt.tip, core: opt.core, press: opt.press || 0 };
    const P = pencilSessionFor(ctx);
    if (P) {
      const Ly = pencilLayerFor(P, col, opt.pressure === undefined ? 0.55 : opt.pressure, opt.mode);
      if (Ly) { pencilSyncTransform(Ly, ctx); pencilStroke(Ly, x0, y0, x1, y1, w, o); return; }
    }
    pencilStrokeNow(ctx, col, x0, y0, x1, y1, w, o);
  }
  // a pencil line along a polyline: wavering, in segments whose weight varies (the hand presses
  // and lifts), with a second line laid beside it (opt.dbl = its lateral offset) over part of the
  // length; broken where it would cross the face when a face box is given
  function toilePencilLine(ctx, rng, pts, col, w, a, opt, face) {
    opt = opt || {};
    const P = resample(pts, false, opt.step || 9);
    const S = pencilSessionFor(ctx);
    const Ly = S ? pencilLayerFor(S, col, opt.pressure === undefined ? 0.6 : opt.pressure) : null;
    if (Ly) pencilSyncTransform(Ly, ctx);
    const gA = ctx.globalAlpha;
    const draw = (run, ww, aa, sideOff) => {
      if (run.length < 2) return;
      toileStrokeCount++;
      const o = { rng: rng, a: aa * gA, sideOff: sideOff, wob: w * 0.35, press: opt.press || 0 };
      if (Ly) pencilLine(Ly, run, ww, o); else pencilLineNow(ctx, col, run, ww, o);
    };
    let run = [];
    const flush = () => {
      draw(run, w, a, 0);
      if (opt.dbl && run.length >= 3) {
        const n = run.length, k0 = Math.floor(rng.r(0, 0.4) * n), k1 = Math.min(n, k0 + Math.floor(n * rng.r(0.6, 1.0)));
        draw(run.slice(k0, k1), w * 0.7, a * 0.75, opt.dbl * (rng.f() < 0.5 ? 1 : -1));
      }
      run = [];
    };
    for (let i = 0; i < P.length; i++) {
      if (face && navaHitsFace(face, P[i][0], P[i][1], w, w, 24)) flush(); else run.push(P[i]);
    }
    flush();
  }
  // a tight scribble: loops that wander around a centre, one pencil line
  function toilePencilScribble(ctx, rng, x, y, r, col, w, a, loops, loose) {
    const pts = pencilScribblePts(rng, x, y, r, loops, loose);
    toileStrokeCount++;
    const gA = ctx.globalAlpha, o = { a: a * gA };
    const S = pencilSessionFor(ctx);
    const Ly = S ? pencilLayerFor(S, col, 0.7) : null;
    if (Ly) { pencilSyncTransform(Ly, ctx); pencilScribbleInto(Ly.ctx, S.rng, pts, w, o); Ly.n++; S.strokes++; return; }
    const gco = ctx.globalCompositeOperation;
    ctx.strokeStyle = css(col); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.globalCompositeOperation = pencilModeFor(col, pencilGroundLum());
    pencilScribbleInto(ctx, pencilFreeRng(), pts, w, o);
    ctx.globalAlpha = gA; ctx.globalCompositeOperation = gco;
  }
  // a hatch bundle in a petal / leaf shape: the shape is an elongated lens from (cx,cy) along ang,
  // length L, greatest width W; n strokes, each running along the shape between two positions on
  // the axis, its lateral offset following the outline (so the bundle radiates from the base and
  // gathers at the tip), the ends ragged. opt.dense 'base'|'tip'|'even' sets where the strokes
  // crowd; opt.side +-1 keeps the strokes on one side; opt.tilt turns every stroke by that angle;
  // opt.loose: stroke lengths run 0.25-1.0 of the shape (three times the variance of the tidy
  // 0.55-1.0) and a third of the strokes escape the outline by 5-15% (the bouquet's fat bundles).
  function toilePencilBundle(ctx, rng, cx, cy, ang, L, W, n, col, w, a, opt) {
    opt = opt || {};
    const S = pencilSessionFor(ctx);
    const er = S ? S.rng : pencilFreeRng();
    const o2 = { wav: opt.wav, tip: opt.tip, core: opt.core, pressure: opt.pressure, press: 0 };
    pencilBundleGeom(rng, er, cx, cy, ang, L, W, n, opt, (x0, y0, x1, y1, wj, aj, press) => {
      o2.press = press;
      toilePencil(ctx, rng, x0, y0, x1, y1, col, w * wj * (1 + press * 0.25), a * aj * (1 + press * 0.35), o2);
    });
  }
  // the hatched paper: cream paper, then the field's colour hatched over the whole sheet at density D
