          let Lf = null;
          for (let i = 0; i < leafLib.length && !Lf; i++) if (Math.abs(lum(leafLib[i]) - lum(gnd)) >= 45) Lf = leafLib[i];
          plan.pal.leaf = Lf || (lum(gnd) > 120 ? hx('#14382a') : hx('#1f7a4a'));
