        const ey = pickE < 0.4 ? -320 : pickE < 0.8 ? 500 : 1300;
        const erx = pickE < 0.4 ? 1100 : pickE < 0.8 ? 760 : 1200, ery = pickE < 0.4 ? 720 : pickE < 0.8 ? 1000 : 640;
        voidCloud(ctx, r, ex, ey, erx, ery, tone, 0.9);
