      const word = r.pick(VOID_WORDS);
      const h = r.r(26, 36), tw = word.length * h * 0.56;
      const ink = dark ? mix(hx('#f4f2ea'), ground, 0.12) : mix(hx('#221d18'), ground, 0.14);
      const cands = room.openSide < 0 ? [[44, 958], [956 - tw, 958]] : [[956 - tw, 958], [44, 958]];
      let put = null;
      for (let i = 0; i < cands.length; i++) {
        const p = cands[i];
        if (voidHitsKeep(keep, p[0] + tw / 2, p[1] - h / 2, tw / 2, h / 2, 14)) continue;
        if (navaHitsFace(face, p[0] + tw / 2, p[1] - h / 2, tw / 2, h / 2, 20)) continue;
        put = p; break;
      }
      if (!put) { ctx.globalAlpha = gA; return; }
