    if (!arm || !arm.on || !ext) return null;
    const paint = NAVA_PAINTERS[kind];
    if (!paint) return null;
    const want = air ? arm.sky : (stage === 'front' ? arm.front : arm.behind);
    if (!want) return null;
    const crop = !!arm.crop;
    const pole = kind === 'crosspole' || kind === 'drivein';
