    const pr = P.prof, ta = Date.now();
    const img = L.ctx.getImageData(0, 0, W, H), d = img.data;
    const lut = (T && kS > 0) ? pencilKeepLUT(P, L.pressure) : null;
    const sum = new Float32Array(P.cw * P.ch);
