      ctx.beginPath(); ctx.moveTo(form.poly[0][0], form.poly[0][1]); for (let i = 1; i < form.poly.length; i++) ctx.lineTo(form.poly[i][0], form.poly[i][1]); ctx.closePath(); ctx.fill(); ctx.globalAlpha = gA;
