    slSun(env, nr, L, S, horizon, variant);
    slGround(ctx, nr, asphalt, horizon);
    // the supporting object: the low building on the closed side, stucco or dark at night
    {
      const sd = -room.openSide, bw = nr.r(280, 520), bh = nr.r(60, 140);
      const x0 = sd < 0 ? -20 : 1020 - bw, x1 = sd < 0 ? bw - 20 : 1020;
      const cream = variant === 'night' ? hx('#3a3040') : variant === 'dusk' ? mix(hx('#E3D8C3'), SL_SODIUM, 0.3) : hx(nr.pick(['#E3D8C3', '#EFEADF']));
      paintShape(ctx, nr, [[x0, horizon - bh], [x1, horizon - bh + nr.r(-8, 8)], [x1, horizon + 4], [x0, horizon + 4]], cream, { under: 0.96, n: 8, szMul: 0.9, drift: 0.04, ang: 0 });
      slShadeSide(ctx, nr, L, x0, horizon - bh, x1, horizon + 4, cream, 0.45);
      oilStick(ctx, nr, [[x0, horizon - bh], [x1, horizon - bh + nr.r(-8, 8)]], S.ink, 3.5, { dbl: 0.3, over: 10, tooth: 0.3, a: 0.8 });
      const dx = x0 + bw * nr.r(0.3, 0.7);
      const doorC = variant === 'night' ? SL_SODIUM : sink(cream, 0.6);
      paintShape(ctx, nr, [[dx - 18, horizon - bh * 0.72], [dx + 18, horizon - bh * 0.72], [dx + 18, horizon + 2], [dx - 18, horizon + 2]], doorC, { under: 0.95, n: 3, szMul: 0.5 });
      if (variant === 'night') { navaGlow(ctx, nr, dx, horizon - bh * 0.3, 50, 60, SL_SODIUM, 0.7); elevEmit(dx, horizon - bh * 0.35, 80, SL_SODIUM, 0.7); }
      elevRecord(env, { kind: 'building', x: (x0 + x1) / 2, y: horizon - bh / 2, w: bw, h: bh, base: horizon + 4, color: cream, stage: 'behind', thick: 0.7 });
      slShadowOf(env, nr, L, (x0 + x1) / 2, horizon + 4, bw * 0.9, bh, { flat: 0.12, taper: 0.9, alpha: L.a * 0.8 });
    }
    // the headline: the lit cloud in the sky (the event), else the pole and its wires
    const cloud = nr.chance(0.6);
    if (cloud) {
      const cs = nr.r(140, 240);
      const cx = S.headX !== null ? slHeadX(S, nr, cs * 0.7) : (room.openSide < 0 ? nr.r(120, 420) : nr.r(580, 880));
      const cy = S.crop ? nr.r(40, 120) : nr.r(100, Math.max(110, horizon - 260));
      if (!navaHitsFace(face, cx, cy, cs * 0.7, cs * 0.5, 20)) { navaLitCloud(ctx, nr, cx, cy, cs, P, 1); elevRecord(env, { kind: 'litcloud', x: cx, y: cy, w: cs * 1.4, h: cs, base: null, color: SL_SODIUM, stage: 'behind', thick: 0.6 }); }
      else slPole(env, nr, L, S, room.openSide < 0 ? nr.r(80, 300) : nr.r(700, 920), nr.r(40, 160), horizon, true);
    } else {
      const px = S.headX !== null ? slHeadX(S, nr, 40) : (room.openSide < 0 ? nr.r(80, 320) : nr.r(680, 920));
      if (Math.abs(px - face.x) > face.rx + 40) slPole(env, nr, L, S, px, S.crop ? -10 : nr.r(40, 200), horizon, true);
    }
    // litter as texture: few, scaled to the dog
    const litterC = variant === 'night' ? mix(S.white, asphalt, 0.4) : S.white;
    for (let k = 0, nL = nr.r(0, 5) | 0; k < nL; k++) {
      const x = nr.r(0, 1000), y = nr.r(horizon + 40, 990), r = nr.r(9, 16);
      if (navaHitsFace(face, x, y, r, r, 0)) continue;
      ctx.globalAlpha = nr.r(0.6, 0.95);
      fillPts(ctx, [[x - r, y - r * 0.4], [x + r * nr.r(0.5, 1.2), y - r * 0.6], [x + r * 0.8, y + r * 0.4], [x - r * 0.6, y + r * 0.5]], nr.chance(0.8) ? litterC : nr.pick([SL_TEAL, SL_PATCH, SL_ACID]));
    }
    ctx.globalAlpha = 1;
    slFinish(env, nr, L, S);
    env.D.navaFieldC = sky; env.D.navaVariant = variant;
