    nava: { speed: 0.7, attack: 0.25, end: 'lift', press: 0.7, pressVar: 0.15, tremor: 0.7, smooth: 2, overshoot: 8 },
    careful: { speed: 0.3, attack: 0.5, end: 'stop', press: 0.75, pressVar: 0.05, tremor: 0.4, smooth: 3, overshoot: 2 },
    none: {},
