    r.step = Math.max(0.25, +r.step || 1); r.attack = clamp(+r.attack, 0, 1); r.press = clamp(+r.press, 0, 1); r.pressVar = Math.max(0, +r.pressVar || 0);
    r.tremor = Math.max(0, +r.tremor || 0); r.smooth = Math.max(0, Math.floor(r.smooth)); r.overshoot = Math.max(0, +r.overshoot || 0);
