    const pressU = r.r(-1, 1), trPh = r.r(0, 1000), trW1 = r.r(12.5, 20), trW2 = r.r(20, 30), drPh = r.r(0, 1000), ovU = r.r(0.8, 1.2), curl = r.r(-1, 1), drW = r.r(90, 160);
