    const cols = [[232, 158, 176], [154, 210, 176], [232, 208, 96]];
    if (r.chance(0.5)) cols.reverse();
    const span = Math.min(S.maxW * 0.92, W * 0.28);
    const top = S.base - Math.min(S.maxH * (S.behind ? 0.94 : 0.86), W * 0.50);
    const bot = S.base - Math.min(S.maxH * (S.behind ? 0.48 : 0.30), W * 0.18);
