      const tg = blob(rng, cx + rng.r(-mw * 0.15, mw * 0.15), cy + mh * 0.48, mw * rng.r(0.5, 0.62), mh * rng.r(0.36, 0.46), 12, 0.1);
      paintShape(ctx, rng, tg, red, { n: 3, szMul: 0.7, under: 1 });
      oilStick(ctx, rng, S.concat([S[0]]), fcINK(D.inkC), fcW(D, 0.42), { a: 0.9, dbl: 0.3, tooth: 0.3, over: 6 });
