      oilStick(ctx, rng, smoothPts(blob(rng, nx, ny + nr * 0.1, nr * 1.05, nr * 0.85, 12, 0.08), true, 1).concat([]), mix(fcINK(D.inkC), red, 0.3), fcW(D, 0.3), { a: 0.75, dbl: 0.2, tooth: 0.35, over: 4 });
      // the spray: a few small pale dots flying out and down from the nose to one side
